// Generated by tools/docs/build-docs.mjs. Do not edit.
export const DOCUMENTATION: Readonly<Record<string, string>> = {
  'documentation/releases/1.4.20/README.md':
    '<h1>Blocks 1.4.20</h1>\n<p>Published October 31, 2026 on the Release channel (<code>latest</code>). Install this exact version with <code>npm install @filip.mazev/blocks@1.4.20</code>.</p>\n<p><a href="https://www.npmjs.com/package/@filip.mazev/blocks/v/1.4.20">View version 1.4.20 on NPM</a>.</p>\n<p>Blocks 1.4.20 brings together the unified Angular UI package, semantic themes, appearance effects, forms, navigation, notifications and icons developed leading\nup to this version. These cumulative notes include changes from earlier versions without their own notes, including 1.4.19, and the final side-navigation\nrefinements shipped in 1.4.20. They do not imply that every feature first appeared in this patch.</p>\n<p>The documented source range is <code>f9bf13b2bb6914c26d11639076006bd1dcc5a851</code> through <code>b18ac855a86e7ad9fe77d1d4944f069ccde309ba</code>, NPM&#39;s recorded 1.4.20 source\ncommit. Features added after that endpoint are covered by the <a href="release-notes/1.5.0">1.5.0 Beta change notes</a>.</p>\n<h2>Unified package and installation</h2>\n<ul>\n<li>Consolidated <code>@filip.mazev/blocks-core</code> and <code>@filip.mazev/modal</code> into <code>@filip.mazev/blocks</code>.</li>\n<li>Added dedicated public entry points for <code>core</code>, <code>forms</code>, <code>primitives</code>, <code>navigation</code>, <code>icons</code>, <code>modal</code>, <code>toastr</code> and <code>effects</code>.</li>\n<li>Added an interactive <code>ng add @filip.mazev/blocks</code> schematic with palette selection, global Sass configuration and effects stylesheet registration.</li>\n<li>Updated Angular peer dependencies from Angular 21 to Angular 22.</li>\n</ul>\n<h2>Theming and customization</h2>\n<ul>\n<li>Reworked theming around semantic roles for backgrounds, text, borders, primary and accent colors, and status feedback.</li>\n<li>Added typed color contracts, including <code>SemanticColorToken</code>, palette shade tokens and light/dark <code>ThemedColor</code> configurations.</li>\n<li>Introduced seven duo-tone palettes: Carbon / Cobalt, Azure / Ember, Violet / Teal, Tangerine / Indigo, Brick Rose / Cyan, Lime / Violet and Cyberpunk.</li>\n<li>Expanded <code>ThemingService</code> with runtime palette selection, high-contrast controls, appearance configuration and persisted preferences.</li>\n<li>Added shared styling utilities and component CSS variables for more consistent customization of spacing, typography, surfaces and interaction states.</li>\n<li>Preserved the connection between responsive Sass mixins and <code>WindowDimensionsService</code> breakpoints.</li>\n</ul>\n<p>See the <a href="appearance">appearance guide</a> for current application-wide configuration. Its API\ncontinues to evolve after this release.</p>\n<h2>Glass, physics and lighting</h2>\n<ul>\n<li>Added a shared glass material across components and overlays, configurable globally through <code>ThemingService.setAppearance()</code>.</li>\n<li>Added numeric <code>glassiness</code> for tint and blur, automatic/baseline/enhanced rendering quality and reduced-transparency settings.</li>\n<li>Added <code>BxSurfaceDirective</code> for applying Blocks materials to application-owned surfaces, with local appearance and interaction overrides.</li>\n<li>Introduced spring-based press feedback and spatial lighting that responds to interaction and active states.</li>\n<li>Added ambient edge tinting from nearby content, with depth and occlusion handling that respects overlay boundaries.</li>\n<li>Added opaque fallbacks for forced colors, reduced transparency and unsupported backdrop filters.</li>\n<li>Exposed a framework-independent DOM effects runtime through <code>@filip.mazev/blocks/effects/runtime</code>.</li>\n</ul>\n<p>Here <code>glassiness</code> is the numeric appearance preference used by 1.4.20; the later <code>translucency</code> name and refraction policy belong to subsequent versions.</p>\n<h2>Forms and controls</h2>\n<ul>\n<li>Added buttons, form fields, text and numeric inputs, multiline inputs, search inputs, checkboxes, radio buttons and groups, switches, selects, multiselects,\nnative sliders and range sliders.</li>\n<li>Added integration with Angular Signal Forms, Reactive Forms, template-driven forms and standalone value models.</li>\n<li>Introduced shared validation presentation with configurable error messages, priorities, visibility policies, projected errors and application defaults.</li>\n<li>Added composable prefixes, suffixes, hints, required markers, floating labels and filled/outlined field appearances.</li>\n<li>Added native-control integration through <code>bxInput</code> and an extension contract for custom form-field controls.</li>\n<li>Added distinct readonly behavior through both <code>readOnly</code> and Angular&#39;s lowercase <code>readonly</code> contract.</li>\n<li>Added numeric parse-state handling, keyboard-accessible steppers, textarea autosizing and native input attribute forwarding.</li>\n</ul>\n<h2>Asynchronous selection and pagination</h2>\n<ul>\n<li>Added application-owned loading, searching, error and pagination state to selection controls.</li>\n<li>Added searchable multiselects with tag presentation, overflow summaries, configurable templates and explicit select-all intent.</li>\n<li>Introduced reusable <code>LoadMoreDirective</code> behavior with guarded scroll requests, a visible fallback action when content does not overflow, and explicit retry.</li>\n<li>Distinguished scroll, button and retry request sources.</li>\n<li>Added retained-content error states and separate feedback for initial loading, replacement searches and incremental loading.</li>\n</ul>\n<h2>Primitives and overlays</h2>\n<ul>\n<li>Added loading indicators, spinners and determinate/indeterminate progress bars.</li>\n<li>Added tags and tabs with controlled selection, disabled states, per-tab colors and icons, keyboard navigation and lazy content templates.</li>\n<li>Added menus, cascading submenus, dropdowns, context menus and tooltips.</li>\n<li>Added shared overlay positioning, live theme inheritance, keyboard dismissal and focus behavior for these overlay controls.</li>\n<li>Added <code>TruncateDirective</code>, <code>TruncatedTextPipe</code> and <code>truncatedText()</code> for reusable overflow detection and conditional tooltips.</li>\n<li>Added configurable automatic truncation tooltips across supported controls.</li>\n</ul>\n<p>Cards, layout primitives, alerts, chips, collapsibles, accordions, skeletons and interactive popovers arrive in 1.5.0.</p>\n<h2>Navigation foundation</h2>\n<ul>\n<li>Added <code>NavigationService</code>, route metadata helpers, breadcrumbs and shared navigation configuration.</li>\n<li>Added <code>defineNavigation()</code> with typed section IDs and reusable route declarations.</li>\n<li>Added route-driven side navigation with hierarchical browsing, contextual search and active-route handling.</li>\n<li>Added compact side rails, responsive mobile drawers, configurable slots and persisted desktop navigation state.</li>\n<li>Added access-adapter filtering, translated navigation metadata and focus/scroll restoration when navigating submenu levels.</li>\n</ul>\n<p>The following sections describe the side-navigation refinements included at the end of this cumulative range.</p>\n<h2>Responsive submenu browsing</h2>\n<ul>\n<li>Added <code>submenuBreakpoint</code> (default <code>xl</code>) and <code>submenuMode</code> (<code>auto</code>, <code>inline</code>, or <code>flyout</code>) to control desktop submenu presentation independently of nesting\ndepth.</li>\n<li>At or below the threshold, children replace the current list inside the rail. Inline navigation also measures its containing shell, so an embedded narrow rail\nuses the appropriate layout even on a wide screen.</li>\n<li>Above the threshold, children open in one adjacent opaque panel. Deeper levels reuse that panel instead of accumulating recursive overlays.</li>\n<li>Mobile drawers always browse inside their own panel. Changing available width preserves the browsing path.</li>\n<li>Added a persistent Back action, ancestor path, and a parent heading that links to the parent&#39;s page. Returning to a previous level restores its scroll\nposition and disclosure focus.</li>\n<li>A compact rail temporarily expands when inline browsing needs space, while retaining the saved collapse preference.</li>\n<li>Explicit level changes animate briefly; reduced motion removes that movement.</li>\n</ul>\n<h2>Page links, selection, and search</h2>\n<ul>\n<li>Kept labels as native route links and separated their child-disclosure controls. Clicking a label navigates; clicking its chevron browses descendants.</li>\n<li>Required an explicit disclosure action for submenu opening. Hovering labels no longer opens navigation panels.</li>\n<li>Added independent hover and focus surfaces to page links and disclosures. Selection belongs to the active page link; expanded ancestors and search matches do\nnot acquire selected styling.</li>\n<li>Reworked search into a flat list of direct matches with translated parent paths in the main navigation. Searching does not open nested panels.</li>\n<li>Search normalizes accents and case, ranks exact, subsequence, and keyword matches, and tolerates one edit in words of at least four characters.</li>\n<li>Result labels navigate directly. Their disclosure leaves search and opens the chosen result&#39;s children. Clearing search restores the previous browsing level\nand its scroll position.</li>\n<li>Search temporarily expands a compact rail without changing its stored preference and searches only the currently supplied tree.</li>\n<li>Added a monochrome guide for the best nested result, with a static alternative under reduced motion. Top-level results have no guide; <code>showSearchGuide: false</code>\nhides it. This describes 1.4.20 behavior; later releases retire the guide.</li>\n</ul>\n<h2>Keyboard, focus, and mobile drawers</h2>\n<ul>\n<li>Preserved native links and menu/menuitem semantics with separate, named disclosure buttons.</li>\n<li>Enter, Space, or the arrow toward a submenu opens children. Up/Down and Home/End move within the current menu.</li>\n<li>Back, Escape, or the opposite arrow returns one level with focus and scroll restoration. At the root, Escape dismisses the mobile drawer.</li>\n<li>Kept Tab within adjacent panels and mobile drawers, and restored the opening control&#39;s focus after closing.</li>\n<li>Fixed mobile and inline preview presentation so layout changes establish the closed geometry immediately; explicit open/close actions animate the drawer.</li>\n<li>Retained the mobile close action, click-to-close scrim, and shared scroll locking. Resizing out of mobile presentation closes the drawer and releases its\nlock.</li>\n<li>Kept embedded inline drawers and scrims inside their positioned preview shell without locking the page.</li>\n</ul>\n<h2>Shared menu overlays</h2>\n<ul>\n<li>Added <code>menuManual: true</code> to <code>MenuTriggerDirective</code> for owners coordinating a single overlay across multiple disclosure controls.</li>\n<li>In manual mode, the owner supplies trigger interaction and ARIA semantics and calls <code>open()</code>/<code>close()</code>; automatic trigger handlers and host ARIA are omitted.</li>\n<li>Extended <code>open(focus?, origin?)</code> with an optional per-opening positioning origin.</li>\n<li>Preserved outside-click dismissal, focus trapping, keyboard dismissal, theme inheritance, overlay context, and origin visibility tracking.</li>\n<li>Reused native CSS anchoring and the existing measured fallback. Panels close when their origins leave the viewport or clipping container.</li>\n</ul>\n<h2>Icons and notifications</h2>\n<ul>\n<li>Added Lucide SVG icon integration with asynchronous loading, typed names, configurable sizing and stroke width, and semantic colors.</li>\n<li>Added custom icon definition helpers and decorative/meaningful icon semantics.</li>\n<li>Added <code>ToastrService</code> with standard information, success, warning and danger notifications, plus custom content.</li>\n<li>Added six notification positions, configurable duration, progress indicators, swipe dismissal, pause/resume controls and typed close results.</li>\n<li>Added shared notification defaults and theme-aware notification surfaces.</li>\n</ul>\n<h2>Accessibility, translations and developer experience</h2>\n<ul>\n<li>Added <code>BxA11yService</code> for reactive reduced-motion preferences and application overrides.</li>\n<li>Added optional <code>BX_I18N</code> integration and shared <code>ResolvableText</code> contracts for configurable text.</li>\n<li>Added reactive translation updates through the adapter&#39;s version signal.</li>\n<li>Added keyboard interaction, focus presentation, accessible labels, validation descriptions and RTL behavior across the new components.</li>\n<li>Expanded public configuration interfaces, template customization points and component documentation.</li>\n</ul>\n<h2>Playground</h2>\n<p>The playground application uses the shared <code>SideNav</code> with an expanded, text-focused menu. Its dedicated demo adds controls for comparing submenu presentations\nand exercising a four-level tree, search, focus, and scroll restoration.</p>\n<h2>Migration notes</h2>\n<p>Applications upgrading from the separate packages should update their imports and theme setup:</p>\n<table>\n<thead>\n<tr>\n<th>Previous API or setup</th>\n<th>Replacement in 1.4.20</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>@filip.mazev/blocks-core</code> imports</td>\n<td><code>@filip.mazev/blocks/core</code></td>\n</tr>\n<tr>\n<td><code>@filip.mazev/modal</code> imports</td>\n<td><code>@filip.mazev/blocks/modal</code></td>\n</tr>\n<tr>\n<td>Deep Sass imports from the old packages</td>\n<td><code>@use &#39;@filip.mazev/blocks&#39; as *;</code></td>\n</tr>\n<tr>\n<td><code>core-theme(...)</code> and legacy theme maps</td>\n<td><code>bx-theme(...)</code> with a current palette map</td>\n</tr>\n<tr>\n<td>Custom <code>--fm-*</code> theme overrides</td>\n<td>Review and migrate to the <code>--bx-*</code> semantic tokens</td>\n</tr>\n<tr>\n<td>Modal <code>bannerText</code></td>\n<td><code>header: { text: ... }</code>, with optional icon configuration</td>\n</tr>\n<tr>\n<td>Angular 21 applications</td>\n<td>Upgrade to Angular 22</td>\n</tr>\n</tbody></table>\n<p>For manual installation, register <code>@filip.mazev/blocks/effects/effects.css</code> once alongside the global Blocks theme. The installation schematic configures this\nautomatically.</p>\n<p>Existing <code>SideNav</code> consumers can retain automatic defaults. Set <code>submenuMode: &#39;inline&#39;</code> or <code>&#39;flyout&#39;</code> for an explicit desktop presentation, and customize Back\ntext through the existing translatable configuration. Applications relying on hover-to-open navigation should use the separate disclosure action. The former\n<code>--bx-side-nav-item-highlight-background</code> no longer colors search rows. Generic menu triggers retain automatic handling unless <code>menuManual</code> is enabled.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-side-nav</span> [<span class="hljs-attr">config</span>]=<span class="hljs-string">&quot;{ submenuBreakpoint: &#x27;xl&#x27;, submenuMode: &#x27;auto&#x27;, backLabel: { key: &#x27;nav.back&#x27; } }&quot;</span> /&gt;</span></code></pre>\n',
  'documentation/releases/1.5.0/README.md':
    '<h1>Blocks 1.5.0 Beta change notes</h1>\n<p>Published October 31, 2026 on the Beta channel. The exact NPM package version is <code>1.5.0</code>, without a <code>-beta</code> suffix. Install this historical version with\n<code>npm install @filip.mazev/blocks@1.5.0</code>.</p>\n<p><a href="https://www.npmjs.com/package/@filip.mazev/blocks/v/1.5.0">View version 1.5.0 on NPM</a>.</p>\n<p>This version adds top navigation, editable autocomplete, layout and feedback primitives, interactive popovers, platform-aware shortcuts and refined surface\ninteraction. These notes cover only the changes after <a href="release-notes/1.4.20">1.4.20</a>, from <code>b18ac855a86e7ad9fe77d1d4944f069ccde309ba</code> through\n<code>55b915c819525cfa365d4b59389a765233b2cd35</code>, NPM&#39;s recorded 1.5.0 source commit. The unified package, Angular 22 upgrade, semantic themes, existing forms,\nnotifications and initial glass runtime are documented in the cumulative 1.4.20 notes.</p>\n<h2>Top navigation and shared navigation behavior</h2>\n<ul>\n<li>Added <code>TopNav</code> with a horizontal menubar, a responsive compact presentation and one shared submenu/search panel.</li>\n<li>Added <code>bxTopNavBrand</code> and <code>bxTopNavActions</code> template slots, custom item content and typed <code>ITopNavConfig</code>, <code>ITopNavSlotContext</code> and shared navigation\ncontracts.</li>\n<li>Added <code>compactBreakpoint</code> (default <code>lg</code>), an explicit <code>compact</code> override, sticky positioning and panel dimensions. Content overflow also switches to compact\nnavigation, keeping essential links reachable as translations, slots, fonts, zoom or available width change.</li>\n<li>Shared hierarchical browsing, flat contextual search, active-route selection, translated labels and focus/scroll restoration between top and side navigation.</li>\n<li>Added clickable ancestor paths that browse a level without navigating away; the current parent&#39;s heading remains a page link.</li>\n<li>After selecting a search result, clearing search now opens its containing submenu and scrolls the selected row into view while keeping search-field focus.\nClearing without a successful selection restores the previous browsing location.</li>\n<li>Added RTL-aware horizontal arrow navigation, Home/End and roving tab stops to the shared menu keyboard helper.</li>\n<li>Removed floating search guides. The retained <code>showSearchGuide</code> option is deprecated and ignored; former guide CSS variables have no effect.</li>\n<li>Updated the playground toolbar to use <code>TopNav</code>, with responsive examples and shared English, Spanish, French and German navigation fixtures.</li>\n</ul>\n<h2>Editable autocomplete</h2>\n<ul>\n<li>Added <code>Autocomplete</code>, <code>IAutocompleteOption</code> and <code>IAutocompleteOptionContext</code> through the forms entry point.</li>\n<li>Added a <code>string | null</code> value model with valid free text, optional suggestions, disabled options and customizable option templates.</li>\n<li>Added optional inline completion that remains uncommitted until accepted, keyboard selection, IME-aware editing and a clear action.</li>\n<li>Reused the existing form-field, validation, disabled/readonly, translation and Angular forms integration contracts.</li>\n<li>Added application-owned query/search/loading/error state and external filtering. Pagination reuses <code>LoadMoreDirective</code>, including retained-content failure,\nexplicit retry and the reachable action when there is no scrollbar.</li>\n<li>Added delayed playground requests demonstrating search, empty results, incremental loading, failure and successful retry, with page-size controls.</li>\n</ul>\n<h2>Layout, feedback and disclosure primitives</h2>\n<ul>\n<li>Added <code>Card</code>, <code>Container</code>, <code>Stack</code>, <code>Grid</code> and <code>Divider</code>, with semantic surfaces, responsive layout settings and component CSS variables.</li>\n<li>Added <code>Alert</code>, also available as <code>bx-banner</code>, with semantic tones, projected actions, optional announcements, dismissal and focus restoration.</li>\n<li>Added alert emission controls that reuse the shared lighting engine and respect scene boundaries.</li>\n<li>Added interactive <code>Chip</code> with controlled selection, activation and removal events, separate remove actions and disabled/readonly behavior.</li>\n<li>Added <code>Collapsible</code> and coordinated <code>Accordion</code> expansion, keyboard-accessible headers and reduced-motion behavior.</li>\n<li>Added <code>Skeleton</code> with configurable shapes and animation that respects reduced motion.</li>\n<li>Added colocated guides and reachable playground examples for the new primitives.</li>\n</ul>\n<h2>Interactive popovers and menu overlays</h2>\n<ul>\n<li>Added <code>Popover</code>, <code>PopoverDirective</code>, <code>IPopoverConfig</code> and <code>BX_POPOVER_DEFAULTS</code> for interactive help, compact forms and contextual content.</li>\n<li>Added nonmodal dialog semantics, configurable placement and dismissal, optional autofocus, translated accessible names and trigger-focus restoration.</li>\n<li>Kept popover content scrollable within the viewport, with live theme inheritance and existing overlay/top-layer support.</li>\n<li>Added <code>MenuTriggerDirective.menuPlacement</code> for dropdown placement while retaining side-aligned submenu defaults.</li>\n<li>Added <code>menuClosing</code>, emitted before overlay detachment so navigation owners can preserve scroll and focus context.</li>\n<li>Updated overlay theme inheritance to observe direction changes and propagate <code>dir</code> to mounted panels.</li>\n</ul>\n<h2>Platform-aware keyboard shortcuts</h2>\n<ul>\n<li>Expanded <code>BxShortcutService</code> with platform selection, normalized display tokens, <code>toAriaKeyshortcuts()</code> and application-owned event matching through\n<code>matches()</code>.</li>\n<li>Added portable <code>mod</code> combinations, common key aliases and explicit iOS/Android overrides through <code>IOSShortcut</code>, alongside <code>ShortcutPlatform</code> and\n<code>IShortcutMatchOptions</code>.</li>\n<li>Ignored handled, composing and AltGraph events, plus repeated keys and editable targets by default. Applications can explicitly allow repeat/editable matches.</li>\n<li>Added valid <code>aria-keyshortcuts</code> metadata to menu items. Shortcut hints do not register global handlers; applications retain ownership of actions and scopes.</li>\n<li>Improved iPadOS desktop-user-agent detection and desktop/mobile operating-system classification.</li>\n</ul>\n<h2>Press feedback, lighting and form presentation</h2>\n<ul>\n<li>Refined shared pressure feedback with a soft inset sheen and button-content compression while keeping hit areas, layout and overlay origins fixed.</li>\n<li>Added a visible initial response for quick taps and cleanup on cancellation, key release, focus loss, hidden documents and teardown. Reduced motion uses\nstatic feedback, and touch hover does not remain latched.</li>\n<li>Kept editable fields illuminated for pointer focus while ordinary actions use keyboard focus. Expanded popup triggers retain light; plain layout expansion\nalone does not mark a control selected.</li>\n<li>Changed explicit scene-light selection to rank all eligible sources by visible contribution per receiver, with at most four selected lights, rather than\ntaking the first four registered sources.</li>\n<li>Exposed <code>getGlassLightRoot()</code> for resolving existing light-scope boundaries.</li>\n<li>Aligned checkbox/radio presentation and radio subscript sizing with shared form defaults, and reused common caret and opaque option-panel styling for Select\nand Autocomplete.</li>\n</ul>\n<h2>Migration notes</h2>\n<p>Existing 1.4.20 package imports, Angular 22 peer requirements, theme setup and effects stylesheet registration remain applicable. New components are available\nthrough the existing public entry points.</p>\n<p>Remove dependencies on side-navigation search guides and their CSS variables. <code>showSearchGuide</code> remains accepted for compatibility but no longer changes the\nrendered navigation. Shortcut combinations use arrays such as <code>[&#39;mod&#39;, &#39;k&#39;]</code>; plain strings remain single display tokens. Continue handling shortcut actions in\nthe application, using <code>BxShortcutService.matches()</code> where needed.</p>\n<p>The Beta channel describes this historical publication&#39;s intended maturity. Because <code>1.5.0</code> was already published as an exact version, it cannot later identify\na different stable package. Future prereleases should use a suffix such as <code>1.6.0-beta.1</code>, following <a href="https://semver.org/spec/v2.0.0.html">Semantic Versioning</a>.</p>\n',
  'documentation/releases/1.5.2/README.md':
    '<h1>Blocks 1.5.2</h1>\n<p>Blocks 1.5.2 alpha adds opt-in glassiness, selectable cards and a more focused appearance page, with shared lighting fixes for themed controls.</p>\n<p>Package version: <code>1.5.2</code>. Distribution channel: npm&#39;s <code>alpha</code> tag.</p>\n<h2>Glassiness and surface appearance</h2>\n<ul>\n<li>Added SVG-backed refraction for explicitly selected surfaces on supported browsers, with the existing material as the fallback.</li>\n<li>Added <code>glassiness</code> policies (<code>auto</code>, <code>off</code>, <code>on</code>) to surface configuration and opt-in controls. Global Off, device budgets and accessibility preferences take\nprecedence.</li>\n<li>Added Automatic rendering with one refraction pass and Enhanced rendering with reflection and bevel layers. Shared geometry caches, bounded reflection regions\nand paused offscreen work limit rendering costs.</li>\n<li>Kept glassiness opt-in for controls and cards that benefit from it, including the appearance preview, overview feature cards and toast surfaces.</li>\n<li>Renamed the numeric surface preference to <code>translucency</code>. Tint and blur use a nonlinear scale with a lighter default, a sharp minimum and a stronger finish at\nthe maximum. Reduce transparency remains the fully opaque presentation.</li>\n<li>Kept text, placeholders and icons in their theme or component colors. A minimum tint backing provides readability without dynamic foreground switching.</li>\n<li>Persisted rendering, glassiness, translucency and reduced transparency together, including Enhanced rendering across refreshes. Glassiness Off returns\nEnhanced to Automatic.</li>\n<li>Baseline temporarily switches Glassiness to Off and disables its controls, including browser opt-in. Returning to Automatic or Enhanced restores the previous\nglassiness policy, including after a reload; an explicitly chosen Off stays Off. Enhanced remains available from Baseline when the remembered policy permits\nit.</li>\n<li>Preserved the material while scrolling under translucent surfaces and during overlay fades.</li>\n</ul>\n<h2>Selectable cards</h2>\n<ul>\n<li>Added clickable cards with controlled <code>selected</code> state, <code>selectedChange</code>, <code>activated</code>, disabled and readonly behavior.</li>\n<li>Added the native <code>button[bx-card]</code> variant alongside <code>bx-card</code>.</li>\n<li>Added configurable selection lighting through <code>highlightColor</code> and <code>--bx-card-highlight</code>, using the shared semantic lighting engine.</li>\n<li>Preserved keyboard activation, visible focus and nested action behavior. Disabled cards cannot activate; readonly cards remain focusable and preserve their\nselected state.</li>\n</ul>\n<h2>Lighting and form controls</h2>\n<ul>\n<li>Resolved emission colors in the source component&#39;s theme scope so accent-colored controls illuminate neighboring surfaces with the correct color.</li>\n<li>Kept active borders painted as surfaces cross viewport edges or pass behind sticky headers, avoiding a visible fade on re-entry.</li>\n<li>Kept surrounding light active while sources and receivers remain partly exposed, including inside clipped scrolling containers. A covered center or projected\ncorner no longer removes the entire effect; fully covered surfaces remain excluded.</li>\n<li>Restored accent emission for form checkboxes, including checked and indeterminate states, hover and keyboard focus. Disabled and readonly checkboxes remain\npassive.</li>\n<li>Added the <code>Checkbox.emissive</code> input, defaulting to <code>true</code>, and the decorative <code>CheckboxIndicator.emissive</code> input, defaulting to <code>false</code>.</li>\n<li>Kept multiselect option and select-all indicators non-emissive while retaining their themed faces and selection marks.</li>\n<li>Aligned slide-toggle hints and errors with the control and added layout tokens for settings rows with labels and switches at opposite ends.</li>\n</ul>\n<h2>Accordion and collapsible headers</h2>\n<ul>\n<li>Matched hover highlights to the container&#39;s inner corner radius, including custom radius values.</li>\n<li>Kept expanded headers rounded at the top and square at the bottom, and removed the divider between the header and content.</li>\n</ul>\n<h2>Appearance playground</h2>\n<ul>\n<li>Organized preferences into Appearance, Surfaces, Theme and Accessibility sections.</li>\n<li>Added selectable Light, Dark and Auto preview cards built from Blocks components.</li>\n<li>On smaller screens, Light and Dark cards sit side by side with portrait previews and an Automatic slide toggle below. Automatic highlights the active system\nmode; choosing the other card switches to an explicit preference.</li>\n<li>Moved the translucency slider into a padded pill below the surface demo, with a separate description and a Reset action. Advanced settings use the Blocks\ncollapsible component.</li>\n<li>Kept the disabled glassiness controls synchronized with Baseline and the remembered rendering preferences.</li>\n<li>Simplified the top bar to one Appearance action. Mode and palette controls live on the appearance page.</li>\n<li>Added alpha channel labeling to the playground and release-note selector while preserving earlier version URLs.</li>\n<li>Linked the overview&#39;s npm action to the newest version in the configured release channel.</li>\n</ul>\n<h2>Migration and configuration</h2>\n<p>The numeric <code>glassiness</code> preference is now <code>translucency</code>; <code>glassiness</code> selects browser policy for refraction. Existing saved numeric preferences migrate\nautomatically. Applications using the old numeric API should update these names:</p>\n<table>\n<thead>\n<tr>\n<th>Previous numeric API</th>\n<th>Replacement</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>setAppearance({ glassiness: 0.5 })</code></td>\n<td><code>setAppearance({ translucency: 0.5 })</code></td>\n</tr>\n<tr>\n<td><code>bxSurfaceGlassiness</code> with a numeric value</td>\n<td><code>bxSurfaceTranslucency</code></td>\n</tr>\n<tr>\n<td><code>--bx-glassiness</code></td>\n<td><code>--bx-translucency</code></td>\n</tr>\n</tbody></table>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">const</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\nthemingService.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span>, <span class="hljs-attr">glassiness</span>: <span class="hljs-string">&#x27;auto&#x27;</span> });</code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;icon&quot;</span> <span class="hljs-attr">glassiness</span>=<span class="hljs-string">&quot;auto&quot;</span> <span class="hljs-attr">aria-label</span>=<span class="hljs-string">&quot;Open contents&quot;</span>&gt;</span>…<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span> <span class="hljs-tag">&lt;<span class="hljs-name">bx-checkbox</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Receive updates&quot;</span> [<span class="hljs-attr">emissive</span>]=<span class="hljs-string">&quot;true&quot;</span> /&gt;</span></code></pre>\n<p>Register the effects stylesheet once through the existing Blocks setup. Custom material and foreground overrides remain application-owned. See the\n<a href="appearance">appearance guide</a>,\n<a href="components/card">card documentation</a> and\n<a href="components/checkbox">checkbox documentation</a> for the complete APIs.</p>\n',
  'documentation/releases/1.5.3-alpha/README.md':
    '<h1>Blocks 1.5.3-alpha</h1>\n<p>Published Alpha change notes for <a href="https://www.npmjs.com/package/@filip.mazev/blocks/v/1.5.3-alpha">@filip.mazev/blocks@1.5.3-alpha</a>.</p>\n<h2>Declarative side panel</h2>\n<ul>\n<li>Added standalone <code>SidePanel</code> (<code>bx-side-panel</code>) to <code>@filip.mazev/blocks/primitives</code>, controlled through the <code>open</code> boolean model and its <code>openChange</code> output.</li>\n<li>Supports left/right placement, numeric or CSS-length widths, optional element containment, viewport bounds, scoped backdrops, and reactive configuration.</li>\n<li>Added <code>SidePanelLayout</code> for stable CSS containment and real push slots beside page content. <code>layoutMode</code> defaults to overlay; optional typed <code>breakpoints</code>\nresolve minimum-width modes through <code>WindowDimensionsService</code>, with the highest matching configured threshold winning. <code>currentLayoutMode()</code> exposes the\neffective mode. Push and overlay changes retain the same panel and projected content.</li>\n<li>Panels inside the layout no longer follow document-scroll rectangles or use deferred scroll-time positioning. Standalone/external-bound overlay presentation\nremains supported; <code>container=&quot;viewport&quot;</code> explicitly escapes an enclosing layout. All four side-panel corners are square through shared Modal Side styles.</li>\n<li>The panel provides the existing top-layer overlay context for nested selection controls, menus, popovers, and tooltips. Tooltips now honor that context and\nuse the shared synchronous origin tracker, avoiding clipping and panel-relative stacking failures.</li>\n<li>Unhandled Escape is observed for the complete open lifetime, including after projected-content updates or focus moves to the surrounding page. Child overlays\nretain first dismissal through their existing event handling; tooltip dismissal now marks Escape handled.</li>\n<li>Added <code>SidePanelHeaderDirective</code>, <code>SidePanelFooterDirective</code>, and <code>SidePanelBannerDirective</code> for projected sections. Body content remains mounted across\nclosing and reopening; omitted sections reserve no space, and the body scrolls separately from header/footer actions.</li>\n<li>Nonmodal complementary-region semantics preserve ordinary page interaction and keyboard navigation. Configurable focus entry/restoration, close controls,\nEscape dismissal, translated accessible names, and mounted reduced-motion updates are supported without page scroll locking or focus trapping.</li>\n<li>Shared panel-frame, header/footer, banner, and close-control Sass presentation with Modal Side. Existing modal services, layouts, backdrops, focus trapping,\nscroll locks, nested modal handling, animations, and dismissal contracts remain in place.</li>\n</ul>\n<h2>Modal and panel presentation</h2>\n<ul>\n<li>Fixed centered modal content clipping on small screens, including nested dialogs. The content region scrolls while header and footer actions remain reachable.</li>\n<li>Declarative SidePanel and left/right Modal Side surfaces use square corners on all four edges, including their material decorations.</li>\n<li>Centered, side, and bottom-sheet modals share the declarative panel&#39;s translucent surface presentation. <code>--bx-modal-bg</code> / <code>--bx-modal-text</code> retain priority,\nwith shared panel and semantic surface/text fallbacks. Root dialogs retain the ordinary 0.52 opacity floor and their shared appearance preferences.</li>\n<li>The root dialog paints dimming outside its border so its translucent surface samples the page without its own black scrim. Centered layouts keep viewport\ndimming on an unscaled frame while the clear opening follows the dialog&#39;s zoom. The shared backdrop retains blur, pointer hit testing, and dismissal.</li>\n<li>Nested dialogs use independent fixed backdrops, retaining the parent&#39;s material and backdrop. The first nested dialog uses a 0.9 minimum opacity; subsequent\nnested levels use 1. <code>ModalGlobalSettingsService.nestedOpacityFloors</code> configures those floors reactively, with the final entry repeated at deeper levels. An\nempty array disables depth adjustment. Appearance/accessibility settings may increase opacity further. Close guards and responsive layouts share the policy.</li>\n<li>All built-in light-mode accents now use white foregrounds on contrast-safe semantic base/hover/active shades. Raw palette anchors and theme-picker swatches\nremain unchanged. Other on-fill roles prefer white when it reaches 4.5:1 contrast, otherwise a dark foreground.</li>\n<li>Corrected brand/accent text against its supported surfaces and secondary text against dark hover/pressed surfaces. Success, information, warning, and danger\nretain their original foreground, border, and normal/hover/active fill shades. High-contrast definitions and explicit theme overrides retain control. Filled\nchips preserve their semantic fill during hover and add an inset outline to retain on-fill contrast.</li>\n<li>Declarative SidePanel headings share Modal Side&#39;s title/icon layout, wrapping, divider spacing, and compact 32px close controls. <code>SidePanel.headerIcon</code>\naccepts optional <code>IIconData</code> with modal-banner size, semantic color, background, and stroke behavior. Projected headings and the separate top-banner slot\nremain supported.</li>\n</ul>\n<h2>Reusable resizing</h2>\n<ul>\n<li>Added <code>ResizeHandleDirective</code> (<code>bxResizeHandle</code>) to Primitives with a numeric <code>resizeValue</code> model, physical left/right width and top/bottom height edges, and\ntyped <code>IResizeHandleEvent</code> lifecycle events. Owners apply sizes to their own layouts; no table/panel-specific state or target-style mutation is required.</li>\n<li>Added explicit pixel minimum/maximum inputs, optional original-size references, and container observation. Default maximum is 50% of the container; the\nrelative minimum is 30% of original size. <code>resizeDisableShrink</code> defaults to true, retaining the original-size floor until shrinking is explicitly enabled.\nAvailable container extent wins over conflicting bounds.</li>\n<li>Pointer capture, frame-coalesced updates, final-position flushing, keyboard arrows/Home/End, Shift increments, and Escape cancellation share bounded values.\nListeners, capture, and temporary selection/cursor styles are cleaned up on completion, cancellation, disabling, focus loss, and destruction.</li>\n<li>Added opt-in SidePanel width resizing with a handle on its inner edge. <code>width</code> is a model supporting <code>widthChange</code>; existing one-way bindings still work.\n<code>resizable</code>, <code>resizeMinWidth</code>, <code>resizeMaxWidth</code>, <code>resizeDisableShrink</code>, and translatable <code>resizeLabel</code> configure interaction. CSS-length initial widths are\nsupported; completed adjustments write numeric pixels, and cancellation restores the original representation. Side panels resize horizontally only.</li>\n<li>Added shared neutral resize-grip styling: a compact three-dot pill in a separate gutter and a full-edge line without dots on hover/drag. Pointer inactivity\nfades the idle grip; focus, touch, reduced motion, and forced colors retain appropriate feedback. Push panels reserve the gutter. <code>resizeActivityContainer</code>\nseparates pointer activity from portal bounds, and <code>resizeIdleDelay</code> defaults to 2000ms with zero retaining a persistent idle grip.</li>\n<li>Added <code>Chip.deselectable</code>, default true. False supports owner-coordinated single-choice chip groups without toggling the active choice off. Filled chip\nmaterial now defaults to an opaque semantic fill, configurable through <code>--bx-chip-fill-opacity</code>, so primary selection remains visible.</li>\n</ul>\n<h2>Scroll-boundary detection and shared loading</h2>\n<ul>\n<li>Added <code>InfiniteScrollDirective</code> (<code>bxInfiniteScroll</code>) to Primitives for detecting proximity to the end of arbitrary scroll containers or an ancestor/document\nviewport. Inputs configure pixel thresholds, disabled/loading states, completion revisions, and an optional footer offset.</li>\n<li>Detection remains separate from fetching, pagination, indicators, buttons, retries, and exhaustion. <code>scrollEnd</code> emits a guarded boundary event; <code>complete()</code>\nacknowledges completion when the owner has no loading cycle or revision change. Read-only <code>overflowing()</code> exposes measured overflow.</li>\n<li>Optional <code>infiniteScrollCheckOnRender</code> enables finite local progressive rendering to fill short viewports after initial render, content changes, and resizing.\nIt defaults to false to avoid uncontrolled remote request loops. Owners explicitly disable detection at exhaustion.</li>\n<li>Exported <code>findScrollContainer</code>, <code>measureScrollBoundary</code>, <code>observeScrollBoundary</code>, and <code>IScrollBoundary</code> for reusable viewport discovery, geometry, and\ndisposable passive observation. Browser observers start after rendering, reconnect for container changes, and release removed content targets and listeners.</li>\n<li>Refined <code>LoadMoreDirective</code> to use the same Core boundary measurement/observation helpers. Select and Multiselect retain one shared orchestration layer for\nloading, no-scrollbar fallback actions, failure, explicit retry, and request-source payloads. Their public inputs and outputs remain unchanged.</li>\n<li>Kept footer-excluded overflow measurement and explicit remote fallback behavior. Scroll request guards now run before entering Angular when no new request can\nbe emitted, avoiding redundant change-detection work while loading or awaiting completion.</li>\n</ul>\n<h2>Bidirectional virtual rendering</h2>\n<ul>\n<li>Added <code>VirtualCollection&lt;T&gt;</code> and typed <code>VirtualItemDirective&lt;T&gt;</code> to Primitives for a sliding row window independent of detection and data loading. List and\nresponsive multi-column grid modes mount overscan near the viewport and unmount distant items while preserving overall scroll extent with spacers.</li>\n<li>Exported <code>IVirtualCollectionConfig</code>, <code>IVirtualItemContext&lt;T&gt;</code>, <code>IVirtualRange</code>, stable-key/track-by contracts, and layout types. Configuration covers\nestimated row height, overscan pixels, and CSS or numeric minimum column width; <code>measurementRevision</code> invalidates cached geometry.</li>\n<li>Measure dynamic rows with <code>ResizeObserver</code> and maintain a cached prefix-sum tree for efficient height updates and offset lookups. Width and column changes\nregroup rows and retain a stable visible anchor. Scroll corrections run after spacer rendering, including when the browser clamps a shrinking scroll extent.</li>\n<li>Exposed read-only <code>renderedRange()</code> and <code>renderedItems()</code> for bounded consumer presentation work, plus <code>scrollToIndex()</code>, <code>scrollToItem()</code>, and\n<code>refreshMeasurements()</code>. Programmatic smooth scrolling respects reduced motion. Focused rows can remain independently mounted; responsive regrouping restores\ntheir focused control when available. Measurement internals and coordination tokens remain outside public exports.</li>\n</ul>\n<h2>Icons and generated categories</h2>\n<ul>\n<li>Broadened <code>IconSize</code> to positive numeric pixel values or numeric strings and <code>number</code> to positive numeric values, enabling continuous customization. Existing\nvalues remain valid. Runtime invalid dimensions use 24 pixels and invalid stroke widths use 1.5.</li>\n<li>Ignore icon-load completions after input replacement or destruction.</li>\n<li>Added <code>LUCIDE_CATEGORIES</code>, <code>LUCIDE_ICON_CATEGORIES</code>, and <code>LucideCategoryId</code> to the icons entry point. Category records are synchronized with the generated\nicon names, support multiple assignments and upstream aliases, and use a predictable uncategorized fallback.</li>\n<li>Extended the existing generation pipeline with an offline, release-pinned official Lucide snapshot. A controlled synchronization command resolves upstream\ncategory inheritance and preserves attribution. Normal builds and runtime require no metadata network requests, and mismatched dependency/snapshot versions\nfail with synchronization instructions.</li>\n</ul>\n<h2>Catalog navigation</h2>\n<ul>\n<li>Icons and Tokens show their scroll action only after scrolling 400 pixels past the results&#39; start. Reading documentation above the catalog does not trigger\nit.</li>\n<li>The action returns to the catalog results and focuses that region. Its tooltip and accessible name are <strong>Scroll to catalog top</strong>. Documentation expansion and\nviewport changes update the threshold and destination; reduced motion remains supported.</li>\n</ul>\n<h2>Page layouts and breadcrumbs</h2>\n<ul>\n<li>Added <code>PageContainer</code>, <code>PageHeader</code>, <code>PageContent</code>, and <code>PageFooter</code> to primitives with public configuration and colocated guides.</li>\n<li>Added responsive width/padding presets and <code>ResolvableText</code> support for section titles, page titles, explicit descriptions, breadcrumb labels, and the\nbreadcrumb navigation&#39;s accessible name. Already-rendered text reacts to the optional <code>BX_I18N</code> language revision.</li>\n<li>Added <code>autoResolveTitlesFromNavigation</code>, default true, to infer undefined headings. Descriptions remain explicit; empty titles suppress automatic values.\nProjected headers support additional content and configurable semantic heading levels.</li>\n<li>Connected <code>provideNavigation()</code> and <code>NavigationService.page</code> to optional <code>BX_PAGE_NAVIGATION</code> without a dependency from primitives to navigation. Applications\ncan supply their own reactive <code>IPageNavigation</code> adapter or explicit headings and breadcrumb trails.</li>\n<li>Added automatic breadcrumbs with a configurable <code>breadcrumbsAfter</code> threshold. The default hides root trails and shows ancestor links on child pages. Native\nordered links, current-page markers, focus indicators, and wrapping support narrow screens, translated labels, and RTL layouts.</li>\n</ul>\n<h2>Mobile navigation and scroll locking</h2>\n<ul>\n<li>Reused the shared backdrop in mobile side navigation, including blur and opaque accessibility fallbacks. Added a translatable dismissal label, tab-order\ninput, and presentation CSS variables.</li>\n<li>Tied drawer <code>ScrollLockService</code> ownership to open overlay presentation and released its own lock on close, navigation, presentation changes, and destruction.\nEmbedded inline drawers retain their container-scoped behavior without a page lock.</li>\n<li>Made scroll-lock ownership idempotent. Releasing one owner preserves other locks, recalculates touch/overflow requirements, and restores original inline body\nstyles only after the final owner releases its lock.</li>\n</ul>\n<h2>Window dimensions and responsive breakpoints</h2>\n<ul>\n<li>Expanded <code>WindowDimensionsService</code> with extra-small/small mobile, small laptop, large desktop, ultra-wide, and cumulative <code>*AndBelow</code> signals while retaining\n<code>isMobile</code>, <code>isTablet</code>, and <code>isDesktop</code>.</li>\n<li>Added <code>currentBreakpoint()</code> and <code>currentBreakpointValue()</code>, returning undefined outside the browser. The active breakpoint is the highest configured\nminimum-width threshold not exceeding the viewport width.</li>\n<li>Added typed <code>isAtLeast()</code>, <code>isBelow()</code>, <code>isBetween()</code>, and generic <code>resolveResponsiveValue()</code> with a caller-provided server fallback.</li>\n<li>Centralized comparisons and improved first-render dimension detection. Resize updates are animation-frame-coalesced instead of debounced by 150 ms and clean\nup automatically on destruction.</li>\n</ul>\n<h2>Navigation API</h2>\n<ul>\n<li>Replaced side-navigation submenu popups with nested lists at every screen size and depth. Back, ancestor navigation, scroll restoration, and temporary compact\nrail expansion remain available.</li>\n<li>Removed <code>submenuMode</code>, <code>submenuBreakpoint</code>, <code>SideNavSubmenuMode</code>, and <code>isInlineSubmenus()</code>. Nested browsing always uses the panel; obsolete submenu\nwidth/height variables no longer apply.</li>\n<li>Kept route selection separate from programmatic focus and focused the active route when entering its level. Ancestor navigation reveals the original entry and\nscrolls only the navigation list. Section-only ancestors return directly to the navigation root.</li>\n<li>Renamed <code>withNav</code> to <code>withInAppNavigation</code> without a deprecated alias.</li>\n</ul>\n<h2>Design tokens and theme palettes</h2>\n<ul>\n<li>Added generated Core inventories for CSS custom properties, references, design scales, breakpoints, and utility classes, covering semantic roles, palettes,\neffects properties, component overrides, registered properties, and discoverable runtime values.</li>\n<li>Exported <code>CSS_TOKEN_CATALOG</code>, <code>ICssToken</code>, and category/kind/scope contracts. Metadata distinguishes global, theme, local, and runtime availability and\nrecords declarations and use-site fallbacks; local/runtime discovery does not imply a document-root value or supported override.</li>\n<li>Centralized semantic companion mappings. <code>getComplementaryToken()</code> uses these mappings and the existing palette rule; <code>resolveTokenToCssVar()</code> returns\n<code>CssVariableReference</code>. Palette guards validate supported palettes and shades.</li>\n<li>Centralized theme IDs, labels, brand/accent assignments, and preview ordering in the Sass <code>$theme-palettes</code> registry; generated <code>THEME_PALETTES</code>,\n<code>THEME_PALETTE_IDS</code>, and <code>BxThemeId</code> derive from it.</li>\n<li>Added <code>make-palette-theme(id, dark?, overrides?)</code> while preserving existing palette IDs, labels, classes, and preview colors.</li>\n</ul>\n<h2>Shared primitive customization</h2>\n<ul>\n<li>Added <code>SearchInput.compact</code>, default false, for compact unlabeled search controls. Supplying a label automatically enables compact mode; existing search,\nloading, readonly, and accessibility behavior remains available.</li>\n<li>Fixed surface highlights changing when context menus open. Lighting visibility ignores fully transparent dismissal backdrops while retaining occlusion from\nvisible panels and opaque backdrops. Menu rows keep themed hover/pressed fills and focus without casting near-white light behind the panel.</li>\n<li>Added <code>false</code> support to <code>BxSurfaceDirective.bxSurfaceEmission</code> and runtime <code>ISurfaceOptions.emission</code>. Automatic emission can be disabled independently of\npress feedback and received lighting; an explicit focus-emission color still enables focus-only emission. Mounted hover state reacts to changes.</li>\n<li>Made inherited overlay lighting directional, preserving overlay boundaries for semantic, explicit, reflected, and ambient sources. Exposure checks use\nprojected receiving locations and perimeter-based edge falloff.</li>\n<li>Fixed number-only Tag proportions while preserving configurable horizontal padding and minimum diameter.</li>\n<li>Added <code>Collapsible.titleTemplate</code>, <code>Collapsible.trailingTemplate</code>, and exported <code>ICollapsibleTitleContext</code> for translated, noninteractive heading content and\nstatus while retaining shared disclosure/focus behavior and RTL support.</li>\n<li>Added <code>Card.surfaceEffects</code>, default true, allowing dense collections to disable decorative controllers while preserving themed styling, slots, and\ninteraction.</li>\n</ul>\n<h2>Overlay positioning</h2>\n<ul>\n<li>Fixed selection-panel drift when a trigger inside a native top-layer popover moves in a nested scroller. Top-layer overlays use synchronous measured CDK\npositioning; ordinary overlays retain native CSS anchoring where supported.</li>\n<li>Preserved origin tracking cleanup, resize handling, visibility callbacks, and explicit <code>reposition()</code> in both positioning paths.</li>\n<li>Release Select and Multiselect overlays after completed closes so reopening resolves the current ordinary/top-layer context. Values and search terms remain on\nthe control; reopening during exit reverses the existing transition.</li>\n</ul>\n<h2>Breaking changes and migration</h2>\n<ul>\n<li><p><code>InfiniteScrollDirective</code> now belongs to <code>@filip.mazev/blocks/primitives</code>. Update imports from the earlier Core location; no deprecated Core alias is\nretained. Geometry and scroll-container helpers remain in Core as shared non-presentational utilities.</p>\n</li>\n<li><p>Replace <code>withNav(...)</code> with <code>withInAppNavigation(...)</code> in imports and navigation configuration.</p>\n</li>\n<li><p>Remove side-navigation submenu settings and <code>isInlineSubmenus()</code> calls; nested inline navigation is now the only presentation.</p>\n</li>\n<li><p><code>isDesktop()</code> begins at <code>xl</code> (1280 px). Use <code>isAtLeast(&#39;lg&#39;)</code> or <code>isSmallLaptop()</code> when the previous desktop threshold is needed. <code>isMobile()</code> and\n<code>isTablet()</code> boundaries remain unchanged.</p>\n</li>\n<li><p><code>_dimensions</code> is private. Read the service&#39;s readonly <code>dimensions()</code> signal instead of setting it directly. Review expensive resize computations because\nupdates now occur per animation frame.</p>\n</li>\n<li><p><code>meta-brand-palette</code> and <code>meta-accent-palette</code> are Sass metadata and are excluded from <code>Color</code> and <code>SEMANTIC_COLOR_TOKENS</code>. Use <code>ThemingService.palette()</code> for\npalette metadata and <code>primary</code>/<code>accent</code> for themed colors. Filter <code>CSS_TOKEN_CATALOG</code> by scope when globally available values are required.</p>\n</li>\n<li><p>Icon numeric contracts are broader; consumers enumerating <code>IconSize</code> or <code>number</code> as exhaustive unions should use their own preset arrays. Existing rendered\npresets and defaults remain supported. No Select, Multiselect, load-more, or Modal public API was removed by the scroll/panel additions.</p>\n</li>\n</ul>\n<h2>Documentation, tooling, and source organization</h2>\n<ul>\n<li>Colocated library guides with their owning entry points, components, and directives. Standardized guide sections, public imports, examples, Markdown\nformatting, and documentation generation. Added a strict <code>lint:docs</code> gate.</li>\n<li>Added <code>release.config.json</code> with optional <code>nextVersion</code> and shared package-version resolution. Unassigned targets increment the configured channel&#39;s patch;\nexplicit version overrides and publication retry remain supported. Registry request failure is not treated as proof of non-publication.</li>\n<li>Applied entry-point category folders for types, interfaces, constants, helpers, services, classes, enums, and tokens, including secondary entry points. Moved\ngenerated Lucide definitions under <code>icons/constants/lucide</code> with contracts in <code>icons/types</code> and updated generation/import paths.</li>\n<li>Enforced full lower-camel injected class names, direct injected-member projection names, declaration organization, colocated guides, and descriptive public\nJSDoc with parameter/type-parameter coverage.</li>\n<li>Replaced theme-type synchronization with <code>tools:generate-tokens</code>, retaining its previous script alias. Token generation evaluates Sass maps and uses the\nTypeScript AST, with generated-source banners, formatting, strict generation rules, and unchanged-output detection.</li>\n</ul>\n<p>Stable NPM installs continue using the <code>latest</code> tag; Alpha and Beta remain opt-in.</p>\n',
  'documentation/releases/1.5.4-alpha/README.md':
    '<h1>Blocks 1.5.4-alpha draft change notes</h1>\n<p>Draft for the next Alpha publication of <code>@filip.mazev/blocks</code>. This version has not been published; these notes may change before release.</p>\n<h2>Side navigation</h2>\n<ul>\n<li>Fixed missing label tooltips on compact submenu buttons. Parent icons now use the same shared hover, keyboard-focus, positioning, and theme behavior as\ncompact route links.</li>\n<li>Stabilized expanded content at its final width while the panel opens, preventing labels from repeatedly wrapping into narrow columns during the transition.</li>\n<li>Labels, search, and disclosure arrows fade in during the final <code>60ms</code> of the width transition. The delay uses the running transition&#39;s remaining time,\navoiding an additional wait after rendering. Initial expanded rendering and mobile drawers have no additional reveal delay.</li>\n<li>Added <code>--bx-side-nav-label-duration</code>, defaulting to <code>90ms</code>, to customize the fade duration. Existing <code>--bx-side-nav-duration</code> and <code>--bx-side-nav-easing</code>\ncontinue to configure the width transition.</li>\n</ul>\n<h2>Accessibility and lifecycle</h2>\n<ul>\n<li><p>Reduced-transparency tab triggers no longer cover the active selection surface. Stepper highlights retain a soft opaque tint instead of becoming solid accent\nblocks. Buttons expose persistent selected contours (text buttons use an underline), and selected cards default to the semantic brand border.</p>\n</li>\n<li><p>Local <code>opaque: false</code> and surface <code>reducedTransparency: false</code> now defer to active application or OS accessibility preferences. Remove the owning preference\nto restore translucency; local options can still request opacity. Custom alpha-based materials can provide <code>--bx-glass-opaque-surface</code> for an opaque tint.</p>\n</li>\n<li><p>Surface positioning now defaults through CSS instead of an inline runtime override, preserving absolutely positioned selection indicators when component\nstyles arrive after surface initialization.</p>\n</li>\n<li><p>Reduced motion removes the width animation, reveal delay, and fade. Changing the preference while the rail opens reveals content immediately.</p>\n</li>\n<li><p>Keyboard focus reveals content immediately. Accessible control names remain available while labels are visually fading; icons and focus indicators remain\nindependent of the text fade.</p>\n</li>\n<li><p>Pending reveal work is cancelled when the rail collapses, its presentation changes, or the component is destroyed. Browser measurements run after rendering\nand are skipped during server rendering.</p>\n</li>\n</ul>\n<h2>Compatibility and customization</h2>\n<p>Existing navigation inputs, outputs, routes, and persistence contracts remain unchanged. Applications using the default templates receive the fixes directly.</p>\n<p>Custom item, header, and footer templates can apply the shared reveal to their text using <code>opacity: var(--bx-side-nav-label-opacity, 1)</code> and an opacity\ntransition with <code>var(--bx-side-nav-label-transition-duration, 0ms)</code>. Keep icons and focus indicators outside the faded text. The inherited values follow the\nnavigation&#39;s reduced-motion and keyboard-focus behavior.</p>\n<h2>Reactive modal and toast configuration</h2>\n<ul>\n<li>Added strongly typed <code>ModalRef.patch(IModalPatch)</code> and <code>ToastRef.patch(IToastPatch&lt;D&gt;)</code>, backed by one reactive configuration source per reference. Callers\nand mounted content can update supported properties without recreating the overlay, restarting its entrance animation, or resetting application content state.</li>\n<li>Modal patches merge heading, icon, dismissal policies, close-action visibility, and supported wrapper/content presentation. Undefined retains existing values;\nsupported null values clear optional content or presentation. Layout, identity, mounting, initialization data, and lifecycle callbacks remain opening-time\nconfiguration.</li>\n<li>Added optional header and simple-toast icon loading, plus translatable accessible loading labels. The shared spinner temporarily replaces the retained icon,\npreserves its area, and respects reduced motion. Simple toasts now support configurable icons alongside their existing semantic type, title, and message.</li>\n<li>Toast patches shallow-merge plain-object content data and replace arrays, primitives, and nonplain objects. Translation, semantic surfaces, and derived\npresentation react to updates. Data nullability follows the application contract; simple-toast title and icon accept null to clear them.</li>\n<li>Explicit duration patches reset toast lifetime and progress, including repeated equal durations and duration zero for manual dismissal. Unrelated patches\nretain remaining time, paused toasts remain paused, and restoring a hidden progress indicator uses the current remaining fraction.</li>\n<li>Queued notifications receive patches before display without promotion or a running lifetime. Closing queued references cancels them without display. Closing\nand destroyed overlays ignore late patches; timers, subscriptions, progress controllers, and dismissal callbacks are cleaned up.</li>\n<li>Fixed modal close-action visibility to honor disabled dismissal and show-close-button settings consistently. Mounted modal motion responds to shared\naccessibility preferences; requested animation preferences are retained so reduced-motion changes can be applied reactively.</li>\n<li>Serialized toast queue processing to prevent reentrant content construction or initialization from exceeding capacity or changing queue order. Rechecked the\ncurrent capacity and pause policy before each notification is mounted; configuration, progress, and lifetime remain instance-owned.</li>\n<li>Restricted Escape dismissal to the top registered modal, preventing background dialogs from closing or opening extra confirmations. Deduplicated pending close\nguards per dialog while retaining force-close behavior.</li>\n<li>Registered parent dialogs before constructing content so synchronously opened children retain correct stacking and depth. Failed content initialization\nreleases the affected dialog, and bottom-sheet views remain mounted through their close animation.</li>\n</ul>\n<h2>Reactive API migration</h2>\n<ul>\n<li>Replace <code>ModalRef.modalConfig</code> with <code>ModalRef.config()</code>. <code>ModalCore.config</code> and <code>ToastCore.config</code> are now signals; <code>ToastRef.config</code> is read with <code>config()</code>.\nUse patch methods rather than mutating configuration snapshots. References are service-created; their construction/attachment lifecycle has changed.</li>\n<li><code>Toast&lt;D, R&gt;.data</code> and the <code>IToast</code> data contract are now <code>Signal&lt;D | undefined&gt;</code>. Read <code>data()?.message</code> in templates or <code>this.data()?.message</code> in\nTypeScript. Custom toast implementations must expose reactive data and a read-only reference. <code>TOAST_DATA</code> remains an initialization snapshot; migrate to\n<code>ToastRef.data</code> for live updates. Modal initialization data is unchanged.</li>\n<li>Removed the unused <code>ModalRef.modalContainer</code> and <code>parentElement</code> properties. Mounted content/container getters are undefined after destruction. The toast host\nno longer replaces the reference&#39;s close method at runtime; service-created content can inject its typed reference directly.</li>\n</ul>\n<h2>Stepper</h2>\n<ul>\n<li>Added standalone <code>Stepper</code> (<code>bx-stepper</code>), declarative <code>Step</code> (<code>bx-step</code>), and content/label template directives to <code>@filip.mazev/blocks/navigation</code>. The same\ncomponent supports passive progress indicators, application-owned section navigation, and guarded wizard workflows.</li>\n<li>Supports typed data-driven definitions or projected steps, stable-ID <code>activeStep</code> binding, optional and disabled steps, explicit completion/skipping,\nnon-editable completed steps, and separate loading/error state. Visiting a step does not imply completion.</li>\n<li>Added <code>goTo</code>, <code>next</code>, <code>previous</code>, <code>skip</code>, <code>finish</code>, and <code>reset</code>, with typed request, selection, transition, and completion events. Synchronous, promise, and\nobservable guards share validation, duplicate-request protection, cancellation, and stale-result checks. Failed saves retain the current selection and content\nfor an explicit retry.</li>\n<li>Integrates with Reactive Forms and Signal Forms through a structural validation contract. Linear workflows enforce required predecessors, invalid forward\nattempts mark controls touched, optional steps can be skipped, and completion remains distinct from visiting the final step.</li>\n<li>Supports internal selection and application-confirmed wizard selection. Accepted controlled destinations show a clock marker, accent text, and translatable\n“Awaiting confirmation” feedback while the current step remains selected. Confirmation, reset, and superseding requests clear the waiting presentation.</li>\n<li>Added eager, retained, and active-only content policies, configurable wizard controls, custom label/content templates, and an application-owned completion\nview. Reset clears workflow progress without clearing application-owned form values.</li>\n<li>Added steps, segments, dots, progress, and cards in three sizes, horizontal/vertical layouts, and scroll, vertical, or compact responsive behavior. Connectors\nare solid and continuous between marker bounds and update on layout changes; small markers and dots leave room around status symbols. Card text uses the same\ntop alignment as alerts and banners. Horizontal scrollbars have a reserved strip below the steps, keeping mobile WebKit overlay scrollbars clear of glass card\nsurfaces and focus indicators.</li>\n<li>Supports percentage progress and <code>progressFormat=&quot;fraction&quot;</code> for completed/enabled step counts such as <code>1/3</code>. The <code>showPercentage</code> input controls visibility\nfor both formats; explicit <code>progressValue</code> overrides only the percentage and progress bar.</li>\n<li>Uses Blocks semantic colors, shared glass and lighting, translation support, and configurable CSS variables. Non-card variants keep transparent selected\nbackgrounds with marker/label hover feedback. Disabled steps are visibly muted; read-only presentation retains focus and progress with neutral markers.</li>\n<li>Includes roving keyboard navigation, RTL support, accessible status descriptions, predictable wizard focus, and shared reduced-motion/transparency and\nforced-color behavior. Shared text defaults are configurable through <code>BX_STEPPER_DEFAULTS</code> and per-instance labels.</li>\n<li>Added the <code>/components/stepper</code> playground with appearance controls, section navigation, form validation, asynchronous save failure/retry, controlled\nconfirmation and dynamic steps. Colocated guides and browser regression coverage document the supported integration patterns.</li>\n</ul>\n<p>See the <a href="components/stepper">Stepper guide</a> for public imports, runnable examples, configuration, and\naccessibility.</p>\n<h2>Material and motion refinement</h2>\n<ul>\n<li>Stepper markers and connectors now receive the existing engine&#39;s directional and ambient light independently of their emission. Current filled indicators emit\nmore strongly than tonal completed or neutral inactive indicators; errors receive restrained additional emphasis. Card surfaces retain their backing.</li>\n<li>Rounded stepper highlights use semantic color mixed with the theme surface instead of an enlarged dark hover shadow; the traveling accent has no drop shadow.</li>\n<li>Segment tracks retain a continuous, brighter fill without extra inner geometry. Descendant emission origins paint their registered rim as well as illuminating\nneighbors. Error contours take precedence over cached ambient tint; semantic changes request urgent marker-lighting refresh.</li>\n<li>Circular step indicators use the shared pressure spring for squash and recovery. A persistent selection accent travels between committed markers in both axes\nand stretches modestly along its velocity. Cards use an in-place border/rim response without travel across unconnected cards. Completion fills remain separate\nfrom active navigation. Rejected guards and unconfirmed controlled requests never advance the animated selection.</li>\n<li>Tabs use one persistent lit selection surface with spring position/size interpolation and bounded velocity stretch. Pointer/touch dragging previews the\nsurface continuously and selects the nearest enabled tab on release. Escape, cancellation, outside release and stale gestures restore committed selection. New\n<code>dragSelection</code> defaults to true; false disables selection dragging; native touch swipe scrolling remains available with either setting. Click and keyboard\nselection remain available.</li>\n<li>Added optional <code>bxSurfaceEmissionStrength</code> / runtime <code>emissionStrength</code> (0–2, default 1) without changing reception, pressure feedback, or existing defaults.\nAdded runtime <code>createSpringMotion</code>, <code>ISpringMotion</code>, <code>MOTION_PRESETS</code>, and <code>paintMotionStyles</code>, reusing the exact spring and shared lazy frame clock. Existing\ndesign tokens and theme scales remain intact; no dependency or competing lighting renderer was added.</li>\n<li>Live reduced motion snaps travel/fills and removes deformation. Reduced transparency independently uses existing opaque fallbacks. Native semantics, disabled\nstates, focus outlines, and committed selection remain authoritative. Motion controllers and observers stop on teardown.</li>\n<li>Review <code>/components/stepper</code> and <code>/components/tabs</code>, including rapid selection, variable widths, overflow, dynamic tabs, guards, vertical layouts and the\nindependent accessibility settings in <code>/appearance</code>. The reviewed pilot direction also informs the shared rollout below.</li>\n</ul>\n<h2>Shared motion rollout</h2>\n<ul>\n<li>Recorded the reviewed material and interaction principles in <code>AGENTS.md</code>. Segment steppers retain continuous, brighter fills; cards keep local feedback.</li>\n<li>Sliders and range sliders now use bounded velocity stretch and pressure recovery while preserving immediate native values and pointer precision. Range\ndeformation decreases as thumbs approach. Thumb and fill use the same received-light context; no new lens or palette was introduced.</li>\n<li>Slide toggles retarget the shared checked-position spring, with bounded stretch, existing engine pressure response, stronger checked-state emission and RTL\ntravel. Initial state and live reduced motion snap without entrance movement. Buttons keep labels/icons undistorted and refine material pressure feedback\ninside stationary hit areas.</li>\n<li>Added reusable runtime <code>mountSelectionMotion</code>, <code>ISelectionMotion</code>, and <code>ISelectionMotionOptions</code> for one lit surface behind enabled menu/option rows. Menus,\nselects, multi-selects and autocomplete share pointer/keyboard movement while preserving disabled states, selected values, checkmarks and focus outlines.</li>\n<li>Shared overlay motion now combines retargetable opacity with a restrained 0.985–1 scale, preserving collision-aware positioning transforms. Dropdowns, context\nmenus, tooltips, select panels, autocomplete and popovers reuse the same controller. <code>IGlassTransitionOptions.scale: 1</code> retains opacity-only motion.\nAutocomplete/popover exit makes old panels inert immediately and cancels stale completion on reopening or destruction.</li>\n<li>Centered modals use restrained scale and opacity instead of growing content from zero. Larger side/sheet surfaces use a calmer shared curve; side entrance\nframes clean up on close and destruction. Toasts use smaller travel and restrained settling with their existing coordinated stack collapse.</li>\n<li>Collapsibles/accordions gain interruptible grid-height transitions, immediate inert/accessibility state, and local trigger material feedback. Initial\nrendering and reduced motion remain immediate. Passive tags keep their established shape; their actions and pagination controls inherit button feedback.\nExisting side-navigation width/reveal behavior remains the reference for larger navigation surfaces.</li>\n<li>Existing theme tokens, palette roles, async data ownership, guards, and public selection contracts are retained. Shared CSS curves live in the existing motion\nSass helper; no dependency or parallel lighting system was added. Relevant guides and existing Playground examples document the behavior and review controls.</li>\n</ul>\n<h3>Interaction review refinements</h3>\n<ul>\n<li>Pointer hover on menu/option rows is immediate, with a clearly visible semantic danger backing. Keyboard focus can retain spatial settling; pointer hover\nnever waits for a traveling spring.</li>\n<li>Removed button-label squeezing and offsets. The former <code>--bx-button-press-compression</code> and <code>--bx-button-press-offset</code> effects no longer apply; migrate their\noverrides to supported material settings. Text and icons remain undistorted while the backing/rim responds to pressure.</li>\n<li>Sliders and range sliders enlarge their existing magnifier while held, then spring back to a fully opaque resting thumb. Native values and centers remain\ndirect. Range enlargement respects actual pixel clearance to the neighboring thumb, without measuring layout on each input event. Reduced motion and\nopaque-surface fallbacks remain independent.</li>\n</ul>\n<h3>Tab overflow and disclosure timing</h3>\n<ul>\n<li>Isolated tab-selection deformation in a clipped decorative layer. A separate viewport scrolls the actual tab row, preventing artificial horizontal scrollbar\nchanges during spring travel, including nested code-file tabs in the modal configurator. Genuine overflow, keyboard scrolling and drag edge scrolling remain\navailable.</li>\n<li>Reduced collapsible/accordion height transitions from 220ms to 120ms. <code>--bx-collapsible-duration</code> optionally customizes the duration; live reduced motion\nstill removes the transition immediately.</li>\n</ul>\n<h2>Fluid interaction across the library</h2>\n<ul>\n<li>Restored native horizontal touch scrolling in tabs. A short hold begins selection dragging; release uses bounded recent-velocity projection, with direct\ntracking, preserved spring velocity and continuous edge scrolling. Pausing removes flick momentum.</li>\n<li>Added shared <code>GestureVelocity</code>, <code>projectMotion</code>, <code>ISpringMotion.track</code>, and <code>subscribeFrame</code> APIs to the effects runtime. Gesture previews remain separate\nfrom committed state, guards, native scrolling and precise input values.</li>\n<li>Bottom-sheet handles now support touch, pen and mouse, with predicted release intent and spring recovery. Cancellation, lost capture, blur and Escape during\ndragging restore the sheet without dismissing it; accepted release requests still use the modal close guard.</li>\n<li>Shared surface pressure adapts to the input modality and preserves velocity through repeated presses. Reduced motion removes deformation and all CSS delays.</li>\n<li>Menu and option selection surfaces use a clipped decorative layer so spring overshoot cannot create scrolling. Field, disclosure and panel feedback uses\nshared motion curves. The runtime guide records interaction contracts and Playground review routes across component families.</li>\n</ul>\n',
  'projects/blocks/README.md':
    '<h1>@filip.mazev/blocks</h1>\n<p>Blocks is a modular Angular UI library with shared theming, accessibility, translations, form behavior and overlay infrastructure. Its public entry points ship\nin one package, alongside the installation schematic.</p>\n<p>Use the playground&#39;s generated component catalog for the current API reference and runnable examples. This guide covers installation and application-wide setup.</p>\n<h2>Installation</h2>\n<p>Requires Angular 22 and RxJS 7.8 or later within major 7.</p>\n<p>To install the complete Blocks ecosystem and automatically configure your workspace, run:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="bash code example"><code class="hljs language-bash">ng add @filip.mazev/blocks</code></pre>\n<h2>What does ng add do?</h2>\n<p>When you run the command above, the Angular CLI will execute our custom schematic to handle the boilerplate for you:</p>\n<ul>\n<li>Palette selection: Carbon / Cobalt is the CLI default. Azure / Ember, Violet / Teal, Tangerine / Indigo, Brick Rose / Cyan, Lime / Violet, and Cyberpunk are\nalso available. Use <code>--theme=azure-ember</code> to select Azure / Ember.</li>\n<li>Dependency Management: Automatically adds the latest versions of the Blocks ecosystem to your package.json and runs npm install.</li>\n<li>SCSS Injection: Intelligently locates your project&#39;s global stylesheet (styles.scss or styles.sass) and injects the required @use statements, mixins, and both\nlight/dark mode CSS variables based on your theme selection.</li>\n</ul>\n<h2>Manual Setup (Without Angular CLI)</h2>\n<p>If you prefer not to use <code>ng add</code> or are in an environment that doesn&#39;t support Angular Schematics, you can install the packages manually:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="bash code example"><code class="hljs language-bash">npm install @filip.mazev/blocks@latest</code></pre>\n<p>Then, manually configure your styles.scss:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="scss code example"><code class="hljs language-scss"><span class="hljs-keyword">@use</span> <span class="hljs-string">&#x27;@filip.mazev/blocks&#x27;</span> as *;\n\n<span class="hljs-keyword">@layer</span> base {\n    <span class="hljs-selector-pseudo">:root</span> {\n        <span class="hljs-keyword">@include</span> bx-theme(<span class="hljs-variable">$carbon-cobalt-light-theme</span>);\n    }\n\n    <span class="hljs-selector-attr">[data-theme=<span class="hljs-string">&#x27;dark&#x27;</span>]</span> {\n        <span class="hljs-keyword">@include</span> bx-theme(<span class="hljs-variable">$carbon-cobalt-dark-theme</span>);\n    }\n}</code></pre>\n<h2>Palettes</h2>\n<p>Use paired palette IDs consistently in the CLI and <code>ThemingService.setPalette()</code>. For example:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="sh code example"><code class="hljs language-sh">ng add @filip.mazev/blocks --theme=azure-ember</code></pre>\n<p>The Sass exports use the same names: <code>$azure-ember-light-theme</code> and <code>$azure-ember-dark-theme</code>. Carbon / Cobalt is the installer default; the playground starts\nwith Carbon / Cobalt. Only the current palette IDs and Sass names are supported.</p>\n<p>Buttons and tabs accept <code>color=&quot;accent&quot;</code> for the second tone. Icons and custom components can use semantic tokens such as <code>text-accent</code>, <code>accent-subtle</code>,\n<code>on-accent</code>, and <code>border-accent</code>. Canvas backgrounds stay neutral; status roles keep their meaning. See\n<a href="appearance#palettes">the palette reference</a> for all seven pairs.</p>\n<h2>Appearance</h2>\n<p>Version 1.4.0 integrates glass throughout Blocks using its existing semantic theme. Configure it application-wide through\n<code>ThemingService.setAppearance({ translucency: 0.5 })</code>; use <code>resetAppearance()</code> for defaults. Existing controls receive their material automatically, including\nmenus, dialogs and notifications.</p>\n<p>Load <code>@filip.mazev/blocks/effects/effects.css</code> once globally alongside the Blocks Sass theme. <code>ng add</code> registers the stylesheet for new installations.\n<code>BxSurfaceDirective</code> from <code>@filip.mazev/blocks/effects</code> is available for custom containers and local overrides. The framework-independent engine is\n<code>@filip.mazev/blocks/effects/runtime</code>, included in the same package.</p>\n<p>The source playground provides a dedicated README and working page for every component, with global appearance controls at <code>/appearance</code>.</p>\n',
  'projects/blocks/core/README.md':
    '<h1>Core</h1>\n<p>Shared infrastructure for responsive, accessible, theme-aware Blocks applications: appearance, device and viewport signals, shortcuts, translations, overlay\npositioning, design tokens, and scroll locking.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxA11</span>yService, <span class="hljs-title class_">BxShortcutService</span>, <span class="hljs-title class_">DeviceTypeService</span>, <span class="hljs-title class_">ScrollLockService</span>, <span class="hljs-title class_">ThemingService</span>, <span class="hljs-title class_">WindowDimensionsService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;</code></pre>\n<p>Follow the <a href="installation">package setup</a>. Core is a secondary entry point of <code>@filip.mazev/blocks</code>; the old separate <code>blocks-core</code> package is not required.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ChangeDetectionStrategy</span>, <span class="hljs-title class_">Component</span>, computed, inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span>, <span class="hljs-title class_">WindowDimensionsService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-meta">@Component</span>({\n    <span class="hljs-attr">selector</span>: <span class="hljs-string">&#x27;app-responsive-example&#x27;</span>,\n    <span class="hljs-attr">template</span>: <span class="hljs-string">&#x27;&lt;p&gt;{{ compact() ? &quot;Compact layout&quot; : &quot;Wide layout&quot; }}&lt;/p&gt;&#x27;</span>,\n    <span class="hljs-attr">changeDetection</span>: <span class="hljs-title class_">ChangeDetectionStrategy</span>.<span class="hljs-property">OnPush</span>\n})\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">ResponsiveExample</span> {\n    <span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> windowDimensionsService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">WindowDimensionsService</span>);\n\n    <span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> compact = <span class="hljs-title function_">computed</span>(<span class="hljs-function">() =&gt;</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">windowDimensionsService</span>.<span class="hljs-title function_">isBelow</span>(<span class="hljs-string">&#x27;sm&#x27;</span>));\n\n    <span class="hljs-title function_">constructor</span>(<span class="hljs-params"></span>) {\n        <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>).<span class="hljs-title function_">setApplicationTheme</span>(<span class="hljs-literal">null</span>);\n    }\n}</code></pre>\n<h2>API</h2>\n<h3>Viewport, device, and accessibility</h3>\n<p><code>WindowDimensionsService.dimensions()</code> exposes reactive dimensions and <code>breakpoints</code> shares thresholds with Sass:</p>\n<table>\n<thead>\n<tr>\n<th>Token</th>\n<th>Pixels</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>xs</code></td>\n<td>360</td>\n</tr>\n<tr>\n<td><code>sm</code></td>\n<td>640</td>\n</tr>\n<tr>\n<td><code>md</code></td>\n<td>768</td>\n</tr>\n<tr>\n<td><code>lg</code></td>\n<td>1024</td>\n</tr>\n<tr>\n<td><code>xl</code></td>\n<td>1280</td>\n</tr>\n<tr>\n<td><code>2xl</code></td>\n<td>1536</td>\n</tr>\n<tr>\n<td><code>3xl</code></td>\n<td>1920</td>\n</tr>\n<tr>\n<td><code>4xl</code></td>\n<td>2560</td>\n</tr>\n</tbody></table>\n<p><code>DeviceTypeService.getDeviceState()</code> reports mobile/tablet/desktop, desktop and mobile OS, Apple devices, and orientation. Use capabilities rather than assuming\nthat a device category determines interaction. <code>BxA11yService.isReducedMotion()</code> tracks the shared motion preference.</p>\n<p><code>ThemingService</code> exposes application mode, active theme, palette, and appearance signals. Use <code>setApplicationTheme(&#39;light&#39; | &#39;dark&#39; | null)</code>, <code>setPalette(id)</code>,\nand <code>setAppearance(partial)</code> to update mounted Blocks components and their overlays.</p>\n<h3>Design tokens</h3>\n<p>Browse the <a href="tokens">token catalog</a> at <code>/tokens</code> for semantic colors grouped by role, every palette\nshade and color companion, spacing, corner radii, border colors, shadows, layers, effects, component variables, utility classes, and Sass breakpoints. Search by\nname, role, value, or source; copy CSS references and preview the current toolbar theme. <code>CSS_TOKEN_CATALOG</code> exposes typed discovery metadata with explicit\nglobal/theme/local/runtime availability. <code>CSS_VARIABLES</code> and <code>CSS_VARIABLE_REFERENCES</code> supply typed names and references. Local/runtime values are not\nnecessarily available on the document root; the owning feature guide defines supported customization.</p>\n<p>Theme palette IDs, labels, brand/accent roles, and optional swatch preview order live in <code>$theme-palettes</code> in the Sass theme engine. <code>THEME_PALETTES</code> and\n<code>THEME_PALETTE_IDS</code> are generated from that registry; the public <code>BxThemeId</code> union derives from the generated IDs. Existing theme variables use\n<code>make-palette-theme(id, dark?, overrides?)</code>, preserving their public names and colors.</p>\n<p>All built-in light-mode accent fills use white on-accent text. Their semantic base/hover/active shades move darker where needed to meet 4.5:1 text contrast; raw\npalette anchors and picker swatches remain unchanged. Other on-fill foregrounds prefer white when it passes, with dark text for brighter fills. Semantic\nbrand/accent text and secondary text choose readable palette shades across their normal, hover, active, and neutral surfaces in both modes. Success,\ninformation, warning, and danger retain their original status foreground, border, and interaction-fill shades. Explicit theme overrides and high-contrast\npalettes retain control.</p>\n<p>Sass is the source of truth. <code>npm run tools:generate-tokens</code> evaluates the maps and inventories compiled CSS plus TypeScript property usage; generated constants\npass the repository&#39;s lint/format pipeline. Maintain color/type contracts in ordinary TypeScript. See the catalog guide for generation, availability, and the\nmigration of <code>meta-*</code> Sass metadata out of the color-token union.</p>\n<p>The playground&#39;s <a href="studio">Theme Studio</a> opens from the toolbar on every page. It edits the curated\nshared token contract, previews both modes across pages and overlays, and exports a complete named-base SCSS theme. Runtime appearance remains owned by\n<code>ThemingService</code>; high contrast and forced colors suspend Studio overrides.</p>\n<h3><code>BxShortcutService</code></h3>\n<p>Shares shortcut definitions between menu hints and application-owned keyboard handlers. It resolves OS overrides, normalizes modifier aliases, formats platform\nsymbols, creates accessible key names and matches individual keyboard events.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxShortcutService</span>, <span class="hljs-title class_">ResolvableShortcut</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> bxShortcutService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">BxShortcutService</span>);\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">openShortcut</span>: <span class="hljs-title class_">ResolvableShortcut</span> = [<span class="hljs-string">&#x27;mod&#x27;</span>, <span class="hljs-string">&#x27;shift&#x27;</span>, <span class="hljs-string">&#x27;k&#x27;</span>];\n\n<span class="hljs-comment">// resolve() returns [&#x27;⌘&#x27;, &#x27;⇧&#x27;, &#x27;K&#x27;] on Apple devices or [&#x27;Ctrl&#x27;, &#x27;Shift&#x27;, &#x27;K&#x27;] elsewhere.</span>\n<span class="hljs-comment">// A second platform argument supports previews without changing device detection.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">bxShortcutService</span>.<span class="hljs-title function_">resolve</span>(<span class="hljs-variable language_">this</span>.<span class="hljs-property">openShortcut</span>, <span class="hljs-string">&#x27;mac&#x27;</span>);\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">bxShortcutService</span>.<span class="hljs-title function_">toAriaKeyshortcuts</span>(<span class="hljs-variable language_">this</span>.<span class="hljs-property">openShortcut</span>); <span class="hljs-comment">// Meta+Shift+K or Control+Shift+K</span>\n\n<span class="hljs-comment">// Inside an application-owned keyboard handler:</span>\n<span class="hljs-keyword">if</span> (<span class="hljs-variable language_">this</span>.<span class="hljs-property">bxShortcutService</span>.<span class="hljs-title function_">matches</span>(event, <span class="hljs-variable language_">this</span>.<span class="hljs-property">openShortcut</span>)) {\n  event.<span class="hljs-title function_">preventDefault</span>();\n  <span class="hljs-comment">// Invoke the action, or call menuTrigger.open(true).</span>\n}</code></pre>\n<p><code>mod</code> (also <code>primary</code>, <code>cmdorctrl</code>, <code>commandorcontrol</code>) means Command on macOS/iOS and Ctrl elsewhere. Explicit <code>command</code>/<code>cmd</code>/<code>meta</code>, <code>ctrl</code>/<code>control</code>,\n<code>option</code>/<code>alt</code> and <code>shift</code> map to familiar platform labels, including ⌘ ⌃ ⌥ ⇧ on Apple. Explicit Control stays Control on Apple. Letters are uppercase for\ndisplay; arrows, Enter, Escape, Tab, Backspace, Delete, Space and plus have defaults too. Unrecognized labels remain display tokens.</p>\n<p><code>ResolvableShortcut</code> accepts a string, a readonly token array, or <code>IOSShortcut</code> (<code>OSShortcut</code> remains a compatible alias). An OS object requires <code>default</code> and\naccepts optional <code>mac</code>, <code>windows</code>, <code>linux</code>, <code>ios</code>, <code>android</code> values. iOS/iPadOS falls back to <code>mac</code>, then <code>default</code>; all other absent overrides use <code>default</code>.\nTablet hardware keyboards receive mobile OS mappings. <code>ShortcutPlatform</code> includes those five platforms and <code>default</code>; unknown platforms and SSR use <code>default</code>\nwith Ctrl for <code>mod</code>.</p>\n<p><code>matches(event, definition, options?)</code> requires exactly one ordinary key and the exact modifier state. It ignores handled, composing, AltGraph, repeat and\neditable-target events by default; <code>IShortcutMatchOptions</code> allows <code>platform</code>, <code>allowRepeat</code> and <code>allowInEditable</code> overrides. Matching uses <code>KeyboardEvent.key</code>,\ncase insensitive, with layout-dependent characters. Arrays describe combinations, not sequential gestures; combined strings such as <code>&#39;Ctrl+K&#39;</code> remain custom\nlabels. The service does not register listeners, consume events, manage sequences or resolve shortcut conflicts. Applications own scopes, actions, disabled\nguards and cleanup.</p>\n<p>The <a href="components/menu-item">menu item documentation</a> contains the complete mapping table and a runnable component. Try\n<code>/components/menu-item</code> or <code>/components/menu</code> for combinations and sequences opening menus, platform previews and guarded actions.</p>\n<h3>Scroll locking</h3>\n<p><code>ScrollLockService.disableScroll(usageId, config)</code> acquires a lock and <code>enableScroll(usageId)</code> releases only that owner&#39;s lock. Generate a stable ID with\n<code>uuidv4()</code> for each owner and release it on close, presentation changes, and destruction. The service compensates for scrollbar removal and supports\ntouch/overflow options through <code>IScrollLockConfig</code>. Concurrent modal and navigation locks do not release one another. Repeated acquisition with the same ID\nupdates that owner without adding another lock. Touch/overflow requirements follow the remaining owners; the original inline body styles and priorities are\nrestored only after the final owner releases its lock.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">const</span> scrollLockService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ScrollLockService</span>);\n<span class="hljs-keyword">const</span> destroyRef = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">DestroyRef</span>);\n<span class="hljs-keyword">const</span> lockId = <span class="hljs-title function_">uuidv4</span>();\n\nscrollLockService.<span class="hljs-title function_">disableScroll</span>(lockId, { <span class="hljs-attr">handleTouchInput</span>: <span class="hljs-literal">false</span> });\ndestroyRef.<span class="hljs-title function_">onDestroy</span>(<span class="hljs-function">() =&gt;</span> scrollLockService.<span class="hljs-title function_">enableScroll</span>(lockId));\n<span class="hljs-comment">// Also call scrollLockService.enableScroll(lockId) when the owning overlay closes.</span></code></pre>\n<p>Import <code>DestroyRef</code> and <code>inject</code> from <code>@angular/core</code>, and <code>ScrollLockService</code>/<code>uuidv4</code> from the public core entry point. For a scrollable drawer, leave touch\ninput available inside its panel and contain overscroll at the scroll wrapper.</p>\n<h3>Translation and overlays</h3>\n<p><code>BX_I18N</code> optionally adapts application translation. Configurable text uses <code>ResolvableText</code>; resolve it in <code>computed()</code> with <code>resolveText(text, adapter)</code> so\nadapter version changes update mounted content. Plain strings work without an adapter. Custom integrations can use <code>isTextWithKey()</code> and the adapter&#39;s\n<code>translate()</code>.</p>\n<p>Use <code>BxOverlayPositionService</code>, overlay-origin helpers, and shared theme inheritance when extending an existing overlay. Preserve the owning component&#39;s focus\nand lifecycle behavior instead of positioning or recoloring its private DOM.</p>\n<p><code>trackOverlayOrigin()</code> uses native CSS anchors where supported for ordinary overlays. Top-layer popovers use synchronous measured CDK positioning so nested\nscrolling keeps the panel attached to its trigger. The same returned cleanup callback removes listeners and observers for either path; call its <code>reposition()</code>\nmethod after application-owned layout changes.</p>\n<h3>Scroll boundaries</h3>\n<p>Use <a href="components/infinite-scroll">Primitives InfiniteScrollDirective</a> for guarded end detection and bounded local progressive rendering.\nCore also exports <code>findScrollContainer()</code>, <code>measureScrollBoundary()</code>, <code>observeScrollBoundary()</code>, and <code>IScrollBoundary</code> for reusable viewport discovery and\ndisposable observation. Detection owns no fetching, pagination, buttons, or retry state. Forms&#39; <a href="components/load-more">LoadMoreDirective</a>\nshares these helpers and retains remote request orchestration, loading feedback, fallback actions, and explicit retry.</p>\n<h2>Appearance and customization</h2>\n<p>Load global styles once through the established package entry point. Import reusable Sass definitions through the public helpers entry point:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="scss code example"><code class="hljs language-scss"><span class="hljs-keyword">@use</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core/styles/helpers&#x27;</span> as *;\n\n<span class="hljs-selector-class">.example</span> {\n    <span class="hljs-attribute">padding</span>: <span class="hljs-built_in">spacing</span>(<span class="hljs-number">4</span>);\n    <span class="hljs-attribute">border-radius</span>: <span class="hljs-built_in">radius</span>(md);\n    <span class="hljs-attribute">color</span>: <span class="hljs-built_in">var</span>(--bx-text-primary);\n\n    <span class="hljs-keyword">@include</span> respond-up(md) {\n        <span class="hljs-attribute">padding</span>: <span class="hljs-built_in">spacing</span>(<span class="hljs-number">6</span>);\n    }\n}</code></pre>\n<p>Use shared spacing, radius, elevation, motion, z-index, and responsive helpers. See the\n<a href="appearance">appearance guide</a> for palette pairs, semantic colors, translucency, glassiness, and\napplication-wide rendering configuration.</p>\n<h3>Theme-token audit and customization contract</h3>\n<p>The token audit separates application theme controls from the full CSS implementation inventory. The generated catalog currently contains 743 properties; 90 are\ntheme controls: 65 semantic colors, nine nonzero spacing steps, six ordinary radii, eight shadows, and two border properties. Component hooks remain available\nfor targeted overrides; their presence in the inventory does not make them independent theme settings.</p>\n<table>\n<thead>\n<tr>\n<th>Layer</th>\n<th>Source of truth</th>\n<th>Intended use</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Theme colors</td>\n<td><code>_theme-engine.scss</code>, palette maps and explicit theme overrides</td>\n<td>Background, foreground, interaction and semantic border colors per light/dark mode</td>\n</tr>\n<tr>\n<td>Theme geometry and elevation</td>\n<td><code>_variables.scss</code></td>\n<td>Shared spacing, corner radii, shadows, border width and border style</td>\n</tr>\n<tr>\n<td>Component overrides</td>\n<td>Owning component README</td>\n<td>Optional local exceptions that fall back to shared tokens</td>\n</tr>\n<tr>\n<td>Appearance and optical rendering</td>\n<td>Appearance APIs and Effects guides</td>\n<td>Translucency, lighting, refraction and pressure feedback</td>\n</tr>\n<tr>\n<td>Runtime and layout infrastructure</td>\n<td>Owning runtime or service</td>\n<td>Animation coordinates, measurements, stacking, accessibility state and breakpoints</td>\n</tr>\n</tbody></table>\n<p><code>THEME_CSS_VARIABLES</code> and its <code>ThemeCssVariable</code> union provide the curated application theme contract. <code>ICssToken.themeEditable</code> marks the same set in\n<code>CSS_TOKEN_CATALOG</code>. Named palettes and primary/accent shade aliases remain advanced color inputs. Zero spacing, square corners and pill/circular radii remain\nstructural values outside the curated editor set. No existing CSS property or component override was removed.</p>\n<p>The audit corrected four obstacles to live theming:</p>\n<ul>\n<li><code>spacing()</code>, <code>radius()</code> and <code>shadow()</code> previously baked values into component CSS. They now emit CSS-variable references with the configured Sass value as\nfallback. Corresponding utility classes use exactly the same references.</li>\n<li>Ordinary component borders now use <code>--bx-border-width</code> (default <code>1px</code>) and <code>--bx-border-style</code> (default <code>solid</code>). Existing semantic border colors still choose\nthe contour color. Local divider thickness and explicit line-style inputs take precedence.</li>\n<li>Resting button and generic surface shadows now use <code>--bx-shadow-control</code> and <code>--bx-shadow-surface</code>; both preserve their previous values. Existing elevation,\nmodal and toast shadow names remain intact.</li>\n<li>Catalog discovery now records actual declaring selectors, source paths and separate fallback expressions. A reference or fallback is not a global declaration.\nSource-level inline theme-token edits also update already-open overlays without reacting to every animation-state write.</li>\n</ul>\n<p>Focus rings, selected-state outlines, inset pressure, lighting rims, slider optics and semantic emission are deliberately separate from resting borders and\nshadows. High-contrast surfaces retain solid borders and suppress shadows; forced-color rules remain authoritative. Shapes that are deliberately square,\ncircular or inherited keep those contracts. Custom colors must be checked together with their hover, active and foreground partners; changing <code>primary</code> alone\ndoes not derive the other roles or regenerate palette shades.</p>\n<h3>Applying and exporting overrides</h3>\n<p>The playground Studio previews and exports the same validated custom-property values. A plain CSS block is valid in <code>styles.scss</code>; an additional Sass theme\nformat is not required. Keep the existing global Blocks import and <code>bx-theme(...)</code> setup, then place application overrides after the theme selectors:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="scss code example"><code class="hljs language-scss"><span class="hljs-selector-pseudo">:root</span> {\n    <span class="hljs-attr">--bx-rounded-sm</span>: <span class="hljs-number">0.375rem</span>;\n    <span class="hljs-attr">--bx-rounded-md</span>: <span class="hljs-number">0.75rem</span>;\n    <span class="hljs-attr">--bx-rounded-lg</span>: <span class="hljs-number">1rem</span>;\n    <span class="hljs-attr">--bx-border-width</span>: <span class="hljs-number">1px</span>;\n    <span class="hljs-attr">--bx-border-style</span>: solid;\n    <span class="hljs-attr">--bx-shadow-md</span>: <span class="hljs-number">0</span> <span class="hljs-number">6px</span> <span class="hljs-number">18px</span> <span class="hljs-built_in">rgb</span>(<span class="hljs-number">0</span> <span class="hljs-number">0</span> <span class="hljs-number">0</span> / <span class="hljs-number">14%</span>);\n}\n\n<span class="hljs-selector-pseudo">:root</span><span class="hljs-selector-pseudo">:not</span>([data-theme=&#x27;dark&#x27;])<span class="hljs-selector-pseudo">:not</span>(.high-contrast) {\n    <span class="hljs-attr">--bx-bg-surface</span>: <span class="hljs-number">#f8f9fc</span>;\n    <span class="hljs-attr">--bx-text-primary</span>: <span class="hljs-number">#263044</span>;\n}\n\n<span class="hljs-selector-pseudo">:root</span><span class="hljs-selector-attr">[data-theme=<span class="hljs-string">&#x27;dark&#x27;</span>]</span><span class="hljs-selector-pseudo">:not</span>(.high-contrast) {\n    <span class="hljs-attr">--bx-bg-surface</span>: <span class="hljs-number">#171c28</span>;\n    <span class="hljs-attr">--bx-text-primary</span>: <span class="hljs-number">#e7ebf3</span>;\n}</code></pre>\n<p>Scope an override block to a container to customize only that subtree. The nearest declared token wins through normal CSS inheritance; explicit component inputs\nand local hooks can override shared defaults. Open overlays inherit their source context. Keep application color overrides out of high-contrast selectors. A\npreview should remove its inline overrides when reset or when accessibility mode takes precedence; inline colors otherwise outrank stylesheet themes. Runtime\nupdates to stylesheet rule contents alone do not notify existing overlay observers; preview changes should use a scope&#39;s inline properties or classes.</p>\n<p>Shadow values can be a shadow list or <code>none</code> when used alone. For tokens composed with semantic emission (notably <code>shadow-sm</code> in alerts and <code>shadow-toast</code>), use\n<code>0 0 0 0 transparent</code> to remove resting elevation while retaining a valid composed shadow list. Optical and semantic layers remain separately controlled.</p>\n<h3>Sass compatibility</h3>\n<p>The helper signatures remain source-compatible for CSS declarations. They now return CSS expressions rather than Sass numbers/lists by default. For compile-time\narithmetic or Sass list manipulation, opt into the previous value with <code>$static: true</code>, or access the corresponding public Sass map:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="scss code example"><code class="hljs language-scss"><span class="hljs-keyword">@use</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core/styles/helpers&#x27;</span> as bx;\n\n<span class="hljs-selector-class">.example</span> {\n    <span class="hljs-attribute">padding</span>: bx.<span class="hljs-built_in">spacing</span>(<span class="hljs-number">4</span>);\n    <span class="hljs-attribute">margin-block-end</span>: <span class="hljs-built_in">calc</span>(bx.<span class="hljs-built_in">spacing</span>(<span class="hljs-number">4</span>) * <span class="hljs-number">2</span>);\n    <span class="hljs-attribute">border-radius</span>: bx.<span class="hljs-built_in">radius</span>(lg);\n    <span class="hljs-attribute">box-shadow</span>: bx.<span class="hljs-built_in">shadow</span>(md);\n}\n\n<span class="hljs-variable">$fixed-gap</span>: bx.<span class="hljs-built_in">spacing</span>(<span class="hljs-number">4</span>, <span class="hljs-variable">$static</span>: true) * <span class="hljs-number">2</span>;</code></pre>\n<p>Unknown spacing/radius/shadow keys now fail compilation with a descriptive error instead of silently omitting a declaration. Breakpoint helpers and <code>z()</code> retain\ntheir compile-time behavior. The existing <code>$spacing</code>, <code>$radiuses</code>, <code>$shadows</code> and new <code>$borders</code> maps remain configurable before the global Sass entry point is\nloaded. The catalog describes the default library configuration, not application-specific Sass map overrides.</p>\n<p>The toolbar Studio and <code>/studio</code> preview provide coordinated geometry controls, structured shadows, import/export and session undo/redo. They use the curated\ntheme set with per-mode semantic colors and shared geometry; runtime effect and component properties remain outside the theme document.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use injected shared services and signal derivation for updates under OnPush. Browser measurement and overlay work must wait for rendering and remain safe for\nSSR. Clean up locks, observers, listeners, subscriptions, timers, and asynchronous work with their owning view. Respect reduced motion, reduced transparency,\nforced colors, native semantics, focus visibility, and accessible naming in custom integrations.</p>\n<p>Reduced-motion styling also clears animation and transition delays, so disabling motion never leaves content waiting invisibly. The\n<a href="../effects/runtime/README.md#fluid-interaction-across-blocks">library motion contract</a> describes the shared interaction policy and review routes across Blocks.</p>\n<h2>Playground</h2>\n<p>Open <code>/utilities</code> for the cumulative <a href="utilities">utilities playground guide</a>, including viewport and\ndevice detection, independent scroll-lock owners, UUIDs, color-token helpers, and overlay infrastructure. Open <code>/components</code> for the component catalog,\n<code>/appearance</code> for shared preferences, <code>/components/menu-item</code> for shortcuts, and <code>/components/side-nav</code> or <code>/modal</code> for coordinated overlays.</p>\n',
  'projects/blocks/effects/README.md':
    '<h1>Appearance effects</h1>\n<p>Blocks components use glass through the existing theme system. The <code>BxSurfaceDirective</code> applies the same material to custom containers. Labels, inputs and icon\npaths retain their native rendering; decorative lighting and blur sit behind content.</p>\n<h2>Global configuration</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({\n  <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span>,    <span class="hljs-comment">// 0–1; the midpoint balances clarity and tint</span>\n  <span class="hljs-attr">quality</span>: <span class="hljs-string">&#x27;auto&#x27;</span>,    <span class="hljs-comment">// auto | baseline | enhanced</span>\n  <span class="hljs-attr">glassiness</span>: <span class="hljs-string">&#x27;auto&#x27;</span>, <span class="hljs-comment">// auto | off | on</span>\n  <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">false</span>\n});\n\n<span class="hljs-comment">// Read the current configuration or return to defaults.</span>\n<span class="hljs-keyword">const</span> current = <span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">appearance</span>();\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">resetAppearance</span>();</code></pre>\n<p>Global settings apply throughout the application, including mounted controls and overlays. Color comes from the active Blocks palette and semantic tokens;\nchanging the palette does not require configuring a separate glass color scheme.</p>\n<h2>Custom surfaces</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxSurfaceDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/effects&#x27;</span>;</code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">section</span> <span class="hljs-attr">bxSurface</span> <span class="hljs-attr">class</span>=<span class="hljs-string">&quot;custom-panel&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">h2</span>&gt;</span>Project settings<span class="hljs-tag">&lt;/<span class="hljs-name">h2</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>This surface inherits the global material.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">section</span>&gt;</span></code></pre>\n<p>Provide layout and padding using the existing Blocks styling helpers. The directive supplies the material and token-based default border and radius. Controls\nand actionable surfaces get automatic hover/focus lighting; decorative containers receive nearby light without responding to hover themselves. Containing one\ninput does not turn a panel into an interactive surface. Wrappers inside <code>bx-form-field</code> retain field interaction; custom control wrappers outside a field can\nopt in with <code>bxSurfaceInteractive</code>. Components can override the default border and radius with their existing tokens.</p>\n<table>\n<thead>\n<tr>\n<th>Input</th>\n<th>Default</th>\n<th>Local override</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>bxSurfaceTranslucency</code></td>\n<td>Global translucency</td>\n<td>0–1</td>\n</tr>\n<tr>\n<td><code>bxSurfaceGlassiness</code></td>\n<td>Off unless selected</td>\n<td><code>auto</code>, <code>off</code>, or <code>on</code>; baseline and accessibility settings take precedence</td>\n</tr>\n<tr>\n<td><code>bxSurfaceInteractive</code></td>\n<td>Automatic control/action detection</td>\n<td>Boolean; explicitly enables or disables interaction lighting and press deformation</td>\n</tr>\n<tr>\n<td><code>bxSurfaceEmission</code></td>\n<td>Theme accent (error color in invalid fields)</td>\n<td>CSS color override, or <code>false</code> to disable automatic emission while retaining press feedback</td>\n</tr>\n<tr>\n<td><code>bxSurfaceEmissionOrigin</code></td>\n<td>Entire surface</td>\n<td>Descendant CSS selector for the visible light source; no match falls back to the host</td>\n</tr>\n<tr>\n<td><code>bxSurfaceEmissionStrength</code></td>\n<td><code>1</code></td>\n<td>Local 0–2 emission multiplier; leaves reception and pressure feedback unchanged</td>\n</tr>\n<tr>\n<td><code>bxSurfaceFocusEmission</code></td>\n<td>Fields: surface emission color; actions: keyboard focus only</td>\n<td>Explicitly illuminate for any focus using this color</td>\n</tr>\n<tr>\n<td><code>bxReducedTransparency</code></td>\n<td>Global setting</td>\n<td>Boolean</td>\n</tr>\n</tbody></table>\n<p>Omit local inputs to keep the surface connected to application settings. A deliberate local override continues to take precedence until removed.</p>\n<p>Noninteractive surfaces retain received lighting but do not apply pointer pressure or the refractive active tint.</p>\n<p>Disable automatic emission independently of press feedback and received lighting with <code>[bxSurfaceEmission]=&quot;false&quot;</code>. This also suppresses the default keyboard\nfocus emission. An explicit <code>bxSurfaceFocusEmission</code> can opt the surface back into focus-only emission. Hiding decoration with CSS opacity does not disable a\nsource in the lighting runtime.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">bxSurface</span> [<span class="hljs-attr">surfaceEffects</span>]=<span class="hljs-string">&quot;false&quot;</span> [<span class="hljs-attr">bxSurfaceEmission</span>]=<span class="hljs-string">&quot;false&quot;</span> <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;tonal&quot;</span>&gt;</span>Local interaction feedback<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<p>Here <code>[surfaceEffects]=&quot;false&quot;</code> lets the directive own the button&#39;s material without mounting a second surface. The <code>/components/surface</code> playground includes a\nBlocks checkbox that switches automatic emission on and off.</p>\n<h2>Glassiness and translucency</h2>\n<p>Translucency controls tint and blur from 0 to 1, with a default of 0.5. Its material strength is <code>0.5 × value² + 0.35 × value⁴</code>: zero retains the lightest\nmaterial tint, and the preceding midpoint now falls around 70% while both endpoints stay unchanged. The classic material ranges from 6% to about 72.5% tint;\nactive refraction uses the stronger readability floor described below. Reduce transparency remains the explicit opaque presentation.</p>\n<p>Glassiness is an opt-in enhancement. Ordinary components keep the existing material. Select individual buttons or custom surfaces:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;icon&quot;</span> <span class="hljs-attr">glassiness</span>=<span class="hljs-string">&quot;auto&quot;</span> <span class="hljs-attr">aria-label</span>=<span class="hljs-string">&quot;Bookmark&quot;</span>&gt;</span>…<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">section</span> <span class="hljs-attr">bxSurface</span> <span class="hljs-attr">bxSurfaceGlassiness</span>=<span class="hljs-string">&quot;auto&quot;</span>&gt;</span>…<span class="hljs-tag">&lt;/<span class="hljs-name">section</span>&gt;</span></code></pre>\n<p><code>themingService.setAppearance({ glassiness: &#39;auto&#39; })</code> sets the browser policy for selected elements; it never enables every surface. Automatic works on\nsupported browsers and preserves the existing look elsewhere. <code>off</code> is an application-wide switch. <code>on</code> allows testing SVG backdrop support on another browser\nand bypasses automatic device hints; it cannot add missing rendering support. Enhanced returns to Automatic when Glassiness is Off, and the playground disables\nthat option until glassiness is enabled. Baseline, opaque intent fills, nested-surface guards and accessibility preferences still win. Asymmetric or elliptical\ncorners keep their existing material.</p>\n<p>Automatic rendering uses one SVG backdrop pass per selected element, with the existing Blocks lighting. Enhanced adds the reference&#39;s reflection and bevel\nlayers. A surface can request <code>bxSurfaceQuality=&quot;enhanced&quot;</code>; the global baseline/device policy still applies. The overview&#39;s three feature cards and the toast\nwrappers opt into Enhanced. Toasts are bounded by the existing maximum of four open notifications; applications can choose <code>glassQuality: &#39;auto&#39;</code> or\n<code>glassiness: &#39;off&#39;</code> in toast settings. Hidden receivers suspend filter work, maps are shared by effective geometry, reflections reach at most 64 CSS pixels\nbeyond a surface, and reflection invalidation is rate limited.</p>\n<p>Text, placeholders and icons retain their theme or component foreground colors as content moves underneath. Refraction uses a fixed readability backing instead\nof sampling the backdrop to change text color. At the clearest slider setting its default tint is at least 72%, with 0.5px blur. Blur follows the slider from\n0.5px through about 0.8px at the midpoint to 9.2px at maximum, preserving a sharper refractive appearance at low settings. Increasing translucency adds tint and\nblur; the default midpoint is about 74.9% tint and the maximum about 89%. Active, selected and open-popup controls use at least 90% tint for their semantic\nforegrounds. Component opacity constraints can request a stronger backing. Reduced transparency still supplies the fully opaque presentation.</p>\n<p>Customize <code>--bx-refraction-min-opacity</code> (0.72), <code>--bx-refraction-min-blur</code> (0.5px), or <code>--bx-refraction-blur</code> for application-specific materials. Custom\nbackgrounds and foreground colors should preserve readability. Ambient edge lighting continues to sample the scene without changing text or icon colors.</p>\n<p>Additional surface variables are <code>--bx-refraction-blur</code>, <code>--bx-refraction-saturation</code> (1.15), <code>--bx-refraction-reflection-opacity</code> (1), and the full renderer&#39;s\nedge exposure variables. Existing <code>--bx-glass-blur</code>, <code>--bx-glass-surface</code>, <code>--bx-glass-opacity</code> and radius tokens still apply. CSS supplies the live backdrop;\nTypeScript assembles cached grayscale PNG displacement maps in SVG. The Nordify MIT notice is retained. Standard and WebKit declarations are supplied, with\nstandard CSS for other engines.</p>\n<p>The distributed <code>effects/effects.css</code> path is unchanged. Its source is <code>effects/effects.scss</code>; <code>npm run tools:build-effects</code> regenerates it, and normal build\nscripts run this automatically. Explore the selected controls and slider at <code>/appearance</code>.</p>\n<h3>Migration</h3>\n<p>The former numeric <code>glassiness</code> setting is now <code>translucency</code>. Rename <code>bxSurfaceGlassiness</code> (numeric) to <code>bxSurfaceTranslucency</code>. The scalar CSS property is now\n<code>--bx-translucency</code>. Persisted older preferences migrate automatically; normalized values use the new curve.</p>\n<h2>Composition and motion</h2>\n<p>Use a single backing per physical surface. For example, a menu owns the backing while menu-item content shares it; a form-field label does not need an extra\nblurred card. Apply <code>bxTransition=&quot;fade&quot;</code> on a dropdown to fade its menu without resizing its contents. The fade runs on the material itself, preserving the\nconfigured translucency and blur throughout the animation.</p>\n<p>Buttons, links, native field surfaces and elements with actionable ARIA roles automatically illuminate their border and nearby surfaces on hover, press, or\nkeyboard focus. Editable field surfaces also illuminate for pointer focus; ordinary actions do not stay lit solely because a click left native focus on them.\nChecked, pressed, selected, and current states keep the light enabled. Expanded popup triggers also retain light, while plain layout-disclosure controls do not\nbecome selected just by expanding. Plain panels, sections and other decorative containers remain passive receivers, while their edges pick up subtle color from\nnearby foreground and background content. The runtime samples CSS backgrounds and local pixels from visible images, video and canvas, then uses paint order,\ndepth and distance to shape the edge tint. Give a custom clickable element its appropriate role (such as <code>role=&quot;button&quot;</code>), or explicitly enable\n<code>bxSurfaceInteractive</code> for a custom interaction. Use <code>bxSurfaceEmission</code> to override the semantic color. The source follows the surface geometry, or the\ndescendant selected by <code>bxSurfaceEmissionOrigin</code>, rather than mouse coordinates. For example, <code>bxSurfaceEmissionOrigin=&quot;.status-dot&quot;</code> confines the emitted light\nto a status marker while hover, selection and keyboard focus remain on the whole control. When that descendant also owns a registered surface, its existing\nrenderer paints the emitted rim too. Source teardown or an origin change clears the delegated rim. Unregistered descendants continue to supply bounds while the\nhost paints its own rim.</p>\n<p>Presses use the shared pressure spring for a soft inset sheen. Blocks buttons keep labels and icons undistorted inside a fixed hit area; quick taps still\nreceive visible material feedback. Pointer release/cancellation, keyboard release, focus loss, hidden documents, and teardown clear press state. Touch hover\ndoes not latch. Reduced motion uses static press feedback.</p>\n<p>The surface renderer does not reposition application content; controls own selection and pointer gestures. Spatial highlights are a lightweight lighting\napproximation, while backdrop blur uses browser compositing. These effects do not ray-trace arbitrary DOM content. Rendering quality can add supported\nenhancements, and baseline/solid modes remain available for constrained devices.</p>\n<h2>Accessibility and lifecycle</h2>\n<p><code>BxA11yService</code> controls reduced motion. Reduced transparency, unsupported backdrop filters and forced colors use opaque surfaces. Give controls visible or\naccessible labels independently of the glass decoration.</p>\n<p>The directive initializes only in the browser, runs decorative updates outside Angular and tears down its resources when the host is destroyed. Do not directly\nmount a second engine surface on a host already owned by the directive or a Blocks component.</p>\n<h2>Framework independent engine</h2>\n<p>The stepper and tabs pilot shares <code>createSpringMotion</code>, <code>ISpringMotion</code>, <code>MOTION_PRESETS</code>, and <code>paintMotionStyles</code> from the runtime entry point. These extend\nthe existing exact spring and lazy frame scheduler; they introduce no additional lighting renderer or theme token collection. See the\n<a href="runtime/README.md#retargetable-selection-motion">runtime motion contract</a>. The validated patterns also support slider/toggle feedback, moving menu/option\nhighlights, and restrained overlay motion.</p>\n<p>The <code>@filip.mazev/blocks/effects/runtime</code> entry point included in Blocks exports the native DOM surface and transition APIs. Refer to its README for non-Angular\nuse. The native runtime does not import Angular.</p>\n<h2>Playground</h2>\n<p>Use <code>/appearance</code> to configure the entire application and <code>/components/surface</code> to inspect a custom surface.</p>\n<p>Inputs, searches, selects, checkboxes, radio buttons and switches inherit automatic interaction lighting. Invalid fields use the error color. Projected native\ncontrols wrapped in <code>bxSurface</code> inside <code>bx-form-field</code> receive the same field material, focus outline and invalid glow as packaged inputs. All emitters respect\noverlay boundaries and occlusion; light does not pass through a modal into the page or another dialog.</p>\n',
  'projects/blocks/effects/directives/surface/README.md':
    '<h1>Custom appearance surfaces</h1>\n<p>Apply Blocks&#39; shared decorative material to a custom container while preserving its native content and semantics.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxSurfaceDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/effects&#x27;</span>;</code></pre>\n<p>Add the directive to the consuming standalone component&#39;s imports.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">section</span> <span class="hljs-attr">bxSurface</span> [<span class="hljs-attr">bxSurfaceTranslucency</span>]=<span class="hljs-string">&quot;0.5&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">h2</span>&gt;</span>Project settings<span class="hljs-tag">&lt;/<span class="hljs-name">h2</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>This panel inherits the active theme.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">section</span>&gt;</span></code></pre>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Input</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>bxSurfaceTranslucency</code></td>\n<td>Optional local translucency on the shared 0–1 scale.</td>\n</tr>\n<tr>\n<td><code>bxSurfaceGlassiness</code></td>\n<td>Optional <code>auto</code>, <code>off</code>, or <code>on</code> refraction policy.</td>\n</tr>\n<tr>\n<td><code>bxSurfaceQuality</code></td>\n<td>Optional <code>auto</code>, <code>baseline</code>, or <code>enhanced</code> detail policy.</td>\n</tr>\n<tr>\n<td><code>bxSurfaceInteractive</code></td>\n<td>Optional override of automatic interaction feedback.</td>\n</tr>\n<tr>\n<td><code>bxSurfaceEmission</code></td>\n<td>Optional CSS color emitted toward nearby surfaces during interaction.</td>\n</tr>\n<tr>\n<td><code>bxSurfaceFocusEmission</code></td>\n<td>Optional CSS color emitted while a contained control has focus.</td>\n</tr>\n<tr>\n<td><code>bxReducedTransparency</code></td>\n<td>Optional opaque-material request; false cannot override application or OS reduced transparency.</td>\n</tr>\n</tbody></table>\n<p>Omitted inputs inherit application/runtime policy. Export the directive as <code>bxSurface</code> when a template reference is needed.</p>\n<h2>Appearance and customization</h2>\n<p>Use shared semantic tokens and layout helpers for spacing, border, and radius. The <a href="components/surface">effects guide</a> describes material variables, global\nconfiguration, browser policy, and refraction limits.</p>\n<h2>Behavior and accessibility</h2>\n<p>The directive mounts after browser rendering, updates when inputs or reduced-motion preferences change, and releases its controller on destruction. Decorative\nfeedback does not replace focus indicators or native control semantics. Global accessibility and rendering limits take precedence over requested effects.</p>\n<h2>Playground</h2>\n<p>Visit <code>/appearance</code> to configure and compare shared materials.</p>\n',
  'projects/blocks/effects/runtime/README.md':
    '<h1>Blocks effects runtime</h1>\n<p>Framework independent glass surfaces, spatial lighting and overlay fades. Native DOM content keeps its layout, semantics and text rendering. This entry point\nimports no Angular code; it is bundled inside Blocks alongside the Angular adapter and application-wide theme controls.</p>\n<h2>Install and use</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="sh code example"><code class="hljs language-sh">npm install @filip.mazev/blocks</code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/effects/effects.css&#x27;</span>;\n<span class="hljs-keyword">import</span> { configureAppearance, mountSurface, createGlassTransition } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/effects/runtime&#x27;</span>;\n\n<span class="hljs-keyword">const</span> config = <span class="hljs-title function_">configureAppearance</span>(<span class="hljs-variable language_">document</span>.<span class="hljs-property">documentElement</span>, {\n    <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span>,\n    <span class="hljs-attr">quality</span>: <span class="hljs-string">&#x27;auto&#x27;</span>\n});\n<span class="hljs-keyword">const</span> buttonSkin = <span class="hljs-title function_">mountSurface</span>(button);\n<span class="hljs-keyword">const</span> panelSkin = <span class="hljs-title function_">mountSurface</span>(panel);\n\n<span class="hljs-comment">// The application or overlay library positions the panel before this call.</span>\n<span class="hljs-keyword">const</span> transition = <span class="hljs-title function_">createGlassTransition</span>(button, panel);\n<span class="hljs-keyword">await</span> transition.<span class="hljs-title function_">enter</span>();\nconfig.<span class="hljs-title function_">update</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.45</span> }); <span class="hljs-comment">// All existing surfaces and body-mounted overlays update.</span>\n<span class="hljs-keyword">const</span> result = <span class="hljs-keyword">await</span> transition.<span class="hljs-title function_">exit</span>();\n<span class="hljs-keyword">if</span> (result === <span class="hljs-string">&#x27;finished&#x27;</span>) panel.<span class="hljs-property">hidden</span> = <span class="hljs-literal">true</span>;\n\n<span class="hljs-comment">// At component/application teardown:</span>\ntransition.<span class="hljs-title function_">destroy</span>();\nbuttonSkin.<span class="hljs-title function_">destroy</span>();\npanelSkin.<span class="hljs-title function_">destroy</span>();\nconfig.<span class="hljs-title function_">destroy</span>();</code></pre>\n<p><code>configureAppearance</code> owns one root scope, merges updates, and restores the attributes and inline properties it owned on destroy. Mount it on\n<code>document.documentElement</code> to include overlays. Per-surface options override the global configuration; omitted options inherit it. There must be only one\nconfiguration controller per root and one surface controller per element. <code>surface.update(options)</code> replaces that surface&#39;s local options so <code>{}</code> returns it to\nglobal settings. Noninteractive surfaces receive environmental light without pointer pressure or the refractive active tint. Their resolved interaction state is\nrestored with other owned attributes on teardown.</p>\n<p>Setting application <code>quality: &#39;baseline&#39;</code> temporarily sets <code>glassiness: &#39;off&#39;</code>, including during initialization and partial updates. Switching back to\n<code>quality: &#39;auto&#39;</code> or <code>&#39;enhanced&#39;</code> restores the requested glassiness policy. An explicit <code>glassiness</code> update replaces that preference, including while baseline\nis selected. A previously requested <code>&#39;off&#39;</code> remains off and continues to prevent Enhanced rendering.</p>\n<h2>Global material and theme contract</h2>\n<p>Per-surface <code>emissionOrigin</code> optionally names a descendant selector for the visible light source. <code>emissionStrength</code> is a local 0–2 multiplier, defaulting to\nthe historical strength of 1. It affects the emitted rim and neighboring illumination while leaving environmental reception and pressure feedback unchanged.\nThese local settings are not application-wide appearance configuration. Existing callers need no migration. Registered descendant origins also paint the emitted\nrim through their existing surface controller; unregistered origins supply bounds and retain host rim painting. <code>refreshGlassLighting(element, true)</code> urgently\nresamples and snaps environmental colors for committed semantic changes; the omitted second argument preserves smooth lighting updates.</p>\n<p>The renderer defines no brand palette or spacing system. It uses the existing Blocks semantic tokens and preserves each component&#39;s border radius, size and\nlayout. Load the glass CSS once after your theme CSS, and set border radius on your native element when using the package outside Blocks.</p>\n<p>Live radius and border-width token changes refresh both refraction renderers, even when the surface dimensions stay fixed. Optical maps retain their caches\nuntil geometry changes; border-only changes update layer insets. Theme controls use Core&#39;s\n<a href="components#theme-token-audit-and-customization-contract">curated token contract</a>; optical and animation properties remain advanced runtime state.</p>\n<p><code>mountSurface(element)</code> includes a default token-based border. Buttons, links, native field surfaces and actionable ARIA roles automatically illuminate their\nborder and nearby surfaces on interaction or an active ARIA state. Decorative containers receive nearby light without their own hover effect, even when they\ncontain a single input such as a slider. Only wrappers within <code>bx-form-field</code> infer interactivity from their input; other custom wrappers can opt in with\n<code>interactive: true</code>. The default color is the theme accent, or the error color inside an invalid Blocks form field. Override <code>emission</code>/<code>focusEmission</code> for a\ndifferent semantic color; <code>interactive</code> explicitly overrides automatic control/action detection.</p>\n<table>\n<thead>\n<tr>\n<th>Setting</th>\n<th>Values</th>\n<th>Inherited CSS property</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>translucency</code></td>\n<td>0–1, default 0.5</td>\n<td><code>--bx-translucency</code></td>\n</tr>\n<tr>\n<td><code>quality</code></td>\n<td><code>auto</code>, <code>baseline</code>, <code>enhanced</code></td>\n<td>root <code>data-bx-glass-quality</code></td>\n</tr>\n<tr>\n<td><code>glassiness</code></td>\n<td><code>auto</code> (default), <code>off</code>, <code>on</code></td>\n<td>root <code>data-bx-glassiness-mode</code>; only explicitly selected surfaces participate</td>\n</tr>\n<tr>\n<td><code>reducedTransparency</code></td>\n<td>boolean</td>\n<td>root <code>data-bx-reduced-transparency</code></td>\n</tr>\n<tr>\n<td><code>reducedMotion</code></td>\n<td>boolean</td>\n<td>root <code>data-bx-reduced-motion</code></td>\n</tr>\n</tbody></table>\n<p>Translucency controls tint and blur together. Material strength is <code>m = 0.5 × translucency² + 0.35 × translucency⁴</code>. Tint is <code>0.06 + 1.02m − 0.28m²</code>,\nexisting-material blur is <code>4 + 24m²</code> px, and glassiness blur is <code>0.5 + 12m²</code> px. The default translucency is 0.5; the preceding midpoint falls around 70% on\nthis scale. Both endpoints stay unchanged, and maximum classic tint is about 72.5%. Reduced transparency provides opaque surfaces without losing that\npreference.</p>\n<p>Opt in per element with <code>mountSurface(element, { glassiness: &#39;auto&#39; })</code>. Omitted surfaces keep their existing material.\n<code>configureAppearance(root, { glassiness: &#39;auto&#39; })</code> is a browser policy for selected surfaces, not a global opt-in. Automatic uses one refraction pass on\nsupported browsers; unsupported engines keep the previous look. <code>on</code> permits testing another engine, while <code>off</code> disables selected enhancements. Local\n<code>quality: &#39;enhanced&#39;</code> adds the full reflection/bevel treatment, subject to application baseline and device policy.</p>\n<p>Foreground colors stay theme-owned. Refraction retains at least 72% tint for readable theme foregrounds. Blur ranges from 0.5px at the clearest setting to about\n0.8px at the midpoint and 9.2px at maximum; low settings preserve sharper refraction while the tint supplies the backing. Component opacity constraints can\nrequest more backing. No text-contrast sampling, foreground switching, grouping or per-control contrast subscriptions are mounted. The existing shared sampler\ncontinues to supply decorative ambient edge lighting. See <a href="components/surface#glassiness-and-translucency">appearance effects</a> for material variables and\nbrowser/accessibility fallbacks.</p>\n<p>Local color aliases preserve component intent:</p>\n<table>\n<thead>\n<tr>\n<th>Glass alias</th>\n<th>Blocks fallback</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--bx-glass-surface</code></td>\n<td><code>--bx-bg-surface</code></td>\n</tr>\n<tr>\n<td><code>--bx-glass-opaque-surface</code></td>\n<td>local <code>--bx-glass-surface</code></td>\n</tr>\n<tr>\n<td><code>--bx-glass-text</code></td>\n<td><code>--bx-text-primary</code></td>\n</tr>\n<tr>\n<td><code>--bx-glass-edge</code></td>\n<td><code>--bx-border-subtle</code></td>\n</tr>\n<tr>\n<td><code>--bx-glass-accent</code></td>\n<td><code>--bx-primary</code></td>\n</tr>\n</tbody></table>\n<p>For example, a success toast can set <code>--bx-glass-surface: var(--bx-bg-success)</code> and retain its established semantic appearance. Outside Blocks, system colors\nsupply neutral fallbacks.</p>\n<p>Use opaque semantic colors for <code>--bx-glass-surface</code> and let the material opacity control translucency. When a custom surface color contains alpha, supply an\nopaque <code>--bx-glass-opaque-surface</code> on that element. The override also applies to increased contrast and unsupported backdrop filtering; it resolves locally on\neach surface, so nested controls retain their own colors. For example, an accent wash can use\n<code>--bx-glass-opaque-surface: color-mix(in srgb, var(--bx-accent) 22%, var(--bx-bg-surface))</code> to retain a soft tint without transparency.</p>\n<p>Composite controls keep their opaque backing separate from their hit targets. Tabs paint the header and traveling selected surface, while the foreground\ntriggers remain unpainted so they cannot cover the highlight. Reduced transparency does not disable selection motion, direct manipulation, or lighting.</p>\n<p>Reduced-transparency state review covers these shared patterns:</p>\n<table>\n<thead>\n<tr>\n<th>Family</th>\n<th>Opaque state feedback</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Tabs and connected steppers</td>\n<td>Separate selection backing; opaque tint stays distinct from the header and solid current marker.</td>\n</tr>\n<tr>\n<td>Buttons, cards and chips</td>\n<td>Persistent selection contour; text buttons retain an underline.</td>\n</tr>\n<tr>\n<td>Menus, select/autocomplete options and navigation</td>\n<td>Solid semantic hover/active colors on an opaque container; selected options retain their selection indicators.</td>\n</tr>\n<tr>\n<td>Checkbox, radio and switch controls</td>\n<td>Opaque checked fill with a check, dot or thumb position.</td>\n</tr>\n<tr>\n<td>Sliders and progress</td>\n<td>Opaque thumb or filled track; value and progress geometry remain available.</td>\n</tr>\n<tr>\n<td>Alerts, tags, dialogs and toasts</td>\n<td>Opaque semantic/content surfaces; borders, icons and text preserve meaning independently of decorative light.</td>\n</tr>\n</tbody></table>\n<p>Transparent foreground hit targets, hover washes and lighting over an opaque parent are intentional composition, not translucent windows into page content. When\ncustomizing a state color with alpha, define its opaque counterpart and check selected, hovered, focused, disabled and readonly states in both themes.</p>\n<h2>Spatial lighting and reflections</h2>\n<p><code>getGlassLightRoot(element)</code> resolves the existing overlay or <code>data-bx-light-scope</code> boundary for passive emitters. Angular integrations can register and update\ntheir emitters through <code>BxGlassLightingService</code>.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { mountGlassScene } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/effects/runtime&#x27;</span>;\n\n<span class="hljs-keyword">const</span> scene = <span class="hljs-title function_">mountGlassScene</span>(<span class="hljs-variable language_">document</span>.<span class="hljs-property">documentElement</span>, {\n    <span class="hljs-attr">lights</span>: [{ <span class="hljs-attr">element</span>: lamp, <span class="hljs-attr">z</span>: <span class="hljs-number">180</span>, <span class="hljs-attr">color</span>: <span class="hljs-string">&#x27;var(--bx-primary)&#x27;</span>, <span class="hljs-attr">intensity</span>: <span class="hljs-number">1.2</span>, <span class="hljs-attr">radius</span>: <span class="hljs-number">640</span> }],\n    <span class="hljs-attr">reflectors</span>: [\n        { <span class="hljs-attr">element</span>: backgroundShape, <span class="hljs-attr">depth</span>: -<span class="hljs-number">100</span>, <span class="hljs-attr">intensity</span>: <span class="hljs-number">0.25</span> },\n        { <span class="hljs-attr">element</span>: foregroundCard, <span class="hljs-attr">depth</span>: <span class="hljs-number">70</span>, <span class="hljs-attr">intensity</span>: <span class="hljs-number">0.35</span> }\n    ]\n});\n\n<span class="hljs-comment">// After application code moves one of those elements:</span>\nscene.<span class="hljs-title function_">refresh</span>();\n<span class="hljs-comment">// Or replace the scene configuration:</span>\nscene.<span class="hljs-title function_">update</span>({ <span class="hljs-attr">lights</span>: [{ <span class="hljs-attr">x</span>: <span class="hljs-number">300</span>, <span class="hljs-attr">y</span>: <span class="hljs-number">80</span>, <span class="hljs-attr">z</span>: <span class="hljs-number">220</span>, <span class="hljs-attr">intensity</span>: <span class="hljs-number">1</span> }] });\n<span class="hljs-comment">// On teardown:</span>\nscene.<span class="hljs-title function_">destroy</span>();</code></pre>\n<p>Coordinates are viewport CSS pixels. An element supplies its live bounding-box center (<code>offsetX</code>/<code>offsetY</code>, from 0 to 1, can move the source within it); a\nreflector uses its computed background color unless <code>color</code> is supplied. Signed <code>depth</code> places foreground and background reflection proxies relative to the\nglass plane. Light distance, height and falloff affect the position and strength of the highlight. Scrolling, resizing, visibility changes and explicit\nrefreshes invalidate the scene; call <code>refresh()</code> after application-driven transforms or layout changes. For frequent updates that only move lights,\n<code>reuseGeometry: true</code> in the scene options retains receiver measurements until those invalidations. Ordinary scene updates continue to remeasure receivers.</p>\n<p>Every mounted glass surface also gets subtle, localized edge colors from the visible layers around its perimeter. Different sources keep their own colors;\nambient gradients crossfade beneath hover, focus, validation and explicit scene lights. The runtime samples nearby computed backgrounds and local pixels from\nvisible images, video and canvas, including <code>pointer-events: none</code> backdrops. Hit-test order and stacking layers distinguish foreground from background; depth\nand distance reduce the contribution. CSS gradients are approximated from their color stops. If the browser blocks pixel access to cross-origin or tainted\nmedia, the runtime falls back to the element&#39;s computed CSS colors. Asset loads, layout/scroll changes, and visual class/style changes refresh the samples; call\n<code>refreshGlassLighting(element)</code> after application-driven changes to a custom surface&#39;s surroundings.</p>\n<p>Portalled overlays can call <code>inheritGlassLighting(overlay, trigger)</code> before mounting their surfaces to receive light from the trigger&#39;s context. Call the\nreturned cleanup function after removing the overlay. Tooltips and menus use this connection to preserve dialog boundaries and receive nearby colors. Tooltips\nremain transparent to pointer events.</p>\n<p>For compound opaque shapes, <code>--bx-glass-unified-lighting: 1</code> exposes restrained samples of received lighting through <code>--bx-glass-lit-edge</code> and its <code>-top</code>,\n<code>-right</code>, <code>-bottom</code>, and <code>-left</code> variants. Tooltip bodies retain their neutral backing and use a subtle spatial rim; arrows sample their facing side instead of\ntinting the entire outline. Interior decorative lighting stays hidden to avoid coloring the fill or introducing seams.</p>\n<p>This is a bounded, stylized lighting model. The browser&#39;s backdrop filter displays content behind glass; refraction rendering also displaces those pixels and\nreflects surroundings into the edge. Raster lighting samples use a shared 32-by-32 scratch buffer cached across receivers and frames. The package does not\ncapture arbitrary DOM into a texture or implement ray tracing. Registered foreground/background objects remain available as explicit reflection proxies when a\nmore deliberate scene is needed. Gradient-backed reflectors can supply an explicit representative color.</p>\n<h2>Overlay fades</h2>\n<p>Overlays use the shared retargetable spring for opacity and a restrained material scale, keeping layout dimensions and collision-aware positioning unchanged.\nThe first material surface animates its own opacity and scale; the positioning pane retains its transform. Controller-owned paint avoids invalidating unrelated\nlighting receivers. Reversal preserves current position and velocity, and the interrupted promise resolves to <code>cancelled</code>.</p>\n<p>The transition temporarily owns the skin&#39;s <code>opacity</code>, <code>scale</code>, and <code>transform-origin</code>, plus the target&#39;s <code>visibility</code>. Without a material skin it animates the\ntarget. Supply an already positioned target and destroy the controller with its overlay. Both endpoints must belong to the same document. <code>refresh()</code> updates\nthe scale origin after an overlay-positioning flip. Reduced motion snaps to the requested state without a running spring.</p>\n<h2>Press feedback</h2>\n<p>The delegated pointer and keyboard handlers drive the existing pressure spring, including a visible initial response for quick taps. A soft inset sheen sits\nwithin the material’s fixed clipping box. <code>--bx-glass-press</code> exposes current pressure to decorative material. Button text and icons remain undistorted, and the\nhit area and overlay origin stay fixed. Controller-owned pressure writes are excluded from scene invalidation, so a press does not resample the entire document\nevery frame.</p>\n<p>Pointer cancellation, matching key release, focus loss during a keyboard press, document/window blur, disabled state, and teardown clear pressure. Touch does\nnot latch hover emission, typing in a field does not activate keyboard pressure, and Space on a native link keeps its normal scrolling behavior. Reduced motion\napplies static pressure feedback immediately and removes it on release.</p>\n<h2>Performance and accessibility</h2>\n<ul>\n<li>One lazy animation clock and delegated press, hover-boundary and focus handling per document. Moving the pointer within an element does not change lighting.\nSettled scenes schedule no animation frames.</li>\n<li>Each receiver evaluates at most four explicit scene lights, chosen from all registered sources by visible contribution after exclusions, intensity and\ndistance falloff. Registration order does not discard nearby sources. Each scene retains a maximum of four reflectors, and at most 24 visible surfaces update\nper frame. Interaction and active-state emitters share one delegated event stream and semantic-attribute observer; there is no observer per control.</li>\n<li>Ambient geometry/style invalidations coalesce over 180 ms. A sampling frame handles at most four receivers, yielding after about 4 ms between receivers; a\nsingle receiver/readback remains atomic. Sixteen perimeter probes discover nearby colors, and media inventories update on insertion rather than on each frame.</li>\n<li>Static images and failed readbacks are cached until their assets change. Only media used by visible receivers is polled: live canvas/video checks begin at 500\nms and back off to 2 seconds while unchanged. Color-only changes reuse source bindings and geometry without hit testing; coverage or layout changes rediscover\nthe layers. Unchanged samples do not repaint. Image/video samples respect object fit and position.</li>\n<li>Each surface uses two shared ambient edge layers for a 180 ms crossfade, instead of a DOM layer and animation per sample. Semantic lighting retains its\nindependent contributions and immediate interaction updates. Hidden documents, reduced-motion receivers and unused media stop live polling; removing the last\nreceiver tears down sampling. Static scenes schedule no polling or animation frames.</li>\n<li>Nested surfaces retain their tint and reflection but skip additional backdrop filters.</li>\n<li><code>baseline</code> uses one backdrop pass and a dynamic highlight. Supported <code>enhanced</code> rendering adds a narrow specular edge and colored reflection overlay; active\nrefraction adds SVG backdrop passes for refraction and rim reflection. <code>auto</code> chooses baseline for coarse pointers, data saving or low reported CPU\nconcurrency; capability checks guard enhancements. Hardware hints are conservative defaults, not measured frame-rate guarantees.</li>\n<li>Operating-system reduced motion/transparency, increased contrast and forced colors receive simpler rendering. A global <code>reducedTransparency: false</code> leaves the\nOS transparency preference enabled; local surface options cannot turn off an owning or OS transparency preference. An explicit reduced-motion setting takes\nprecedence so Blocks can preserve its existing manual accessibility override; omit it to follow the OS. Reduced motion finishes transitions immediately.\nUnsupported backdrop filtering or color mixing produces an opaque fallback.</li>\n<li>Backdrop filters still have a cost. Use one outer material for large sections, avoid full-screen stacked filtered panels, and profile actual target devices\nbefore treating any frame-rate target as verified.</li>\n</ul>\n<p>See <code>../examples/index.html</code> for a native DOM demo. Serve the repository over HTTP after building the workspace; no framework runtime is required. Build with\n<code>npm run build:blocks</code> at the workspace root; this builds all Blocks entry points and generates the native example’s design tokens from Blocks. Browser\nregressions live in <code>tools/browser</code>.</p>\n<h3>Semantic lighting</h3>\n<p><code>BxGlassLightingService</code> in the Angular adapter combines sources within a form or toast stack. Validation text illuminates nearby controls and removes its\nsource when the error clears. Toast light is anchored to the rendered progress bar’s right edge, pauses with the toast, and illuminates adjacent notifications.\nIts own glow uses that same measured edge; it has no independent progress animation. <code>excludeSource</code> or <code>excludeElement</code> lets a source render its own glow\nseparately. <code>observeGlassLighting</code> and <code>refreshGlassLighting</code> support custom decorative receivers, including the opaque circular slider thumb beside its native\nrange input.</p>\n<p>A surface can opt into semantic emission with <code>mountSurface(element, { emission: &#39;var(--bx-primary)&#39; })</code>. Hover, press, or keyboard focus activates that element\nas a source; its visible border and declared color determine the facing edges and corners of nearby surfaces. Source colors are resolved in the emitting element\nbefore projection, so local custom properties and scoped themes retain their color on other receivers. Hover light has a 120 CSS-pixel falloff radius and stays\nwithin the nearest main, aside, nav, dialog or overlay. Add <code>data-bx-light-scope</code> to isolate a custom region. Modal panels, native dialogs, popovers,\nfixed/sticky panels, CDK overlays and toast stacks form separate lighting boundaries. Positioned stacking layers also constrain hover/focus light. Receiver hit\ntesting excludes covered surfaces, including rounded corners. Fully transparent CDK dismissal backdrops intercept input without occluding lighting; visible menu\npanels and opaque backdrops still occlude. Opening or removing overlays invalidates prior highlights. Each source fades independently over 200 ms, including the\nemitter’s own colored border. Borders can combine several sources; retiring contributions fade out rather than jumping to a new source. Reduced motion applies\nchanges immediately. Source coordinates project directly into each receiver without a second position spring, pointer tracking, DOM capture, or a permanent\nhover animation loop. Hover contributions use a bounded circular spread, so a large receiver does not stretch a small source across its entire border. Edge\nfalloff uses the distance to the receiver&#39;s perimeter even when a source projects inside its bounds.</p>\n<p>Use <code>mountSurface(element, { emission: false })</code> to disable automatic hover, press, active-state and keyboard-focus emission while keeping press deformation and\nreceived lighting. An explicit <code>focusEmission</code> still enables focus-only emission. Omission retains the existing theme accent/error default. Blocks menu rows use\nlocal hover/pressed fills and focus outlines without becoming light sources.</p>\n<p><code>inheritGlassLighting(overlay, origin)</code> shares incoming lighting with an overlay while retaining its physical boundary for outgoing sources. Controls inside an\noverlay can illuminate nearby receivers in that overlay, but cannot cast light back into its trigger&#39;s page or parent overlay. This applies to dropdowns,\ncontext menus, popovers, selection panels and passive tooltips. Theme inheritance remains independent of this direction of lighting.</p>\n<p>Backdrop behavior follows the browser’s <a href="https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/backdrop-filter">backdrop-root rules</a>. Visual\ntreatment follows <a href="https://developer.apple.com/design/human-interface-guidelines/materials">Apple’s material guidance</a>: restrained highlights and readable\ntranslucent layers.</p>\n<p>Editable field surfaces emit while their native control has focus by default; action surfaces emit for keyboard focus only. An explicit <code>focusEmission</code> opts a\ncustom surface into illumination for any focus. Checked, pressed, selected, and current states retain emission. An expanded trigger retains emission when it\nalso declares <code>aria-haspopup</code>; ordinary layout expansion alone does not select a control. Focused fields remain active when a different button is hovered.\nDecorative native-control receivers can pass their hit target as the third argument to <code>observeGlassLighting</code>.</p>\n<p>Active borders stay painted when surfaces are partly clipped by the viewport, a scrolling container, or an overlapping header. Scrolling them back into view\npreserves their lighting without a fade. A partly exposed source can still emit, but each receiving interior/edge location must be uncovered. A visible area\nelsewhere on a receiver does not authorize light through an overlapping opaque panel. Fully covered surfaces remain excluded. Whole-source exposure checks share\na short-lived cache and use bounded fallback probes only when the preferred point is covered; projected receiver points use separate visibility checks.</p>\n<h2>Retargetable selection motion</h2>\n<p><code>createSpringMotion(initial, render, options?)</code> builds scalar channels over the existing exact damped spring and shared lazy frame clock. The callback receives\npositions and velocities per second. <code>retarget(values, immediate = false)</code> preserves current velocity; <code>immediate: true</code> snaps, clears velocity and unsubscribes\nfrom frames. The initial and target arrays must contain the same number of finite values; invalid targets throw <code>RangeError</code> before changing any channel.\n<code>destroy()</code> stops animation permanently. Owners must destroy the controller and snap when their live reduced-motion preference changes. Without a browser\nanimation clock, targets paint immediately. Settled channels leave no running frame loop; the scheduler bounds frame deltas after stalls.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { createSpringMotion, <span class="hljs-variable constant_">MOTION_PRESETS</span>, paintMotionStyles } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/effects/runtime&#x27;</span>;\n\n<span class="hljs-keyword">const</span> motion = <span class="hljs-title function_">createSpringMotion</span>(\n    [<span class="hljs-number">0</span>, <span class="hljs-number">100</span>],\n    <span class="hljs-function">(<span class="hljs-params">[x, width]</span>) =&gt;</span> {\n        <span class="hljs-title function_">paintMotionStyles</span>(selection, { <span class="hljs-attr">transform</span>: <span class="hljs-string">`translateX(<span class="hljs-subst">${x}</span>px)`</span>, <span class="hljs-attr">width</span>: <span class="hljs-string">`<span class="hljs-subst">${width}</span>px`</span> }, <span class="hljs-literal">true</span>);\n    },\n    <span class="hljs-variable constant_">MOTION_PRESETS</span>.<span class="hljs-property">fluid</span>\n);\n\nmotion.<span class="hljs-title function_">retarget</span>([<span class="hljs-number">160</span>, <span class="hljs-number">140</span>]);\n<span class="hljs-comment">// When reduced motion becomes active, snap the current destination:</span>\nmotion.<span class="hljs-title function_">retarget</span>([<span class="hljs-number">160</span>, <span class="hljs-number">140</span>], <span class="hljs-literal">true</span>);\n<span class="hljs-comment">// When the owning view is destroyed:</span>\nmotion.<span class="hljs-title function_">destroy</span>();</code></pre>\n<p><code>paintMotionStyles(element, styles, geometry = false)</code> writes decorative CSS properties without invalidating unrelated lighting receivers. Pass <code>true</code> when\nmoving/resizing a registered surface so its own lighting geometry is refreshed through the existing engine. The owner must restore any persistent element&#39;s\nstyles if it outlives its motion view. The pilots remove their decorative surfaces with their views.</p>\n<p><code>MOTION_PRESETS</code> exports <code>snappy</code>, <code>smooth</code>, <code>soft</code>, <code>elastic</code>, and <code>fluid</code> stiffness/damping/mass defaults, checked against <code>ISpringOptions</code>. Callers can\nsupply custom spring options. These are motion characteristics, not new CSS theme tokens. The pilots cap deformation separately and remove it under reduced\nmotion. Inspect <code>/components/stepper</code> and <code>/components/tabs</code>; use <code>/appearance</code> for accessibility and theme combinations. The same foundations serve sliders,\ntoggles, menus and overlays.</p>\n<h2>Shared row and overlay motion</h2>\n<p><code>mountSelectionMotion(root, { selector?, reducedMotion? })</code> adds one noninteractive surface behind an existing <code>role=&quot;menu&quot;</code> or <code>role=&quot;listbox&quot;</code> container. The\ndefault selector is <code>[role=&quot;menuitem&quot;], [role=&quot;option&quot;]</code>. Disabled rows and nested lists are excluded. Pointer hover and exit restore the backing immediately;\npointer exit hides it when there is no selected or keyboard-focused row. Mouse-only focus does not keep a hover highlight after exit. Pointer\nselection/deselection retains the hovered row without traveling to another selected option. Actual keyboard focus and <code>aria-selected</code> changes may spring without\nchanging selection. The controller remeasures dynamic/scrolling content, bounds stretch, and releases its observers and surface renderer on <code>destroy()</code>. Omitted\nmotion policy follows live inherited/system preferences; call <code>update({ reducedMotion })</code> to change an explicit application override. Use a div container with\nunrestricted children. Set <code>--bx-selection-surface</code> to customize the backing; defaults use existing semantic hover/error surfaces. Focus rings and persistent\nselection/checkmarks remain owned by the rows. Menus, selects, multi-selects, and autocomplete demonstrate this at their existing Playground routes.</p>\n<p><code>createGlassTransition</code> now uses the shared retargetable spring for opacity and restrained scale. <code>IGlassTransitionOptions.scale</code> is the closed scale, clamped\nfrom 0.9 to 1 and defaulting to 0.985. Use 1 for opacity-only motion. The controller preserves the overlay&#39;s positioning transform, follows the opening side,\nrestores owned styles, cancels superseded promises, and snaps on live reduced motion. <code>refresh()</code> updates its scale origin after a positioning flip. Existing\nenter/exit/destroy contracts remain available. Native CSS <code>motion-easing()</code> presets from <code>core/styles/helpers</code> supply restrained curves where continuous physics\nis unnecessary, including large modal surfaces and toast stack collapse. These Sass curves add no CSS token scale or generator-owned token changes.</p>\n<h2>Fluid interaction across Blocks</h2>\n<p>Blocks applies Apple&#39;s <a href="https://developer.apple.com/design/human-interface-guidelines/motion">motion guidance</a>,\n<a href="https://developer.apple.com/design/human-interface-guidelines/gestures">gesture guidance</a>, and\n<a href="https://developer.apple.com/videos/play/wwdc2018/803/">Designing Fluid Interfaces</a> through the shared runtime. The web interaction contract remains native:\nscrolling, zoom, keyboard activation, focus, disabled/readonly state and application guards take precedence over decorative motion.</p>\n<table>\n<thead>\n<tr>\n<th>Interaction family</th>\n<th>Motion contract</th>\n<th>Playground review</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Buttons, chips, checkbox/radio controls and interactive surfaces</td>\n<td>Immediate material pressure; stronger for touch, subtler for mouse/pen/keyboard. Repeated presses retain spring velocity. Labels and hit targets stay stable.</td>\n<td><code>/components/button</code>, <code>/components/checkbox</code>, <code>/components/radio</code>, <code>/components/chip</code></td>\n</tr>\n<tr>\n<td>Tabs</td>\n<td>Native touch scrolling; hold to select by dragging. Actual position drives the preview; bounded velocity projection chooses the release destination.</td>\n<td><code>/components/tabs</code></td>\n</tr>\n<tr>\n<td>Sliders, range sliders and resize handles</td>\n<td>Direct values and geometry follow actual input. No predicted value changes. Decorative feedback releases independently.</td>\n<td><code>/components/slider</code>, <code>/components/range-slider</code>, <code>/components/resize-handle</code></td>\n</tr>\n<tr>\n<td>Toggles and stepper selection</td>\n<td>Retarget committed state without restarting springs. Stepper guards and application confirmation remain authoritative; separate cards use local feedback.</td>\n<td><code>/components/slide-toggle</code>, <code>/components/stepper</code></td>\n</tr>\n<tr>\n<td>Menus, select, multiselect and autocomplete</td>\n<td>Pointer hover is immediate. Keyboard selection can settle spatially. A clipped decorative layer cannot create scroll overflow.</td>\n<td><code>/components/menu</code>, <code>/components/select</code>, <code>/components/multi-select</code>, <code>/components/autocomplete</code></td>\n</tr>\n<tr>\n<td>Fields, errors and disclosures</td>\n<td>Brief feedback uses shared curves. Error text remains available; disclosure state changes immediately and can be reversed.</td>\n<td><code>/components/input-field</code>, <code>/components/collapsible</code></td>\n</tr>\n<tr>\n<td>Navigation, side panels and modal views</td>\n<td>Large surfaces use restrained motion; dimensions and viewport constraints remain authoritative. Bottom-sheet releases use recent velocity and guarded dismissal.</td>\n<td><code>/components/side-nav</code>, <code>/components/side-panel</code>, <code>/modal</code></td>\n</tr>\n<tr>\n<td>Dropdowns, popovers and tooltips</td>\n<td>Shared overlay springs preserve positioning and cancel superseded completion promises.</td>\n<td><code>/components/dropdown</code>, <code>/components/popover</code>, <code>/components/tooltip</code></td>\n</tr>\n<tr>\n<td>Toasts, progress, loading and skeletons</td>\n<td>Status and lifetime remain independent of decorative motion. Reduced motion retains static state, text and accessible feedback.</td>\n<td><code>/toastr</code>, <code>/components/progress-bar</code>, <code>/components/loading-spinner</code>, <code>/components/skeleton</code></td>\n</tr>\n</tbody></table>\n<p>Use live reduced-motion and reduced-transparency preferences independently. Reduced motion removes travel, deformation and transition delays, while direct\nmanipulation, focus, semantics and loading state remain available. Reduced transparency changes material opacity without disabling useful lighting. Check light\nand dark themes, constrained widths, zoom, RTL, interrupted gestures and cancellation. Browser automation does not replace physical iOS Safari touch review.</p>\n<h3>Gesture sampling and handoff</h3>\n<p><code>GestureVelocity</code> samples recent scalar motion in coordinate units per second. <code>update(position, timestamp)</code> filters event samples, responds immediately to a\nreversal and ignores stale timestamps. <code>velocity(timestamp)</code> returns zero after a 100 ms stationary pause. Coordinates must use the same space throughout a\ngesture; scroll offsets must not masquerade as pointer velocity.</p>\n<p><code>projectMotion(position, velocity, limit, seconds = 0.16)</code> chooses a bounded prospective destination. It throws <code>RangeError</code> for nonfinite coordinates or\nnegative bounds. Use it to select a discrete snap destination or request dismissal; do not use prediction to change precise slider values or to bypass guards.\nThe projection horizon is Blocks tuning, not an Apple-prescribed constant.</p>\n<p><code>ISpringMotion.track(values, velocities?)</code> paints direct manipulation immediately, stops pending frames, and retains the supplied velocities for the next\n<code>retarget()</code>. Omitted velocities are zero. Both arrays must contain finite values and match the initial channel count; invalid inputs throw <code>RangeError</code> without\npartially changing the channels. Snap with <code>retarget(values, true)</code> under reduced motion, and call <code>destroy()</code> on teardown.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { createSpringMotion, <span class="hljs-title class_">GestureVelocity</span>, projectMotion } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/effects/runtime&#x27;</span>;\n\n<span class="hljs-keyword">const</span> velocity = <span class="hljs-keyword">new</span> <span class="hljs-title class_">GestureVelocity</span>(<span class="hljs-number">0</span>, <span class="hljs-number">0</span>);\n<span class="hljs-keyword">const</span> motion = <span class="hljs-title function_">createSpringMotion</span>([<span class="hljs-number">0</span>], <span class="hljs-function">(<span class="hljs-params">[position]</span>) =&gt;</span> {\n    selection.<span class="hljs-property">style</span>.<span class="hljs-property">transform</span> = <span class="hljs-string">`translateX(<span class="hljs-subst">${position}</span>px)`</span>;\n});\n\nvelocity.<span class="hljs-title function_">update</span>(<span class="hljs-number">24</span>, <span class="hljs-number">32</span>);\nmotion.<span class="hljs-title function_">track</span>([<span class="hljs-number">24</span>], [velocity.<span class="hljs-title function_">velocity</span>(<span class="hljs-number">32</span>)]);\n<span class="hljs-keyword">const</span> destination = <span class="hljs-title function_">projectMotion</span>(<span class="hljs-number">24</span>, velocity.<span class="hljs-title function_">velocity</span>(<span class="hljs-number">32</span>), <span class="hljs-number">100</span>);\n<span class="hljs-comment">// Resolve destination to an allowed snap point before committing application state.</span>\nmotion.<span class="hljs-title function_">retarget</span>([destination]);\n<span class="hljs-comment">// When the owning view is destroyed:</span>\nmotion.<span class="hljs-title function_">destroy</span>();</code></pre>\n<p><code>subscribeFrame(callback)</code> exposes the existing shared lazy clock for coordinated work such as drag edge scrolling. Its <code>FrameCallback</code> receives bounded elapsed\nseconds and an animation timestamp in milliseconds. Return <code>false</code> when settled or blocked; call the returned cleanup function on release, cancellation and\nteardown. Without <code>requestAnimationFrame</code>, it schedules no work. It is not an automatic reduced-motion policy: callers must distinguish useful direct\ninteraction from optional decorative movement. Tabs demonstrate continuous edge scrolling with this clock.</p>\n',
  'projects/blocks/forms/README.md':
    '<h1>Forms</h1>\n<p>Blocks fields use Angular 22 native signal control contracts and support Signal Forms, Reactive Forms, Template-driven Forms and standalone models. The library\nsupplies presentation, interaction and accessible feedback; Angular owns validation and submission.</p>\n<h2>Import and basic usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { signal } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { form, <span class="hljs-title class_">FormField</span> <span class="hljs-keyword">as</span> <span class="hljs-title class_">SignalFormField</span>, <span class="hljs-title class_">FormRoot</span>, required, email } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/forms/signals&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Button</span>, <span class="hljs-title class_">InputField</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;\n\n<span class="hljs-keyword">readonly</span> accountModel = <span class="hljs-title function_">signal</span>({ <span class="hljs-attr">email</span>: <span class="hljs-string">&#x27;&#x27;</span> });\n<span class="hljs-keyword">readonly</span> account = <span class="hljs-title function_">form</span>(<span class="hljs-variable language_">this</span>.<span class="hljs-property">accountModel</span>, <span class="hljs-function">(<span class="hljs-params">p</span>) =&gt;</span> {\n  <span class="hljs-title function_">required</span>(p.<span class="hljs-property">email</span>, { <span class="hljs-attr">message</span>: <span class="hljs-string">&#x27;Email is required.&#x27;</span> });\n  <span class="hljs-title function_">email</span>(p.<span class="hljs-property">email</span>, { <span class="hljs-attr">message</span>: <span class="hljs-string">&#x27;Enter a valid email address.&#x27;</span> });\n}, {\n  <span class="hljs-attr">submission</span>: {\n    <span class="hljs-attr">ignoreValidators</span>: <span class="hljs-string">&#x27;none&#x27;</span>,\n    <span class="hljs-attr">action</span>: <span class="hljs-title function_">async</span> (field) =&gt; { <span class="hljs-keyword">await</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">api</span>.<span class="hljs-title function_">save</span>(<span class="hljs-title function_">field</span>().<span class="hljs-title function_">value</span>()); }\n  }\n});</code></pre>\n<p>Import <code>SignalFormField</code>, <code>FormRoot</code>, and the used Blocks controls into the standalone component. Alias Angular&#39;s directive because Blocks also exports its\nframe component as <code>FormField</code>.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">form</span> [<span class="hljs-attr">formRoot</span>]=<span class="hljs-string">&quot;account&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-input-field</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Email&quot;</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;email&quot;</span> [<span class="hljs-attr">formField</span>]=<span class="hljs-string">&quot;account.email&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;submit&quot;</span> [<span class="hljs-attr">disabled</span>]=<span class="hljs-string">&quot;!account().valid()&quot;</span> [<span class="hljs-attr">loading</span>]=<span class="hljs-string">&quot;account().submitting()&quot;</span>&gt;</span>Save<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">form</span>&gt;</span></code></pre>\n<h2>Validation and state</h2>\n<p>Schema validation supplies <code>required</code>, numeric and length limits, pattern metadata, errors, pending, disabled and readonly state to compatible controls.\n<code>valid()</code> is false while asynchronous validation is pending; <code>!invalid()</code> alone does not guarantee readiness.</p>\n<p>Use <code>ignoreValidators: &#39;none&#39;</code> to gate the submission handler as well as the visible button while async validation is pending. Submission marks interactive\nfields touched, prevents duplicate submissions, and applies returned server errors to their target fields.</p>\n<p>Read field state through the Angular field tree. Derive UI with <code>computed()</code> and use <code>effect()</code> for side effects when validity or pending state changes.\nCross-field validators belong in the schema and can read related values. Blocks does not implement a second validation engine.</p>\n<h2>Custom messages and visibility</h2>\n<p>Shared inputs include <code>errorMessages</code>, <code>errorPriority</code>, <code>errorMode</code> (<code>first</code> or <code>all</code>), and <code>errorPolicy</code> (<code>touched</code>, <code>dirty</code>, <code>submitted</code>, <code>always</code>, or a\nfunction receiving <code>IErrorState</code>). The default reveals invalid fields after touch or submission. A function can include custom group or application state. The\nsubmitted policy tracks native form submission; when invoking submission programmatically outside the form element, pass the shared <code>submitted</code> input from\napplication state.</p>\n<p>Message resolution prefers projected <code>bx-error</code> content, then field message overrides, schema messages, and configured defaults. <code>minlength</code>/<code>maxlength</code>\nReactive Forms keys and <code>minLength</code>/<code>maxLength</code> Signal Forms kinds are recognized. Resolvers receive the original error plus its parameter payload.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">readonly</span> <span class="hljs-attr">messages</span>: <span class="hljs-title class_">ValidationMessages</span> = {\n  <span class="hljs-attr">minLength</span>: <span class="hljs-function">(<span class="hljs-params">{ params }</span>) =&gt;</span> <span class="hljs-string">`Use at least <span class="hljs-subst">${params[<span class="hljs-string">&#x27;minLength&#x27;</span>] ?? params[<span class="hljs-string">&#x27;requiredLength&#x27;</span>]}</span> characters.`</span>,\n  <span class="hljs-attr">required</span>: { <span class="hljs-attr">key</span>: <span class="hljs-string">&#x27;validation.required&#x27;</span> }\n};</code></pre>\n<p>Put this declaration in the appropriate constants or types-supporting module according to the house rules. Translation-key overrides receive error parameters\nthrough the existing adapter. Default messages can be replaced application-wide using <code>FormSettingsService.update()</code>; instance inputs take precedence. No\nerror-message map is mandatory when the schema supplies messages.</p>\n<p>Projected <code>bx-error</code> supports rich content. <code>bx-hint</code>, <code>hint</code>, <code>hintEnd</code>, <code>bxPrefix</code>, and <code>bxSuffix</code> provide composable support and adornments. Supporting text\nand errors are associated automatically through <code>aria-describedby</code>. Custom error regions announce changes politely.</p>\n<h2>Compatibility and migration</h2>\n<p>Existing <code>[formControl]</code>, <code>formControlName</code>, and <code>[(ngModel)]</code> component bindings remain supported. Text edits honor Reactive Forms blur and submit update\nstrategies. <code>reset()</code> on the owning field/form clears component interaction and parse state. Standalone value controls expose <code>[(value)]</code>; checkbox-style\ncontrols expose <code>[(checked)]</code>.</p>\n<p><code>BxBaseControl</code> remains available for existing external CVA subclasses; repeated touch reporting and schema error-message handling are corrected. New Blocks\ncontrols use native signal contracts, without implementing CVA on the same component. The legacy individually bound radio remains available, while new forms\nshould bind a <code>RadioGroup</code> once around its options.</p>\n<p>Native <code>input</code>, <code>textarea</code> and <code>select</code> elements can use <code>bxInput</code> inside <code>bx-form-field</code>. Consumer components can provide <code>BX_FORM_FIELD_CONTROL</code> with\n<code>IFormFieldControl</code> to integrate their own state and focus behavior.</p>\n<h2>Asynchronous options</h2>\n<p>Single select and multiselect support application-owned requests, comparison, templates, incremental loading and error/retry behavior. Their scroll wrappers use\n<code>LoadMoreDirective</code>, which can also be used by future paginated components. See the <a href="components/load-more">load-more guide</a> and\n<a href="components/multi-select">multiselect guide</a>.</p>\n<h2>Appearance and accessibility</h2>\n<p>Controls follow Blocks semantic tokens, global theme/appearance configuration, reduced motion through <code>BxA11yService</code>, and reactive text resolution through\n<code>BX_I18N</code>. Configuration supports filled/outlined appearance, label placement, required markers, floating-label behavior and supporting-text sizing. Readonly\nand disabled states remain distinct in form state. All applicable controls accept <code>readOnly</code> as well as Angular Signal Forms&#39; lowercase <code>readonly</code> contract.\nEither true value prevents edits while retaining focusability. Readonly controls use the default cursor and suppress pointer hover/click highlights and\ninteractive glass lighting while preserving their static appearance and keyboard focus styling. Focus origin uses the shared Angular CDK focus monitor. Changes\nto readonly state update mounted surfaces, including projected native controls and grouped radios. Native select integration prevents interaction without\nbinding a nonexistent native readOnly property.</p>\n<p>All existing form ellipsis and full-selection fit measurement use the public <code>TruncateDirective</code> from <code>@filip.mazev/blocks/primitives</code>. Set\n<code>[tooltipOnTruncate]=&quot;false&quot;</code> on an input, search, select, or multiselect to retain truncation while supplying your own tooltip.\n<code>FormSettingsService.update({ tooltipOnTruncate: false })</code> changes the application default; instance inputs take precedence. Tag and menu controls expose the\nsame opt-out. The public <code>TruncatedTextPipe</code> (<code>bxTruncatedText</code>) and <code>truncatedText()</code> helper support custom feedback. See the\n<a href="components/truncate">shared truncation guide</a>.</p>\n<h3>Motion and direct input</h3>\n<p>Shared surfaces provide immediate pressure feedback with a stronger touch response and a subtler precise-pointer response. Press interruption preserves spring\nvelocity, while text and icons retain their shape. Sliders and range sliders retain native precise value tracking; release prediction is reserved for discrete\nnavigation and dismissal. Option surfaces are clipped independently from scrollable results, and pointer hover remains immediate. Field feedback uses brief\nshared curves. See the <a href="../effects/runtime/README.md#fluid-interaction-across-blocks">library motion contract</a>.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/signal-forms</code> for multiple controls, sync/async/cross-field rules, pending state, custom messages, server errors, disabled submission, dynamic\ndisabled/readonly, reset and reactive validation status. Use Fill valid data to exercise submission, or an email containing <code>server-error</code> to see a server\nrejection.</p>\n<p>The load-more and selection pages include fake APIs, failed requests, retry and small pages without scrollbars.</p>\n',
  'projects/blocks/forms/components/autocomplete/README.md':
    '<h1>Editable autocomplete</h1>\n<p>An editable string control with optional suggestions. Free text remains valid; choosing a suggestion inserts its value. Integrates with the shared form-field\nand signal, reactive and template-driven forms contracts.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Autocomplete</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-autocomplete</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Destination&quot;</span> [<span class="hljs-attr">options</span>]=<span class="hljs-string">&quot;suggestions&quot;</span> [(<span class="hljs-attr">value</span>)]=<span class="hljs-string">&quot;destination&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>value</code> is a <code>string | null</code> model. <code>options</code> accepts <code>readonly IAutocompleteOption[]</code>, each with a unique string <code>value</code>, optional <code>ResolvableText label</code> and\noptional <code>disabled</code>.</p>\n<table>\n<thead>\n<tr>\n<th>API</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>externalFiltering</code></td>\n<td>false</td>\n<td>Application supplies filtered results</td>\n</tr>\n<tr>\n<td><code>inlineCompletion</code></td>\n<td>true</td>\n<td>Shows an uncommitted gray suffix for the first matching suggestion</td>\n</tr>\n<tr>\n<td><code>clearable</code></td>\n<td>true</td>\n<td>Shows the select-style clear action for nonempty text; hidden while readonly</td>\n</tr>\n<tr>\n<td><code>clearLabel</code></td>\n<td>Clear selection</td>\n<td>Translated accessible name of the clear action</td>\n</tr>\n<tr>\n<td><code>clearTooltip</code></td>\n<td>clearLabel</td>\n<td>Optional translated tooltip; empty string disables it</td>\n</tr>\n<tr>\n<td><code>searching</code></td>\n<td>false</td>\n<td>Replaces stale results with a distinct loading state</td>\n</tr>\n<tr>\n<td><code>loading</code></td>\n<td>false</td>\n<td>Application-owned initial/incremental request state</td>\n</tr>\n<tr>\n<td><code>hasMore</code></td>\n<td>false</td>\n<td>Explicit remote exhaustion contract</td>\n</tr>\n<tr>\n<td><code>loadError</code></td>\n<td>absent</td>\n<td>Retains options and offers explicit retry</td>\n</tr>\n<tr>\n<td><code>loadMoreConfig / loadMoreTemplate</code></td>\n<td>{} / absent</td>\n<td>Shared <code>ILoadMoreConfig</code> and <code>ILoadMoreContext</code></td>\n</tr>\n<tr>\n<td><code>loadMoreRevision</code></td>\n<td>options array</td>\n<td>Override the request-completion revision</td>\n</tr>\n<tr>\n<td><code>optionTemplate</code></td>\n<td>absent</td>\n<td><code>TemplateRef&lt;IAutocompleteOptionContext&gt;</code>; keep its content noninteractive</td>\n</tr>\n<tr>\n<td><code>emptyText / loadingText</code></td>\n<td>descriptive text</td>\n<td>Translatable status messages</td>\n</tr>\n<tr>\n<td><code>autocomplete</code></td>\n<td>off</td>\n<td>Native browser autocomplete attribute</td>\n</tr>\n<tr>\n<td><code>queryChange</code></td>\n<td>—</td>\n<td>Text edits; application owns debounce and cancellation</td>\n</tr>\n<tr>\n<td><code>optionSelected</code></td>\n<td>—</td>\n<td>Selected <code>IAutocompleteOption</code></td>\n</tr>\n<tr>\n<td><code>loadMore</code></td>\n<td>—</td>\n<td><code>ILoadMoreRequest</code> with scroll, button or retry source</td>\n</tr>\n<tr>\n<td><code>openedChange</code></td>\n<td>—</td>\n<td>Boolean panel state changes</td>\n</tr>\n<tr>\n<td><code>open() / close() / isOpen()</code></td>\n<td>—</td>\n<td>Public panel controls</td>\n</tr>\n<tr>\n<td><code>completeLoadMore()</code></td>\n<td>—</td>\n<td>Releases a request with no loading cycle or revision change</td>\n</tr>\n<tr>\n<td><code>clear()</code></td>\n<td>—</td>\n<td>Clears text, marks touched, focuses the input and emits queryChange with an empty string; respects disabled/readonly</td>\n</tr>\n</tbody></table>\n<p>Inherits labels, placeholders, hints, validation, disabled, lowercase <code>readonly</code> and consumer <code>readOnly</code>, focus and reset behavior. See the\n<a href="components/signal-forms">forms guide</a>.</p>\n<p>For a standalone component, import <code>Autocomplete</code> and declare:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">public</span> <span class="hljs-attr">destination</span>: <span class="hljs-built_in">string</span> | <span class="hljs-literal">null</span> = <span class="hljs-string">&#x27;&#x27;</span>;\n<span class="hljs-keyword">public</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">suggestions</span>: <span class="hljs-keyword">readonly</span> <span class="hljs-title class_">IAutocompleteOption</span>[] = [\n  { <span class="hljs-attr">value</span>: <span class="hljs-string">&#x27;Skopje&#x27;</span> }, { <span class="hljs-attr">value</span>: <span class="hljs-string">&#x27;Ohrid&#x27;</span> }, { <span class="hljs-attr">value</span>: <span class="hljs-string">&#x27;Unavailable&#x27;</span>, <span class="hljs-attr">disabled</span>: <span class="hljs-literal">true</span> }\n];</code></pre>\n<p>Import <code>IAutocompleteOption</code> from the forms public entry point.</p>\n<h2>Appearance and customization</h2>\n<p><code>--bx-autocomplete-panel-height</code>, <code>--bx-autocomplete-panel-padding</code>, <code>--bx-autocomplete-background</code>, <code>--bx-autocomplete-radius</code> and\n<code>--bx-autocomplete-completion-color</code>. The editable control reuses InputField&#39;s styling, including its height, typography, spacing, floating label, required\nmarker, focus state and filled/outlined appearance. Its inline completion shares the native input&#39;s metrics. Results use the same opaque backing and\nbackdrop-free option-panel styling as Select/MultiSelect. Options wrap, panel width follows the control, and height is constrained to the viewport. Custom\noption templates receive the option, resolved label, active state and index.</p>\n<h2>Behavior and accessibility</h2>\n<p>Typing <code>Sk</code> can show a muted <code>opje</code> suffix for <code>Skopje</code>, without changing the form value. The hint appears only with the caret at the end, no selection, and an\navailable prefix match; it is hidden during replacement searches and IME composition. Accept it with the forward arrow (Right in LTR, Left in RTL), End or\nEnter. The full selected suggestion becomes the value only on acceptance. Set <code>inlineCompletion</code> to false to use list suggestions alone.</p>\n<p>Up/Down move between available suggestions while focus stays in the combobox; Enter selects; Escape closes. Other native editing keys retain their meaning. IME\ncomposition does not issue partial searches. Tab visits the clear action when present, then the shared load-more/retry action, before continuing through the\npage. Readonly preserves readable, focusable text and prevents editing.</p>\n<p>The clear action reuses the shared field-clear appearance used by Select/MultiSelect. It remains disabled on disabled controls and is absent on readonly\ncontrols. Clearing keeps focus in the editable input and lets the application refresh suggestions for the empty query. The trailing Blocks <code>chevron-down</code>\nfollows the open state and is replaced by a same-size decorative spinner during requests. Caret dimensions and gaps share Select&#39;s field-caret mixin; trailing\npadding, clear-action placement and available text spacing match Select while preserving InputField&#39;s full height and vertical text padding.</p>\n<p>For asynchronous results bind <code>[externalFiltering]=&quot;true&quot;</code>, <code>[searching]=&quot;searching()&quot;</code>, <code>[loading]=&quot;loading()&quot;</code>, <code>[hasMore]=&quot;hasMore()&quot;</code>,\n<code>[loadError]=&quot;error()&quot;</code>, handle <code>(queryChange)</code> and forward <code>(loadMore)</code> to your request coordinator. Set loading before starting requests. Cancel or ignore\nstale queries; retain loaded data and the failed cursor on failure; advance the cursor only on success. Clear errors when retrying. Searching suppresses old\nresults and pagination without implying exhaustion.</p>\n<p>The shared LoadMoreDirective deduplicates requests, exposes an action when no scrollbar exists and preserves its button spinner during loading. Customize\nnormal/loading/retry text through <code>ILoadMoreConfig</code>; custom footer templates must use the guarded callback and preserve keyboard access.</p>\n<p>The playground includes a runnable mock service with delayed initial/search/incremental requests, failure followed by explicit successful retry, empty results\nand a compact page-size control for exercising overflow transitions. Its load-more/error/retry footer shares the select/multi-select styling, with tonal accent\nactions. Source: <code>projects/playground/src/app/components/screens/library-components/essentials-examples/services/autocomplete-demo.service.ts</code>.</p>\n<h3>Motion and material response</h3>\n<p>Suggestions use the shared overlay opacity/scale spring and a persistent surface following the active descendant or hovered enabled option. Typing and keyboard\nnavigation retain their existing focus and selection contracts. Closing immediately reports the closed state, makes the old panel inert, and releases it after\nexit; reopening or destruction cancels stale completion. Reduced motion closes immediately. Async filtering and pagination remain application-owned. Inspect\n<code>/components/autocomplete</code> with rapid edits, keyboard selection, pending results, and <code>/appearance</code> settings.</p>\n<h2>Playground</h2>\n<p><code>/components/autocomplete</code> includes live examples and shared appearance controls.</p>\n',
  'projects/blocks/forms/components/button/README.md':
    '<h1>Button</h1>\n<p>An action control with Blocks intent colors, familiar variants and visible focus.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Button</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;filled&quot;</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;save()&quot;</span>&gt;</span>Save changes<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>variant</code>: text, filled, tonal, icon, fab, mini-fab, extended-fab. <code>color</code>: primary, accent, success, danger, info, warn, grayscale. <code>outlined</code>, <code>elevated</code>,\n<code>disabled</code>, and <code>interactive</code> control presentation and availability.</p>\n<p><code>glassiness</code> is an explicit per-button opt-in: omitted buttons keep their existing material. Set <code>glassiness=&quot;auto&quot;</code> for supported browsers, or <code>&quot;on&quot;</code> to test\nother engines. Application-wide Off, baseline quality, opaque intent fills and accessibility still take precedence. Automatic rendering uses one SVG backdrop\npass; Enhanced adds the full reflection/bevel treatment. Text and icons keep their semantic theme colors; active refraction maintains a minimum tint and blur\neven at the clearest translucency setting.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;icon&quot;</span> <span class="hljs-attr">glassiness</span>=<span class="hljs-string">&quot;auto&quot;</span> <span class="hljs-attr">aria-label</span>=<span class="hljs-string">&quot;Bookmark&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-icon</span> <span class="hljs-attr">name</span>=<span class="hljs-string">&quot;bookmark&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<p>Use the active palette&#39;s second tone for supporting actions:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;tonal&quot;</span> <span class="hljs-attr">color</span>=<span class="hljs-string">&quot;accent&quot;</span>&gt;</span>Explore<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Icon, tonal and outlined glass buttons follow the full translucency range without a minimum\nbutton-specific tint. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<p>Interactive button variants illuminate their border and nearby glass on hover, press and keyboard focus. Text buttons do not emit light, but keep their\nunderline hover and focus outline. The same light remains active for <code>aria-pressed=&quot;true&quot;</code>, <code>aria-selected=&quot;true&quot;</code>, a current <code>aria-current</code> value, or an\nexpanded popup trigger (<code>aria-expanded=&quot;true&quot;</code> with <code>aria-haspopup</code>). Plain expansion controls, such as a rail collapse action, do not acquire selected styling\nsolely from <code>aria-expanded</code>. If an application used expansion as a toggle selection, use <code>aria-pressed</code> for that toggle instead. Primary and grayscale buttons\nuse the primary palette role; accent buttons use the second tone; success, danger, info and warning buttons use their semantic color. Disabled and\nnoninteractive buttons do not emit. Pointer focus alone does not keep an action illuminated after the pointer leaves; focus stays on the native control and\nkeyboard focus remains visible. Touch does not latch hover illumination. No additional effects directive or lighting configuration is needed.</p>\n<p>Selected actions also retain an inset contour independently of lighting or transparency. Selected text buttons underline their label. These cues track the same\nARIA selection states and do not change the hit target or label dimensions.</p>\n<p>Filled buttons retain their semantic background and paired foreground color across translucency settings and reduced transparency, including hover and press.\nFilled actions use an opaque palette fill and a foreground matched to each interaction state. Surface lighting remains active; tonal and outlined actions retain\ntranslucency. Text buttons have no background, border, shadow or backdrop blur; hover underlines the label and keyboard focus retains a visible outline. Tonal\nand outlined buttons keep their glass backing.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<p>Press feedback keeps button labels and icons undistorted. Translucent glass buttons deepen their existing inset reflection and gather a soft theme-colored\nsheen; solid filled and floating actions use their semantic pressed color. The shared pressure spring returns the material to rest, including quick taps. The\nhit area, text geometry, layout, and overlay origin stay fixed. Release, cancellation, blur, and removal clear pressure. Text buttons and surface opt-outs\nretain native press feedback.</p>\n<table>\n<thead>\n<tr>\n<th>CSS variable</th>\n<th>Default / behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--bx-button-press-shadow</code></td>\n<td>Semantic inset shadow for translucent buttons; <code>none</code> for solid filled/floating actions</td>\n</tr>\n<tr>\n<td><code>--bx-glass-press-opacity</code></td>\n<td><code>0.6</code> for translucent buttons; <code>0</code> for solid filled/floating actions</td>\n</tr>\n</tbody></table>\n<p>The former <code>--bx-button-press-compression</code> and <code>--bx-button-press-offset</code> content effects have been removed deliberately; remove those overrides when migrating.\nCustomize the supported material variables instead. Reduced motion keeps static color/inset/underline feedback. Reduced transparency retains the opaque pressed\nappearance. Forced colors preserve a visible pressed outline; disabled and noninteractive controls do not illuminate.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use the native <code>button[bx-button]</code> selector for actions and <code>a[bx-button]</code> with a real <code>href</code> for navigation. Give icon-only actions an accessible label.\nDisabled actions do not emit an action through a click listener.</p>\n<p><code>surfaceEffects</code> defaults to <code>true</code>. Set <code>[surfaceEffects]=&quot;false&quot;</code> for dense collections such as the icon catalog to retain Blocks button styling, theme\nupdates, focus, loading and disabled behavior without mounting per-button runtime glass lighting or deformation. It can be changed while mounted. An explicitly\napplied <code>bxSurface</code> directive continues to own its surface independently.</p>\n<h3>Motion and material response</h3>\n<p>Surface-backed buttons reuse the existing pressure spring on their material, with fixed text and icon geometry. Repeated presses remain responsive, and reduced\nmotion retains static press feedback. Inspect <code>/components/button</code>.</p>\n<p>Filled/floating intent emits more strongly than outlined, tonal, icon, or grayscale intent. Danger and warning receive modest semantic emphasis. This local\ncalibration uses the existing surface engine and leaves environmental reception independent; original fills, colors, and public appearance inputs remain intact.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/button</code> for filled, tonal, text, icon, outlined, floating, disabled, and runtime-effects-disabled examples with observable action results.\nPress and release with mouse, touch, Enter, or Space, then move the pointer away while leaving focus on the button to inspect its resting state. The global\nAppearance controls also exercise theme, translucency, and reduced-motion changes.</p>\n<h2>Asynchronous actions</h2>\n<p><code>loading</code> enables a spinner, exposes <code>aria-busy</code>, and disables activation independently from the <code>disabled</code> input. When loading ends, the original disabled\nstate is retained. The spinner appears before the text and replaces a projected Blocks icon at its original size, including under page zoom or surface\ntransforms. An icon-only button retains its accessible name and dimensions.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;button&quot;</span> <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;filled&quot;</span> [<span class="hljs-attr">loading</span>]=<span class="hljs-string">&quot;saving()&quot;</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;save()&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-icon</span> <span class="hljs-attr">name</span>=<span class="hljs-string">&quot;save&quot;</span> <span class="hljs-attr">size</span>=<span class="hljs-string">&quot;20&quot;</span> /&gt;</span>Save changes<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<p>For another icon implementation, import <code>ButtonIconDirective</code> and mark its element <code>bxButtonIcon</code>. Plain text buttons get an icon-sized spinner only during\nloading. Spinner colors inherit the button foreground; <code>BxA11yService</code> removes rotation in reduced-motion mode.</p>\n<p>Open <code>/components/button-loading</code> for fake asynchronous actions with and without icons. Application code owns the promise and loading state.</p>\n',
  'projects/blocks/forms/components/checkbox-indicator/README.md':
    '<h1>Checkbox indicator</h1>\n<p>The reusable, decorative checkbox face used by Blocks checkbox controls and multiselect options. Supports unchecked, checked and partial selection using Blocks\nsurfaces and icons.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">CheckboxIndicator</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<p>Add <code>CheckboxIndicator</code> to the standalone component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;button&quot;</span> <span class="hljs-attr">role</span>=<span class="hljs-string">&quot;checkbox&quot;</span> [<span class="hljs-attr">attr.aria-checked</span>]=<span class="hljs-string">&quot;partial() ? &#x27;mixed&#x27; : selected()&quot;</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;toggleSelection()&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-checkbox-indicator</span> [<span class="hljs-attr">checked</span>]=<span class="hljs-string">&quot;selected()&quot;</span> [<span class="hljs-attr">indeterminate</span>]=<span class="hljs-string">&quot;partial()&quot;</span> /&gt;</span>\n    Select all locations\n<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<p>Use <code>Checkbox</code> for a standalone form control. Use this indicator inside an existing interactive control whose semantics and events are already managed.</p>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Input</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>checked</code></td>\n<td><code>false</code></td>\n<td>Shows the Blocks check icon and accent face.</td>\n</tr>\n<tr>\n<td><code>indeterminate</code></td>\n<td><code>false</code></td>\n<td>Shows the Blocks minus icon and accent face; takes precedence over checked.</td>\n</tr>\n<tr>\n<td><code>invalid</code></td>\n<td><code>false</code></td>\n<td>Uses validation colors from the theme.</td>\n</tr>\n<tr>\n<td><code>disabled</code></td>\n<td><code>false</code></td>\n<td>Suppresses the active surface finish; the owner provides disabled semantics and opacity.</td>\n</tr>\n<tr>\n<td><code>emissive</code></td>\n<td><code>false</code></td>\n<td>Enables shared lighting for an owning interactive control. <code>Checkbox</code> enables it by default; multiselect indicators remain passive.</td>\n</tr>\n</tbody></table>\n<h2>Appearance and customization</h2>\n<p>Uses the same shared surface and choice finish as <code>Checkbox</code>. <code>--bx-checkbox-size</code> customizes its dimensions (default <code>1.125rem</code>). Semantic tokens control\ncolors and radius; theme and appearance changes update mounted indicators. Motion follows the shared accessibility styles. Forced colors and high contrast\nflatten the decorative finish.</p>\n<h2>Behavior and accessibility</h2>\n<p>The indicator is always hidden from assistive technology, has no tab stop and does not handle pointer or keyboard input. With <code>emissive</code> enabled, its face\nparticipates in hit testing so the shared engine can illuminate the owning control; events still reach that control. The owner must supply an accessible label,\nvisible focus, checked/mixed state, readonly/disabled handling and keyboard interaction. Multiselect uses listbox option semantics for each row and checkbox\nsemantics for the select-all action without nested interactive elements.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/checkbox-indicator</code> for live unchecked, checked and partial states controlled by Blocks checkboxes. <code>/components/checkbox</code> and\n<code>/components/multi-select</code> demonstrate its integration.</p>\n',
  'projects/blocks/forms/components/checkbox/README.md':
    '<h1>Checkbox</h1>\n<p>A boolean choice integrated with Angular forms.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Checkbox</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-checkbox</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Receive updates&quot;</span> [<span class="hljs-attr">formControl</span>]=<span class="hljs-string">&quot;updates&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p>The control uses Angular 22 native signal control contracts. Use <code>[formField]</code>, <code>[formControl]</code>, <code>formControlName</code>, <code>[(ngModel)]</code>, or standalone <code>[(checked)]</code>.\nShared presentation includes labels, hints, tooltips, required/readonly/disabled state, error policies and typed message resolvers. See the\n<a href="components/signal-forms">forms guide</a> for validation, submission, translations and compatibility.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use a visible label. Space toggles the native input; focus and checked state remain visible in glass and solid modes. The control supports validation and\ntouched state.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/checkbox</code> for a working example and its current value or action result.</p>\n<h2>Selection configuration</h2>\n<p><code>indeterminate</code> is a boolean model with <code>indeterminateChange</code>. <code>clickAction</code> supports <code>check-indeterminate</code> (default), <code>check</code>, and <code>noop</code>. <code>labelPosition</code> is\n<code>before</code> or <code>after</code>. Use <code>checkedChange</code> or the Angular field value to observe changes. Required-true validation is reflected in required decoration and\naccessible state.</p>\n<p><code>emissive</code> defaults to <code>true</code>. Hover, keyboard focus, checked and indeterminate states use the shared accent lighting; invalid controls use validation colors.\nDisabled and readonly checkboxes remain passive. Set <code>[emissive]=&quot;false&quot;</code> to keep the themed face without emitting light. Multiselect indicators are passive by\ndefault and retain their row&#39;s selection appearance.</p>\n<p>The checkbox face is shared with multiselect through the public <a href="components/checkbox-indicator">CheckboxIndicator</a> component. <code>--bx-checkbox-size</code> changes its\ndimensions (default <code>1.125rem</code>).</p>\n',
  'projects/blocks/forms/components/error/README.md':
    '<h1>Error message</h1>\n<p>A projected custom error message inside a form-field.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxError</span>, <span class="hljs-title class_">FormField</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<p>Add the standalone component to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-form-field</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Reference&quot;</span> <span class="hljs-attr">forId</span>=<span class="hljs-string">&quot;reference&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">input</span> <span class="hljs-attr">id</span>=<span class="hljs-string">&quot;reference&quot;</span> <span class="hljs-attr">aria-describedby</span>=<span class="hljs-string">&quot;reference-error&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-error</span> <span class="hljs-attr">id</span>=<span class="hljs-string">&quot;reference-error&quot;</span>&gt;</span>Enter at least three characters.<span class="hljs-tag">&lt;/<span class="hljs-name">bx-error</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-form-field</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>BxError</code> is a content projection component with selector <code>bx-error</code>. It has no inputs; the form field projects it into its error region.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Render only when validation should be shown. Tie the input to the error ID with <code>aria-describedby</code> and update <code>aria-invalid</code> as needed. This component does not\nrun validation.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/error</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/forms/components/form-field/README.md':
    '<h1>Form field</h1>\n<p>A shared label, help text, validation and loading frame for controls.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">FormField</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-form-field</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Project name&quot;</span> <span class="hljs-attr">forId</span>=<span class="hljs-string">&quot;project&quot;</span> [<span class="hljs-attr">required</span>]=<span class="hljs-string">&quot;true&quot;</span> [<span class="hljs-attr">error</span>]=<span class="hljs-string">&quot;error&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">input</span> <span class="hljs-attr">id</span>=<span class="hljs-string">&quot;project&quot;</span> (<span class="hljs-attr">input</span>)=<span class="hljs-string">&quot;update($event)&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-form-field</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>label</code>, <code>tooltip</code>, <code>error</code>: text or a translation key object. <code>forId</code>: the native input ID. <code>required</code>, <code>loading</code>: booleans. Projects the control and an\noptional <code>bx-error</code>.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<p><code>--bx-field-padding-bottom</code> overrides the field wrapper’s bottom padding (default: <code>0</code>). Set it on a group of controls when additional row spacing is needed.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Set <code>forId</code> to the actual input ID. Required decoration does not add validation to your control; apply the corresponding validator and native required\nattribute. Associate custom error text with <code>aria-describedby</code> when projecting your own control.</p>\n<p>The information button reveals short help on mouse hover or keyboard focus, and toggles it on touch tap. Tap elsewhere, scroll, or press Escape to dismiss it.\nIts description also remains available to screen readers when the visual help is hidden. Keep essential field instructions visible rather than relying on the\nhelp button.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/form-field</code> for a working example and its current value or action result.</p>\n<h2>Composable support and control registration</h2>\n<p><code>hint</code>, <code>hintEnd</code>, projected <code>bx-hint</code>, <code>bxPrefix</code>, and <code>bxSuffix</code> add support and adornments. <code>subscriptSizing</code> selects fixed or dynamic reserved space.\nDynamic sizing collapses an empty supporting-text region and its gap, allowing controls to align with adjacent buttons and checkboxes. <code>hideRequiredMarker</code>\nhides decoration without changing validation. <code>tooltipLabel</code> provides translated accessible help-button text.</p>\n<p>A registered control supplies its state through <code>BX_FORM_FIELD_CONTROL</code> and <code>IFormFieldControl</code>, or the <code>control</code> input. The frame discovers projected\nregistrations, resolves error visibility, associates its supporting-text region and native control, and announces errors politely. The <code>bxInput</code> directive\nsupplies this registration for native controls.</p>\n<p>Built-in convenience controls forward projected rich errors and hints into their internal frame. See the <a href="components/signal-forms">forms guide</a> for global error\npolicies, messages and form-system compatibility.</p>\n',
  'projects/blocks/forms/components/hint/README.md':
    '<h1>Field hint</h1>\n<p>Composable content and native integration for the shared field frame.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxHint</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-input-field</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Reference&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-hint</span>&gt;</span>Public identifier<span class="hljs-tag">&lt;/<span class="hljs-name">bx-hint</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-input-field</span>&gt;</span></code></pre>\n<h2>API and behavior</h2>\n<p>Use <code>align=&quot;start&quot;</code> or <code>align=&quot;end&quot;</code> for projected supporting content. Convenience fields also accept <code>hint</code> and <code>hintEnd</code> as translated text. Descriptions are\nconnected automatically and replaced by visible errors.</p>\n<h2>Appearance and accessibility</h2>\n<p>Uses Blocks semantic tokens and the active <code>ThemingService</code> configuration. Customize through documented inputs, templates and CSS variables. Existing components\nupdate when the application theme changes. Keyboard focus, forced colors, reduced transparency and <code>BxA11yService</code> reduced-motion preferences remain supported.</p>\n<p>Text inputs accept <code>ResolvableText</code>: plain text or <code>{ key: &#39;translation.key&#39; }</code>. With <code>BX_I18N</code>, text is resolved reactively, including already-mounted controls\nwhen the adapter&#39;s <code>version</code> signal changes. Plain text works without an adapter.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/hint</code> for working field composition and compatibility examples.</p>\n',
  'projects/blocks/forms/components/input-field/README.md':
    '<h1>Input field</h1>\n<p>A text, date or numeric input with a floating label and validation feedback.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">InputField</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-input-field</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Project name&quot;</span> [<span class="hljs-attr">formControl</span>]=<span class="hljs-string">&quot;name&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p>The control uses Angular 22 native signal control contracts. Use <code>[formField]</code>, <code>[formControl]</code>, <code>formControlName</code>, <code>[(ngModel)]</code>, or standalone <code>[(value)]</code>.\nShared presentation includes labels, hints, tooltips, required/readonly/disabled state, error policies and typed message resolvers. See the\n<a href="components/signal-forms">forms guide</a> for validation, submission, translations and compatibility.</p>\n<p><code>type</code>: text, password, email, number, date, time, datetime-local. Numeric controls accept <code>min</code>, <code>max</code>, and <code>step</code>.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use a label and an appropriate input type. Number input emits a number or null when empty. Validators should enforce application constraints, including minimum\nand maximum values.</p>\n<p>Labels stay on one line and truncate with an ellipsis when space is limited, without overlapping the value or trailing actions. A truncated label shows its full\ntext through the Blocks tooltip on hover, keyboard focus within the input, or a long press on the label. Resizing and language changes update truncation\nautomatically. The full label remains the input&#39;s accessible name, and required markers remain visible. Suffixes and numeric steppers share a trailing action\ncontainer aligned to the inline end.</p>\n<p>Label ellipsis and measurement reuse the shared <a href="components/truncate">TruncateDirective</a>, including content, font, and viewport\nupdates. Set <code>[tooltipOnTruncate]=&quot;false&quot;</code> to disable the automatic label tooltip without disabling ellipsis. Its default inherits\n<code>FormSettingsService.settings().tooltipOnTruncate</code>, then true.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/input-field</code> for a working example and its current value or action result.</p>\n<h2>Extended input API</h2>\n<p><code>autocomplete</code>, <code>inputmode</code>, <code>spellcheck</code>, <code>name</code>, length and pattern constraints, <code>ariaLabelledBy</code>, <code>ariaDescribedBy</code> and explicit <code>id</code> reach the native\nelement. Supported text types include <code>tel</code>, <code>url</code> and <code>search</code>. <code>multiline</code> enables a textarea; <code>rows</code>, <code>autosize</code>, <code>minRows</code>, and <code>maxRows</code> configure it.\nComposition input and autofill maintain floating-label behavior.</p>\n<p>Number input preserves parse errors through Angular&#39;s <code>transformedValue</code>, keeps empty values as null, and supports keyboard-accessible steppers. <code>decreaseLabel</code>\nand <code>increaseLabel</code> are translatable. <code>appearance</code> (<code>fill</code> or <code>outline</code>), <code>floatLabel</code>, <code>hideRequiredMarker</code>, <code>subscriptSizing</code>, <code>hint</code> and <code>hintEnd</code> customize\nthe frame. Prefix/suffix and rich errors can be projected directly into the convenience component.</p>\n<p>Prefix/suffix content uses <code>--bx-field-adornment-padding</code> and <code>--bx-field-adornment-gap</code>, so text such as # and ID remains inset from the field edges.\nSupporting text uses <code>--bx-field-support-padding</code>.</p>\n',
  'projects/blocks/forms/components/multi-select/README.md':
    '<h1>Multiselect</h1>\n<p>Checkbox-style multiple selection with remote pagination and explicit select-all intent.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">MultiSelect</span>, <span class="hljs-title class_">IBxSelectOption</span>, <span class="hljs-title class_">ISelectAllChange</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-multi-select</span>\n    <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Workspaces&quot;</span>\n    [<span class="hljs-attr">options</span>]=<span class="hljs-string">&quot;options()&quot;</span>\n    [<span class="hljs-attr">formField</span>]=<span class="hljs-string">&quot;account.workspaces&quot;</span>\n    [<span class="hljs-attr">loading</span>]=<span class="hljs-string">&quot;loading()&quot;</span>\n    [<span class="hljs-attr">hasMore</span>]=<span class="hljs-string">&quot;hasMore()&quot;</span>\n    [<span class="hljs-attr">loadError</span>]=<span class="hljs-string">&quot;loadError()&quot;</span>\n    [<span class="hljs-attr">isSearchable</span>]=<span class="hljs-string">&quot;true&quot;</span>\n    [<span class="hljs-attr">externalFiltering</span>]=<span class="hljs-string">&quot;true&quot;</span>\n    [<span class="hljs-attr">selectionScope</span>]=<span class="hljs-string">&quot;query()&quot;</span>\n    (<span class="hljs-attr">search</span>)=<span class="hljs-string">&quot;search($event)&quot;</span>\n    (<span class="hljs-attr">loadMore</span>)=<span class="hljs-string">&quot;loadNext($event)&quot;</span>\n    (<span class="hljs-attr">selectAllIntentChange</span>)=<span class="hljs-string">&quot;handleSelectAll($event)&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p>Shares single-select options, comparison, templates, field presentation and pagination inputs. Bind <code>[formField]</code>, <code>[formControl]</code>, <code>formControlName</code>,\n<code>[(ngModel)]</code>, or standalone <code>[(value)]</code>. Form models should initialize the field with <code>[]</code>.</p>\n<p><code>showSelectAll</code> defaults to true. <code>selectAllLabel</code> is translatable. <code>selectAll</code> is a boolean model for intent; <code>selectAllChange</code> is its boolean model event.\n<code>selectAllIntentChange</code> emits the detailed <code>ISelectAllChange&lt;T&gt;</code> with selected intent, scope, loaded values and reason. <code>selectionScope</code> defaults to the current\nsearch term.</p>\n<p><code>selectionChange</code> emits <code>{ value, source }</code>; sources distinguish <code>user</code>, <code>select-all</code>, and automatic <code>page</code> selection. Standard value changes remain available\nthrough the chosen Angular form API or <code>valueChange</code>.</p>\n<h2>Select-all semantics</h2>\n<p>Enabling select all selects eligible loaded options. Future eligible options in the same scope are selected as pages arrive. Disabled options and disabled\ngroups are excluded.</p>\n<p>Unchecking an option disables select-all intent, removes only that value, retains other selections, and emits an <code>item-deselected</code> intent event. Future pages\nare no longer automatically selected. Explicitly turning select all off removes eligible current-scope selections while retaining unrelated selections.</p>\n<p>A scope change ends select-all intent and emits <code>scope-change</code>, retaining explicit selections. Reset clears intent and emits <code>reset</code>. Loaded selected values are\nfinite: the application uses intent plus scope when an API needs to select the entire remote result set. Do not send the loaded array as if it enumerated every\nremote record.</p>\n<h2>Behavior</h2>\n<p>The panel stays open while selecting. Arrow keys, Home/End, typeahead, Enter/Space, Escape and Tab support keyboard interaction. Visual checkboxes are\nnon-interactive indicators inside listbox options, avoiding nested checkbox focus targets. <code>compareWith</code> supports stable object-value identity across API\nresponses.</p>\n<p>After the closing transition completes, the shared selection base releases the panel overlay and its tracking resources. Reopening resolves the current\nordinary/top-layer context while retaining the selected values and search term. Top-layer panels use measured positioning to follow nested scrolling.</p>\n<p>Pagination and failure/retry use the shared <a href="components/load-more">load-more directive</a>. Existing items stay visible during incremental requests\nand after failed pages. The application owns request cancellation and page/cursor state.</p>\n<h2>Appearance and accessibility</h2>\n<p>Uses Blocks semantic tokens and the active <code>ThemingService</code> configuration. Customize through documented inputs, templates and CSS variables. Existing components\nupdate when the application theme changes. Keyboard focus, forced colors, reduced transparency and <code>BxA11yService</code> reduced-motion preferences remain supported.</p>\n<p>Text inputs accept <code>ResolvableText</code>: plain text or <code>{ key: &#39;translation.key&#39; }</code>. With <code>BX_I18N</code>, text is resolved reactively, including already-mounted controls\nwhen the adapter&#39;s <code>version</code> signal changes. Plain text works without an adapter.</p>\n<h3>Motion and material response</h3>\n<p>The shared selection base supplies restrained overlay materialization and a traveling focused-row surface. Multiple selected rows retain their checkmarks and\nsemantic fill; hover/focus movement never changes the selected values. Motion follows the actual scroll content and uses the existing surface renderer. Reduced\nmotion snaps geometry; existing disabled/readonly, asynchronous pagination, retry, and focus behavior remain in force. Inspect <code>/components/multi-select</code>.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/multi-select</code>. Enable select all, load another page, deselect one item and load again. Selection and intent events are shown separately. The\npage includes fake requests, failure/retry, page-size controls and live translation changes.</p>\n<h2>Selected-value summaries</h2>\n<p><code>allSelectedText</code> replaces the listed values while select-all intent is enabled, for example <code>All locations</code> or <code>{ key: &#39;locations.all&#39; }</code>. This is separate\nfrom <code>selectAllLabel</code>, which names the select-all action inside the panel.</p>\n<p><code>summaryThreshold</code> defaults to 2 and is clamped to a minimum of 2. More selections than the threshold use <code>selectedCountText</code>, whose default is\n<code>{count} selected</code>. Supply <code>{count} locations selected</code> or a translation key; the translation adapter receives <code>{ count }</code>.</p>\n<p>When at least two selected labels cannot fit the available width, the count summary is also used below the configured threshold. A tooltip on hover, keyboard\nfocus, or touch-and-hold exposes the full loaded selection. A custom <code>triggerTemplate</code> remains available for completely custom presentation.</p>\n<p>The searchable playground includes 24 locations, tag-display controls and a summary-threshold control next to the page-size selector. Search terms remain\nvisible and consistent with their results after closing and reopening the panel. The trigger&#39;s caret slot displays busy state without changing its dimensions.</p>\n<h2>Tags</h2>\n<p>Set <code>selectionDisplay=&quot;tags&quot;</code> to use the separate Blocks <code>Tag</code> component for selected values. <code>visibleTagCount</code> defaults to one; additional selections are\nrepresented by <code>tagOverflowText</code> (<code>+{count}</code> by default) with a tooltip listing their names. Customize ordinary tags with <code>tagConfig</code>, individual options with\n<code>option.tagConfig</code>, and the overflow tag with <code>overflowTagConfig</code>. Embedded tags have no separate tab stop; the combobox supplies the full selection description\nfor keyboard access. <code>allSelectedText</code> remains the caption when select-all intent is active.</p>\n<p>An ordinary tag automatically shows its full label on hover or touch-and-hold only when that label is clipped. Explicit tooltip descriptions and overflow-tag\nlists remain available independently of clipping. The combobox retains the complete selection tooltip for keyboard users, including a single clipped tag. In tag\nmode, touch tooltips belong to the tags so they do not overlap a parent tooltip. Labels, plain values, and the full-selection fit test all reuse\n<code>TruncateDirective</code>. <code>[tooltipOnTruncate]=&quot;false&quot;</code> disables automatic selection/truncation tooltips while preserving clipping, summary behavior, and explicit\noverflow-tag descriptions. This setting inherits <code>FormSettingsService</code> defaults and also suppresses automatic tooltips on ordinary embedded tags.</p>\n<h2>Search loading</h2>\n<p>The debounce/request period hides pagination actions and old results. Provide <code>loadingLabel</code> for centered loading text; without it, a simple centered spinner is\nshown. <code>loadingAriaLabel</code> supplies a translatable accessible name. Once results arrive, filtered pages can be paginated normally.</p>\n<h2>Option spacing</h2>\n<p>Rounded option rows have a small gap, shared by select and multiselect. Set <code>--bx-select-option-gap</code> on the control to customize it (default: Blocks\n<code>spacing(1)</code>). All built-in selection and caret icons use Blocks <code>Icon</code>; searching uses Blocks <code>SearchInput</code>.</p>\n<p>Option and select-all checkboxes reuse the public <code>CheckboxIndicator</code> component, including its indeterminate state and themed finish. Indicators remain\nnon-emissive; the option button owns selection and interaction. Form checkboxes outside multiselect enable emission by default. <code>--bx-checkbox-size</code> customizes\nindicator dimensions without changing keyboard behavior.</p>\n<p>The select-all checkbox also shows checked when every selectable loaded row is individually selected, including deselecting and reselecting the last missing\nrow. Disabled rows and disabled groups do not contribute to this state. Clicking a checked header clears the eligible loaded rows. This finite visual state does\nnot activate remote select-all intent: future pages remain unselected unless the explicit select-all action enabled intent.</p>\n<h2>Clearing selection</h2>\n<p>A Blocks × icon button appears before the dropdown/loading indicator, with equal spacing between the action and the selected text/tags and between the two\nicons, when a selection exists. Its reserved space prevents overlap with selected text or tags. Set <code>[clearable]=&quot;false&quot;</code> to hide it, or use <code>clearLabel</code>\n(<code>ResolvableText</code>, default <code>&#39;Clear selection&#39;</code>) to customize its accessible name. <code>clearTooltip</code> accepts its own <code>ResolvableText</code>, defaults to the resolved\n<code>clearLabel</code> when omitted, and can be set to an empty string to hide the tooltip.</p>\n<p><code>clearSelection()</code> performs the same guarded action programmatically. Clearing closes the panel, marks the control touched and returns focus to the combobox; it\npreserves Angular&#39;s blur/submit update policy. The action is hidden while readonly and disabled when the control is disabled. Keyboard users can Tab to the\naction and activate it with Enter or Space.</p>\n<p>Clearing writes <code>[]</code>, disables future-page select-all intent and emits <code>selectionChange</code> with <code>{ value: [], source: &#39;clear&#39; }</code>. If intent was enabled,\n<code>selectAllIntentChange</code> also emits with <code>selected: false</code> and <code>reason: &#39;clear&#39;</code>. Required controls continue to use the existing validation policy.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-multi-select</span> [<span class="hljs-attr">options</span>]=<span class="hljs-string">&quot;locations&quot;</span> [<span class="hljs-attr">clearLabel</span>]=<span class="hljs-string">&quot;{ key: &#x27;locations.clearAction&#x27; }&quot;</span> [<span class="hljs-attr">clearTooltip</span>]=<span class="hljs-string">&quot;{ key: &#x27;locations.clearTooltip&#x27; }&quot;</span> /&gt;</span></code></pre>\n<p>Use <code>[clearable]=&quot;false&quot;</code> for required selections that must retain a value or for lists with an explicit “None” option. This input controls the clear action\nindependently of validation; <code>required</code> continues to enforce form validity. The select/multiselect playground includes an “Allow clearing selection” switch;\nconfiguration controls such as page size deliberately hide the clear action.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-multi-select</span> [<span class="hljs-attr">options</span>]=<span class="hljs-string">&quot;options&quot;</span> [<span class="hljs-attr">clearable</span>]=<span class="hljs-string">&quot;false&quot;</span> /&gt;</span></code></pre>\n<h2>Select-all tooltip</h2>\n<p><code>allSelectedTooltip</code> accepts the tooltip text for active <code>selectAll</code> intent, including the trigger&#39;s keyboard tooltip and the “all selected” tag&#39;s hover/touch\ntooltip. Pass <code>false</code> or an empty string to disable both. This also prevents the tag&#39;s automatic clipped-label tooltip or <code>tagConfig.tooltip</code> from replacing\ndisabled feedback. Ordinary finite selections keep their existing tooltip behavior when intent ends.</p>\n<p>Omitting the input preserves the list of loaded selected labels, subject to <code>tooltipOnTruncate</code>. Those labels describe only loaded items. For remote “ALL”\nselection, disable that feedback or supply application-owned text representing the full selectable scope:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-multi-select</span> [<span class="hljs-attr">options</span>]=<span class="hljs-string">&quot;loadedLocations&quot;</span> [(<span class="hljs-attr">value</span>)]=<span class="hljs-string">&quot;selected&quot;</span> [(<span class="hljs-attr">selectAll</span>)]=<span class="hljs-string">&quot;allSelected&quot;</span> <span class="hljs-attr">allSelectedText</span>=<span class="hljs-string">&quot;All locations&quot;</span> [<span class="hljs-attr">allSelectedTooltip</span>]=<span class="hljs-string">&quot;false&quot;</span> /&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-multi-select</span>\n    [<span class="hljs-attr">options</span>]=<span class="hljs-string">&quot;loadedLocations&quot;</span>\n    [(<span class="hljs-attr">value</span>)]=<span class="hljs-string">&quot;selected&quot;</span>\n    [(<span class="hljs-attr">selectAll</span>)]=<span class="hljs-string">&quot;allSelected&quot;</span>\n    <span class="hljs-attr">allSelectedText</span>=<span class="hljs-string">&quot;All locations&quot;</span>\n    [<span class="hljs-attr">allSelectedTooltip</span>]=<span class="hljs-string">&quot;allLocationsTooltip()&quot;</span> /&gt;</span></code></pre>\n<p>Compute <code>allLocationsTooltip</code> in the application using its API&#39;s total of selectable results. For example, return\n<code>&#39;All &#39; + pagination.selectableTotal + &#39; locations&#39;</code> or call the application&#39;s translation service with the total. Exclude disabled options and disabled groups\nacross the whole result set, including unloaded pages. Do not subtract only the disabled items on the current page or substitute the loaded selected count for a\nremote total. If the API does not provide enough information, disable the tooltip or use a general description such as “All matching locations”.</p>\n<p>The component accepts <code>ResolvableText</code>, so simple translation keys also work and react to <code>BX_I18N</code> version changes. Interpolation, pluralization, total\ncalculation and any more complex translation logic belong to the application; the component has no tooltip-parameters or pagination-total API. Updating the\nsupplied text refreshes mounted tooltips. Explicit custom tooltips work independently of automatic <code>tooltipOnTruncate</code> feedback; <code>false</code> disables only\nselect-all feedback.</p>\n<p>The playground defaults to application-formatted text using the fake API&#39;s <code>selectableTotal</code>: 23 selectable locations across 24 results, excluding disabled\nVienna even before its page loads. The total follows search scope. <strong>Select-all tooltip</strong> also demonstrates custom finished text, disabled feedback and the\noptional loaded-label compatibility behavior, in text and tag display.</p>\n',
  'projects/blocks/forms/components/radio-button/README.md':
    '<h1>Radio</h1>\n<p>A single choice within a named group.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Radio</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-radio</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Daily&quot;</span> <span class="hljs-attr">name</span>=<span class="hljs-string">&quot;frequency&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;daily&quot;</span> [<span class="hljs-attr">formControl</span>]=<span class="hljs-string">&quot;frequency&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-radio</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Weekly&quot;</span> <span class="hljs-attr">name</span>=<span class="hljs-string">&quot;frequency&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;weekly&quot;</span> [<span class="hljs-attr">formControl</span>]=<span class="hljs-string">&quot;frequency&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p>Legacy individually bound radios support <code>[formControl]</code>, <code>formControlName</code>, and <code>[(ngModel)]</code>. For new forms, bind a <code>RadioGroup</code> with <code>[formField]</code> or an\nexisting Angular form directive, and keep each radio value as its option value. See the <a href="components/radio-group">radio-group guide</a>.</p>\n<p><code>value</code> is required and identifies this option. <code>name</code> groups the native radio inputs.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<p>Selected radios keep emitting the theme color after pointer release and blur. Hovering the circle or its label highlights the surface and emits color; disabled\ncontrols do neither.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use the same form control and name for mutually exclusive options, distinct values, and visible labels. A fieldset with a legend gives the group an accessible\nname.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/radio</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/forms/components/radio-group/README.md':
    '<h1>Radio group</h1>\n<p>Owns one typed form value, group labeling, validation and disabled/readonly state for radio options.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">RadioGroup</span>, <span class="hljs-title class_">Radio</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-radio-group</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Plan&quot;</span> [<span class="hljs-attr">formField</span>]=<span class="hljs-string">&quot;account.plan&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-radio</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Personal&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;personal&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-radio</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Team&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;team&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-radio-group</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p>Bind the group through <code>[formField]</code>, <code>[formControl]</code>, <code>formControlName</code>, <code>[(ngModel)]</code>, or standalone <code>[(value)]</code>. Individual options retain their option\n<code>value</code>; avoid binding both the group and its children to form controls.</p>\n<p>Shared field inputs configure labels, hints, errors, visibility policy, readonly and required state. The group generates a shared native name unless <code>name</code> is\nprovided. Legacy individually bound radio controls remain supported.</p>\n<h2>Behavior</h2>\n<p>Native radio semantics provide arrow navigation and one selected option. A disabled group disables its children; readonly blocks changes. Validation is\npresented once at group level. Focus delegation targets an available native radio.</p>\n<h2>Appearance and accessibility</h2>\n<p>Uses Blocks semantic tokens and the active <code>ThemingService</code> configuration. Customize through documented inputs, templates and CSS variables. Existing components\nupdate when the application theme changes. Keyboard focus, forced colors, reduced transparency and <code>BxA11yService</code> reduced-motion preferences remain supported.</p>\n<p>Text inputs accept <code>ResolvableText</code>: plain text or <code>{ key: &#39;translation.key&#39; }</code>. With <code>BX_I18N</code>, text is resolved reactively, including already-mounted controls\nwhen the adapter&#39;s <code>version</code> signal changes. Plain text works without an adapter.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/radio-group</code>, where the group participates in the complete Signal Forms example.</p>\n',
  'projects/blocks/forms/components/range-slider/README.md':
    '<h1>Range slider</h1>\n<p>Two constrained range thumbs bound to a <code>[number, number]</code> form value.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">RangeSlider</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-range-slider</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Budget&quot;</span> [(<span class="hljs-attr">value</span>)]=<span class="hljs-string">&quot;range&quot;</span> [<span class="hljs-attr">min</span>]=<span class="hljs-string">&quot;0&quot;</span> [<span class="hljs-attr">max</span>]=<span class="hljs-string">&quot;100&quot;</span> [<span class="hljs-attr">step</span>]=<span class="hljs-string">&quot;10&quot;</span> [<span class="hljs-attr">discrete</span>]=<span class="hljs-string">&quot;true&quot;</span> [<span class="hljs-attr">showTickMarks</span>]=<span class="hljs-string">&quot;true&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p>Supports Angular forms and standalone value binding. <code>min</code>, <code>max</code>, and <code>step</code> configure the range. <code>discrete</code> shows formatted values; <code>displayWith(value)</code>\ncustomizes display and accessible value text. <code>startLabel</code> and <code>endLabel</code> are translatable thumb names. <code>showTickMarks</code> shows bounded tick indicators.</p>\n<p>Ticks mark actual step values and are centered on the thumbs&#39; travel, including ranges where the step does not divide the span evenly. The selection fill uses\nthe same thumb centers in LTR and RTL. Set <code>--bx-slider-thumb-size</code> to customize both native and decorative thumbs together; it defaults to the shared\n<code>spacing(6)</code> token, and the fill and tick insets follow that size.</p>\n<p>Each bordered glass thumb magnifies and blurs the rail below it, including both selection boundaries when the thumbs are close. <code>--bx-slider-magnification</code>\ncontrols the enlargement and defaults to <code>1.5</code>; <code>--bx-slider-lens-blur</code> sets the lens and backdrop blur and defaults to <code>1.5px</code>. The lens follows values,\nresizing, theme changes and RTL without per-frame pixel sampling. Reduced transparency and increased contrast use the opaque fallback; forced colors keeps the\nnative thumbs.</p>\n<p>Thumbs cannot cross. Each thumb retains native keyboard input and an accessible name. Initialize form values with a pair of numbers. Shared hints, errors,\nreadonly and disabled state are supported.</p>\n<h2>Appearance and accessibility</h2>\n<p>Uses Blocks semantic tokens and the active <code>ThemingService</code> configuration. Customize through documented inputs, templates and CSS variables. Existing components\nupdate when the application theme changes. Keyboard focus, forced colors, reduced transparency and <code>BxA11yService</code> reduced-motion preferences remain supported.</p>\n<p>Text inputs accept <code>ResolvableText</code>: plain text or <code>{ key: &#39;translation.key&#39; }</code>. With <code>BX_I18N</code>, text is resolved reactively, including already-mounted controls\nwhen the adapter&#39;s <code>version</code> signal changes. Plain text works without an adapter.</p>\n<h3>Motion and material response</h3>\n<p>Both thumbs reuse the native slider&#39;s enlarged pressed magnifier and spring back to fully opaque resting thumbs without delaying pointer precision or changing\nrange ordering. Horizontal expansion is capped by the actual pixel clearance between thumbs, using cached container geometry, and velocity stretch decreases as\nthe selected interval narrows, preserving clarity when thumbs approach. Release and cancellation settle independently. Live reduced motion removes deformation;\nreduced transparency keeps the existing opaque thumbs. Inspect <code>/components/range-slider</code> with close and overlapping endpoints.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/range-slider</code> for a live pair, labels and ticks.</p>\n<p>The rail shares the normal slider&#39;s border, inset shadow, neutral background and pill radius, with the selected interval filled between the two thumb centers.</p>\n',
  'projects/blocks/forms/components/search-input/README.md':
    '<h1>Search input</h1>\n<p>A searchable text control with one clear action, request loading feedback, and an explicit retry action. Requests and results remain application-owned.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SearchInput</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-search-input</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Find a component&quot;</span> [<span class="hljs-attr">formControl</span>]=<span class="hljs-string">&quot;query&quot;</span> (<span class="hljs-attr">search</span>)=<span class="hljs-string">&quot;filter($event)&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p>The control uses Angular 22 native signal control contracts. Use <code>[formField]</code>, <code>[formControl]</code>, <code>formControlName</code>, <code>[(ngModel)]</code>, or standalone <code>[(value)]</code>.\nShared presentation includes labels, hints, tooltips, required/readonly/disabled state, error policies and typed message resolvers. See the\n<a href="components/signal-forms">forms guide</a> for validation, submission, translations and compatibility.</p>\n<p>Search value/placeholder ellipsis uses the shared <code>TruncateDirective</code>; its native-input measurement accounts for the current font and inline padding.\n<code>[tooltipOnTruncate]=&quot;false&quot;</code> disables automatic clipped-value tooltips while keeping ellipsis and measurement. The default inherits <code>FormSettingsService</code>, then\ntrue.</p>\n<p><code>search</code> emits the current string on input and clear. Public methods <code>clear()</code>, <code>focus()</code>, and <code>retrySearch()</code> support integration. <code>retrySearch()</code> emits\n<code>retry</code> only when a request error exists and the control is editable and idle.</p>\n<table>\n<thead>\n<tr>\n<th>Input/output</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>loading</code></td>\n<td><code>false</code></td>\n<td>Application-owned request state; replaces the search icon with the shared spinner.</td>\n</tr>\n<tr>\n<td><code>pending</code></td>\n<td><code>false</code></td>\n<td>Form validation pending state; also shows busy feedback.</td>\n</tr>\n<tr>\n<td><code>loadError</code></td>\n<td><code>undefined</code></td>\n<td><code>ResolvableText</code> request failure, independent of form validation. Reveals retry immediately.</td>\n</tr>\n<tr>\n<td><code>loadingLabel</code></td>\n<td><code>undefined</code></td>\n<td>Optional visible <code>ResolvableText</code> loading message.</td>\n</tr>\n<tr>\n<td><code>loadingAriaLabel</code></td>\n<td><code>&#39;Searching&#39;</code></td>\n<td><code>ResolvableText</code> announcement when no visible loading message is supplied.</td>\n</tr>\n<tr>\n<td><code>retryLabel</code></td>\n<td><code>&#39;Retry search&#39;</code></td>\n<td><code>ResolvableText</code> retry button text. Remains stable during loading.</td>\n</tr>\n<tr>\n<td><code>retryConfig</code></td>\n<td><code>{}</code></td>\n<td><code>ISearchRetryConfig</code>: optional accessible name, Blocks button variant/color, outline, and CSS classes.</td>\n</tr>\n<tr>\n<td><code>clearLabel</code></td>\n<td><code>&#39;Clear search&#39;</code></td>\n<td><code>ResolvableText</code> accessible clear action name.</td>\n</tr>\n<tr>\n<td><code>autocomplete</code></td>\n<td><code>&#39;off&#39;</code></td>\n<td>Native search autocomplete.</td>\n</tr>\n<tr>\n<td><code>retry</code></td>\n<td>—</td>\n<td>Emits the current query as a string when retry is requested. Does not also emit <code>search</code>.</td>\n</tr>\n<tr>\n<td><code>compact</code></td>\n<td><code>false</code></td>\n<td>Controls compact field presentation. Automatically enabled when a label is provided; otherwise follows this setting.</td>\n</tr>\n</tbody></table>\n<h3>Asynchronous requests</h3>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-search-input</span>\n    <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Find a component&quot;</span>\n    [(<span class="hljs-attr">value</span>)]=<span class="hljs-string">&quot;query&quot;</span>\n    [<span class="hljs-attr">loading</span>]=<span class="hljs-string">&quot;loading()&quot;</span>\n    [<span class="hljs-attr">loadError</span>]=<span class="hljs-string">&quot;loadError()&quot;</span>\n    <span class="hljs-attr">loadingAriaLabel</span>=<span class="hljs-string">&quot;Searching components&quot;</span>\n    <span class="hljs-attr">retryLabel</span>=<span class="hljs-string">&quot;Try again&quot;</span>\n    [<span class="hljs-attr">retryConfig</span>]=<span class="hljs-string">&quot;{ variant: &#x27;tonal&#x27;, color: &#x27;accent&#x27; }&quot;</span>\n    (<span class="hljs-attr">search</span>)=<span class="hljs-string">&quot;runSearch($event)&quot;</span>\n    (<span class="hljs-attr">retry</span>)=<span class="hljs-string">&quot;runSearch($event)&quot;</span> /&gt;</span></code></pre>\n<p>For example, the application can coordinate a promise-returning API with cancellation:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> destroyRef = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">DestroyRef</span>);\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> query = signal&lt;<span class="hljs-built_in">string</span> | <span class="hljs-literal">null</span>&gt;(<span class="hljs-string">&#x27;&#x27;</span>);\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> loading = <span class="hljs-title function_">signal</span>(<span class="hljs-literal">false</span>);\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> loadError = signal&lt;<span class="hljs-built_in">string</span> | <span class="hljs-literal">undefined</span>&gt;(<span class="hljs-literal">undefined</span>);\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> results = signal&lt;<span class="hljs-keyword">readonly</span> <span class="hljs-built_in">string</span>[]&gt;([]);\n<span class="hljs-keyword">private</span> <span class="hljs-attr">request</span>?: <span class="hljs-title class_">AbortController</span>;\n\n<span class="hljs-title function_">constructor</span>(<span class="hljs-params"></span>) {\n  <span class="hljs-variable language_">this</span>.<span class="hljs-property">destroyRef</span>.<span class="hljs-title function_">onDestroy</span>(<span class="hljs-function">() =&gt;</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">request</span>?.<span class="hljs-title function_">abort</span>());\n}\n\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">async</span> <span class="hljs-title function_">runSearch</span>(<span class="hljs-attr">query</span>: <span class="hljs-built_in">string</span>): <span class="hljs-title class_">Promise</span>&lt;<span class="hljs-built_in">void</span>&gt; {\n  <span class="hljs-variable language_">this</span>.<span class="hljs-property">request</span>?.<span class="hljs-title function_">abort</span>();\n  <span class="hljs-keyword">const</span> request = <span class="hljs-keyword">new</span> <span class="hljs-title class_">AbortController</span>();\n  <span class="hljs-variable language_">this</span>.<span class="hljs-property">request</span> = request;\n  <span class="hljs-variable language_">this</span>.<span class="hljs-property">loading</span>.<span class="hljs-title function_">set</span>(<span class="hljs-literal">true</span>);\n  <span class="hljs-variable language_">this</span>.<span class="hljs-property">loadError</span>.<span class="hljs-title function_">set</span>(<span class="hljs-literal">undefined</span>);\n\n  <span class="hljs-keyword">try</span> {\n    <span class="hljs-keyword">const</span> results = <span class="hljs-keyword">await</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">api</span>.<span class="hljs-title function_">search</span>(query, request.<span class="hljs-property">signal</span>);\n\n    <span class="hljs-keyword">if</span> (!request.<span class="hljs-property">signal</span>.<span class="hljs-property">aborted</span>) <span class="hljs-variable language_">this</span>.<span class="hljs-property">results</span>.<span class="hljs-title function_">set</span>(results);\n  } <span class="hljs-keyword">catch</span> {\n    <span class="hljs-keyword">if</span> (!request.<span class="hljs-property">signal</span>.<span class="hljs-property">aborted</span>) <span class="hljs-variable language_">this</span>.<span class="hljs-property">loadError</span>.<span class="hljs-title function_">set</span>(<span class="hljs-string">&#x27;Search failed. Try again.&#x27;</span>);\n  } <span class="hljs-keyword">finally</span> {\n    <span class="hljs-keyword">if</span> (<span class="hljs-variable language_">this</span>.<span class="hljs-property">request</span> === request) <span class="hljs-variable language_">this</span>.<span class="hljs-property">loading</span>.<span class="hljs-title function_">set</span>(<span class="hljs-literal">false</span>);\n  }\n}</code></pre>\n<p>Import <code>DestroyRef</code>, <code>inject</code>, and <code>signal</code> from <code>@angular/core</code>. Supply your application API&#39;s <code>search(query, signal): Promise&lt;readonly string[]&gt;</code>. Add\ndebouncing in the application when useful, and mark loading from the start of that debounce. Keep the previous results during a replacement request or failure;\nreplace them only when the latest request succeeds. A successful empty response is distinct from a failure. Set <code>loading</code> synchronously in the event handler and\nclear <code>loadError</code> when starting a new attempt. The component makes no requests and has no pagination behavior.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<p>The retry action uses the same Blocks <code>Button</code> and <code>LoadingSpinner</code> as select request feedback. Import <code>ISearchRetryConfig</code> from <code>@filip.mazev/blocks/forms</code> for\ntyped presentation settings. Native browser search decorations are suppressed so only the named Blocks clear action appears. Set <code>--bx-search-feedback-gap</code> to\ncustomize the space between the field and its visible status message; it defaults to the shared spacing-2 token and applies equally to initial loading, errors,\nand retry loading.</p>\n<h2>Behavior and accessibility</h2>\n<p>The output is immediate; debounce expensive network searches in the application. Keep a visible or accessible label instead of relying only on placeholder text.</p>\n<p>Busy feedback sets <code>aria-busy</code>, uses a polite status announcement, and preserves the input&#39;s dimensions. Feedback uses a status row followed by the retry\naction. On retry, the error is replaced by <code>loadingLabel</code> or, when absent, <code>loadingAriaLabel</code> as visible searching text. The status row reserves space for both\nmessages so wrapping at narrow widths or zoom does not move the button. The retry button stays mounted in the same position and disabled during its request,\ndisplaying its own spinner without a second input spinner. Retry focuses the input so successful completion keeps focus predictable. Loading allows further\nediting and clearing to cancel or replace a request. Disabled and readonly state prevent clear and retry actions. Readonly mode hides the clear button while\nkeeping the text focusable and selectable. API failures are described by the input without marking the query invalid. Text inputs accept translation keys and\nupdate with the active <code>BX_I18N</code> language.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/search-input</code> for cancellable, debounced fake API requests, loading text, empty results, retained results on failure, retry through to\nsuccess, and readonly/disabled controls. Enabling Show loading text starts a preview request so the message is immediately observable.</p>\n',
  'projects/blocks/forms/components/select/README.md':
    '<h1>Select</h1>\n<p>A typed single-value control with searchable, grouped options and remote pagination.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Select</span>, <span class="hljs-title class_">IBxSelectOption</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-select</span>\n    <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Workspace&quot;</span>\n    [<span class="hljs-attr">options</span>]=<span class="hljs-string">&quot;options()&quot;</span>\n    [<span class="hljs-attr">formField</span>]=<span class="hljs-string">&quot;account.workspace&quot;</span>\n    [<span class="hljs-attr">isSearchable</span>]=<span class="hljs-string">&quot;true&quot;</span>\n    [<span class="hljs-attr">externalFiltering</span>]=<span class="hljs-string">&quot;true&quot;</span>\n    [<span class="hljs-attr">loading</span>]=<span class="hljs-string">&quot;loading()&quot;</span>\n    [<span class="hljs-attr">hasMore</span>]=<span class="hljs-string">&quot;hasMore()&quot;</span>\n    [<span class="hljs-attr">loadError</span>]=<span class="hljs-string">&quot;loadError()&quot;</span>\n    [<span class="hljs-attr">loadMoreConfig</span>]=<span class="hljs-string">&quot;paginationAppearance&quot;</span>\n    (<span class="hljs-attr">search</span>)=<span class="hljs-string">&quot;search($event)&quot;</span>\n    (<span class="hljs-attr">loadMore</span>)=<span class="hljs-string">&quot;loadNext($event)&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p>Supports Signal Forms, Reactive Forms, Template-driven Forms, and standalone <code>[(value)]</code>. Existing <code>[formControl]</code> and <code>formControlName</code> bindings remain\navailable.</p>\n<p>Options provide <code>label</code>, <code>value</code>, optional <code>disabled</code>, <code>icon</code>, <code>group</code> and <code>groupDisabled</code>. Labels and group headings accept translation keys.\n<code>compareWith(a, b)</code> defaults to <code>Object.is</code>; supply a comparator for object values. Selected labels are retained when filtering replaces the visible results.\n<code>searchValue</code> is a string model: the term and matching results persist together across panel close/reopen. Bind it when application code needs to clear or\nreplace a query.</p>\n<p><code>isSearchable</code>, <code>externalFiltering</code>, <code>searchPlaceholder</code>, <code>searchDebounce</code>, and <code>emptyMessage</code> configure search. <code>search</code> emits debounced terms; external\nfiltering leaves request cancellation and results ownership with the application. <code>loadingLabel</code> names loading feedback.</p>\n<p><code>optionTemplate</code> receives <code>$implicit</code> (option), <code>selected</code>, and <code>index</code>. <code>triggerTemplate</code> receives <code>$implicit</code> (form value) and resolved <code>labels</code>. <code>panelClass</code>\ncustomizes the panel. <code>--bx-select-panel-background</code>, <code>--bx-select-panel-border</code>, and <code>--bx-select-panel-shadow</code> customize the opaque surface, contrast and\nelevation independently from the form container. <code>--bx-select-panel-height</code> changes the maximum panel height, which is also constrained to the viewport.</p>\n<p><code>selectionChange</code> emits <code>{ value, source: &#39;user&#39; }</code>. <code>openedChange</code> reports panel state. <code>open()</code>, <code>close()</code>, and <code>toggleOpen()</code> control the panel. Readonly\nstate prevents value changes without changing the form&#39;s disabled state.</p>\n<h2>Pagination</h2>\n<p><code>hasMore</code>, <code>loading</code>, <code>loadError</code>, <code>loadMoreConfig</code>, and <code>loadMoreTemplate</code> feed the shared <a href="components/load-more">load-more directive</a>.\n<code>loadMore</code> distinguishes scroll, button and retry requests. Append pages rather than replacing previously loaded items during ordinary pagination. Retain items\nand the failed cursor on error.</p>\n<p>Small result pages expose a bottom-left action when no item scrollbar exists. A visible action stays present while loading. Errors show an explicit retry even\nwith overflow. Applications need not know the viewport size or reproduce fallback behavior.</p>\n<h2>Behavior and accessibility</h2>\n<p>Arrow keys, Home/End, typeahead, Enter/Space, Escape, Alt+ArrowUp and Tab support panel interaction. Focus returns appropriately when the panel closes. Field\nerror/hint descriptions and invalid/required states are connected automatically.</p>\n<p>Panels retain the shared overlay positioning, theme inheritance and top-layer context behavior. Provide <code>BX_OVERLAY_CONTEXT</code> through the existing\noverlay-context directive for custom top-layer containers.</p>\n<p>Ordinary panels use native CSS anchors where supported. Panels promoted into the top layer use measured CDK positioning so nested scrolling and filtering\npreserve their gap, focus and placement without a frame of anchor drift.</p>\n<p>Completed closes release the panel&#39;s overlay and tracking resources. Reopening resolves the current overlay context, including after moving the control into or\nout of a native popover. Selection and the application-owned search term remain on the control.</p>\n<h2>Appearance and accessibility</h2>\n<p>Uses Blocks semantic tokens and the active <code>ThemingService</code> configuration. Customize through documented inputs, templates and CSS variables. Existing components\nupdate when the application theme changes. Keyboard focus, forced colors, reduced transparency and <code>BxA11yService</code> reduced-motion preferences remain supported.</p>\n<p>Text inputs accept <code>ResolvableText</code>: plain text or <code>{ key: &#39;translation.key&#39; }</code>. With <code>BX_I18N</code>, text is resolved reactively, including already-mounted controls\nwhen the adapter&#39;s <code>version</code> signal changes. Plain text works without an adapter.</p>\n<h3>Motion and material response</h3>\n<p>Select and multi-select overlays use the shared retargetable opacity/scale spring, anchored to the side chosen by overlay positioning. A persistent engine\nsurface follows pointer or keyboard focus between enabled rows; selection, checkmarks and focus outlines remain authoritative. The highlight moves in the list&#39;s\nscrolling coordinates and is remeasured after content/size changes. No data requests are owned by motion. Live reduced motion snaps geometry, while opaque\nmaterial and forced-color fallbacks remain independent. Inspect <code>/components/select</code>, <code>/components/multi-select</code>, and <code>/appearance</code>.</p>\n<p>Closing cleans up and detaches the connected overlay in the same turn when its exit finishes. Switching to another selector or dismissing with Escape does not\nbriefly repaint the closed panel; reopening during an exit retargets the existing transition.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/select</code> for mock pagination, external filtering, loading, failed requests and retry. Switch page sizes to exercise the scroll and\nfallback-action states.</p>\n<h2>Busy presentation</h2>\n<p>The trigger replaces its caret with a same-size spinner, preserving width. When a visible load-more or retry button starts a request, that button stays mounted\nand shows its own spinner. The panel uses a row-aligned loading indicator only when no footer button is visible; the two loading presentations are mutually\nexclusive.</p>\n<h2>Tags and search feedback</h2>\n<p><code>selectionDisplay=&quot;tags&quot;</code> renders the selected value through the standalone Blocks <code>Tag</code> component. <code>tagConfig</code> controls common appearance and\n<code>option.tagConfig</code> provides per-option overrides. See the <a href="components/tag">tag guide</a>.</p>\n<p>Clipped tag labels automatically expose their full text in a tooltip; fitting labels do not. Explicit option/tag tooltip descriptions retain their existing\nbehavior. The parent combobox supplies keyboard access to the complete selection without adding nested tab stops. Labels and plain values also use the shared\ntruncation directive. Set <code>[tooltipOnTruncate]=&quot;false&quot;</code> to disable automatic truncation tooltips, including ordinary selected tags, while retaining ellipsis and\ncustom templates. Per-tag configuration can disable the tag tooltip when the owner is enabled. The component inherits the shared <code>FormSettingsService</code> default.</p>\n<p>While searching (including debounce and the external request), old results and load-more actions are suppressed. <code>loadingLabel</code> provides centered loading text;\nwithout it, the panel displays a simple centered spinner named by <code>loadingAriaLabel</code>. Pagination becomes available for the filtered result set after the request\ncompletes.</p>\n<h2>Option spacing</h2>\n<p>Rounded option rows have a small gap, shared by select and multiselect. Set <code>--bx-select-option-gap</code> on the control to customize it (default: Blocks\n<code>spacing(1)</code>). All built-in selection and caret icons use Blocks <code>Icon</code>; searching uses Blocks <code>SearchInput</code>.</p>\n<h2>Clearing selection</h2>\n<p>A Blocks × icon button appears before the dropdown/loading indicator, with equal spacing between the action and the selected text/tags and between the two\nicons, when a selection exists. Its reserved space prevents overlap with selected text or tags. Set <code>[clearable]=&quot;false&quot;</code> to hide it, or use <code>clearLabel</code>\n(<code>ResolvableText</code>, default <code>&#39;Clear selection&#39;</code>) to customize its accessible name. <code>clearTooltip</code> accepts its own <code>ResolvableText</code>, defaults to the resolved\n<code>clearLabel</code> when omitted, and can be set to an empty string to hide the tooltip.</p>\n<p><code>clearSelection()</code> performs the same guarded action programmatically. Clearing closes the panel, marks the control touched and returns focus to the combobox; it\npreserves Angular&#39;s blur/submit update policy. The action is hidden while readonly and disabled when the control is disabled. Keyboard users can Tab to the\naction and activate it with Enter or Space.</p>\n<p>Clearing writes <code>null</code> and emits <code>selectionChange</code> with <code>{ value: null, source: &#39;clear&#39; }</code>. Required controls report validation through the existing error\npolicy.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-select</span> [<span class="hljs-attr">options</span>]=<span class="hljs-string">&quot;locations&quot;</span> [<span class="hljs-attr">clearLabel</span>]=<span class="hljs-string">&quot;{ key: &#x27;locations.clearAction&#x27; }&quot;</span> [<span class="hljs-attr">clearTooltip</span>]=<span class="hljs-string">&quot;{ key: &#x27;locations.clearTooltip&#x27; }&quot;</span> /&gt;</span></code></pre>\n<p>Use <code>[clearable]=&quot;false&quot;</code> for required selections that must retain a value or for lists with an explicit “None” option. This input controls the clear action\nindependently of validation; <code>required</code> continues to enforce form validity. The select/multiselect playground includes an “Allow clearing selection” switch;\nconfiguration controls such as page size deliberately hide the clear action.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-select</span> [<span class="hljs-attr">options</span>]=<span class="hljs-string">&quot;options&quot;</span> [<span class="hljs-attr">clearable</span>]=<span class="hljs-string">&quot;false&quot;</span> /&gt;</span></code></pre>\n',
  'projects/blocks/forms/components/shared/load-more/README.md':
    '<h1>Load-more footer</h1>\n<p>Internal presentation used by <code>LoadMoreDirective</code>. Applications configure it through <code>ILoadMoreConfig</code> and <code>ILoadMoreContext</code>; it is not a separate public\nconstruction API.</p>\n<p>See the <a href="components/load-more">load-more directive</a> for imports, request ownership, error/retry behavior, templates, appearance and\naccessibility. Its live page is <code>/components/load-more</code>.</p>\n',
  'projects/blocks/forms/components/slide-toggle/README.md':
    '<h1>Slide toggle</h1>\n<p>A boolean preference that takes effect immediately.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SlideToggle</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-slide-toggle</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Enable notifications&quot;</span> [<span class="hljs-attr">formControl</span>]=<span class="hljs-string">&quot;notifications&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p>The control uses Angular 22 native signal control contracts. Use <code>[formField]</code>, <code>[formControl]</code>, <code>formControlName</code>, <code>[(ngModel)]</code>, or standalone <code>[(checked)]</code>.\nShared presentation includes labels, hints, tooltips, required/readonly/disabled state, error policies and typed message resolvers. See the\n<a href="components/signal-forms">forms guide</a> for validation, submission, translations and compatibility.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<p>Hints and errors align with the control&#39;s inline start by default. <code>--bx-field-support-padding</code> overrides that support-text padding. For a full-width settings\nrow with the label at the start and the switch at the end, use <code>labelPosition=&quot;before&quot;</code> with <code>--bx-toggle-inline-size: 100%</code> and\n<code>--bx-toggle-justify-content: space-between</code>. Their defaults are <code>auto</code> and <code>start</code>. Labels can wrap while the switch retains its size; logical layout also\nfollows RTL direction.</p>\n<p>Toggles keep emitting the theme color while switched on, including values set through Angular forms. Hovering the track or its label highlights the surface and\nemits color; disabled controls do neither.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use for immediate settings, with a label describing the enabled state. The native checkbox retains keyboard behavior and checked state.</p>\n<h3>Motion and material response</h3>\n<p>The thumb retargets the shared elastic spring when the displayed checked state changes, including programmatic and deferred form updates. Velocity stretch and\nthe engine&#39;s pressure response are bounded inside a stationary switch track. RTL uses the logical starting edge. The checked surface emits more strongly than\nthe neutral track without increasing reception. Initial render snaps; live reduced motion snaps to the current state and removes deformation. Disabled and\nreadonly behavior remains owned by the form control. Inspect <code>/components/slide-toggle</code> and <code>/appearance</code>.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/slide-toggle</code> for a working example and its current value or action result.</p>\n<h2>Switch semantics</h2>\n<p>The internal checkbox exposes switch semantics. <code>labelPosition</code> supports before/after placement, and projected label content is supported. <code>checkedChange</code> is\navailable for standalone interaction. Readonly preserves the value while disabled state blocks interaction.</p>\n',
  'projects/blocks/forms/directives/button-icon/README.md':
    '<h1>Button icon slot</h1>\n<p>Import <code>ButtonIconDirective</code> from <code>@filip.mazev/blocks/forms</code> and mark a custom projected icon element with <code>bxButtonIcon</code>. The loading button replaces that\nelement with a same-size spinner and restores it when the operation completes. Built-in <code>bx-icon</code> content is recognized automatically.</p>\n<p>Provide the action name as button text or an accessible label, and mark decorative custom icons appropriately. See the parent\n<a href="components/button">button guide</a> and <code>/components/button-loading</code> playground page.</p>\n',
  'projects/blocks/forms/directives/load-more/README.md':
    '<h1>Load more</h1>\n<p>Shared incremental loading for a scroll container. The directive appends a footer at the bottom-left, inside the container&#39;s padding. Use it for paginated\noption panels and future data tables or lists; attach it to their scroll wrapper rather than a native <code>table</code>, <code>tbody</code>, <code>ul</code> or <code>select</code> element.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">LoadMoreDirective</span>, <span class="hljs-title class_">ILoadMoreRequest</span>, <span class="hljs-title class_">ILoadMoreConfig</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">div</span>\n    <span class="hljs-attr">bxLoadMore</span>\n    #<span class="hljs-attr">pager</span>=<span class="hljs-string">&quot;bxLoadMore&quot;</span>\n    <span class="hljs-attr">role</span>=<span class="hljs-string">&quot;region&quot;</span>\n    <span class="hljs-attr">aria-label</span>=<span class="hljs-string">&quot;Workspaces&quot;</span>\n    <span class="hljs-attr">tabindex</span>=<span class="hljs-string">&quot;0&quot;</span>\n    [<span class="hljs-attr">loadMoreHasMore</span>]=<span class="hljs-string">&quot;hasMore()&quot;</span>\n    [<span class="hljs-attr">loadMoreLoading</span>]=<span class="hljs-string">&quot;loading()&quot;</span>\n    [<span class="hljs-attr">loadMoreError</span>]=<span class="hljs-string">&quot;loadError()&quot;</span>\n    [<span class="hljs-attr">loadMoreRevision</span>]=<span class="hljs-string">&quot;items()&quot;</span>\n    [<span class="hljs-attr">loadMoreConfig</span>]=<span class="hljs-string">&quot;paginationAppearance&quot;</span>\n    (<span class="hljs-attr">loadMore</span>)=<span class="hljs-string">&quot;loadNext($event)&quot;</span>&gt;</span>\n    @for (item of items(); track item.id) {\n    <span class="hljs-tag">&lt;<span class="hljs-name">div</span>&gt;</span>{{ item.name }}<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>\n    }\n<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span></code></pre>\n<p>Give the wrapper a constrained maximum height and <code>overflow: auto</code>. Applications own API calls, cursors, cancellation and data accumulation. The directive never\nfetches data itself.</p>\n<h2>API</h2>\n<ul>\n<li><code>loadMoreHasMore</code>: whether another page exists; defaults to false.</li>\n<li><code>loadMoreLoading</code>: application request state; defaults to false.</li>\n<li><code>loadMoreError</code>: optional text or translation key describing a failed request. Failure reveals a retry action even when the container overflows. Without a\nresolved retry label, it uses a retry icon with the supplied load-more text.</li>\n<li><code>loadMoreSuppressed</code>: temporarily hides the footer and blocks page requests, for example during a search request.</li>\n<li><code>loadMoreDisabled</code>: blocks requests without removing content.</li>\n<li><code>loadMoreRevision</code>: pass the items array or a page revision to acknowledge new data.</li>\n<li><code>loadMoreConfig</code>: <code>ILoadMoreConfig</code> controls action text, busy/retry text, accessible label, button variant/color/outline, custom button/footer classes,\nscroll threshold and <code>buttonMode</code> (<code>auto</code> or <code>always</code>).</li>\n<li><code>loadMoreTemplate</code>: optional <code>TemplateRef&lt;ILoadMoreContext&gt;</code> for a custom action. Its context includes the resolved label (<code>$implicit</code>), <code>loading</code>,\n<code>disabled</code>, and guarded <code>request()</code> callback.</li>\n<li><code>loadMore</code>: emits <code>{ source: &#39;scroll&#39; | &#39;button&#39; | &#39;retry&#39; }</code>.</li>\n<li><code>complete()</code>: acknowledges completion when no loading-state cycle or items revision is available.</li>\n<li><code>actionVisible()</code>: indicates whether the footer action is visible, allowing an owning component to avoid rendering a second loading indicator.</li>\n<li><code>request(source?)</code>: invokes the same request guard from application code.</li>\n</ul>\n<p>Scroll geometry and passive content/resize observation use Core&#39;s <code>measureScrollBoundary()</code> and <code>observeScrollBoundary()</code> helpers, shared with\n<code>InfiniteScrollDirective</code>. The orchestration remains here: it excludes its own footer when measuring overflow, exposes a reachable action, and guards remote\nrequests. Select and Multiselect continue using this one directive. No new Select/Multiselect API is required, and remote underfill never starts an automatic\nfetch loop.</p>\n<h2>Loading, failure and retry</h2>\n<p>Set loading before starting the promise. Append data only on success. On failure retain the previous data and page/cursor, set <code>loadMoreError</code>, and clear\nloading in <code>finally</code>. Retry the same page; advance its cursor only after success. Clear the error when a retry begins.</p>\n<p>The button shows its loading spinner and becomes disabled while loading. A button visible before a request stays visible during it, including when newly\nappended items create overflow. The error and retry remain reachable after failure, and scroll events cannot automatically retry a failing request. Request\nguards prevent duplicates until a loading cycle completes, the revision changes, or <code>complete()</code> is called.</p>\n<p>When more data exists without usable item overflow, auto mode displays the footer action. Container resizing, viewport/zoom resizing, and data changes\nre-evaluate overflow. The footer itself does not count as item overflow, preventing show/hide oscillation. Always mode retains an explicit action even with a\nscrollbar. There is no automatic fetch loop to fill the viewport.</p>\n<h2>Custom action</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> #<span class="hljs-attr">customAction</span> <span class="hljs-attr">let-label</span> <span class="hljs-attr">let-loading</span>=<span class="hljs-string">&quot;loading&quot;</span> <span class="hljs-attr">let-disabled</span>=<span class="hljs-string">&quot;disabled&quot;</span> <span class="hljs-attr">let-request</span>=<span class="hljs-string">&quot;request&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;button&quot;</span> <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;tonal&quot;</span> <span class="hljs-attr">color</span>=<span class="hljs-string">&quot;accent&quot;</span> [<span class="hljs-attr">loading</span>]=<span class="hljs-string">&quot;loading&quot;</span> [<span class="hljs-attr">disabled</span>]=<span class="hljs-string">&quot;disabled&quot;</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;request()&quot;</span>&gt;</span>{{ label }}<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span></code></pre>\n<p>Pass the template through <code>loadMoreTemplate</code>. Keep the action keyboard-accessible and represent its busy/disabled states. <code>--bx-load-more-padding</code> changes\nfooter padding; the default has no additional horizontal inset. Button classes and semantic theme variables customize appearance without DOM access.</p>\n<h2>Appearance and accessibility</h2>\n<p>Uses Blocks semantic tokens and the active <code>ThemingService</code> configuration. Customize through documented inputs, templates and CSS variables. Existing components\nupdate when the application theme changes. Keyboard focus, forced colors, reduced transparency and <code>BxA11yService</code> reduced-motion preferences remain supported.</p>\n<p>Text inputs accept <code>ResolvableText</code>: plain text or <code>{ key: &#39;translation.key&#39; }</code>. With <code>BX_I18N</code>, text is resolved reactively, including already-mounted controls\nwhen the adapter&#39;s <code>version</code> signal changes. Plain text works without an adapter.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/load-more</code>. Fake API requests take 800ms. Use small pages for the no-scrollbar action, <strong>Fail next page now</strong> for a failed request, then\n<strong>Retry request</strong>. The event log distinguishes loading, failed, retry and successful states.</p>\n',
  'projects/blocks/forms/directives/native-control/README.md':
    '<h1>Native control</h1>\n<p>Composable content and native integration for the shared field frame.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">NativeControlDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-form-field</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Notes&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">textarea</span> <span class="hljs-attr">bxInput</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Notes&quot;</span> [<span class="hljs-attr">formField</span>]=<span class="hljs-string">&quot;account.note&quot;</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">textarea</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-form-field</span>&gt;</span></code></pre>\n<h2>API and behavior</h2>\n<p>Registers a native input, textarea or select with the field frame. Import the desired Angular forms directives separately. Native attributes and third-party\ndirectives remain available. <code>BX_FORM_FIELD_CONTROL</code> and <code>IFormFieldControl</code> allow consumer controls to register their own state and focus contract.</p>\n<h2>Appearance and accessibility</h2>\n<p>Uses Blocks semantic tokens and the active <code>ThemingService</code> configuration. Customize through documented inputs, templates and CSS variables. Existing components\nupdate when the application theme changes. Keyboard focus, forced colors, reduced transparency and <code>BxA11yService</code> reduced-motion preferences remain supported.</p>\n<p>Text inputs accept <code>ResolvableText</code>: plain text or <code>{ key: &#39;translation.key&#39; }</code>. With <code>BX_I18N</code>, text is resolved reactively, including already-mounted controls\nwhen the adapter&#39;s <code>version</code> signal changes. Plain text works without an adapter.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/native-control</code> for working field composition and compatibility examples.</p>\n',
  'projects/blocks/forms/directives/prefix/README.md':
    '<h1>Field prefix</h1>\n<p>Composable content and native integration for the shared field frame.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">PrefixDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-input-field</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Amount&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">span</span> <span class="hljs-attr">bxPrefix</span> <span class="hljs-attr">aria-hidden</span>=<span class="hljs-string">&quot;true&quot;</span>&gt;</span>$<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-input-field</span>&gt;</span></code></pre>\n<h2>API and behavior</h2>\n<p>Projects custom content before the input. Keep decorative prefixes hidden from assistive technology; express meaningful units in the label or description.</p>\n<h2>Appearance and accessibility</h2>\n<p>Uses Blocks semantic tokens and the active <code>ThemingService</code> configuration. Customize through documented inputs, templates and CSS variables. Existing components\nupdate when the application theme changes. Keyboard focus, forced colors, reduced transparency and <code>BxA11yService</code> reduced-motion preferences remain supported.</p>\n<p>Text inputs accept <code>ResolvableText</code>: plain text or <code>{ key: &#39;translation.key&#39; }</code>. With <code>BX_I18N</code>, text is resolved reactively, including already-mounted controls\nwhen the adapter&#39;s <code>version</code> signal changes. Plain text works without an adapter.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/prefix</code> for working field composition and compatibility examples.</p>\n',
  'projects/blocks/forms/directives/slider/README.md':
    '<h1>Slider</h1>\n<p><code>SliderDirective</code> gives a native range input a glass thumb, a recessed track, and a value fill. Native keyboard, touch, disabled, minimum, maximum, step, and\nAngular forms behavior are preserved.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SliderDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">label</span> <span class="hljs-attr">for</span>=<span class="hljs-string">&quot;volume&quot;</span>&gt;</span>Volume<span class="hljs-tag">&lt;/<span class="hljs-name">label</span>&gt;</span> <span class="hljs-tag">&lt;<span class="hljs-name">input</span> <span class="hljs-attr">id</span>=<span class="hljs-string">&quot;volume&quot;</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;range&quot;</span> <span class="hljs-attr">bxSlider</span> <span class="hljs-attr">min</span>=<span class="hljs-string">&quot;0&quot;</span> <span class="hljs-attr">max</span>=<span class="hljs-string">&quot;100&quot;</span> [<span class="hljs-attr">formControl</span>]=<span class="hljs-string">&quot;volume&quot;</span> /&gt;</span></code></pre>\n<p>Import the directive into your component and include the existing Blocks core stylesheet. The directive also supports <code>ngModel</code> or native <code>[value]</code> and\n<code>(input)</code> bindings. It reads programmatic value changes after Angular renders, so resetting a form updates the fill too.</p>\n<p>The slider inherits semantic theme colors. Solid material, reduced transparency, increased contrast, and unsupported backdrop filtering use an opaque thumb.\nWebKit/Blink and Firefox have separate native thumb and track rules. Provide an associated label or <code>aria-label</code> for every slider.</p>\n<p><code>--bx-slider-thumb-size</code> sets the native and decorative thumb diameter together, defaulting to <code>spacing(6)</code> from the shared tokens. The decorative thumb&#39;s\nposition follows the same travel distance as the native thumb.</p>\n<p>The bordered glass thumb magnifies and blurs the rail beneath it. Set <code>--bx-slider-magnification</code> to adjust the enlargement from its default <code>1.5</code>, and\n<code>--bx-slider-lens-blur</code> to adjust the lens and backdrop blur from <code>1.5px</code>. It uses the current rail colors and value, including RTL, without reading screen\npixels. Reduced transparency, increased contrast and unsupported backdrop filtering use an opaque thumb; forced colors retains the native thumb.</p>\n<h2>Labels and ticks</h2>\n<p>Native <code>[formField]</code> binding is supported alongside existing Angular form directives. <code>discrete</code> adds a formatted visible value; <code>displayWith(value)</code> controls\nthat label. <code>showTickMarks</code> adds bounded native tick metadata. For a pair of values use <a href="components/range-slider">RangeSlider</a>.</p>\n<h2>Behavior and accessibility</h2>\n<p>Native values, thumb centers, and fill endpoints update immediately. Holding enlarges the existing magnifying lens, with capped velocity stretch; release\nsprings back to a fully opaque resting thumb; motion never delays the native value. The lens and fill share the existing engine&#39;s received lighting. Pointer\ncancellation, blur, hidden documents, disabled/readonly changes, and destruction release gesture state. Live reduced motion clears deformation and stops its\nclock. Existing glass/opaque fallbacks remain independent. Inspect <code>/components/slider</code> with rapid drags and <code>/appearance</code> for accessibility settings.</p>\n',
  'projects/blocks/forms/directives/suffix/README.md':
    '<h1>Field suffix</h1>\n<p>Composable content and native integration for the shared field frame.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SuffixDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-input-field</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Weight&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">span</span> <span class="hljs-attr">bxSuffix</span> <span class="hljs-attr">aria-hidden</span>=<span class="hljs-string">&quot;true&quot;</span>&gt;</span>kg<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-input-field</span>&gt;</span></code></pre>\n<h2>API and behavior</h2>\n<p>Projects custom content after the input. Custom interactive suffix actions need accessible names and native button semantics.</p>\n<h2>Appearance and accessibility</h2>\n<p>Uses Blocks semantic tokens and the active <code>ThemingService</code> configuration. Customize through documented inputs, templates and CSS variables. Existing components\nupdate when the application theme changes. Keyboard focus, forced colors, reduced transparency and <code>BxA11yService</code> reduced-motion preferences remain supported.</p>\n<p>Text inputs accept <code>ResolvableText</code>: plain text or <code>{ key: &#39;translation.key&#39; }</code>. With <code>BX_I18N</code>, text is resolved reactively, including already-mounted controls\nwhen the adapter&#39;s <code>version</code> signal changes. Plain text works without an adapter.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/suffix</code> for working field composition and compatibility examples.</p>\n',
  'projects/blocks/icons/components/icon/README.md':
    '<h1>Icon</h1>\n<p>An asynchronously loaded SVG icon using semantic foreground and background tokens.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Icon</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/icons&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-icon</span> <span class="hljs-attr">name</span>=<span class="hljs-string">&quot;sparkles&quot;</span> <span class="hljs-attr">size</span>=<span class="hljs-string">&quot;32&quot;</span> <span class="hljs-attr">color</span>=<span class="hljs-string">&quot;text-primary&quot;</span> [<span class="hljs-attr">decorative</span>]=<span class="hljs-string">&quot;false&quot;</span> <span class="hljs-attr">ariaLabel</span>=<span class="hljs-string">&quot;Highlights&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>name</code> is required. <code>size</code>, <code>strokeWidth</code>, <code>color</code>, <code>bgColor</code>, <code>decorative</code>, <code>ariaLabel</code> configure rendering. Color accepts a semantic token or themed color;\n<code>bgColor=&quot;auto&quot;</code> derives a complementary token.</p>\n<p><code>size</code> accepts positive finite numbers or numeric strings in CSS pixels, including <code>[size]=&quot;64&quot;</code>, <code>size=&quot;18&quot;</code>, and the existing presets. The default is <code>&#39;24&#39;</code>;\ninvalid dimensions fall back to 24. <code>strokeWidth</code> accepts positive finite numbers, including fractional values; omission or invalid values use 1.5. Icon\nrequests completing after an input change or destruction are ignored.</p>\n<p>Generated <code>LUCIDE_CATEGORIES</code>, <code>LUCIDE_ICON_CATEGORIES</code>, and <code>LucideCategoryId</code> are available from the same public entry point. Categories come from a pinned\nofficial upstream snapshot and include multiple assignments, resolved inheritance, aliases, and an uncategorized fallback. See the\n<a href="../../../../../tools/icons/README.md">generator guide</a> for synchronization. The mapping contains only icons generated into Blocks.</p>\n<h2>Appearance and customization</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Leave decorative icons hidden from assistive technology; meaningful standalone icons need <code>decorative=false</code> and <code>ariaLabel</code>. Label icon buttons on the button\nitself. The catalog progressively renders icon previews in bounded batches.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/icon</code> for a working example, or <code>/icons</code> for categories, persistent catalog preferences, and a live customization inspector.</p>\n',
  'projects/blocks/modal/README.md':
    '<h1>Modal</h1>\n<p>Service-driven dialogs with typed content and results, centered and side layouts, responsive bottom sheets, close guards, and shared Blocks appearance.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Modal</span>, <span class="hljs-title class_">ModalService</span>, <span class="hljs-title class_">ModalHeaderDirective</span>, <span class="hljs-title class_">ModalFooterDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/modal&#x27;</span>;</code></pre>\n<p>Install <code>@filip.mazev/blocks</code> and follow the <a href="installation">package setup</a>. Modal is a secondary entry point of that package.</p>\n<h2>Usage</h2>\n<p>Create standalone content in <code>message-dialog.ts</code>:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ChangeDetectionStrategy</span>, <span class="hljs-title class_">Component</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Button</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Modal</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/modal&#x27;</span>;\n\n<span class="hljs-meta">@Component</span>({\n    <span class="hljs-attr">selector</span>: <span class="hljs-string">&#x27;app-message-dialog&#x27;</span>,\n    <span class="hljs-attr">imports</span>: [<span class="hljs-title class_">Button</span>],\n    <span class="hljs-attr">template</span>: <span class="hljs-string">&#x27;&lt;p&gt;{{ data }}&lt;/p&gt;&lt;button bx-button (click)=&quot;confirm()&quot;&gt;Confirm&lt;/button&gt;&#x27;</span>,\n    <span class="hljs-attr">changeDetection</span>: <span class="hljs-title class_">ChangeDetectionStrategy</span>.<span class="hljs-property">OnPush</span>\n})\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">MessageDialog</span> <span class="hljs-keyword">extends</span> <span class="hljs-title class_ inherited__">Modal</span>&lt;<span class="hljs-built_in">string</span>, <span class="hljs-built_in">boolean</span>&gt; {\n    <span class="hljs-keyword">protected</span> <span class="hljs-title function_">confirm</span>(): <span class="hljs-built_in">void</span> {\n        <span class="hljs-variable language_">this</span>.<span class="hljs-property">modal</span>.<span class="hljs-title function_">close</span>(<span class="hljs-string">&#x27;confirm&#x27;</span>, <span class="hljs-literal">true</span>);\n    }\n}</code></pre>\n<p>Open it from an application action:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ChangeDetectionStrategy</span>, <span class="hljs-title class_">Component</span>, <span class="hljs-title class_">DestroyRef</span>, inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { takeUntilDestroyed } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core/rxjs-interop&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Button</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ModalService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/modal&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">MessageDialog</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;./message-dialog&#x27;</span>;\n\n<span class="hljs-meta">@Component</span>({\n    <span class="hljs-attr">selector</span>: <span class="hljs-string">&#x27;app-example&#x27;</span>,\n    <span class="hljs-attr">imports</span>: [<span class="hljs-title class_">Button</span>],\n    <span class="hljs-attr">template</span>: <span class="hljs-string">&#x27;&lt;button bx-button (click)=&quot;open()&quot;&gt;Open dialog&lt;/button&gt;&#x27;</span>,\n    <span class="hljs-attr">changeDetection</span>: <span class="hljs-title class_">ChangeDetectionStrategy</span>.<span class="hljs-property">OnPush</span>\n})\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">Example</span> {\n    <span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> modalService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ModalService</span>);\n    <span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> destroyRef = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">DestroyRef</span>);\n\n    <span class="hljs-keyword">protected</span> <span class="hljs-title function_">open</span>(): <span class="hljs-built_in">void</span> {\n        <span class="hljs-keyword">const</span> ref = <span class="hljs-variable language_">this</span>.<span class="hljs-property">modalService</span>.<span class="hljs-property">open</span>&lt;<span class="hljs-built_in">string</span>, <span class="hljs-built_in">boolean</span>&gt;(<span class="hljs-title class_">MessageDialog</span>, {\n            <span class="hljs-attr">data</span>: <span class="hljs-string">&#x27;Save these changes?&#x27;</span>,\n            <span class="hljs-attr">header</span>: { <span class="hljs-attr">text</span>: <span class="hljs-string">&#x27;Confirm changes&#x27;</span> },\n            <span class="hljs-attr">style</span>: { <span class="hljs-attr">layout</span>: <span class="hljs-string">&#x27;center&#x27;</span>, <span class="hljs-attr">breakpoints</span>: { <span class="hljs-attr">sm</span>: <span class="hljs-string">&#x27;bottom-sheet&#x27;</span> } }\n        });\n\n        ref.<span class="hljs-title function_">afterClosed</span>()\n            .<span class="hljs-title function_">pipe</span>(<span class="hljs-title function_">takeUntilDestroyed</span>(<span class="hljs-variable language_">this</span>.<span class="hljs-property">destroyRef</span>))\n            .<span class="hljs-title function_">subscribe</span>(<span class="hljs-function">(<span class="hljs-params">result</span>) =&gt;</span> {\n                <span class="hljs-variable language_">console</span>.<span class="hljs-title function_">log</span>(result.<span class="hljs-property">state</span>, result.<span class="hljs-property">data</span>);\n            });\n    }\n}</code></pre>\n<p>For custom header/footer content, add <code>ModalHeaderDirective</code> and <code>ModalFooterDirective</code> to the content component&#39;s imports and use <code>*appModalHeader</code> and\n<code>*appModalFooter</code>. These existing selectors remain supported.</p>\n<h2>API</h2>\n<h3>Content and references</h3>\n<p><code>Modal&lt;D, R&gt;</code> supplies typed <code>data</code>, the active <code>modal: ModalRef&lt;D, R&gt;</code>, <code>onModalInit()</code>, and <code>close(result?)</code> (cancel mode).\n<code>ModalService.open&lt;D, R&gt;(ContentComponent, config?)</code> returns that reference.</p>\n<table>\n<thead>\n<tr>\n<th>Member</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>close(state?, result?, forceClose?)</code></td>\n<td>Close with <code>confirm</code> or <code>cancel</code> mode; force closing bypasses guards.</td>\n</tr>\n<tr>\n<td><code>modalState$()</code></td>\n<td>Observe <code>OPENING</code>, <code>OPEN</code>, <code>CLOSING</code>, and <code>CLOSED</code>.</td>\n</tr>\n<tr>\n<td><code>backdropClick()</code></td>\n<td>Observe backdrop pointer events.</td>\n</tr>\n<tr>\n<td><code>afterClosed()</code></td>\n<td>Observe the final <code>IModalCloseResult&lt;R | undefined&gt;</code> with <code>state</code> and optional <code>data</code>.</td>\n</tr>\n<tr>\n<td><code>config()</code></td>\n<td>Read the authoritative reactive configuration.</td>\n</tr>\n</tbody></table>\n<p><code>modalsCount()</code> is reactive when read in an Angular template or computed. It includes dialogs while opening and closing, until unregister completes. A nonmodal\nowner can bind its <code>closeOnEscape</code> to <code>modalService.modalsCount() === 0</code> so a dialog handles Escape independently.</p>\n<p>Use supported configuration and slots to customize the dialog. Applications do not need to inspect its component references or DOM.</p>\n<h3>Configuration</h3>\n<p><code>IModalConfig&lt;D, R&gt;</code> accepts:</p>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Default and purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>data</code></td>\n<td>Optional typed content payload.</td>\n</tr>\n<tr>\n<td><code>header</code></td>\n<td>Optional heading text, icon, icon loading, and loading label.</td>\n</tr>\n<tr>\n<td><code>style</code></td>\n<td>Optional <code>IModalStyleConfig</code> described below.</td>\n</tr>\n<tr>\n<td><code>open</code></td>\n<td><code>true</code>; initial open state.</td>\n</tr>\n<tr>\n<td><code>disableClose</code></td>\n<td><code>false</code>; prevent ordinary dismissal.</td>\n</tr>\n<tr>\n<td><code>disableCloseOnBackdropClick</code></td>\n<td><code>false</code>; restrict backdrop dismissal only.</td>\n</tr>\n<tr>\n<td><code>disableCloseOnNavigation</code></td>\n<td><code>false</code>; retain the dialog during navigation when enabled.</td>\n</tr>\n<tr>\n<td><code>closeGuard</code></td>\n<td>Optional <code>ModalCloseGuard</code>.</td>\n</tr>\n<tr>\n<td><code>closeGuardOnlyOnCancel</code></td>\n<td><code>true</code>; run the guard for cancellation only.</td>\n</tr>\n<tr>\n<td><code>id</code></td>\n<td>Generated unique identifier when omitted.</td>\n</tr>\n<tr>\n<td><code>contentClasses</code>, <code>contentStyles</code></td>\n<td>Optional content presentation overrides.</td>\n</tr>\n<tr>\n<td><code>afterClose</code></td>\n<td>Optional observable callback contract. Prefer <code>afterClosed()</code> for application result handling.</td>\n</tr>\n</tbody></table>\n<p>Instance options override <code>ModalGlobalSettingsService</code> defaults. Its <code>update()</code> currently applies <code>animate</code>, <code>hasBackdrop</code>, and <code>disableCloseOnBackdropClick</code>;\nother exposed default signals can be configured directly before opening.</p>\n<h3>Live configuration patching</h3>\n<p><code>ModalRef.patch(patch: IModalPatch): void</code> updates the existing dialog synchronously. Use the reference returned by <code>open()</code> or <code>this.modal</code> inside a component\nextending <code>Modal&lt;D, R&gt;</code>. Both paths share the same configuration signal; <code>config()</code> reads the current resolved value. The reference is also injectable as\n<code>inject&lt;ModalRef&lt;D, R&gt;&gt;(ModalRef)</code> inside service-created content.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">const</span> ref = <span class="hljs-variable language_">this</span>.<span class="hljs-property">modalService</span>.<span class="hljs-title function_">open</span>(<span class="hljs-title class_">WizardDialog</span>, {\n    <span class="hljs-attr">header</span>: { <span class="hljs-attr">text</span>: <span class="hljs-string">&#x27;Step 1: Details&#x27;</span>, <span class="hljs-attr">icon</span>: { <span class="hljs-attr">name</span>: <span class="hljs-string">&#x27;pencil&#x27;</span> } }\n});\n\nref.<span class="hljs-title function_">patch</span>({ <span class="hljs-attr">header</span>: { <span class="hljs-attr">text</span>: <span class="hljs-string">&#x27;Step 2: Review&#x27;</span> } });\nref.<span class="hljs-title function_">patch</span>({ <span class="hljs-attr">header</span>: { <span class="hljs-attr">loading</span>: <span class="hljs-literal">true</span> }, <span class="hljs-attr">disableClose</span>: <span class="hljs-literal">true</span> });\nref.<span class="hljs-title function_">patch</span>({\n    <span class="hljs-attr">header</span>: { <span class="hljs-attr">text</span>: <span class="hljs-string">&#x27;Changes saved&#x27;</span>, <span class="hljs-attr">icon</span>: { <span class="hljs-attr">name</span>: <span class="hljs-string">&#x27;check&#x27;</span> }, <span class="hljs-attr">loading</span>: <span class="hljs-literal">false</span> },\n    <span class="hljs-attr">disableClose</span>: <span class="hljs-literal">false</span>\n});</code></pre>\n<p>Inside <code>WizardDialog</code>, the same update is <code>this.modal.patch({ header: { text: &#39;Step 2: Review&#39; } })</code>. Draft values, the mounted component, scroll position,\nfocus on retained elements, and the entrance animation remain intact.</p>\n<table>\n<thead>\n<tr>\n<th>Patch property</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>header.text</code></td>\n<td>Replace <code>ResolvableText</code>; null clears only the text.</td>\n</tr>\n<tr>\n<td><code>header.icon</code></td>\n<td>Merge supplied <code>IIconData</code> members; null removes the icon. A new partial icon without a name uses <code>info</code>.</td>\n</tr>\n<tr>\n<td><code>header.loading</code></td>\n<td>Replace only the icon area with the shared spinner, retaining the configured icon. Defaults to false.</td>\n</tr>\n<tr>\n<td><code>header.loadingLabel</code></td>\n<td>Accessible spinner label as <code>ResolvableText</code>; defaults to the shared spinner&#39;s <code>Loading</code> label.</td>\n</tr>\n<tr>\n<td><code>header: null</code></td>\n<td>Remove the configured heading and icon; custom header slots remain mounted.</td>\n</tr>\n<tr>\n<td><code>disableClose</code></td>\n<td>Prevent user dismissal through Escape, close actions, backdrop, and swipe. Programmatic <code>close()</code> remains available.</td>\n</tr>\n<tr>\n<td><code>disableCloseOnBackdropClick</code>, <code>disableCloseOnNavigation</code>, <code>closeGuardOnlyOnCancel</code></td>\n<td>Update the existing dismissal policies.</td>\n</tr>\n<tr>\n<td><code>style.showCloseButton</code></td>\n<td>Toggle the close action, subject to <code>disableClose</code>.</td>\n</tr>\n<tr>\n<td><code>style.wrapperClasses</code>, <code>style.wrapperStyles</code></td>\n<td>Replace presentation overrides; null clears the override.</td>\n</tr>\n<tr>\n<td><code>contentClasses</code>, <code>contentStyles</code></td>\n<td>Replace classes or inline styles on the content wrapper; null clears them.</td>\n</tr>\n</tbody></table>\n<p>Omitted and <code>undefined</code> properties retain their current values. Header, icon, and supported style updates merge instead of resetting siblings. No consumer-owned\nconfiguration object is mutated. Patches are applied in call order, including during <code>onModalInit()</code>. Closing and destroyed modals ignore late updates.</p>\n<p>Layout, responsive breakpoints, animation, backdrop mounting, identity, component type, initialization data, and lifecycle callbacks remain opening-time\noptions. They are absent from <code>IModalPatch</code>. Application form and wizard data stays application-owned.</p>\n<p>When loading switches off, the configured icon returns. A hidden normal icon preserves its dimensions, including its backing. When there is no configured icon,\nexplicit loading state reserves a default 24px slot so switching between true and false does not shift the heading. Spinner size follows <code>icon.size</code> and reduced\nmotion uses the shared static presentation. This loading flag affects the icon only; it does not disable the dialog or prevent dismissal automatically.</p>\n<h3>Migration for reactive references</h3>\n<p>Replace <code>ref.modalConfig</code> with <code>ref.config()</code> and direct configuration assignments with <code>ref.patch(...)</code>. <code>ModalCore.config</code> is now a signal as well.\nConfiguration snapshots must be treated as read-only. The old unused <code>modalContainer</code> and <code>parentElement</code> properties are removed; service-owned mounting is not\nconfigurable through the reference. Mounted component/container getters become undefined after destruction. References are created and attached by\n<code>ModalService</code>; use its <code>open()</code> API rather than constructing references yourself. <code>Modal&lt;D, R&gt;.data</code> and <code>MODAL_DATA</code> remain initialization data.</p>\n<h3>Close guards</h3>\n<p>Extend <code>ModalCloseGuard</code> and implement <code>canClose(modalService)</code> returning a boolean, Promise, or Observable. A false result retains the dialog.\n<code>ModalConfirmCloseGuard&lt;D, R&gt;(ConfirmationComponent, config)</code> opens a typed confirmation dialog and waits for its result. Keep application-owned unsaved state\nin the application; provide the guard when opening its content. <code>forceClose: true</code> deliberately bypasses the guard.</p>\n<p>Only the top registered modal handles Escape, including when other dialogs remain mounted behind it. A disabled top dialog does not pass Escape to its parent.\nRepeated close requests share the pending guard decision instead of opening duplicate confirmation dialogs; force closing remains available. Each dialog retains\nits own patch configuration, guard, and close timer. Parents are registered before constructing application content, so a synchronously opened child retains the\ncorrect stack order and nesting depth. Bottom-sheet presentation stays mounted throughout dismissal.</p>\n<h3>Declarative nonmodal panels</h3>\n<p>For page-owned inspectors and filters, use <a href="components/side-panel">SidePanel</a> from the primitives entry point with its boolean <code>open</code>\nmodel. It shares square panel corners, surface material, layout, and close-control presentation with Modal Side while keeping nonmodal behavior separate. Modal\ncontinues to own its guarded service lifecycle, modal semantics, nested stacking, backdrops, focus trapping/restoration, and scroll locks.</p>\n<h2>Appearance and customization</h2>\n<p><code>IModalStyleConfig</code> supports <code>layout: &#39;center&#39; | &#39;left&#39; | &#39;right&#39; | &#39;bottom-sheet&#39;</code>, responsive <code>breakpoints</code>, <code>animate</code> (true), <code>hasBackdrop</code> (true),\n<code>showCloseButton</code> (true), <code>closeDelay</code> (175 ms), <code>contentWrapper</code> (true), <code>overrideFullHeight</code> (false), and optional <code>wrapperClasses</code>/<code>wrapperStyles</code>.\n<code>mobileConfig</code> accepts <code>downSwipeLimit</code> (3) and optional <code>customHeight</code> for bottom sheets.</p>\n<p>Breakpoints use a max-width strategy: sort overrides from smallest to largest and apply the first matching threshold. Above all thresholds, use <code>layout</code>. Keys\nmatch the <a href="components">core breakpoint tokens</a>: <code>xs</code>, <code>sm</code>, <code>md</code>, <code>lg</code>, <code>xl</code>, <code>2xl</code>, <code>3xl</code>, and <code>4xl</code>.</p>\n<p>The dialog inherits palette, semantic tokens, and appearance from <code>ThemingService</code>. See the\n<a href="appearance">appearance guide</a> for application-wide configuration.</p>\n<p>All modal layouts share the declarative SidePanel&#39;s translucent surface material and semantic background tokens. <code>--bx-modal-bg</code> and <code>--bx-modal-text</code> remain\nmodal-specific overrides, falling back to <code>--bx-panel-bg</code> / <code>--bx-panel-text</code> and then <code>--bx-bg-surface</code> / <code>--bx-text-primary</code>. Root dialogs retain their normal\n0.52 opacity floor and shared appearance preferences. Left/right modal panels have four square corners; centered dialogs and bottom sheets retain their shapes.</p>\n<p>The first dialog paints dimming outside its surface, while the shared backdrop retains blur and pointer dismissal. This prevents the root surface from blending\nwith its own black scrim. Its centered animation keeps the dimming cutout aligned with the zooming frame; the oversized dimming shadow continues to cover the\nviewport.</p>\n<h3>Nested dialogs</h3>\n<p>Each nested dialog restores an independent fixed backdrop and dims the parent normally. Opening or closing a child never changes the parent&#39;s material or turns\nits backdrop off. The first nested dialog uses a minimum 0.9 material opacity; the next nested dialog and deeper levels use 1. More opaque application or\naccessibility settings still take precedence. This policy applies to centered, side, and bottom-sheet layouts, including responsive layout changes and close\nguards. Depth follows the mounted modal stack and updates when an intervening dialog is removed; a dialog remains mounted through its close animation.</p>\n<p>Customize the floors through the shared settings service. Index zero is the first nested dialog; the last entry repeats for deeper levels. An empty array\nretains ordinary material at every depth. Values clamp to 0.52–1; nonfinite entries use the defaults for their depth. Replace the array when updating it;\nmounted modals respond reactively.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ModalGlobalSettingsService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/modal&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> modalGlobalSettingsService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ModalGlobalSettingsService</span>);\n\n<span class="hljs-comment">// First nested dialog: at least 90% opaque; further nesting: fully opaque.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">modalGlobalSettingsService</span>.<span class="hljs-property">nestedOpacityFloors</span>.<span class="hljs-title function_">set</span>([<span class="hljs-number">0.9</span>, <span class="hljs-number">1</span>]);</code></pre>\n<p><code>hasBackdrop: false</code> keeps that dialog&#39;s backdrop off. Reduced-transparency and forced-color modes retain the opaque fallback.</p>\n<h2>Behavior and accessibility</h2>\n<p>Centered entrance and exit retain the centered zoom and content fade. Transform and opacity animate directly on their owning layers, without propagating an\nanimated custom property through filtered descendants. Starting styles apply before the first paint, and the dimming cutout follows the frame. On close,\ncontent, dimming and the blur backdrop fade together over 175ms; teardown waits for the rendered transitions to finish rather than using a timer started before\nrendering. Closing during entrance continues from the current visual state. Reduced motion removes the transitions.</p>\n<p>Modal hosts use the Angular CDK focus trap across the banner, custom header, scrolling content and footer. Opening captures keyboard focus; closing restores the\npreviously focused element when it remains connected, including when dismissing a responsive bottom sheet or nested dialog. Runtime header patches retain the\nmounted focus trap.</p>\n<p>Open content through <code>ModalService</code> so focus handling, Escape/backdrop dismissal, close guards, scroll locks, layout, and cleanup stay coordinated.\n<code>ScrollLockService</code> keeps separate locks for concurrent overlays. Closing one overlay does not unlock another. Reduced motion takes precedence over requested\nanimation; reduced transparency and forced colors receive opaque backdrop presentation.</p>\n<p>Centered dialogs constrain their content to the available viewport, including when nested on small screens. Their content region scrolls independently while the\nheader and footer remain reachable.</p>\n<p>Header text accepts <code>ResolvableText</code> and updates through the optional <code>BX_I18N</code> adapter. Content components own the translation and accessible naming of their\ncustom actions, descriptions, errors, and form controls. Keep actions reachable in constrained viewports and preserve focus when completing asynchronous work.</p>\n<h3>Motion and material response</h3>\n<p>Centered dialogs combine opacity with a restrained 0.975–1 material scale instead of growing content from zero. Their existing viewport dimming layer remains\nindependent. Side dialogs and bottom sheets use the shared smooth curve for large surfaces; side entrance frames are cancelled on close or destruction.\nBottom-sheet handles support mouse, pen and touch dragging with direct tracking. Release uses recent velocity and a bounded projected destination, so a short\nflick can request dismissal without traversing the whole threshold. A pause removes momentum. Cancellation, lost capture, Escape during a gesture, blur and\nhidden documents restore the sheet without requesting dismissal. Tapping or keyboard-activating the handle remains an alternative to dragging. Failed gestures\nreturn using the shared spring; successful gestures still pass through the existing close guard before the lifecycle host starts the exit. Live reduced motion\nremoves decorative movement. Close guards, focus/stacking and reactive patches retain their existing lifecycle. Inspect <code>/modal</code> in centered, side and mobile\nsheet layouts.</p>\n<h2>Playground</h2>\n<p>The live dialog includes <strong>Open nested dialog</strong>, which can be used recursively to compare the root, 90% nested, and fully opaque deeper surfaces. Closing a\nchild returns to its parent. The confirm-close guard exercises the same independent backdrop and depth policy.</p>\n<p>Open <code>/modal</code> for initial configuration, live heading/icon/dismissal controls inside the dialog, and a three-step save wizard. Visit <code>/components/modal-core</code>\nfor the lifecycle host, or the centered, side, bottom-sheet, header, footer, and backdrop entries in the component catalog. The examples demonstrate typed\nresults and guarded dismissal.</p>\n<p>The <code>/modal</code> dialog includes an editable draft note, live presentation controls, and a review/save flow. Patches retain that note and the wizard step. The page\nalso exposes an action to patch heading and dismissal settings on its last open reference.</p>\n',
  'projects/blocks/modal/components/modal-core/README.md':
    '<h1>Modal core</h1>\n<p>The service-owned host that composes modal content and chooses the active layout.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ModalCore</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/modal&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-comment">&lt;!-- Open from an action in your template --&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;openModal()&quot;</span>&gt;</span>Open modal core<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>ModalService.open(ContentComponent, config)</code> accepts data, header, style, close behavior and guards. Style <code>layout</code> selects center, left, right or\nbottom-sheet; <code>animate</code>, <code>hasBackdrop</code>, and <code>showCloseButton</code> customize presentation. The host reads <code>config()</code> from its injected reference; supported runtime\nchanges go through <code>ModalRef.patch()</code> without recreating the mounted content. See <a href="modal#live-configuration-patching">live configuration patching</a>.\nObserve <code>afterClosed()</code> for the close result.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-variable language_">this</span>.<span class="hljs-property">modalService</span>.<span class="hljs-title function_">open</span>(<span class="hljs-title class_">DialogContent</span>, {\n    <span class="hljs-attr">header</span>: { <span class="hljs-attr">text</span>: <span class="hljs-string">&#x27;Modal core&#x27;</span> },\n    <span class="hljs-attr">style</span>: { <span class="hljs-attr">layout</span>: <span class="hljs-string">&#x27;center&#x27;</span>, <span class="hljs-attr">hasBackdrop</span>: <span class="hljs-literal">true</span> }\n});</code></pre>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Open through <code>ModalService</code> so focus management, close guards, backdrop behavior, lifecycle and cleanup remain coordinated. <code>Modal</code> content receives its typed\ndata and <code>ModalRef</code>; call <code>modal.close(mode, result)</code> to return a result. Do not instantiate service-owned view wrappers as general page containers.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/modal-core</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/modal/components/shared/ui/backdrop/README.md':
    '<h1>Modal backdrop</h1>\n<p>The background scrim that separates an open modal from page content.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ModalBackdrop</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/modal&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-comment">&lt;!-- Open from an action in your template --&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;openModal()&quot;</span>&gt;</span>Open modal backdrop<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p>The reusable backdrop exposes <code>isAnimated</code> (false), <code>isOpen</code> (false), <code>label: ResolvableText</code> (&quot;Close dialog&quot;), and <code>tabIndex</code> (0), and emits\n<code>click: MouseEvent</code>. Mobile side navigation uses the same component with its translated close label and tab index -1 because its panel supplies a close action.</p>\n<p><code>ModalService.open(ContentComponent, config)</code> accepts data, header, style, close behavior and guards. Style <code>layout</code> selects center, left, right or\nbottom-sheet; <code>animate</code>, <code>hasBackdrop</code>, and <code>showCloseButton</code> customize presentation. Observe <code>afterClosed()</code> for the close result.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-variable language_">this</span>.<span class="hljs-property">modalService</span>.<span class="hljs-title function_">open</span>(<span class="hljs-title class_">DialogContent</span>, {\n    <span class="hljs-attr">header</span>: { <span class="hljs-attr">text</span>: <span class="hljs-string">&#x27;Modal backdrop&#x27;</span> },\n    <span class="hljs-attr">style</span>: { <span class="hljs-attr">layout</span>: <span class="hljs-string">&#x27;center&#x27;</span>, <span class="hljs-attr">hasBackdrop</span>: <span class="hljs-literal">true</span> }\n});</code></pre>\n<h2>Appearance</h2>\n<p><code>--bx-modal-backdrop-position</code> defaults to <code>fixed</code>, <code>--bx-modal-backdrop-z-index</code> to the shared modal layer, and <code>--bx-modal-backdrop-background</code> to the shared\ndim scrim. Owners can set these variables to contain or stack the backdrop without reaching into its DOM. Reduced-transparency and forced-color fallbacks take\nprecedence over the ordinary background override.</p>\n<p>ModalService uses this same backdrop for centered, side, and bottom-sheet dialogs. In that composition the backdrop supplies blur and dismissal, while the root\nsurface paints dimming outside its own border to avoid a gray tint. Nested dialogs use independent filled backdrops with their own blur and dismissal; older\nbackdrop/material layers stay intact. Nested material becomes at least 90% opaque at the first nested level and fully opaque at deeper levels by default.\nStandalone backdrops and mobile navigation retain their existing filled-scrim presentation.</p>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>When animated, the backdrop fades its blur and fill over 175ms on opening and closing. Starting styles establish the entrance before first paint; changing\ndirection continues from the current opacity. With <code>isAnimated</code> false, presentation changes immediately.</p>\n<p>Open through <code>ModalService</code> so focus management, close guards, backdrop behavior, lifecycle and cleanup remain coordinated. <code>Modal</code> content receives its typed\ndata and <code>ModalRef</code>; call <code>modal.close(mode, result)</code> to return a result. Do not instantiate service-owned view wrappers as general page containers.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/modal-backdrop</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/modal/components/shared/ui/banner/README.md':
    '<h1>Modal banner</h1>\n<p>The shared modal heading, semantic icon and close action.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ModalBanner</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/modal&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-modal-banner</span> [<span class="hljs-attr">header</span>]=<span class="hljs-string">&quot;{ text: &#x27;Project settings&#x27; }&quot;</span> [<span class="hljs-attr">showCloseButton</span>]=<span class="hljs-string">&quot;true&quot;</span> (<span class="hljs-attr">close</span>)=<span class="hljs-string">&quot;handleClose($event)&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p>Required inputs: <code>header</code> (header config or undefined), <code>showCloseButton</code> (boolean). <code>close</code> emits a modal close mode or undefined. Header supports text and an\noptional icon configuration, <code>loading</code> (false by default), and translatable <code>loadingLabel</code> (defaults to <code>Loading</code>). Loading replaces only the icon area with the\nshared spinner, preserving the normal icon for restoration and respecting reduced motion. Header updates flow from <code>ModalRef.patch()</code>; see the\n<a href="modal#live-configuration-patching">modal patch contract</a>.</p>\n<h2>Appearance</h2>\n<p>Title/icon alignment, wrapping, divider spacing, and the compact close action use shared panel-banner Sass presentation. Declarative SidePanel headings reuse\nthe same styling and expose a matching <code>headerIcon: IIconData</code> contract.</p>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Prefer configuring <code>header</code> on ModalService for a normal dialog. Direct use is available for custom composition; ensure the surrounding dialog has an accessible\nname and handle close output.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/modal-banner</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/modal/components/views/bottom-sheet/README.md':
    '<h1>Bottom sheet</h1>\n<p>A bottom-aligned modal surface suitable for compact actions and mobile layouts.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ModalBottomSheet</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/modal&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-comment">&lt;!-- Open from an action in your template --&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;openModal()&quot;</span>&gt;</span>Open bottom sheet<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>ModalService.open(ContentComponent, config)</code> accepts data, header, style, close behavior and guards. Style <code>layout</code> selects center, left, right or\nbottom-sheet; <code>animate</code>, <code>hasBackdrop</code>, and <code>showCloseButton</code> customize presentation. Observe <code>afterClosed()</code> for the close result.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-variable language_">this</span>.<span class="hljs-property">modalService</span>.<span class="hljs-title function_">open</span>(<span class="hljs-title class_">DialogContent</span>, {\n    <span class="hljs-attr">header</span>: { <span class="hljs-attr">text</span>: <span class="hljs-string">&#x27;Bottom sheet&#x27;</span> },\n    <span class="hljs-attr">style</span>: { <span class="hljs-attr">layout</span>: <span class="hljs-string">&#x27;bottom-sheet&#x27;</span>, <span class="hljs-attr">hasBackdrop</span>: <span class="hljs-literal">true</span> }\n});</code></pre>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Open through <code>ModalService</code> so focus management, close guards, backdrop behavior, lifecycle and cleanup remain coordinated. <code>Modal</code> content receives its typed\ndata and <code>ModalRef</code>; call <code>modal.close(mode, result)</code> to return a result. Do not instantiate service-owned view wrappers as general page containers.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/modal-bottom-sheet</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/modal/components/views/centered/README.md':
    '<h1>Centered modal</h1>\n<p>A focused dialog centered in the available viewport.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ModalCentered</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/modal&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-comment">&lt;!-- Open from an action in your template --&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;openModal()&quot;</span>&gt;</span>Open centered modal<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>ModalService.open(ContentComponent, config)</code> accepts data, header, style, close behavior and guards. Style <code>layout</code> selects center, left, right or\nbottom-sheet; <code>animate</code>, <code>hasBackdrop</code>, and <code>showCloseButton</code> customize presentation. Observe <code>afterClosed()</code> for the close result.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-variable language_">this</span>.<span class="hljs-property">modalService</span>.<span class="hljs-title function_">open</span>(<span class="hljs-title class_">DialogContent</span>, {\n    <span class="hljs-attr">header</span>: { <span class="hljs-attr">text</span>: <span class="hljs-string">&#x27;Centered modal&#x27;</span> },\n    <span class="hljs-attr">style</span>: { <span class="hljs-attr">layout</span>: <span class="hljs-string">&#x27;center&#x27;</span>, <span class="hljs-attr">hasBackdrop</span>: <span class="hljs-literal">true</span> }\n});</code></pre>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Open through <code>ModalService</code> so focus management, close guards, backdrop behavior, lifecycle and cleanup remain coordinated. <code>Modal</code> content receives its typed\ndata and <code>ModalRef</code>; call <code>modal.close(mode, result)</code> to return a result. Do not instantiate service-owned view wrappers as general page containers.</p>\n<p>The centered entrance and exit retain the centered zoom and content fade. Transform and opacity animate on their owning layers rather than propagating an\ninherited custom property through every filtered descendant. Starting styles apply before first paint; the dimming cutout follows the frame. The content,\ndimming cutout and blur backdrop fade out together over 175ms. Teardown waits for the rendered exit transitions to finish, including an interrupted entrance,\nrather than counting from the close request. Live reduced motion removes the transitions.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/modal-centered</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/modal/components/views/side/README.md':
    '<h1>Side modal</h1>\n<p>A left or right panel for editing alongside the page context.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ModalSide</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/modal&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-comment">&lt;!-- Open from an action in your template --&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;openModal()&quot;</span>&gt;</span>Open side modal<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>ModalService.open(ContentComponent, config)</code> accepts data, header, style, close behavior and guards. Style <code>layout</code> selects center, left, right or\nbottom-sheet; <code>animate</code>, <code>hasBackdrop</code>, and <code>showCloseButton</code> customize presentation. Observe <code>afterClosed()</code> for the close result.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-variable language_">this</span>.<span class="hljs-property">modalService</span>.<span class="hljs-title function_">open</span>(<span class="hljs-title class_">DialogContent</span>, {\n    <span class="hljs-attr">header</span>: { <span class="hljs-attr">text</span>: <span class="hljs-string">&#x27;Side modal&#x27;</span> },\n    <span class="hljs-attr">style</span>: { <span class="hljs-attr">layout</span>: <span class="hljs-string">&#x27;right&#x27;</span>, <span class="hljs-attr">hasBackdrop</span>: <span class="hljs-literal">true</span> }\n});</code></pre>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Open through <code>ModalService</code> so focus management, close guards, backdrop behavior, lifecycle and cleanup remain coordinated. <code>Modal</code> content receives its typed\ndata and <code>ModalRef</code>; call <code>modal.close(mode, result)</code> to return a result. Do not instantiate service-owned view wrappers as general page containers.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/modal-side</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/modal/directives/footer/README.md':
    '<h1>Modal footer</h1>\n<p>Projects custom footer content into the active Blocks modal layout.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ModalFooterDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/modal&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">div</span> *<span class="hljs-attr">appModalFooter</span>&gt;</span>Custom footer content<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p>A standalone structural directive. It captures a TemplateRef and registers it with the owning ModalCore; it has no public inputs.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use only inside content opened by ModalService. The template moves to the active modal view. Keep action buttons keyboard accessible and use ModalRef to close\nwith a result. Outside a modal the directive emits a development warning.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/modal-footer</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/modal/directives/header/README.md':
    '<h1>Modal header</h1>\n<p>Projects custom header content into the active Blocks modal layout.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ModalHeaderDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/modal&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">div</span> *<span class="hljs-attr">appModalHeader</span>&gt;</span>Custom header content<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p>A standalone structural directive. It captures a TemplateRef and registers it with the owning ModalCore; it has no public inputs.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use only inside content opened by ModalService. The template moves to the active modal view. Keep action buttons keyboard accessible and use ModalRef to close\nwith a result. Outside a modal the directive emits a development warning.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/modal-header</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/navigation/README.md':
    '<h1>Navigation</h1>\n<p>Declare UI sections once with <code>defineNavigation</code>. Its <code>withInAppNavigation</code> helper restricts each route&#39;s <code>section</code> to the declared IDs and checks the remaining\nnavigation metadata. Declarations can live in <code>app.routes.ts</code> or a shared <code>app.navigation.ts</code> used by multiple route files.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { defineNavigation } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Routes</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/router&#x27;</span>;\n\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">const</span> navigation = <span class="hljs-title function_">defineNavigation</span>({\n    <span class="hljs-attr">sections</span>: [\n        { <span class="hljs-attr">id</span>: <span class="hljs-string">&#x27;start&#x27;</span>, <span class="hljs-attr">title</span>: <span class="hljs-string">&#x27;Get started&#x27;</span> },\n        { <span class="hljs-attr">id</span>: <span class="hljs-string">&#x27;forms&#x27;</span>, <span class="hljs-attr">title</span>: <span class="hljs-string">&#x27;Form controls&#x27;</span> }\n    ]\n});\n\n<span class="hljs-keyword">const</span> { withInAppNavigation } = navigation;\n\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">const</span> <span class="hljs-attr">routes</span>: <span class="hljs-title class_">Routes</span> = [\n    <span class="hljs-title function_">withInAppNavigation</span>({ <span class="hljs-attr">path</span>: <span class="hljs-string">&#x27;home&#x27;</span>, <span class="hljs-attr">loadComponent</span>: <span class="hljs-function">() =&gt;</span> <span class="hljs-keyword">import</span>(<span class="hljs-string">&#x27;./home&#x27;</span>).<span class="hljs-title function_">then</span>(<span class="hljs-function">(<span class="hljs-params">m</span>) =&gt;</span> m.<span class="hljs-property">Home</span>) }, { <span class="hljs-attr">label</span>: <span class="hljs-string">&#x27;Overview&#x27;</span>, <span class="hljs-attr">section</span>: <span class="hljs-string">&#x27;start&#x27;</span> })\n];\n\n<span class="hljs-comment">// withInAppNavigation({}, { section: &#x27;typo&#x27; }); // TypeScript error: undeclared section.</span></code></pre>\n<p>Provide the same configuration in your application&#39;s providers:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { provideNavigation } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;\n<span class="hljs-keyword">import</span> { navigation } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;./app.routes&#x27;</span>;\n\n<span class="hljs-comment">// In ApplicationConfig.providers, alongside provideRouter(routes):</span>\n<span class="hljs-title function_">provideNavigation</span>(navigation.<span class="hljs-property">config</span>);</code></pre>\n<p><code>NavigationService.menuGroups()</code> returns nonempty <code>{ id, title, items }</code> groups. Sections follow declaration order unless their numeric <code>order</code> is specified;\nsections with an order come first. Titles default to the section ID. Each group&#39;s items are flat entries from the menu tree, including descendants, with\nexisting route ordering, access checks, visibility and translations applied. Excluded parent containers do not become links. <code>menu()</code> continues to expose the\nmenu tree.</p>\n<p>The standalone <code>withInAppNavigation</code> and <code>provideNavigation</code> helpers remain available. For these existing callers, undeclared sections appear after declared\nsections with their ID as the title. Items without a section appear in a group with an empty ID and title. Type checking against a declaration applies when\nusing the <code>withInAppNavigation</code> returned by <code>defineNavigation</code>.</p>\n<p>The UI can apply search to <code>menuGroups()</code> without defining section titles, ordering or flattening. Track groups by <code>id</code> and entries by <code>route</code>.</p>\n<p>Run the grouping and metadata type checks with <code>npm run test:navigation</code>.</p>\n<h2>Navigation views</h2>\n<p><code>SideNav</code> and <code>TopNav</code> consume the same hierarchical route sections, metadata, access filtering, translation adapter, and most-specific active route. They share\nitem presentation, one-level-at-a-time browsing, flat contextual search, and focus/scroll restoration. Configure application defaults through <code>sideNav</code> and\n<code>topNav</code> in <code>defineNavigation</code>; instance configuration overrides those settings.</p>\n<p>See <a href="components/side-nav">side navigation</a> and <a href="components/top-nav">top navigation</a> for public imports, configuration, slots, accessibility,\nand runnable examples. Their playground routes are <code>/components/side-nav</code> and <code>/components/top-nav</code>.</p>\n<h2>Page layout integration</h2>\n<p><code>provideNavigation()</code> also provides the optional <code>BX_PAGE_NAVIGATION</code> adapter from primitives. <code>NavigationService.page</code> exposes reactive section and page titles\nplus breadcrumbs for <a href="components/layout/page-container">PageContainer</a>. Descriptions remain application-owned. Breadcrumbs appear after one\nnesting by default and the threshold can be configured on each container. Existing Breadcrumbs components retain their own display settings.</p>\n<h2>Stepper workflows</h2>\n<p><a href="components/stepper">Stepper</a> provides passive progress, externally controlled section navigation and guarded wizards through the same <code>bx-stepper</code>\ncomponent. Import <code>Stepper</code>, <code>Step</code> and its optional template directives from <code>@filip.mazev/blocks/navigation</code>.</p>\n',
  'projects/blocks/navigation/components/breadcrumbs/README.md':
    '<h1>Breadcrumbs</h1>\n<p>A route-aware trail derived from Blocks navigation metadata.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Breadcrumbs</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-breadcrumbs</span> [<span class="hljs-attr">minimumBreadcrumbs</span>]=<span class="hljs-string">&quot;1&quot;</span> <span class="hljs-attr">divider</span>=<span class="hljs-string">&quot;chevron-right&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>minimumBreadcrumbs</code> defaults to 2; values below 1 are clamped. <code>divider</code> accepts an icon name. Route labels come from <code>withInAppNavigation</code> metadata and\n<code>NavigationService</code>.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Register metadata with <code>withInAppNavigation</code> and provide navigation in application configuration. Breadcrumbs navigate using the router and update after\nnavigation. This demo lives under Components so the trail has a real parent route.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/breadcrumbs</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/navigation/components/shared/navigation-item/README.md':
    '<h1>Navigation item</h1>\n<p>Internal item presentation shared by <a href="components/side-nav">SideNav</a> and <a href="components/top-nav">TopNav</a>. Consumers configure the public owners rather\nthan importing this implementation component.</p>\n<p>A native page link and a separate disclosure retain independent hover/focus surfaces. Only the most specific active route receives selected styling. Top-level\nhorizontal disclosures point down/up; vertical levels use a forward arrow. The scoped navigation state coordinates all requests through the owner&#39;s one submenu\npanel.</p>\n<p>Search results always retain their muted parent path, including custom templates. Search results have no floating guides or additional selection styling. The\nestablished side-nav CSS variables remain supported; top navigation maps its own variables into the same shared styles.</p>\n<p>Both public playground pages demonstrate these interactions, translation changes, disabled routes, and four levels of nesting.</p>\n',
  'projects/blocks/navigation/components/shared/navigation-level/README.md':
    '<h1>Navigation level</h1>\n<p>Internal nested-list presentation shared by <a href="components/side-nav">SideNav</a> and <a href="components/top-nav">TopNav</a>. The owner supplies one scoped state/focus\nservice and chooses the surface: inline rail, side panel, or top dropdown.</p>\n<p>The current parent remains a route link. Back, Escape, or the opposite arrow returns one level, while Up/Down and Home/End move through the list. The header and\nparent path remain above the scrolling list. Ancestor path buttons open their respective panels without route navigation, using Blocks text buttons and the\nowner’s focus/scroll restoration. The current parent heading remains a separate page link. Owners restore the matching scroll position and disclosure focus.\nLevels use the same short slide, disabled reactively by reduced-motion preferences.</p>\n<p>Neither this view nor an item creates additional overlays. Theme, text resolution, route matching, and flat contextual search come from the shared navigation\nstate. Consumer APIs and examples live with the public owners.</p>\n',
  'projects/blocks/navigation/components/side-nav/README.md':
    '<h1>Side navigation</h1>\n<p>A route-driven application rail with collapsible sections, a compact icon rail, nested browsing inside the panel, contextual fuzzy search, and a responsive\nmobile drawer. It shares <code>NavigationService</code> with breadcrumbs and <code>TopNav</code>, and shares item, search, level, and focus behavior with top navigation. Theme,\nsurface, search, tag, and accessibility behavior follow the shared Blocks facilities.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> {\n    <span class="hljs-title class_">SideNav</span>,\n    <span class="hljs-title class_">SideNavHeaderDirective</span>,\n    <span class="hljs-title class_">SideNavFooterDirective</span>,\n    defineNavigation,\n    provideNavigation,\n    <span class="hljs-title class_">ISideNavConfig</span>,\n    <span class="hljs-title class_">ISideNavItemContext</span>,\n    <span class="hljs-title class_">ISideNavLayout</span>,\n    <span class="hljs-title class_">INavigationTreeGroup</span>,\n    <span class="hljs-title class_">INavigationItem</span>\n} <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;</code></pre>\n<p><code>SideNavConfig</code> aliases <code>ISideNavConfig</code>; <code>NavItem</code> aliases the resolved <code>INavigationItem</code> contract. Interfaces follow the library&#39;s <code>I</code> naming convention.\nImport all three components/directives in the shell&#39;s Angular <code>imports</code>.</p>\n<h2>Working usage and withInAppNavigation</h2>\n<p>Declare sections once, attach metadata to Angular routes, and provide the same configuration to navigation. Nested routes inherit the parent&#39;s section;\nassigning another section moves that branch to the named section. No component-specific copy of your routing configuration is required.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Routes</span>, provideRouter } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/router&#x27;</span>;\n<span class="hljs-keyword">import</span> { defineNavigation, provideNavigation } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;\n\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">const</span> navigation = <span class="hljs-title function_">defineNavigation</span>({\n    <span class="hljs-attr">sections</span>: [\n        { <span class="hljs-attr">id</span>: <span class="hljs-string">&#x27;workspace&#x27;</span>, <span class="hljs-attr">title</span>: <span class="hljs-string">&#x27;Workspace&#x27;</span>, <span class="hljs-attr">icon</span>: { <span class="hljs-attr">name</span>: <span class="hljs-string">&#x27;building-2&#x27;</span> }, <span class="hljs-attr">collapsible</span>: <span class="hljs-literal">true</span>, <span class="hljs-attr">showInBreadcrumbs</span>: <span class="hljs-literal">true</span> },\n        { <span class="hljs-attr">id</span>: <span class="hljs-string">&#x27;admin&#x27;</span>, <span class="hljs-attr">title</span>: { <span class="hljs-attr">key</span>: <span class="hljs-string">&#x27;sections.admin&#x27;</span> }, <span class="hljs-attr">icon</span>: { <span class="hljs-attr">name</span>: <span class="hljs-string">&#x27;settings&#x27;</span> }, <span class="hljs-attr">collapsible</span>: <span class="hljs-literal">true</span>, <span class="hljs-attr">collapsed</span>: <span class="hljs-literal">true</span>, <span class="hljs-attr">showInBreadcrumbs</span>: <span class="hljs-literal">false</span> }\n    ],\n    <span class="hljs-attr">sideNav</span>: { <span class="hljs-attr">side</span>: <span class="hljs-string">&#x27;left&#x27;</span>, <span class="hljs-attr">persistenceKey</span>: <span class="hljs-string">&#x27;studio.navigation.v1&#x27;</span> }\n});\n<span class="hljs-keyword">const</span> { withInAppNavigation } = navigation;\n\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">const</span> <span class="hljs-attr">routes</span>: <span class="hljs-title class_">Routes</span> = [\n    <span class="hljs-title function_">withInAppNavigation</span>(\n        {\n            <span class="hljs-attr">path</span>: <span class="hljs-string">&#x27;projects&#x27;</span>,\n            <span class="hljs-attr">children</span>: [\n                <span class="hljs-title function_">withInAppNavigation</span>(\n                    { <span class="hljs-attr">path</span>: <span class="hljs-string">&#x27;tokens&#x27;</span>, <span class="hljs-attr">loadComponent</span>: <span class="hljs-function">() =&gt;</span> <span class="hljs-keyword">import</span>(<span class="hljs-string">&#x27;./tokens&#x27;</span>).<span class="hljs-title function_">then</span>(<span class="hljs-function">(<span class="hljs-params">m</span>) =&gt;</span> m.<span class="hljs-property">Tokens</span>) },\n                    {\n                        <span class="hljs-attr">label</span>: { <span class="hljs-attr">key</span>: <span class="hljs-string">&#x27;nav.tokens&#x27;</span> },\n                        <span class="hljs-attr">icon</span>: { <span class="hljs-attr">name</span>: <span class="hljs-string">&#x27;swatch-book&#x27;</span> },\n                        <span class="hljs-attr">endIcon</span>: { <span class="hljs-attr">name</span>: <span class="hljs-string">&#x27;sparkles&#x27;</span> },\n                        <span class="hljs-attr">keywords</span>: [<span class="hljs-string">&#x27;palette&#x27;</span>, <span class="hljs-string">&#x27;variables&#x27;</span>],\n                        <span class="hljs-attr">tags</span>: [{ <span class="hljs-attr">text</span>: { <span class="hljs-attr">key</span>: <span class="hljs-string">&#x27;nav.new&#x27;</span> }, <span class="hljs-attr">config</span>: { <span class="hljs-attr">color</span>: <span class="hljs-string">&#x27;success&#x27;</span> } }],\n                        <span class="hljs-attr">showInBreadcrumbs</span>: <span class="hljs-literal">false</span>\n                    }\n                )\n            ]\n        },\n        { <span class="hljs-attr">label</span>: <span class="hljs-string">&#x27;Projects&#x27;</span>, <span class="hljs-attr">section</span>: <span class="hljs-string">&#x27;workspace&#x27;</span>, <span class="hljs-attr">icon</span>: { <span class="hljs-attr">name</span>: <span class="hljs-string">&#x27;folder&#x27;</span> } }\n    )\n];\n\n<span class="hljs-comment">// In application providers:</span>\n<span class="hljs-comment">// provideRouter(routes), ...provideNavigation(navigation.config)</span></code></pre>\n<p>A route that only groups children can omit a component. Provide an empty child route if that group&#39;s own URL should render a page. Parent labels remain links;\ntheir adjacent disclosure opens the child list inside the rail. In compact presentation, the parent icon temporarily expands the rail to show its children; the\nheading link inside navigates to the parent&#39;s route.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">div</span> <span class="hljs-attr">class</span>=<span class="hljs-string">&quot;application-shell&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-side-nav</span> #<span class="hljs-attr">navigation</span> [<span class="hljs-attr">config</span>]=<span class="hljs-string">&quot;{ side: &#x27;left&#x27; }&quot;</span> [(<span class="hljs-attr">collapsed</span>)]=<span class="hljs-string">&quot;collapsed&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxSideNavHeader</span> <span class="hljs-attr">let-compact</span> <span class="hljs-attr">let-mobile</span>=<span class="hljs-string">&quot;mobile&quot;</span>&gt;</span>\n            <span class="hljs-tag">&lt;<span class="hljs-name">a</span> <span class="hljs-attr">routerLink</span>=<span class="hljs-string">&quot;/home&quot;</span> <span class="hljs-attr">aria-label</span>=<span class="hljs-string">&quot;Studio home&quot;</span>&gt;</span>\n                <span class="hljs-tag">&lt;<span class="hljs-name">bx-icon</span> <span class="hljs-attr">name</span>=<span class="hljs-string">&quot;blocks&quot;</span> /&gt;</span>\n                @if (!compact) { <span class="hljs-tag">&lt;<span class="hljs-name">strong</span>&gt;</span>Studio<span class="hljs-tag">&lt;/<span class="hljs-name">strong</span>&gt;</span> }\n            <span class="hljs-tag">&lt;/<span class="hljs-name">a</span>&gt;</span>\n        <span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxSideNavFooter</span> <span class="hljs-attr">let-compact</span>&gt;</span>\n            <span class="hljs-tag">&lt;<span class="hljs-name">bx-icon</span> <span class="hljs-attr">name</span>=<span class="hljs-string">&quot;circle-user-round&quot;</span> /&gt;</span>\n            @if (!compact) { <span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>Alex · Workspace admin<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span> }\n        <span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-side-nav</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">main</span>&gt;</span><span class="hljs-comment">&lt;!-- router outlet --&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">main</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span></code></pre>\n<p>Use <code>display: flex; min-width: 0</code> on your shell and <code>flex: 1; min-width: 0</code> on its content. The component reserves its own desktop width; the host adjusts its\nflex order for the configured physical side, including RTL layouts. Mobile drawers reserve zero horizontal space. The built-in Blocks tonal hamburger is fixed\nat the configured edge and hides while the drawer is open, leaving one close action in its header; reserve room for it in your toolbar. For exact alignment with\nother toolbar actions, put an application-owned trigger in that toolbar’s flex layout and disable the built-in trigger; bind its <code>aria-controls</code> to\n<code>navigation.panelId</code>. A custom trigger can call <code>navigation.open($event)</code>, <code>close()</code>, or <code>toggle($event)</code> with <code>showMobileTrigger: false</code>. Passing the click\nevent or opening button ensures focus returns to it even in browsers that do not focus buttons on pointer activation.</p>\n<p>Header/footer slots use the modal pattern: directives register <code>ng-template</code> references with their containing component. <code>$implicit</code> and <code>collapsed</code> contain the\neffective compact presentation state; <code>mobile</code> identifies drawer presentation. Keep interactive projected content accessible and avoid fixed widths inside\ncompact slots.</p>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Input/model/output</th>\n<th>Contract</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>config</code></td>\n<td><code>ISideNavConfig</code>, optional per-instance overrides of <code>provideNavigation</code> defaults</td>\n</tr>\n<tr>\n<td><code>groups</code></td>\n<td>Optional readonly <code>INavigationTreeGroup[]</code>; otherwise <code>NavigationService.menuTreeGroups()</code></td>\n</tr>\n<tr>\n<td><code>itemTemplate</code></td>\n<td>Optional <code>TemplateRef&lt;ISideNavItemContext&gt;</code> for content inside the managed link/button</td>\n</tr>\n<tr>\n<td><code>collapsed</code> / <code>collapsedChange</code></td>\n<td>Optional controlled desktop state; defaults to persisted state, then configuration</td>\n</tr>\n<tr>\n<td><code>mobileOpen</code> / <code>mobileOpenChange</code></td>\n<td>Mobile openness, initially false; never persisted</td>\n</tr>\n<tr>\n<td><code>itemSelected</code></td>\n<td>Resolved <code>INavigationItem</code> selected by the user</td>\n</tr>\n<tr>\n<td><code>layoutChange</code></td>\n<td><code>ISideNavLayout</code>: physical side, current content offset, compact/mobile/open flags</td>\n</tr>\n<tr>\n<td><code>panelId</code></td>\n<td>Stable drawer ID for an application-owned trigger’s <code>aria-controls</code></td>\n</tr>\n<tr>\n<td><code>layout()</code></td>\n<td>Readonly computed layout state for application shells</td>\n</tr>\n<tr>\n<td><code>isMobile()</code>, <code>isCollapsed()</code>, <code>query()</code></td>\n<td>Readonly current presentation and query state</td>\n</tr>\n<tr>\n<td><code>search(query)</code></td>\n<td>Set or clear search programmatically</td>\n</tr>\n<tr>\n<td><code>toggleCollapsed()</code></td>\n<td>Change the desktop state and update persistence</td>\n</tr>\n<tr>\n<td><code>open(origin?)</code>, <code>close()</code>, <code>toggle(origin?)</code></td>\n<td>Mobile drawer controls; pass a click event or opening element for reliable focus return</td>\n</tr>\n</tbody></table>\n<p><code>collapsedChange</code> always emits a boolean, so <code>[(collapsed)]</code> works with an ordinary <code>signal(false)</code>. Omitting the input lets persistence/configuration own the\nstate; a bound value takes precedence.</p>\n<p><code>config</code> options (all optional):</p>\n<table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Default / behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>side</code></td>\n<td><code>&#39;left&#39;</code>; physical <code>&#39;right&#39;</code> changes drawer edge and hamburger placement</td>\n</tr>\n<tr>\n<td><code>position</code></td>\n<td><code>&#39;fixed&#39;</code>; <code>&#39;inline&#39;</code> participates in local layout, useful for previews</td>\n</tr>\n<tr>\n<td><code>width</code>, <code>collapsedWidth</code></td>\n<td><code>&#39;17rem&#39;</code>, <code>&#39;4.5rem&#39;</code>; viewport constrained</td>\n</tr>\n<tr>\n<td><code>searchable</code>, <code>collapsible</code></td>\n<td><code>true</code>, <code>true</code></td>\n</tr>\n<tr>\n<td><code>showItemIcons</code>, <code>showSectionIcons</code></td>\n<td><code>true</code>, <code>true</code>; hide leading icons in expanded rows/headings while compact triggers retain their icons</td>\n</tr>\n<tr>\n<td><code>collapsed</code></td>\n<td><code>false</code>; initial state, used when neither saved nor controlled state exists</td>\n</tr>\n<tr>\n<td><code>persistenceKey</code></td>\n<td>Unset; enables localStorage persistence for panel and section states</td>\n</tr>\n<tr>\n<td><code>mobileBreakpoint</code></td>\n<td><code>&#39;lg&#39;</code>, from <code>WindowDimensionsService.breakpoints</code>; controls the drawer independently of submenu presentation</td>\n</tr>\n<tr>\n<td><code>showSearchGuide</code></td>\n<td>Deprecated compatibility option; ignored because search guides have been removed</td>\n</tr>\n<tr>\n<td><code>backLabel</code>, <code>pathLabel</code></td>\n<td><code>&#39;Back&#39;</code>, <code>&#39;Navigation path&#39;</code>; both accept <code>ResolvableText</code></td>\n</tr>\n<tr>\n<td><code>mobile</code></td>\n<td>Unset; optional responsive override for embedded shells</td>\n</tr>\n<tr>\n<td><code>showMobileTrigger</code></td>\n<td><code>true</code>; disabling it requires an application trigger</td>\n</tr>\n<tr>\n<td><code>ariaLabel</code></td>\n<td><code>&#39;Main navigation&#39;</code></td>\n</tr>\n<tr>\n<td><code>searchPlaceholder</code>, <code>searchLabel</code>, <code>clearSearchLabel</code></td>\n<td><code>&#39;Search navigation…&#39;</code>, <code>&#39;Search navigation&#39;</code>, <code>&#39;Clear search&#39;</code></td>\n</tr>\n<tr>\n<td><code>emptyText</code></td>\n<td><code>&#39;No matching pages.&#39;</code></td>\n</tr>\n<tr>\n<td><code>openLabel</code>, <code>closeLabel</code></td>\n<td><code>&#39;Open navigation&#39;</code>, <code>&#39;Close navigation&#39;</code></td>\n</tr>\n<tr>\n<td><code>collapseLabel</code>, <code>expandLabel</code></td>\n<td><code>&#39;Collapse navigation&#39;</code>, <code>&#39;Expand navigation&#39;</code></td>\n</tr>\n<tr>\n<td><code>submenuLabel</code>, <code>resultLabel</code></td>\n<td><code>&#39;Open submenu&#39;</code>, <code>&#39;Search result&#39;</code>; the resolved item label is appended</td>\n</tr>\n</tbody></table>\n<p>Every configurable text accepts <code>ResolvableText</code>. Plain strings work without <code>BX_I18N</code>; keys fall back to their key when no adapter exists. Language changes\nreactively update mounted labels, badges, search keywords, and action names when the adapter exposes its version signal. Function-valued <code>NavText</code> receives the\nexisting navigation context contract.</p>\n<p>Section configuration supports <code>id</code>, translated <code>title</code>, <code>icon</code>, <code>order</code>, <code>collapsible</code>, initial <code>collapsed</code>, and <code>showInBreadcrumbs</code>. Route metadata supports\ntranslated <code>label</code>/<code>breadcrumb</code>, <code>icon</code>, <code>endIcon</code>, <code>tags</code>, translated <code>keywords</code>, <code>disabled</code>, <code>section</code>, <code>order</code>, <code>root</code>, <code>menu</code>, <code>hidden</code>, <code>visible</code>, and\n<code>showInBreadcrumbs</code>. A route&#39;s explicit breadcrumb setting overrides its section&#39;s setting; otherwise inclusion defaults to true. Breadcrumb suppression does\nnot prevent the route from being current or active.</p>\n<p><code>hidden</code> now consistently prunes menu branches as well as suppressing breadcrumbs. If an application previously used <code>hidden</code> only to omit a breadcrumb, migrate\nto <code>showInBreadcrumbs: false</code> to keep that menu item visible.</p>\n<p><code>menu: false</code> promotes visible descendants; <code>hidden: true</code>, failed access checks, or <code>visible: () =&gt; false</code> hide the whole branch. The legacy flat\n<code>menuGroups()</code> API remains available. <code>menuTreeGroups()</code> is the hierarchical API. Dynamic path parameters still need application-owned concrete route entries or\ndeliberate <code>menu: false</code>; the side-nav does not invent parameter values. Declare navigation-bearing routes in the eager route tree; unloaded <code>loadChildren</code>\nconfigurations are not enumerated.</p>\n<h2>Appearance and customization</h2>\n<p>Use application-wide <code>sideNav</code> defaults in <code>defineNavigation</code>, then instance overrides. Nested configuration updates should preserve unrelated keys, e.g.\n<code>config.update(value =&gt; ({ ...value, side: &#39;right&#39; }))</code>.</p>\n<table>\n<thead>\n<tr>\n<th>CSS variable</th>\n<th>Default</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--bx-side-nav-width</code></td>\n<td>Resolved <code>width</code> configuration</td>\n</tr>\n<tr>\n<td><code>--bx-side-nav-collapsed-width</code></td>\n<td>Resolved <code>collapsedWidth</code> configuration</td>\n</tr>\n<tr>\n<td><code>--bx-side-nav-height</code></td>\n<td><code>38rem</code> for inline panels</td>\n</tr>\n<tr>\n<td><code>--bx-side-nav-item-radius</code></td>\n<td>Shared medium radius</td>\n</tr>\n<tr>\n<td><code>--bx-side-nav-item-background</code></td>\n<td>Transparent, over the shared panel/menu surface</td>\n</tr>\n<tr>\n<td><code>--bx-side-nav-item-hover-background</code>, <code>--bx-side-nav-item-active-background</code></td>\n<td>Shared accent tonal surfaces; only the active route has the selected border</td>\n</tr>\n<tr>\n<td><code>--bx-side-nav-item-gap</code></td>\n<td>Shared spacing 2 (<code>0.5rem</code>) between adjacent items</td>\n</tr>\n<tr>\n<td><code>--bx-side-nav-duration</code>, <code>--bx-side-nav-easing</code></td>\n<td><code>250ms</code>, <code>ease</code>; reduced motion takes precedence</td>\n</tr>\n<tr>\n<td><code>--bx-side-nav-label-duration</code></td>\n<td><code>90ms</code> label fade as desktop expansion finishes; reduced motion skips it</td>\n</tr>\n<tr>\n<td><code>--bx-side-nav-backdrop</code></td>\n<td>Shared backdrop color with a neutral scrim fallback</td>\n</tr>\n</tbody></table>\n<p>Route activity comes from Angular Router matching and updates after navigation, redirects, and browser history changes. Query parameters, matrix parameters, and\nfragments do not clear selection. Only the most specific matching item receives the selected tonal background and border. For example,\n<code>/components/side-nav/overview</code> selects Side navigation rather than also selecting <code>/components</code>. Its owning section uses accent text without a second selected\nbox, including custom trees whose child URLs do not share the parent URL. Only the exact current link receives <code>aria-current=&quot;page&quot;</code>.</p>\n<p>The navigation region is the panel&#39;s sole vertical scroller. The compact rail reserves equal scrollbar gutters on both edges and centers icons in the remaining\nspace, aligned with header, search, and footer controls. Both direct links and submenu icons show their labels in tooltips when compact. Activating its search\nicon expands the rail and focuses the search field without scrolling the page. The root and nested lists reserve their scrollbar gutters when content fits,\npreventing width shifts. Horizontal overflow is constrained, and labels wrap within the available width.</p>\n<p>Desktop expansion lays out content at its final width behind the panel&#39;s clipping edge, preventing labels from repeatedly wrapping as the rail opens. Labels and\ndisclosure arrows fade in with search during the final 60ms of the width transition, using its remaining running time. Initial expanded rendering and mobile\ndrawers have no label delay. Reduced motion removes both the delay and fade, including when the preference changes during expansion. Keyboard focus reveals\ncontent immediately; accessible names remain available throughout. Pending reveal work is cancelled on collapse, presentation changes, and destruction.</p>\n<p>Custom header/footer and item templates can follow the same reveal by setting <code>opacity: var(--bx-side-nav-label-opacity, 1)</code> on their text and transitioning\nopacity with <code>var(--bx-side-nav-label-transition-duration, 0ms)</code>. These inherited values also handle reduced motion and keyboard focus; keep icons and focus\nindicators outside the faded text.</p>\n<p>The background and search use Blocks surfaces. Rows reuse their containing surface, and nested lists remain inside the same themed panel. Standard semantic\ncolors, focus styles, forced colors, reduced transparency, and opaque presentation remain available through Blocks. Programmatic row focus does not apply the\nhover fill; keyboard focus keeps its visible outline, and route selection belongs only to the most-specific active item.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> #<span class="hljs-attr">item</span> <span class="hljs-attr">let-entry</span> <span class="hljs-attr">let-active</span>=<span class="hljs-string">&quot;active&quot;</span> <span class="hljs-attr">let-compact</span>=<span class="hljs-string">&quot;collapsed&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-icon</span> [<span class="hljs-attr">name</span>]=<span class="hljs-string">&quot;entry.icon?.name ?? &#x27;circle&#x27;&quot;</span> /&gt;</span>\n    @if (!compact) { <span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>{{ entry.label }}<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span> }\n<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-side-nav</span> [<span class="hljs-attr">itemTemplate</span>]=<span class="hljs-string">&quot;item&quot;</span> /&gt;</span></code></pre>\n<p>Item templates should contain presentation only. The surrounding control owns the accessible interaction; avoid nested links/buttons. Application-owned <code>groups</code>\nuse stable unique item IDs and resolved section titles; item <code>data.label</code> and <code>data.keywords</code> may retain translation definitions. Update the groups input when\napplication-owned data changes. The route access adapter applies to service-generated groups; callers supplying groups own their visibility decisions.</p>\n<h2>Behavior and accessibility</h2>\n<p>Every label remains a native route link. Its separate chevron opens children without navigating. At every viewport width and nesting depth, children replace the\ncurrent list inside the sidebar. The navigation never creates an adjacent submenu popup.</p>\n<p>Back and the ancestor path stay above the scrolling list. Each ancestor button returns to a browsing level without navigating to its page. The first,\nsection-labelled action returns directly to the full navigation root when the section was only a grouping label. For example, clicking Core after opening\nUtilities from the main list restores all sections and reveals Utilities in the sidebar. The item that opened the branch receives focus; the page&#39;s scroll\nposition stays unchanged. If the section&#39;s own list was explicitly opened, such as from the compact rail, that action returns to the section level instead.\nOther ancestor actions also reveal the child item used to enter the deeper branch. The current parent&#39;s heading remains a link to its own page. Returning to a\nlevel restores its scroll position and focus.</p>\n<p>Opening a new level focuses its active route when present, otherwise its first enabled item. Changing the available width preserves the browsing path. A compact\nrail temporarily expands while browsing children without changing its saved collapse preference, and returns to the rail when browsing returns to the root.\nLevels slide briefly on explicit browsing changes; reduced motion disables the slide. Opening a submenu requires a disclosure click, touch, or keyboard action.</p>\n<p>Search normalizes accents and case, ranks exact/subsequence/keyword matches, and tolerates a single edit in words of at least four characters. It renders a flat\nlist of direct matches with translated parent paths in the main navigation, inside the sidebar. Searching never opens submenus. Labels navigate directly; result\ndisclosures leave search and browse the chosen item&#39;s children. After navigating to a search result, clearing search opens its containing submenu and scrolls\nthat result into view, preserving search-field focus. Clearing without a successful selection restores the previous browsing level and its scroll position.\nSearch temporarily expands a compact rail without changing its saved preference. Search covers the currently supplied tree, not unloaded or remote results.</p>\n<p>Search results use muted parent paths without floating arrows, extra selection colors, or outlines. The page link and its separate disclosure have independent\nhover and focus surfaces; selection belongs to the page link. The legacy <code>showSearchGuide</code> option is ignored, and the former guide CSS variables and\n<code>--bx-side-nav-item-highlight-background</code> no longer affect the component.</p>\n<p>Menus retain <code>menu</code>/<code>menuitem</code> semantics, accessible names, native links, and separate disclosure buttons. Enter/Space or the arrow towards the submenu opens\nchildren. Up/Down and Home/End move within the current menu. Back, Escape, or the opposite arrow returns one level, restoring scroll and focus; Escape at the\nroot can dismiss the mobile drawer. Mobile drawers trap Tab; desktop navigation remains part of the page&#39;s normal tab order.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-comment">&lt;!-- App-wide defaults can set the same options through defineNavigation(). --&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-side-nav</span> [<span class="hljs-attr">config</span>]=<span class="hljs-string">&quot;{ backLabel: { key: &#x27;nav.back&#x27; }, pathLabel: { key: &#x27;nav.path&#x27; } }&quot;</span> /&gt;</span></code></pre>\n<h3>Migration from adjacent submenu panels</h3>\n<p>Remove <code>submenuMode</code> and <code>submenuBreakpoint</code> from configuration and remove imports of <code>SideNavSubmenuMode</code>. These options and the type are no longer exposed;\nall nested browsing uses the panel itself. Remove calls to <code>isInlineSubmenus()</code> because there is no submenu presentation switch. The retired\n<code>--bx-side-nav-menu-width</code> and <code>--bx-side-nav-menu-max-height</code> variables no longer apply. Use <code>width</code> for the sidebar width and <code>--bx-side-nav-height</code> for an\nembedded panel&#39;s height. Back and ancestor labels remain configurable through the shared text contract.</p>\n<p>Fixed mobile navigation uses a labelled modal drawer with focus capture/trapping, scroll locking, the shared <code>ModalBackdrop</code> click-to-close scrim (including\nblur and opaque accessibility fallbacks), a Blocks icon-only close button with hover feedback, and Escape dismissal. Closing restores the opening control&#39;s\nfocus. A submenu consumes Escape before the drawer does. Resizing out of mobile mode closes the drawer and releases its lock. Browser-only persistence and\nviewport observation are guarded; unavailable/malformed storage falls back to usable defaults. Storage is scoped by your chosen key and is read when that key\nchanges, without cross-tab synchronization.</p>\n<p>The fixed mobile drawer follows the layout viewport while open, including window resizing and restored-page changes. Opening the search keyboard does not shrink\nor shift the drawer to the smaller visual viewport; the keyboard covers the lower portion instead. Closing or switching presentation releases the viewport\nlisteners and restores the default panel geometry.</p>\n<p>For an inline mobile preview, use a positioned shell (<code>position: relative</code>) with a minimum height and <code>overflow: hidden</code>. Its drawer and scrim stay inside that\nshell and do not lock page scrolling. Off-screen drawer content is clipped without creating a scroll container, and focus capture uses <code>preventScroll</code> to keep\nthe surrounding content stationary during either slide direction. Keep the shell outside another <code>bxSurface</code>: Blocks intentionally disables blur for nested\nglass. Presentation changes establish the closed layout immediately; explicit open/close actions animate the slide. Reduced motion disables that animation.</p>\n<h2>Playground</h2>\n<p>Visit <code>/components/side-nav</code>. The application shell also uses <code>SideNav</code> with real <code>withInAppNavigation</code> routes, a persistent collapsible icon rail, its Blocks\nbrand, and no footer. Components groups the five component categories, with Layout nested under Primitives; Tools groups the configurators behind its own\noverview. Tokens, Icons, and Utilities remain separate root entries. Existing component and configurator URLs remain valid. The dedicated demo supplies a\nfour-level fixture tree so selections remain on the demo page, and exposes side, collapsed/mobile presentation, RTL, custom item content, panel height, optional\nsearch, and a live language dropdown with English, Spanish, French, and German translations covering every menu item, section, action, demo control,\ninstruction, and selection result. The mobile checkbox explicitly controls the embedded presentation, independent of the application shell’s responsive\nnavigation. Desktop and mobile browse the same nested lists. Try <code>dsgn tkns</code>, <code>palette</code>, <code>tokens</code>, or <code>Palette</code> for flat contextual results, clear the search,\nand use the disclosures and Back control through all four levels.</p>\n<p>The fixed drawer acquires its own <code>ScrollLockService</code> lock only while its mobile overlay presentation is open. Closing, route navigation, changing to desktop or\ninline presentation, and destruction release that lock; a concurrently open modal keeps its own lock. <code>--bx-side-nav-backdrop</code> remains available for an explicit\nscrim color. Embedded inline presentation uses the same backdrop inside its shell without locking the page.</p>\n',
  'projects/blocks/navigation/components/step/README.md':
    '<h1>Step definitions</h1>\n<p>Use this declaration inside <code>bx-stepper</code> to configure workflow presentation and content. See the <a href="components/stepper">Stepper guide</a> for the full API and\nrunnable examples.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Step</span>, <span class="hljs-title class_">Stepper</span>, <span class="hljs-title class_">StepContentDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-stepper</span> <span class="hljs-attr">mode</span>=<span class="hljs-string">&quot;wizard&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-step</span> <span class="hljs-attr">id</span>=<span class="hljs-string">&quot;details&quot;</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Details&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxStepContent</span>&gt;</span>Details content<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-step</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-stepper</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>Step</code> mirrors <code>IStepDefinition</code> metadata. Its required inputs are <code>id</code> and <code>label</code>; optional inputs cover descriptions, icons, availability, completion,\nvalidity, form state, loading/error and guards. <code>definition()</code> exposes its current metadata snapshot.</p>\n<h2>Appearance and customization</h2>\n<p>Presentation inherits the owning stepper&#39;s variant, size, semantic tokens and appearance policies. Supply a meaningful plain or translated step label.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use <code>bxStepContent</code> for deferred creation. The stepper supports eager, lazy-retained and destroy-inactive content policies. Ordinary projection is eager.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/stepper</code> for validated workflows and content/label customization.</p>\n',
  'projects/blocks/navigation/components/stepper/README.md':
    '<h1>Stepper</h1>\n<p><code>bx-stepper</code> presents progress, requests application-owned navigation, or orchestrates a guarded wizard. Behavior and presentation are independent: all three\nmodes support steps, segments, dots, progress and cards. The component lives in navigation and reuses Blocks buttons, icons, surfaces and progress indicators.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> {\n    <span class="hljs-title class_">Stepper</span>,\n    <span class="hljs-title class_">Step</span>,\n    <span class="hljs-title class_">StepContentDirective</span>,\n    <span class="hljs-title class_">StepLabelDirective</span>,\n    <span class="hljs-title class_">IStepDefinition</span>,\n    <span class="hljs-title class_">IStepperRequest</span>,\n    <span class="hljs-title class_">IStepperTransition</span>,\n    <span class="hljs-title class_">StepperGuard</span>\n} <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;</code></pre>\n<p>Add the components and directives used by your template to the standalone component&#39;s <code>imports</code>. Public contracts are exported from this same entry point.</p>\n<h2>Usage</h2>\n<h3>Passive progress</h3>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ChangeDetectionStrategy</span>, <span class="hljs-title class_">Component</span>, signal } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">IStepDefinition</span>, <span class="hljs-title class_">Stepper</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;\n\n<span class="hljs-meta">@Component</span>({\n    <span class="hljs-attr">selector</span>: <span class="hljs-string">&#x27;app-release-progress&#x27;</span>,\n    <span class="hljs-attr">imports</span>: [<span class="hljs-title class_">Stepper</span>],\n    <span class="hljs-attr">changeDetection</span>: <span class="hljs-title class_">ChangeDetectionStrategy</span>.<span class="hljs-property">OnPush</span>,\n    <span class="hljs-attr">template</span>: <span class="hljs-string">`&lt;bx-stepper [steps]=&quot;steps&quot; [(activeStep)]=&quot;active&quot; variant=&quot;segments&quot; size=&quot;sm&quot; /&gt;`</span>\n})\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">ReleaseProgress</span> {\n    <span class="hljs-keyword">public</span> <span class="hljs-keyword">readonly</span> active = signal&lt;<span class="hljs-built_in">string</span> | <span class="hljs-literal">null</span>&gt;(<span class="hljs-string">&#x27;build&#x27;</span>);\n    <span class="hljs-keyword">public</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">steps</span>: <span class="hljs-keyword">readonly</span> <span class="hljs-title class_">IStepDefinition</span>[] = [\n        { <span class="hljs-attr">id</span>: <span class="hljs-string">&#x27;plan&#x27;</span>, <span class="hljs-attr">label</span>: <span class="hljs-string">&#x27;Plan&#x27;</span>, <span class="hljs-attr">completed</span>: <span class="hljs-literal">true</span> },\n        { <span class="hljs-attr">id</span>: <span class="hljs-string">&#x27;build&#x27;</span>, <span class="hljs-attr">label</span>: <span class="hljs-string">&#x27;Build&#x27;</span>, <span class="hljs-attr">loading</span>: <span class="hljs-literal">true</span> },\n        { <span class="hljs-attr">id</span>: <span class="hljs-string">&#x27;ship&#x27;</span>, <span class="hljs-attr">label</span>: <span class="hljs-string">&#x27;Ship&#x27;</span> }\n    ];\n}</code></pre>\n<p>Indicator mode creates no focusable step controls by default. Set <code>indicatorInteractive</code> to emit requests without committing selection.</p>\n<h3>Application-controlled navigation</h3>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-stepper</span> <span class="hljs-attr">mode</span>=<span class="hljs-string">&quot;navigation&quot;</span> <span class="hljs-attr">orientation</span>=<span class="hljs-string">&quot;vertical&quot;</span> [<span class="hljs-attr">steps</span>]=<span class="hljs-string">&quot;sections&quot;</span> [(<span class="hljs-attr">activeStep</span>)]=<span class="hljs-string">&quot;activeSection&quot;</span> (<span class="hljs-attr">stepRequested</span>)=<span class="hljs-string">&quot;navigate($event)&quot;</span> /&gt;</span></code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">public</span> <span class="hljs-keyword">readonly</span> activeSection = signal&lt;<span class="hljs-built_in">string</span> | <span class="hljs-literal">null</span>&gt;(<span class="hljs-string">&#x27;overview&#x27;</span>);\n<span class="hljs-keyword">public</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">sections</span>: <span class="hljs-keyword">readonly</span> <span class="hljs-title class_">IStepDefinition</span>[] = [\n    { <span class="hljs-attr">id</span>: <span class="hljs-string">&#x27;overview&#x27;</span>, <span class="hljs-attr">label</span>: <span class="hljs-string">&#x27;Overview&#x27;</span> },\n    { <span class="hljs-attr">id</span>: <span class="hljs-string">&#x27;access&#x27;</span>, <span class="hljs-attr">label</span>: <span class="hljs-string">&#x27;Access&#x27;</span> }\n];\n\n<span class="hljs-keyword">public</span> <span class="hljs-title function_">navigate</span>(<span class="hljs-attr">request</span>: <span class="hljs-title class_">IStepperRequest</span>): <span class="hljs-built_in">void</span> {\n    <span class="hljs-comment">// Scroll, navigate, load, expand or reject in application code.</span>\n    <span class="hljs-comment">// Confirm only when the application accepts the destination:</span>\n    <span class="hljs-variable language_">this</span>.<span class="hljs-property">activeSection</span>.<span class="hljs-title function_">set</span>(request.<span class="hljs-property">id</span>);\n}</code></pre>\n<p><code>stepRequested</code> carries <code>{ id, index, source, action }</code>. A request and confirmed <code>selectionChanged</code> are separate events. The stepper owns no router, scroll\ncontainer, section IDs, observers or scrolling offsets. Scroll/route listeners can update <code>activeStep</code> independently without creating navigation requests.</p>\n<h3>Declarative wizard with Reactive Forms</h3>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ChangeDetectionStrategy</span>, <span class="hljs-title class_">Component</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">FormControl</span>, <span class="hljs-title class_">ReactiveFormsModule</span>, <span class="hljs-title class_">Validators</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/forms&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Button</span>, <span class="hljs-title class_">InputField</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Step</span>, <span class="hljs-title class_">StepContentDirective</span>, <span class="hljs-title class_">Stepper</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;\n\n<span class="hljs-meta">@Component</span>({\n    <span class="hljs-attr">selector</span>: <span class="hljs-string">&#x27;app-workspace-wizard&#x27;</span>,\n    <span class="hljs-attr">imports</span>: [<span class="hljs-title class_">ReactiveFormsModule</span>, <span class="hljs-title class_">Button</span>, <span class="hljs-title class_">InputField</span>, <span class="hljs-title class_">Stepper</span>, <span class="hljs-title class_">Step</span>, <span class="hljs-title class_">StepContentDirective</span>],\n    <span class="hljs-attr">changeDetection</span>: <span class="hljs-title class_">ChangeDetectionStrategy</span>.<span class="hljs-property">OnPush</span>,\n    <span class="hljs-attr">template</span>: <span class="hljs-string">`\n        &lt;bx-stepper #wizard mode=&quot;wizard&quot; [completionContent]=&quot;done&quot;&gt;\n            &lt;bx-step id=&quot;details&quot; label=&quot;Details&quot; [validation]=&quot;name&quot;&gt;\n                &lt;ng-template bxStepContent&gt;\n                    &lt;bx-input-field label=&quot;Workspace name&quot; [formControl]=&quot;name&quot; /&gt;\n                &lt;/ng-template&gt;\n            &lt;/bx-step&gt;\n            &lt;bx-step id=&quot;review&quot; label=&quot;Review&quot;&gt;\n                &lt;ng-template bxStepContent\n                    &gt;&lt;p&gt;Create {{ name.value }}.&lt;/p&gt;&lt;/ng-template\n                &gt;\n            &lt;/bx-step&gt;\n        &lt;/bx-stepper&gt;\n        &lt;ng-template #done&gt;\n            &lt;p&gt;Workspace created.&lt;/p&gt;\n            &lt;button bx-button type=&quot;button&quot; (click)=&quot;wizard.reset()&quot;&gt;Restart&lt;/button&gt;\n        &lt;/ng-template&gt;\n    `</span>\n})\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">WorkspaceWizard</span> {\n    <span class="hljs-keyword">public</span> <span class="hljs-keyword">readonly</span> name = <span class="hljs-keyword">new</span> <span class="hljs-title class_">FormControl</span>(<span class="hljs-string">&#x27;&#x27;</span>, { <span class="hljs-attr">nonNullable</span>: <span class="hljs-literal">true</span>, <span class="hljs-attr">validators</span>: <span class="hljs-title class_">Validators</span>.<span class="hljs-property">required</span> });\n}</code></pre>\n<p>Built-in Back, Next, Skip and Finish actions use Blocks buttons and the same lifecycle as public navigation methods.</p>\n<p>Wizard defaults are linear, internally committed selection, retained lazy templates and built-in controls. Only successful forward advancement or Finish marks\nthe current step completed. An optional Skip records skipped state and never claims completion. Disabled steps are excluded from navigation and progress totals.</p>\n<h3>Signal Forms and other validity models</h3>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { signal } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { form, required } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/forms/signals&#x27;</span>;\n\n<span class="hljs-keyword">public</span> <span class="hljs-keyword">readonly</span> draft = <span class="hljs-title function_">signal</span>({ <span class="hljs-attr">name</span>: <span class="hljs-string">&#x27;&#x27;</span> });\n<span class="hljs-keyword">public</span> <span class="hljs-keyword">readonly</span> registration = <span class="hljs-title function_">form</span>(<span class="hljs-variable language_">this</span>.<span class="hljs-property">draft</span>, <span class="hljs-function">(<span class="hljs-params">schema</span>) =&gt;</span> <span class="hljs-title function_">required</span>(schema.<span class="hljs-property">name</span>));</code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-step</span> <span class="hljs-attr">id</span>=<span class="hljs-string">&quot;details&quot;</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Details&quot;</span> [<span class="hljs-attr">validation</span>]=<span class="hljs-string">&quot;registration()&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxStepContent</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">bx-input-field</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Workspace name&quot;</span> [<span class="hljs-attr">formField</span>]=<span class="hljs-string">&quot;registration.name&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-step</span>&gt;</span></code></pre>\n<p>Import Angular&#39;s Signal Forms <code>FormField</code> directive and Blocks <code>InputField</code> into the owning component. <code>validation</code> accepts the existing form state through\n<code>IStepValidation</code>: <code>valid</code>, optional <code>pending</code>, optional <code>statusChanges</code> and touch methods. Reactive Forms <code>AbstractControl</code>, a non-null <code>NgForm</code>, and Signal\nForms field state are structurally compatible. No form is required: <code>[valid]=&quot;canContinue()&quot;</code> supports application-owned standalone state.</p>\n<p>Explicit <code>valid</code> overrides the form&#39;s valid value. Pending validation, application <code>loading</code> and server <code>error</code> still prevent forward navigation. An invalid\nattempt marks the supplied reactive subtree touched, or calls the supplied field state&#39;s <code>markAsTouched</code>. Angular Signal Forms marks the field and its\ndescendants touched. Untouched steps are not presented as invalid until a forward attempt; explicit server errors are shown immediately. Changing an already\ncompleted form to invalid removes its effective completion and blocks linear progression. Backward navigation still runs guards and remains possible.</p>\n<h3>Asynchronous guards and recovery</h3>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">public</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">saveStep</span>: <span class="hljs-title class_">StepperGuard</span> = <span class="hljs-title function_">async</span> ({ <span class="hljs-keyword">from</span>, signal }) =&gt; {\n    <span class="hljs-keyword">const</span> response = <span class="hljs-keyword">await</span> <span class="hljs-title function_">fetch</span>(<span class="hljs-string">&#x27;/api/workflow/save&#x27;</span>, {\n        <span class="hljs-attr">method</span>: <span class="hljs-string">&#x27;POST&#x27;</span>,\n        signal,\n        <span class="hljs-attr">headers</span>: { <span class="hljs-string">&#x27;Content-Type&#x27;</span>: <span class="hljs-string">&#x27;application/json&#x27;</span> },\n        <span class="hljs-attr">body</span>: <span class="hljs-title class_">JSON</span>.<span class="hljs-title function_">stringify</span>({ <span class="hljs-attr">stepId</span>: <span class="hljs-keyword">from</span>?.<span class="hljs-property">id</span> })\n    });\n\n    <span class="hljs-keyword">if</span> (!response.<span class="hljs-property">ok</span>) <span class="hljs-keyword">throw</span> <span class="hljs-keyword">new</span> <span class="hljs-title class_">Error</span>(<span class="hljs-string">&#x27;Save failed&#x27;</span>);\n\n    <span class="hljs-keyword">return</span> <span class="hljs-literal">true</span>;\n};</code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-stepper</span> <span class="hljs-attr">mode</span>=<span class="hljs-string">&quot;wizard&quot;</span> [<span class="hljs-attr">beforeTransition</span>]=<span class="hljs-string">&quot;saveStep&quot;</span> (<span class="hljs-attr">transitionFinished</span>)=<span class="hljs-string">&quot;showResult($event)&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-step</span> <span class="hljs-attr">id</span>=<span class="hljs-string">&quot;details&quot;</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Details&quot;</span>&gt;</span>Details<span class="hljs-tag">&lt;/<span class="hljs-name">bx-step</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-step</span> <span class="hljs-attr">id</span>=<span class="hljs-string">&quot;review&quot;</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Review&quot;</span>&gt;</span>Review<span class="hljs-tag">&lt;/<span class="hljs-name">bx-step</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-stepper</span>&gt;</span></code></pre>\n<p>The pipeline checks availability, forward validity and linear prerequisites; runs current <code>canExit</code>, destination <code>canEnter</code>, then <code>beforeTransition</code>; rechecks\nvalidity; commits progress and (for internal selection) the active ID. Guards accept booleans, promises or observables. The first observable value is used;\nempty observables refuse navigation. <code>false</code> produces <code>rejected/guard</code>; thrown/rejected operations produce <code>error</code> with the original error value. Neither\nautomatically creates a toast. Application error feedback can inspect <code>transitionFinished</code> or <code>lastTransition()</code> and retry through the same method.</p>\n<p><code>pending()</code> exposes the in-flight request and loading feedback. Duplicate operations return <code>busy</code> without running another guard. Reset, destruction, external\nselection, definition replacement/removal and navigation-policy changes abort pending work. Observables unsubscribe. Promises are detached on cancellation; the\napplication must honor the supplied <code>AbortSignal</code> to cancel their underlying request. A stale result cannot select a removed destination.</p>\n<h3>Controlled wizards and custom controls</h3>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-stepper</span>\n    #<span class="hljs-attr">wizard</span>\n    <span class="hljs-attr">mode</span>=<span class="hljs-string">&quot;wizard&quot;</span>\n    <span class="hljs-attr">selectionMode</span>=<span class="hljs-string">&quot;controlled&quot;</span>\n    [<span class="hljs-attr">steps</span>]=<span class="hljs-string">&quot;steps&quot;</span>\n    [(<span class="hljs-attr">activeStep</span>)]=<span class="hljs-string">&quot;active&quot;</span>\n    [<span class="hljs-attr">controls</span>]=<span class="hljs-string">&quot;false&quot;</span>\n    (<span class="hljs-attr">transitionFinished</span>)=<span class="hljs-string">&quot;confirm($event)&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;button&quot;</span> [<span class="hljs-attr">loading</span>]=<span class="hljs-string">&quot;wizard.pending() !== null&quot;</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;wizard.next()&quot;</span>&gt;</span>Continue<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">public</span> <span class="hljs-title function_">confirm</span>(<span class="hljs-attr">result</span>: <span class="hljs-title class_">IStepperTransition</span>): <span class="hljs-built_in">void</span> {\n    <span class="hljs-keyword">if</span> (result.<span class="hljs-property">outcome</span> === <span class="hljs-string">&#x27;accepted&#x27;</span> &amp;&amp; result.<span class="hljs-property">toId</span> !== <span class="hljs-literal">null</span>) <span class="hljs-variable language_">this</span>.<span class="hljs-property">active</span>.<span class="hljs-title function_">set</span>(result.<span class="hljs-property">toId</span>);\n}</code></pre>\n<p>In controlled mode, successful guards record progress and emit an accepted transition; the application independently confirms <code>activeStep</code>. Indicator and\nnavigation modes always use request-only selection regardless of <code>selectionMode</code>. Direct external model changes are authoritative and bypass wizard guards; use\n<code>goTo</code>, <code>next</code>, <code>previous</code>, <code>skip</code> and <code>finish</code> when the change must be guarded.</p>\n<p>The playground deliberately separates requesting a step from confirming it. Its “Request next step” action shows a “Waiting for application confirmation” banner\nand an “Open Build” (or other destination) action. The current marker moves only when that application action updates <code>activeStep</code>. Applications can confirm\nimmediately in their transition handler, as above; ordinary wizards use the default <code>selectionMode=&quot;internal&quot;</code> to advance automatically.</p>\n<h3>Content ownership and lifecycle</h3>\n<p>Choose either projected <code>bx-step</code> definitions or the <code>steps</code> input, including an explicitly empty array. Mixing sources throws. Nonempty stable IDs are\nrequired; duplicates throw. Reordering preserves identity. Unknown, removed or disabled active IDs display the first enabled step; no enabled steps means no\nselection or controls. This fallback does not overwrite the external model. Removed IDs lose their internal progress and retained views.</p>\n<p>Data-driven wizard steps can supply <code>content: TemplateRef&lt;unknown&gt;</code> and <code>labelTemplate: TemplateRef&lt;IStepperLabelContext&gt;</code> without a separate registry.\n<code>bxStepContent</code> defers expensive projected content. Ordinary direct projection is instantiated by Angular eagerly even when wrapped for display; use the\ntemplate directive when creation policy matters.</p>\n<table>\n<thead>\n<tr>\n<th><code>contentPolicy</code></th>\n<th>Creation and destruction</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>retained</code></td>\n<td>Default. Create a template on first activation and retain it hidden on leaving.</td>\n</tr>\n<tr>\n<td><code>eager</code></td>\n<td>Instantiate every content template when rendered in a wizard.</td>\n</tr>\n<tr>\n<td><code>active</code></td>\n<td>Destroy the inactive embedded view; revisiting creates a fresh view.</td>\n</tr>\n</tbody></table>\n<p><code>reset(id?)</code> aborts work, clears internal progress, skips, attempted validation and inactive visitation, and selects the given/first enabled ID. Application\nform values, explicit step overrides and form touched state remain application-owned. Reset forms separately when starting a fresh draft. A successful Finish\nemits <code>completed</code> once until reset and may replace the panels with <code>completionContent</code>. Viewing the final step alone does not finish the workflow. Percentage\nrepresents completed enabled steps, so skipped optional steps intentionally need not yield 100%; supply <code>progressValue</code> for a different business metric.</p>\n<h3>Progress counter formats</h3>\n<p>Show the completion counter at the top right of the progress variant with <code>showPercentage</code>. Existing usage continues to show percentages. Set\n<code>progressFormat=&quot;fraction&quot;</code> to display completed enabled steps as <code>X/N</code>, for example <code>1/3</code> instead of <code>33%</code>:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-stepper</span> <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;progress&quot;</span> [<span class="hljs-attr">steps</span>]=<span class="hljs-string">&quot;steps&quot;</span> [(<span class="hljs-attr">activeStep</span>)]=<span class="hljs-string">&quot;active&quot;</span> [<span class="hljs-attr">showPercentage</span>]=<span class="hljs-string">&quot;true&quot;</span> <span class="hljs-attr">progressFormat</span>=<span class="hljs-string">&quot;fraction&quot;</span> /&gt;</span></code></pre>\n<p>Both formats describe completion rather than the current position. Disabled steps are excluded, skipped steps do not count as complete, and an empty enabled\nstep set displays <code>0/0</code>. <code>progressValue</code> overrides the percentage and bar only; the fraction always counts actual completed steps. Hide either counter format\nwith <code>showPercentage=&quot;false&quot;</code>.</p>\n<h2>API</h2>\n<h3>Stepper inputs and models</h3>\n<table>\n<thead>\n<tr>\n<th>Member</th>\n<th>Type</th>\n<th>Default / behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>mode</code></td>\n<td><code>StepperMode</code></td>\n<td><code>indicator</code>, <code>navigation</code>, <code>wizard</code></td>\n</tr>\n<tr>\n<td><code>steps</code></td>\n<td><code>readonly IStepDefinition[]</code></td>\n<td>Omitted for projected definitions</td>\n</tr>\n<tr>\n<td><code>activeStep</code></td>\n<td><code>model&lt;string | null&gt;</code></td>\n<td><code>null</code>; stable ID with two-way binding</td>\n</tr>\n<tr>\n<td><code>variant</code></td>\n<td><code>StepperVariant</code></td>\n<td><code>steps</code>, <code>segments</code>, <code>dots</code>, <code>progress</code>, <code>cards</code></td>\n</tr>\n<tr>\n<td><code>size</code></td>\n<td><code>StepperSize</code></td>\n<td><code>md</code>; also <code>sm</code>, <code>lg</code></td>\n</tr>\n<tr>\n<td><code>orientation</code></td>\n<td><code>StepperOrientation</code></td>\n<td><code>horizontal</code>; also <code>vertical</code></td>\n</tr>\n<tr>\n<td><code>responsive</code></td>\n<td><code>StepperResponsive</code></td>\n<td><code>scroll</code>; also <code>vertical</code>, <code>compact</code></td>\n</tr>\n<tr>\n<td><code>showLabels</code></td>\n<td><code>boolean</code></td>\n<td><code>true</code></td>\n</tr>\n<tr>\n<td><code>showDescriptions</code></td>\n<td><code>boolean</code></td>\n<td><code>true</code></td>\n</tr>\n<tr>\n<td><code>indicatorInteractive</code></td>\n<td><code>boolean</code></td>\n<td><code>false</code></td>\n</tr>\n<tr>\n<td><code>readOnly</code>, <code>readonly</code></td>\n<td><code>boolean</code></td>\n<td><code>false</code>; either blocks user/API edits</td>\n</tr>\n<tr>\n<td><code>linear</code></td>\n<td><code>boolean</code></td>\n<td><code>true</code>; requires completed predecessors</td>\n</tr>\n<tr>\n<td><code>selectionMode</code></td>\n<td><code>StepperSelectionMode</code></td>\n<td><code>internal</code>; also <code>controlled</code></td>\n</tr>\n<tr>\n<td><code>beforeTransition</code></td>\n<td><code>StepperGuard</code></td>\n<td>Optional application guard</td>\n</tr>\n<tr>\n<td><code>controls</code></td>\n<td><code>boolean</code></td>\n<td><code>true</code> in wizard mode only</td>\n</tr>\n<tr>\n<td><code>contentPolicy</code></td>\n<td><code>StepperContentPolicy</code></td>\n<td><code>retained</code>; also <code>eager</code>, <code>active</code></td>\n</tr>\n<tr>\n<td><code>focusOnChange</code></td>\n<td><code>boolean</code></td>\n<td><code>true</code> for wizard panels only</td>\n</tr>\n<tr>\n<td><code>completionContent</code></td>\n<td><code>TemplateRef&lt;unknown&gt;</code></td>\n<td>Optional application completion view</td>\n</tr>\n<tr>\n<td><code>progressValue</code></td>\n<td><code>number</code></td>\n<td>Optional explicit 0–100 completion percentage</td>\n</tr>\n<tr>\n<td><code>showPercentage</code></td>\n<td><code>boolean</code></td>\n<td><code>false</code>; shows the progress counter in either format</td>\n</tr>\n<tr>\n<td><code>progressFormat</code></td>\n<td><code>StepperProgressFormat</code></td>\n<td><code>percentage</code> (default) or <code>fraction</code> (<code>X/N</code>)</td>\n</tr>\n<tr>\n<td><code>labels</code></td>\n<td><code>Partial&lt;IStepperLabels&gt;</code></td>\n<td>Shared defaults, then English</td>\n</tr>\n<tr>\n<td><code>glassiness</code></td>\n<td>Shared <code>GlassinessMode</code></td>\n<td>Inherits global appearance for cards</td>\n</tr>\n<tr>\n<td><code>surfaceEffects</code></td>\n<td><code>boolean</code></td>\n<td><code>true</code>; interactive step lighting</td>\n</tr>\n</tbody></table>\n<h3>Step metadata</h3>\n<p>The declarative <code>Step</code> inputs match <code>IStepDefinition</code> fields except <code>content</code>/<code>labelTemplate</code>, which use <code>bxStepContent</code>/<code>bxStepLabel</code> templates.</p>\n<table>\n<thead>\n<tr>\n<th>Field</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code>, <code>label</code></td>\n<td>Required stable ID and <code>ResolvableText</code> name</td>\n</tr>\n<tr>\n<td><code>description</code>, <code>statusText</code></td>\n<td>Optional reactive translated text</td>\n</tr>\n<tr>\n<td><code>icon</code></td>\n<td>Optional Blocks <code>IconName</code></td>\n</tr>\n<tr>\n<td><code>disabled</code>, <code>optional</code></td>\n<td>Default <code>false</code>; excluded navigation / available skip action</td>\n</tr>\n<tr>\n<td><code>editable</code></td>\n<td>Default <code>true</code>; <code>false</code> prevents revisiting completed steps</td>\n</tr>\n<tr>\n<td><code>completed</code>, <code>skipped</code></td>\n<td>Optional explicit overrides of internal wizard state</td>\n</tr>\n<tr>\n<td><code>valid</code>, <code>validation</code></td>\n<td>Explicit validity or application-owned form state</td>\n</tr>\n<tr>\n<td><code>error</code>, <code>loading</code></td>\n<td>Application-owned error/busy state, default <code>false</code></td>\n</tr>\n<tr>\n<td><code>canExit</code>, <code>canEnter</code></td>\n<td>Optional per-step guards</td>\n</tr>\n<tr>\n<td><code>content</code>, <code>labelTemplate</code></td>\n<td>Optional data-driven templates</td>\n</tr>\n</tbody></table>\n<p>Explicit <code>completed: false</code> prevents derived completion; a linear workflow must receive an application-confirmed completion override before advancing that step.\nExplicit completion is still ineffective while validation is invalid/pending or an application error/loading state is set. Derived skipped state is cleared when\nthe step is subsequently completed. Visual priority is disabled, loading, error, skipped, completed, then active/pending; <code>aria-current</code> always tracks selection\nindependently.</p>\n<h3>Methods, state and events</h3>\n<table>\n<thead>\n<tr>\n<th>Member</th>\n<th>Result / payload</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>goTo(id, source?)</code></td>\n<td><code>Promise&lt;IStepperTransition&gt;</code></td>\n</tr>\n<tr>\n<td><code>next(source?)</code>, <code>previous(source?)</code></td>\n<td>Same return type; skip disabled/non-editable completed destinations</td>\n</tr>\n<tr>\n<td><code>skip(source?)</code>, <code>finish(source?)</code></td>\n<td>Same return type; optional skip / explicit final action</td>\n</tr>\n<tr>\n<td><code>reset(id?)</code></td>\n<td><code>void</code>; restart without guards, preserve application-owned form data</td>\n</tr>\n<tr>\n<td><code>selectedStep()</code></td>\n<td>Effective metadata or <code>null</code></td>\n</tr>\n<tr>\n<td><code>pending()</code>, <code>lastTransition()</code></td>\n<td>Read-only current operation / latest settled result</td>\n</tr>\n<tr>\n<td><code>progress()</code>, <code>isComplete()</code>, <code>isReadonly()</code></td>\n<td>Completed percentage / finished workflow / combined readonly</td>\n</tr>\n<tr>\n<td><code>stepRequested</code></td>\n<td><code>IStepperRequest</code>: ID, zero-based index, source, action</td>\n</tr>\n<tr>\n<td><code>selectionChanged</code></td>\n<td><code>IStepperSelection</code>: ID, index, previous ID</td>\n</tr>\n<tr>\n<td><code>transitionFinished</code></td>\n<td><code>IStepperTransition</code>: request, from/to IDs, outcome, reason/error</td>\n</tr>\n<tr>\n<td><code>completed</code></td>\n<td><code>IStepperCompletion</code>: ordered completed and skipped ID arrays</td>\n</tr>\n</tbody></table>\n<p>Sources are <code>pointer</code>, <code>keyboard</code>, <code>programmatic</code> (the method default) and <code>controls</code>. Outcomes are <code>accepted</code>, <code>rejected</code>, <code>invalid</code>, <code>error</code>, <code>cancelled</code> and\n<code>busy</code>. <code>busy</code> is returned directly without a second settled-result event. Readonly state blocks reset and requests but still permits authoritative external\nselection updates. Missing destinations are rejected without throwing. Skipping a final optional step finishes the workflow while keeping that step skipped.\nFinal completion requires all enabled required steps even in non-linear mode.</p>\n<h2>Appearance and customization</h2>\n<p>Sizes change marker diameter, segment thickness, spacing, typography and surface padding. Connectors remain thin and solid, with flush inner joins at fractional\nwidths and unequal compact-step sizes. Interactive controls retain a minimum 44 CSS pixel target. Segments use different thicknesses for <code>sm</code>, <code>md</code> and <code>lg</code>.\nDots use compact filled, hollow and checked indicators; progress uses actual completion rather than active position. Dots measure 1.25 / 1.5 / 1.75rem across\nthe size presets so status symbols have clear interior spacing. Step icons and spinners scale to 16 / 18 / 20 CSS pixels. Vertical progress keeps a horizontal\ncontinuous completion bar above its vertical step list.</p>\n<table>\n<thead>\n<tr>\n<th>CSS custom property</th>\n<th>Default</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--bx-stepper-marker-size</code></td>\n<td>Size preset: 1.75 / 2 / 2.5rem</td>\n</tr>\n<tr>\n<td><code>--bx-stepper-dot-size</code></td>\n<td>Size preset: 1.25 / 1.5 / 1.75rem</td>\n</tr>\n<tr>\n<td><code>--bx-stepper-marker-radius</code></td>\n<td>Shared pill radius</td>\n</tr>\n<tr>\n<td><code>--bx-stepper-thickness</code></td>\n<td>Size preset: 0.125 / 0.25 / 0.5rem</td>\n</tr>\n<tr>\n<td><code>--bx-stepper-gap</code></td>\n<td>Size preset: shared spacing 2 / 3 / 4</td>\n</tr>\n<tr>\n<td><code>--bx-stepper-padding</code></td>\n<td>Size preset: shared spacing 2 / 3 / 4</td>\n</tr>\n<tr>\n<td><code>--bx-stepper-color</code></td>\n<td><code>--bx-accent</code></td>\n</tr>\n<tr>\n<td><code>--bx-stepper-on-color</code></td>\n<td><code>--bx-on-accent</code>; foreground paired with the active fill</td>\n</tr>\n<tr>\n<td><code>--bx-stepper-connector-thickness</code></td>\n<td><code>2px</code>; separate from segment/progress thickness</td>\n</tr>\n<tr>\n<td><code>--bx-stepper-segment-radius</code></td>\n<td>Shared pill radius</td>\n</tr>\n<tr>\n<td><code>--bx-stepper-segment-length</code></td>\n<td>Shared spacing 10 for vertical segments</td>\n</tr>\n<tr>\n<td><code>--bx-stepper-card-background</code></td>\n<td><code>--bx-bg-surface</code></td>\n</tr>\n<tr>\n<td><code>--bx-stepper-card-radius</code></td>\n<td>Shared medium radius</td>\n</tr>\n<tr>\n<td><code>--bx-stepper-compact-active-width</code></td>\n<td><code>8rem</code>; readable active label in compact horizontal layouts</td>\n</tr>\n</tbody></table>\n<p>Step bodies use <code>BxSurfaceDirective</code>, global materials and transparency fallbacks. Cards have a persistent neutral surface. Other variants keep transparent\nbackgrounds, including selected and hovered steps. Hover feedback emphasizes the marker and underlines its label without moving content. Shared lighting\nattaches to the interactive button, with emitted light positioned at the visible marker for non-card variants and the card surface for cards. Labels and empty\nbutton space do not extend a marker&#39;s light source. Markers and segments do not receive independent glass surfaces. Global Off and accessibility policies take\nprecedence over component overrides. Theme and palette changes use semantic CSS variables on mounted instances. Active markers pair the accent fill with its\non-accent foreground; completed markers use the matching subtle surface. Errors consistently use danger tokens for the marker, feedback and emitted light.\nDecorative outlines and dashed connectors are avoided; keyboard focus retains a visible outline. Horizontal labels are centered below markers, and vertical\nlabels align with the marker center. Cards align their text stack to the top with a small marker offset, using the same icon-and-text arrangement as alerts and\nbanners. No independent animation or lighting implementation is introduced.</p>\n<p>Custom labels use <code>&lt;ng-template bxStepLabel let-step let-index=&quot;index&quot; let-status=&quot;status&quot;&gt;…&lt;/ng-template&gt;</code> inside <code>bx-step</code>. Keep content non-interactive and\npreserve a meaningful plain <code>label</code>, which remains the button&#39;s accessible name. The custom label is decorative to avoid duplicated accessible names.</p>\n<p>Unavailable steps use muted markers and reduced visual emphasis. Completed steps with <code>editable: false</code> receive the same unavailable treatment when revisiting\nis blocked. Read-only steppers keep their content, completion symbols and keyboard focus, use neutral markers, and suppress interaction feedback and lighting.\nThe current step remains distinguishable by its stronger marker border; read-only does not disable the control or discard progress.</p>\n<h3>Localization</h3>\n<p>Every component-owned label is configurable as <code>ResolvableText</code>. Supply <code>labels</code> per instance or provide\n<code>{ provide: BX_STEPPER_DEFAULTS, useValue: { labels: { next: { key: &#39;workflow.next&#39; } } } }</code>. Merge precedence is instance member, shared member, English\ndefault. Text reacts to <code>BX_I18N.version()</code> changes. Without an adapter, strings work directly and translation keys fall back to their key. Position text\nreceives <code>index</code> (one-based), <code>count</code>, <code>label</code> and rounded <code>percent</code>; plain strings can use <code>{index}</code>, <code>{count}</code>, <code>{label}</code> and <code>{percent}</code> placeholders.\n<code>IStepperLabels</code> also covers pending, awaitingConfirmation, active, completed, skipped, error, loading, disabled, optional and rejection/invalid feedback.</p>\n<h2>Behavior and accessibility</h2>\n<p>The header is a named group with an ordered list. Passive indicators have no buttons. Interactive headers use native buttons with <code>aria-current=&quot;step&quot;</code>,\ndescriptions and wizard panel relationships. They do not claim tablist semantics. State text, check/error/skip symbols and filled/hollow markers supplement\nsemantic colors. Loading remains identifiable with reduced motion and forced colors.</p>\n<p>Interactive steps use one roving tab stop. Orientation-aware arrows, Home and End move focus without committing selection; Enter and Space activate through\nnative button behavior. Horizontal movement reverses in RTL. Disabled and non-editable completed destinations are skipped. Keyboard direction follows rendered\nCSS orientation, including responsive vertical layouts. Navigation mode never moves focus on external selection. Wizards focus newly rendered panels by default;\nturn off <code>focusOnChange</code> when your application owns focus. If no panel exists, focus falls back to the step button. Completion content receives focus.</p>\n<p>Status announcements cover loading, validation refusal, guard refusal, failures and completion. Wizard panel names identify selection changes without another\nrepeated live announcement. <code>BxA11yService</code> and shared surface/progress/spinner policies handle live reduced-motion preferences. Semantic tokens, logical CSS\nand forced-colors rules preserve readable state across themes, RTL and accessibility modes.</p>\n<p>The step list scrolls inside a separate wrapper with space below its surfaces for native horizontal scrollbars, including WebKit overlay scrollbars.\n<code>responsive=&quot;scroll&quot;</code> preserves labels with a reachable horizontal scroll region. <code>vertical</code> changes the list at the shared <code>sm</code> breakpoint. <code>compact</code> hides\nsupporting text and keeps the active label. Hidden visual text remains in accessible naming/descriptions. CSS performs responsive layout without browser-only\nstate during server rendering. Content wraps for long translations and constrained containers.</p>\n<h3>Material and motion pilot</h3>\n<p>Markers and connectors receive environmental lighting through the existing surface engine. Circular indicators reuse its rim, material and pressure response;\ncard presentations retain their card backing. Filled current indicators emit more strongly than tonal completed or neutral inactive indicators during engine\ninteraction, with restrained extra error emphasis. Emission strength does not increase reception. Indicator mode remains passive unless interaction is enabled.\nRounded hover highlights mix the semantic state color with the theme surface; they do not increase a dark elevation shadow. The traveling accent has no shadow,\nkeeping its light-mode rim distinct from the marker&#39;s resting depth. Segment tracks keep their continuous geometry, with fully tinted active/completed fills so\ntheir existing material remains bright. Emission follows the visible segment surface. Error contours take precedence over cached environmental rim tint, and\ncommitted status changes urgently refresh marker lighting.</p>\n<p>A persistent selection accent travels between the committed positions, interpolating both axes and dimensions. It surrounds circular/segment markers and adapts\nto progress headers, including vertical and responsive layouts. Cards instead animate their own border and rim lighting in place; no accent travels across the\nunconnected space between cards. Velocity adds a small deformation along the travel axis. Connector completion fills independently of active position, so\nvisiting a step never implies completing it. Circular indicators compress on press and recover on the shared spring. Rapid navigation retargets existing motion\nrather than restarting it. Rejected guards and unconfirmed controlled requests leave the selection accent at the committed step.</p>\n<p>Live reduced motion snaps the accent and completion fill and removes indicator deformation. Reduced transparency retains the shared opaque material fallback\nindependently: the traveling accent uses a soft opaque tint, preserving the contrast of the solid current marker and its label. Forced colors retain the\nexplicit current/completed/error markers and hide the decorative traveling accent. Springs and observers are released with their component. No existing theme\ntokens were renamed or changed.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/stepper</code> for all modes, variants, sizes and orientations; English/Spanish/French/German text changes; appearance controls; a scroll-driven\nsection navigator; validated Reactive Forms and Signal Forms; asynchronous save success, guard refusal and failure/retry; optional/disabled/non-editable steps;\ncustom labels and controls; dynamic definitions; controlled confirmation; completion and reset.</p>\n<p>Run <code>npm run test:stepper</code> for the colocated Angular TestBed browser suite. It uses the installed Angular unit-test builder with Karma/Jasmine and\nChromeHeadless.</p>\n<p>Functional references: <a href="https://material.angular.dev/components/stepper/overview">Angular Material</a>, <a href="https://primeng.org/stepper">PrimeNG</a>,\n<a href="https://mui.com/material-ui/react-stepper/">MUI</a>, <a href="https://mantine.dev/core/stepper/">Mantine</a> and <a href="https://ng.ant.design/components/steps/en">NG-ZORRO</a>.\nVisual review also considers <a href="https://github.com/JCarterJohnson/vibecoded-design-tells">vibecoded-design-tells</a>; Blocks tokens and surfaces remain\nauthoritative.</p>\n',
  'projects/blocks/navigation/components/top-nav/README.md':
    '<h1>Top navigation</h1>\n<p>A responsive horizontal route navigation bar with brand/action slots, a compact menu, contextual search, and one shared panel for every nesting level. It uses\nthe same route state, item views, Back behavior, search matching, focus/scroll bookmarks, and tonal styling as <code>SideNav</code>.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> {\n    <span class="hljs-title class_">TopNav</span>,\n    <span class="hljs-title class_">TopNavBrandDirective</span>,\n    <span class="hljs-title class_">TopNavActionsDirective</span>,\n    <span class="hljs-title class_">ITopNavConfig</span>,\n    <span class="hljs-title class_">ITopNavSlotContext</span>,\n    <span class="hljs-title class_">INavigationItemContext</span>,\n    defineNavigation,\n    provideNavigation\n} <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;</code></pre>\n<p>Import the component and any slot directives used by your standalone shell. Root links come from <code>NavigationService.menuTreeGroups()</code> unless the optional\n<code>groups</code> input is supplied. An explicit empty array omits the primary menu control while preserving brand/actions; with search disabled this also serves as a\ntoolbar shell.</p>\n<h2>Working usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Component</span>, signal } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">RouterLink</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/router&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">TopNav</span>, <span class="hljs-title class_">TopNavBrandDirective</span>, <span class="hljs-title class_">TopNavActionsDirective</span>, <span class="hljs-title class_">ITopNavConfig</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Button</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;\n\n<span class="hljs-meta">@Component</span>({\n    <span class="hljs-attr">selector</span>: <span class="hljs-string">&#x27;app-header&#x27;</span>,\n    <span class="hljs-attr">imports</span>: [<span class="hljs-title class_">RouterLink</span>, <span class="hljs-title class_">TopNav</span>, <span class="hljs-title class_">TopNavBrandDirective</span>, <span class="hljs-title class_">TopNavActionsDirective</span>, <span class="hljs-title class_">Button</span>],\n    <span class="hljs-attr">template</span>: <span class="hljs-string">`\n        &lt;bx-top-nav [config]=&quot;config&quot; [(opened)]=&quot;menuOpen&quot;&gt;\n            &lt;ng-template bxTopNavBrand let-compact&gt;\n                &lt;a routerLink=&quot;/home&quot;&gt;Studio&lt;/a&gt;\n            &lt;/ng-template&gt;\n            &lt;ng-template bxTopNavActions&gt;\n                &lt;a bx-button variant=&quot;tonal&quot; color=&quot;grayscale&quot; routerLink=&quot;/settings&quot;&gt;Settings&lt;/a&gt;\n            &lt;/ng-template&gt;\n        &lt;/bx-top-nav&gt;\n    `</span>\n})\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">Header</span> {\n    <span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> menuOpen = <span class="hljs-title function_">signal</span>(<span class="hljs-literal">false</span>);\n    <span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">config</span>: <span class="hljs-title class_">ITopNavConfig</span> = { <span class="hljs-attr">compactBreakpoint</span>: <span class="hljs-string">&#x27;lg&#x27;</span>, <span class="hljs-attr">position</span>: <span class="hljs-string">&#x27;sticky&#x27;</span> };\n}</code></pre>\n<p>Declare the same route metadata used by side navigation and breadcrumbs:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">const</span> navigation = <span class="hljs-title function_">defineNavigation</span>({\n    <span class="hljs-attr">sections</span>: [{ <span class="hljs-attr">id</span>: <span class="hljs-string">&#x27;workspace&#x27;</span>, <span class="hljs-attr">title</span>: <span class="hljs-string">&#x27;Workspace&#x27;</span> }],\n    <span class="hljs-attr">topNav</span>: { <span class="hljs-attr">searchable</span>: <span class="hljs-literal">true</span>, <span class="hljs-attr">ariaLabel</span>: { <span class="hljs-attr">key</span>: <span class="hljs-string">&#x27;navigation.primary&#x27;</span> } }\n});\n<span class="hljs-keyword">const</span> { withInAppNavigation } = navigation;\n<span class="hljs-keyword">const</span> routes = [\n    <span class="hljs-title function_">withInAppNavigation</span>(\n        {\n            <span class="hljs-attr">path</span>: <span class="hljs-string">&#x27;projects&#x27;</span>,\n            <span class="hljs-attr">children</span>: [\n                <span class="hljs-title function_">withInAppNavigation</span>(\n                    { <span class="hljs-attr">path</span>: <span class="hljs-string">&#x27;tokens&#x27;</span>, <span class="hljs-attr">loadComponent</span>: <span class="hljs-function">() =&gt;</span> <span class="hljs-keyword">import</span>(<span class="hljs-string">&#x27;./tokens&#x27;</span>).<span class="hljs-title function_">then</span>(<span class="hljs-function">(<span class="hljs-params">m</span>) =&gt;</span> m.<span class="hljs-property">Tokens</span>) },\n                    { <span class="hljs-attr">label</span>: { <span class="hljs-attr">key</span>: <span class="hljs-string">&#x27;navigation.tokens&#x27;</span> }, <span class="hljs-attr">icon</span>: { <span class="hljs-attr">name</span>: <span class="hljs-string">&#x27;swatch-book&#x27;</span> } }\n                )\n            ]\n        },\n        { <span class="hljs-attr">label</span>: <span class="hljs-string">&#x27;Projects&#x27;</span>, <span class="hljs-attr">section</span>: <span class="hljs-string">&#x27;workspace&#x27;</span>, <span class="hljs-attr">icon</span>: { <span class="hljs-attr">name</span>: <span class="hljs-string">&#x27;folder&#x27;</span> } }\n    )\n];\n<span class="hljs-comment">// Application providers: provideRouter(routes), ...provideNavigation(navigation.config)</span></code></pre>\n<p>A parent label always navigates to the parent&#39;s own route. Its separate chevron opens children without navigating. Declare an empty child route if the parent\nURL should render its own page. Parameterized menu destinations still require concrete application-owned entries; navigation does not invent parameter values.</p>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Input/model/output/method</th>\n<th>Contract</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>config</code></td>\n<td>Optional <code>ITopNavConfig</code>; instance settings override <code>provideNavigation().topNav</code>, then library defaults</td>\n</tr>\n<tr>\n<td><code>groups</code></td>\n<td>Optional readonly <code>INavigationTreeGroup[]</code>; otherwise hierarchical route sections from <code>NavigationService</code></td>\n</tr>\n<tr>\n<td><code>itemTemplate</code></td>\n<td>Optional <code>TemplateRef&lt;INavigationItemContext&gt;</code> inside the managed page link/button; search paths remain visible</td>\n</tr>\n<tr>\n<td><code>opened</code> / <code>openedChange</code></td>\n<td>Two-way panel state, initially false, never persisted</td>\n</tr>\n<tr>\n<td><code>itemSelected</code></td>\n<td>The selected resolved <code>INavigationItem</code>; selecting a page closes the panel</td>\n</tr>\n<tr>\n<td><code>isCompact()</code>, <code>query()</code></td>\n<td>Readonly resolved presentation and current search query</td>\n</tr>\n<tr>\n<td><code>panelId</code></td>\n<td>Stable panel ID for an application-owned trigger&#39;s <code>aria-controls</code></td>\n</tr>\n<tr>\n<td><code>open(origin?, focusSearch?)</code></td>\n<td>Open the panel; pass a click event/element for positioning and focus return; the second argument optionally focuses search</td>\n</tr>\n<tr>\n<td><code>close(restoreFocus?)</code></td>\n<td>Close the panel; defaults to restoring the opening control&#39;s focus</td>\n</tr>\n<tr>\n<td><code>toggle(origin?)</code></td>\n<td>Toggle the panel from an optional click event or element</td>\n</tr>\n<tr>\n<td><code>search(query)</code></td>\n<td>Search programmatically, opening the panel if necessary; an empty query restores browsing</td>\n</tr>\n</tbody></table>\n<p><code>ITopNavConfig</code> options are optional:</p>\n<table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Default / behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>position</code>, <code>top</code></td>\n<td><code>&#39;sticky&#39;</code>, <code>&#39;0px&#39;</code>; <code>&#39;inline&#39;</code> leaves positioning to the containing layout</td>\n</tr>\n<tr>\n<td><code>compactBreakpoint</code></td>\n<td>Shared <code>&#39;lg&#39;</code> breakpoint, applied to both the viewport and the bar&#39;s available width</td>\n</tr>\n<tr>\n<td><code>compact</code></td>\n<td>Unset for automatic presentation; true forces compact, false bypasses the breakpoint. Content that does not fit always uses compact navigation</td>\n</tr>\n<tr>\n<td><code>panelWidth</code>, <code>panelMaxHeight</code></td>\n<td><code>&#39;24rem&#39;</code>, <code>&#39;32rem&#39;</code>; viewport constraints and the available space above/below the trigger take precedence</td>\n</tr>\n<tr>\n<td><code>searchable</code></td>\n<td><code>true</code>; the toolbar search button opens the same shared panel</td>\n</tr>\n<tr>\n<td><code>showItemIcons</code>, <code>showSectionIcons</code></td>\n<td><code>false</code>, <code>false</code>; optional leading item icons and panel section icons</td>\n</tr>\n<tr>\n<td><code>showSearchGuide</code></td>\n<td>Deprecated compatibility option; ignored because search guides have been removed</td>\n</tr>\n<tr>\n<td><code>ariaLabel</code></td>\n<td><code>&#39;Main navigation&#39;</code></td>\n</tr>\n<tr>\n<td><code>searchPlaceholder</code>, <code>searchLabel</code>, <code>clearSearchLabel</code></td>\n<td><code>&#39;Search navigation…&#39;</code>, <code>&#39;Search navigation&#39;</code>, <code>&#39;Clear search&#39;</code></td>\n</tr>\n<tr>\n<td><code>openLabel</code>, <code>closeLabel</code></td>\n<td><code>&#39;Open navigation&#39;</code>, <code>&#39;Close navigation&#39;</code></td>\n</tr>\n<tr>\n<td><code>emptyText</code></td>\n<td><code>&#39;No matching pages.&#39;</code></td>\n</tr>\n<tr>\n<td><code>submenuLabel</code>, <code>resultLabel</code></td>\n<td><code>&#39;Open submenu&#39;</code>, <code>&#39;Search result&#39;</code></td>\n</tr>\n<tr>\n<td><code>backLabel</code>, <code>pathLabel</code></td>\n<td><code>&#39;Back&#39;</code>, <code>&#39;Navigation path&#39;</code></td>\n</tr>\n</tbody></table>\n<p>All configurable text accepts <code>ResolvableText</code>. <code>BX_I18N</code> is optional; strings work without it, missing adapters fall back to translation keys, and an adapter\nversion signal refreshes mounted labels, badges, keywords, action names, and paths. Section titles supplied by application-owned <code>groups</code> are resolved strings,\nso update that input when the language changes. The playground shares one live language adapter between its fixtures and navigation.</p>\n<p><code>bxTopNavBrand</code> and <code>bxTopNavActions</code> register templates with their owner. Their <code>ITopNavSlotContext</code> contains <code>$implicit</code>/<code>compact</code> and <code>open</code>. Both slots\nremain available in compact presentation. Keep projected controls responsive and provide accessible names for icon-only actions.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> #<span class="hljs-attr">item</span> <span class="hljs-attr">let-entry</span> <span class="hljs-attr">let-active</span>=<span class="hljs-string">&quot;active&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>{{ entry.label }}<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span>\n    @if (active) { <span class="hljs-tag">&lt;<span class="hljs-name">small</span> <span class="hljs-attr">aria-hidden</span>=<span class="hljs-string">&quot;true&quot;</span>&gt;</span>✓<span class="hljs-tag">&lt;/<span class="hljs-name">small</span>&gt;</span> }\n<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-top-nav</span> [<span class="hljs-attr">itemTemplate</span>]=<span class="hljs-string">&quot;item&quot;</span> /&gt;</span></code></pre>\n<p>Custom item content is presentation only; do not place nested links/buttons inside it. Native links preserve modified-click and open-in-new-tab behavior.\nSupplying new <code>groups</code> arrays updates mounted navigation without a transport dependency; applications own loading, access policy, and request lifecycle for\ncustom trees. Service-generated groups retain the existing route visibility/access adapter contracts.</p>\n<h2>Appearance and customization</h2>\n<p>The bar uses the shared Blocks surface. Its panel is an opaque menu surface with semantic colors and theme inheritance. It intentionally uses no nested backdrop\nfilter. Keep the component outside another <code>bxSurface</code> when demonstrating bar blur, since Blocks suppresses nested glass passes.</p>\n<table>\n<thead>\n<tr>\n<th>CSS variable</th>\n<th>Default</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--bx-top-nav-top</code></td>\n<td>Resolved sticky offset</td>\n</tr>\n<tr>\n<td><code>--bx-top-nav-panel-width</code>, <code>--bx-top-nav-panel-max-height</code></td>\n<td>Resolved width/height settings</td>\n</tr>\n<tr>\n<td><code>--bx-top-nav-height</code>, <code>--bx-top-nav-gap</code></td>\n<td><code>3.75rem</code> minimum height and shared spacing 2 between bar regions</td>\n</tr>\n<tr>\n<td><code>--bx-top-nav-padding-inline</code>, <code>--bx-top-nav-padding-block</code></td>\n<td>Shared spacing 3 and spacing 2</td>\n</tr>\n<tr>\n<td><code>--bx-top-nav-radius</code></td>\n<td>Shared medium radius</td>\n</tr>\n<tr>\n<td><code>--bx-top-nav-item-radius</code>, <code>--bx-top-nav-item-gap</code></td>\n<td>Shared medium radius, spacing 2</td>\n</tr>\n<tr>\n<td><code>--bx-top-nav-item-background</code></td>\n<td>Transparent</td>\n</tr>\n<tr>\n<td><code>--bx-top-nav-item-hover-background</code>, <code>--bx-top-nav-item-active-background</code></td>\n<td>Shared accent tonal surface</td>\n</tr>\n</tbody></table>\n<p>Only the most specific matching route gets selected styling. Query parameters, matrix parameters, fragments, and redirect URLs do not produce multiple selected\nroutes. A horizontal ancestor may use accent text for context without acquiring the selected box. Section headings in the panel likewise use accent text. Page\nlinks and disclosures have independent hover and focus surfaces.</p>\n<h2>Behavior and accessibility</h2>\n<p>The bar measures its primary links and remaining space after brand/actions. It switches to the compact menu at the configured breakpoint or whenever content\ndoes not fit, including changes from translation, slot content, fonts, resizing, and browser zoom. Links are not left hidden behind an essential horizontal\nscrollbar. A compact slot that shrinks its brand/actions does not cause repeated expand/collapse feedback.</p>\n<p>Both presentations use one dropdown panel. The first disclosure opens it below the bar using <code>MenuTriggerDirective</code> and the existing overlay context. Further\ndisclosures replace its list; recursive overlays never accumulate. Back and the ancestor path remain above the scrolling list. The first, section-labelled\naction returns to the full navigation root and reveals the item that opened the branch unless that section&#39;s own list was explicitly opened. Ancestor buttons\nopen their submenu panels without navigating to their pages, and the parent&#39;s heading remains a route link. Back restores the previous list&#39;s scroll and\ndisclosure focus. The browsing path survives presentation changes; the panel can reattach to the compact control when its former origin disappears.</p>\n<p>Search always renders flat direct matches with muted parent paths. It does not open nested panels or color ancestors as selected. After navigating to a result,\nclearing search opens its containing submenu and scrolls the selected row into view while retaining search-field focus. Without a successful selection it\nrestores the prior browsing location and scroll position. A result label navigates directly; its disclosure leaves search and browses the result&#39;s children.\nSearch results have no floating guides; the legacy <code>showSearchGuide</code> option is ignored and the former guide CSS variables no longer affect the component.</p>\n<p>Horizontal links use a menubar with one tab stop, Left/Right movement respecting RTL, Home/End, and Down to open a parent&#39;s submenu. The panel uses native links\nand menu semantics; Up/Down and Home/End navigate a list. Back, Escape, or the opposite arrow returns one nested level. Escape at the panel root or its close\naction dismisses it and restores the opening control. Tab stays inside the open panel; outside clicks and route changes close it. Focus return uses\n<code>preventScroll</code>.</p>\n<p>The panel is nonmodal: it does not lock page scrolling. Shared native CSS anchoring follows scrolling and closes a panel whose origin becomes clipped/offscreen.\nThe bar&#39;s overlay context supports sticky headers and top-layer surfaces; theme, palette, opaque appearance, forced colors, and accessibility changes update\nmounted controls and overlays. Resize/direction observers, subscriptions, focus traps, and overlays clean up with their owners. Browser measurements are\ndeferred until rendering and guarded for SSR.</p>\n<h2>Playground</h2>\n<p>Visit <code>/components/top-nav</code> (redirects to <code>/components/top-nav/overview</code>). The demo uses the same four-level fixture, keywords, tags, disabled item, and\nlanguage dropdown with English, Spanish, French, and German translations as side navigation. Page links stay on the top-nav demo route family, so route\nhighlighting and selection feedback remain observable.</p>\n<p>Change preview width, force compact, add action controls, toggle icons/RTL/custom templates/sticky presentation, and switch languages. The preview uses the\nshared <code>sm</code> breakpoint so both presentations can be exercised within the documentation layout; library defaults remain <code>lg</code>. Try <code>dsgn tkns</code>, <code>palette</code>,\n<code>tokens</code>, or <code>Palette</code>, enter several levels, and use Back or clear search to inspect context and restoration. Appearance controls in the application toolbar\napply to this component and its open panel.</p>\n<p>The playground application&#39;s own toolbar also uses <code>TopNav</code>: it supplies an empty <code>groups</code> array and disables search to retain the existing sidenav as the sole\nprimary navigation. The sidenav trigger lives in the brand slot; Appearance, palette, and theme-mode controls live in the actions slot. Their dropdowns retain\nthe existing overlay context.</p>\n',
  'projects/blocks/navigation/directives/side-nav-footer/README.md':
    '<h1>Side nav footer slot</h1>\n<p>Provide custom footer content for <code>bx-side-nav</code> through a typed projected template.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SideNav</span>, <span class="hljs-title class_">SideNavFooterDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;</code></pre>\n<p>Add these declarations to the consuming standalone component&#39;s imports.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-side-nav</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxSideNavFooter</span> <span class="hljs-attr">let-collapsed</span>=<span class="hljs-string">&quot;collapsed&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>{{ collapsed ? &#x27;Blocks&#x27; : &#x27;Blocks workspace&#x27; }}<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-side-nav</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>SideNavFooterDirective</code> selects <code>[bxSideNavFooter]</code> and registers its <code>TemplateRef</code> with the containing <code>SideNav</code>. The template context exposes <code>collapsed</code> and\n<code>mobile</code>; <code>$implicit</code> is equivalent to <code>collapsed</code>. There are no configurable directive inputs or outputs.</p>\n<h2>Appearance and customization</h2>\n<p>The template owns its content while the navigation component owns layout and material. Use Blocks controls and shared theme tokens inside the slot.</p>\n<h2>Behavior and accessibility</h2>\n<p>Place the template inside its owning navigation component. Registration is removed when the directive is destroyed. Interactive slot content must retain\naccessible names and keyboard operation. Use the context to adapt content to the available space.</p>\n<h2>Playground</h2>\n<p>Visit <code>/components/side-nav</code> and see the <a href="components/side-nav">owning component guide</a>.</p>\n',
  'projects/blocks/navigation/directives/side-nav-header/README.md':
    '<h1>Side nav header slot</h1>\n<p>Provide custom header content for <code>bx-side-nav</code> through a typed projected template.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SideNav</span>, <span class="hljs-title class_">SideNavHeaderDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;</code></pre>\n<p>Add these declarations to the consuming standalone component&#39;s imports.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-side-nav</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxSideNavHeader</span> <span class="hljs-attr">let-collapsed</span>=<span class="hljs-string">&quot;collapsed&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>{{ collapsed ? &#x27;Blocks&#x27; : &#x27;Blocks workspace&#x27; }}<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-side-nav</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>SideNavHeaderDirective</code> selects <code>[bxSideNavHeader]</code> and registers its <code>TemplateRef</code> with the containing <code>SideNav</code>. The template context exposes <code>collapsed</code> and\n<code>mobile</code>; <code>$implicit</code> is equivalent to <code>collapsed</code>. There are no configurable directive inputs or outputs.</p>\n<h2>Appearance and customization</h2>\n<p>The template owns its content while the navigation component owns layout and material. Use Blocks controls and shared theme tokens inside the slot.</p>\n<h2>Behavior and accessibility</h2>\n<p>Place the template inside its owning navigation component. Registration is removed when the directive is destroyed. Interactive slot content must retain\naccessible names and keyboard operation. Use the context to adapt content to the available space.</p>\n<h2>Playground</h2>\n<p>Visit <code>/components/side-nav</code> and see the <a href="components/side-nav">owning component guide</a>.</p>\n',
  'projects/blocks/navigation/directives/step-content/README.md':
    '<h1>Lazy step content</h1>\n<p>Use this declaration inside <code>bx-stepper</code> to configure workflow presentation and content. See the <a href="components/stepper">Stepper guide</a> for the\nfull API and runnable examples.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">StepContentDirective</span>, <span class="hljs-title class_">Step</span>, <span class="hljs-title class_">Stepper</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-stepper</span> <span class="hljs-attr">mode</span>=<span class="hljs-string">&quot;wizard&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-step</span> <span class="hljs-attr">id</span>=<span class="hljs-string">&quot;details&quot;</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Details&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxStepContent</span>&gt;</span>Details content<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-step</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-stepper</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>StepContentDirective.templateRef</code> captures the projected <code>TemplateRef&lt;unknown&gt;</code>. The owning stepper controls its creation and destruction.</p>\n<h2>Appearance and customization</h2>\n<p>Presentation inherits the owning stepper&#39;s variant, size, semantic tokens and appearance policies. Supply a meaningful plain or translated step label.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use <code>bxStepContent</code> for deferred creation. The stepper supports eager, lazy-retained and destroy-inactive content policies. Ordinary projection is eager.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/stepper</code> for validated workflows and content/label customization.</p>\n',
  'projects/blocks/navigation/directives/step-label/README.md':
    '<h1>Custom step labels</h1>\n<p>Use this declaration inside <code>bx-stepper</code> to configure workflow presentation and content. See the <a href="components/stepper">Stepper guide</a> for the\nfull API and runnable examples.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">StepLabelDirective</span>, <span class="hljs-title class_">Step</span>, <span class="hljs-title class_">Stepper</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-stepper</span> <span class="hljs-attr">mode</span>=<span class="hljs-string">&quot;wizard&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-step</span> <span class="hljs-attr">id</span>=<span class="hljs-string">&quot;review&quot;</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Review&quot;</span>\n        &gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxStepLabel</span> <span class="hljs-attr">let-step</span> <span class="hljs-attr">let-status</span>=<span class="hljs-string">&quot;status&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">strong</span>&gt;</span>{{ step.label }}<span class="hljs-tag">&lt;/<span class="hljs-name">strong</span>&gt;</span> · {{ status }}<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>&lt;/bx-step\n    &gt;\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-stepper</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>StepLabelDirective.templateRef</code> captures <code>TemplateRef&lt;IStepperLabelContext&gt;</code>. The context supplies <code>$implicit</code> metadata, zero-based <code>index</code>, and resolved\n<code>status</code>. The template context guard types these variables.</p>\n<h2>Appearance and customization</h2>\n<p>Presentation inherits the owning stepper&#39;s variant, size, semantic tokens and appearance policies. Supply a meaningful plain or translated step label.</p>\n<h2>Behavior and accessibility</h2>\n<p>Custom labels are visual content inside a native button; do not nest interactive controls. The plain step label remains the accessible name.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/stepper</code> for validated workflows and content/label customization.</p>\n',
  'projects/blocks/navigation/directives/top-nav-actions/README.md':
    '<h1>Top nav actions slot</h1>\n<p>Provide custom action content for <code>bx-top-nav</code> through a typed projected template.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">TopNav</span>, <span class="hljs-title class_">TopNavActionsDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;</code></pre>\n<p>Add these declarations to the consuming standalone component&#39;s imports.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-top-nav</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxTopNavActions</span> <span class="hljs-attr">let-compact</span>=<span class="hljs-string">&quot;compact&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>{{ compact ? &#x27;Blocks&#x27; : &#x27;Blocks workspace&#x27; }}<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-top-nav</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>TopNavActionsDirective</code> selects <code>[bxTopNavActions]</code> and registers its <code>TemplateRef</code> with the containing <code>TopNav</code>. The template context exposes <code>compact</code> and\n<code>open</code>; <code>$implicit</code> is equivalent to <code>compact</code>. There are no configurable directive inputs or outputs.</p>\n<h2>Appearance and customization</h2>\n<p>The template owns its content while the navigation component owns layout and material. Use Blocks controls and shared theme tokens inside the slot.</p>\n<h2>Behavior and accessibility</h2>\n<p>Place the template inside its owning navigation component. Registration is removed when the directive is destroyed. Interactive slot content must retain\naccessible names and keyboard operation. Use the context to adapt content to the available space.</p>\n<h2>Playground</h2>\n<p>Visit <code>/components/top-nav</code> and see the <a href="components/top-nav">owning component guide</a>.</p>\n',
  'projects/blocks/navigation/directives/top-nav-brand/README.md':
    '<h1>Top nav brand slot</h1>\n<p>Provide custom brand content for <code>bx-top-nav</code> through a typed projected template.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">TopNav</span>, <span class="hljs-title class_">TopNavBrandDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;</code></pre>\n<p>Add these declarations to the consuming standalone component&#39;s imports.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-top-nav</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxTopNavBrand</span> <span class="hljs-attr">let-compact</span>=<span class="hljs-string">&quot;compact&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>{{ compact ? &#x27;Blocks&#x27; : &#x27;Blocks workspace&#x27; }}<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-top-nav</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>TopNavBrandDirective</code> selects <code>[bxTopNavBrand]</code> and registers its <code>TemplateRef</code> with the containing <code>TopNav</code>. The template context exposes <code>compact</code> and\n<code>open</code>; <code>$implicit</code> is equivalent to <code>compact</code>. There are no configurable directive inputs or outputs.</p>\n<h2>Appearance and customization</h2>\n<p>The template owns its content while the navigation component owns layout and material. Use Blocks controls and shared theme tokens inside the slot.</p>\n<h2>Behavior and accessibility</h2>\n<p>Place the template inside its owning navigation component. Registration is removed when the directive is destroyed. Interactive slot content must retain\naccessible names and keyboard operation. Use the context to adapt content to the available space.</p>\n<h2>Playground</h2>\n<p>Visit <code>/components/top-nav</code> and see the <a href="components/top-nav">owning component guide</a>.</p>\n',
  'projects/blocks/primitives/components/accordion/README.md':
    '<h1>Accordion</h1>\n<p>Coordinates direct collapsible children into single or multiple expanded sections.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Accordion</span>, <span class="hljs-title class_">Collapsible</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-accordion</span> [<span class="hljs-attr">multiple</span>]=<span class="hljs-string">&quot;false&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-accordion-item</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Overview&quot;</span> [<span class="hljs-attr">expanded</span>]=<span class="hljs-string">&quot;true&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Project overview.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-accordion-item</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-accordion-item</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Details&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Project details.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-accordion-item</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-accordion</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>multiple</code> defaults to false. <code>collapseAll()</code> closes every child. Import <code>Collapsible</code> for the <code>bx-accordion-item</code> selector; it exposes the same inputs and\n<code>expanded</code> model as <a href="components/collapsible">Collapsible</a>.</p>\n<p>Use each item&#39;s <code>titleTemplate</code> to add noninteractive heading content such as number-only Blocks tags.</p>\n<p>Use <code>trailingTemplate</code> for status tags or other noninteractive content at the heading&#39;s logical end, before its disclosure icon. It receives the same typed\ncontext as <code>titleTemplate</code>. <code>/tokens</code> demonstrates compact palette headings with current-theme and companion tags.</p>\n<p>Place items directly inside the accordion. Nested accordions coordinate their own items. Single mode reconciles programmatic expanded-state changes and\ninitially open children.</p>\n<h2>Appearance and customization</h2>\n<p><code>--bx-accordion-gap</code> controls spacing. Each child supports the collapsible surface variables. No parallel animation or theme configuration is introduced.</p>\n<h2>Behavior and accessibility</h2>\n<p>ArrowUp/ArrowDown wrap between enabled headings; Home/End choose the first/last heading. Enter/Space toggle the focused item. Disabled items are skipped;\nreadonly items stay focusable. Closing a section returns focus from its content to its heading. Panels have no motion dependency.</p>\n<h2>Playground</h2>\n<p><code>/components/accordion</code> includes live examples and shared appearance controls.</p>\n',
  'projects/blocks/primitives/components/alert/README.md':
    '<h1>Inline alert / banner</h1>\n<p>Inline feedback and general banners for default, info, danger, warning and success states.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Alert</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-alert</span> <span class="hljs-attr">tone</span>=<span class="hljs-string">&quot;success&quot;</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Saved&quot;</span> <span class="hljs-attr">message</span>=<span class="hljs-string">&quot;Your changes are ready.&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-banner</span> <span class="hljs-attr">tone</span>=<span class="hljs-string">&quot;warning&quot;</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Review needed&quot;</span> [<span class="hljs-attr">dismissible</span>]=<span class="hljs-string">&quot;true&quot;</span> [(<span class="hljs-attr">visible</span>)]=<span class="hljs-string">&quot;visible&quot;</span> <span class="hljs-attr">dismissFocusTarget</span>=<span class="hljs-string">&quot;restore-banner&quot;</span>&gt;</span>\n    Some settings need your attention.\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-banner</span>&gt;</span>\n@if (!visible) { <span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">id</span>=<span class="hljs-string">&quot;restore-banner&quot;</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;visible = true&quot;</span>&gt;</span>Restore banner<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span> }</code></pre>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>API</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>tone</code></td>\n<td>default</td>\n<td><code>AlertTone</code></td>\n</tr>\n<tr>\n<td><code>title / message</code></td>\n<td>absent</td>\n<td><code>ResolvableText</code>; projected content is also supported</td>\n</tr>\n<tr>\n<td><code>dismissible</code></td>\n<td>false</td>\n<td>Shows a named native close action</td>\n</tr>\n<tr>\n<td><code>dismissLabel</code></td>\n<td>Dismiss notification</td>\n<td>Translatable action name</td>\n</tr>\n<tr>\n<td><code>emissive</code></td>\n<td>true</td>\n<td>Steady illumination of the banner and neighboring Blocks surfaces</td>\n</tr>\n<tr>\n<td><code>emissionColor</code></td>\n<td>tone text color</td>\n<td>Optional semantic light-color override</td>\n</tr>\n<tr>\n<td><code>emissionIntensity</code></td>\n<td>0.6</td>\n<td>Neighboring light strength, clamped to 0–4</td>\n</tr>\n<tr>\n<td><code>emissionRadius</code></td>\n<td>320</td>\n<td>Neighboring light falloff in CSS pixels</td>\n</tr>\n<tr>\n<td><code>visible</code></td>\n<td>true</td>\n<td>Two-way visibility model</td>\n</tr>\n<tr>\n<td><code>announcement</code></td>\n<td>off</td>\n<td><code>AlertAnnouncement</code>: off, polite or assertive</td>\n</tr>\n<tr>\n<td><code>dismissFocusTarget</code></td>\n<td>absent</td>\n<td>Optional element or element ID to focus after keyboard dismissal</td>\n</tr>\n<tr>\n<td><code>dismissed</code></td>\n<td>—</td>\n<td>Emitted on dismissal</td>\n</tr>\n<tr>\n<td><code>dismiss()</code></td>\n<td>—</td>\n<td>Respects dismissible and visible</td>\n</tr>\n</tbody></table>\n<p><code>bx-banner</code> is an alternate selector for <code>Alert</code>. Project optional actions with <code>bxAlertActions</code>.</p>\n<h2>Appearance and customization</h2>\n<p><code>--bx-alert-background</code>, <code>--bx-alert-color</code>, <code>--bx-alert-border</code>, <code>--bx-alert-radius</code>, <code>--bx-alert-padding</code>, <code>--bx-alert-gap</code>, <code>--bx-alert-shadow</code>,\n<code>--bx-alert-min-opacity</code>, <code>--bx-alert-light-opacity</code> and <code>--bx-alert-rim-opacity</code>. Borders use the tone color at 44.8% opacity by default; increased contrast\nrestores the full tone color, and <code>--bx-alert-border</code> always accepts an explicit override. Interior light opacity defaults to 0.32 and rim light opacity to 0.8\nto keep illumination gentle while preserving the glass material. The shared glass surface follows application translucency and reduced transparency. Borders\nhave a uniform width; the old <code>--bx-alert-accent-width</code> is no longer used. The severity palette, icon, soft glow and steady light follow the same material and\nemissive mechanisms as toasts, without entrance, exit or progress animations. Optional <code>data-bx-light-scope</code> on an owning container limits neighboring\nillumination to that scene.</p>\n<h2>Behavior and accessibility</h2>\n<p>Static content is silent by default. Use polite for changing status and assertive for urgent errors; the live text excludes the action slot. Supply descriptive\ntext as well as a tone. Content and actions wrap at narrow widths. If dismissal removes the focused control, provide dismissFocusTarget or manage focus through\ndismissed. Focus restoration waits for rendering, so the destination may be created conditionally after dismissal.</p>\n<h2>Playground</h2>\n<p><code>/components/alert</code> includes live examples and shared appearance controls.</p>\n',
  'projects/blocks/primitives/components/card/README.md':
    '<h1>Card</h1>\n<p>A themed content surface with optional whole-card activation and controlled selection, using Blocks&#39; shared lighting and accessibility preferences.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Card</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-card</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Project&quot;</span> <span class="hljs-attr">subtitle</span>=<span class="hljs-string">&quot;Updated recently&quot;</span> <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;outlined&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Project content.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">div</span> <span class="hljs-attr">bxCardFooter</span>&gt;</span>Last updated today<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-card</span>&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-card</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Open project&quot;</span> <span class="hljs-attr">ariaLabel</span>=<span class="hljs-string">&quot;Open project&quot;</span> (<span class="hljs-attr">activated</span>)=<span class="hljs-string">&quot;openProject()&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>A single native button action across the entire card.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<p>For a selectable card, the consumer owns its selection:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { signal } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n\n<span class="hljs-keyword">readonly</span> selected = <span class="hljs-title function_">signal</span>(<span class="hljs-literal">false</span>);</code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-card</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Workspace&quot;</span> [<span class="hljs-attr">clickable</span>]=<span class="hljs-string">&quot;true&quot;</span> [(<span class="hljs-attr">selected</span>)]=<span class="hljs-string">&quot;selected&quot;</span> <span class="hljs-attr">highlightColor</span>=<span class="hljs-string">&quot;accent&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Press anywhere to choose this workspace.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-card</span>&gt;</span></code></pre>\n<p>For an exclusive choice, bind <code>[selected]</code> from the chosen value and update that value on <code>(activated)</code>. Activating an already selected choice keeps it\nselected. Use <code>[(selected)]</code> when each activation should toggle selection.</p>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>API</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>title</code>, <code>subtitle</code></td>\n<td>absent</td>\n<td>Translated <code>ResolvableText</code> content</td>\n</tr>\n<tr>\n<td><code>headingLevel</code></td>\n<td>3</td>\n<td>Title heading level, clamped to 1–6</td>\n</tr>\n<tr>\n<td><code>variant: CardVariant</code></td>\n<td>outlined</td>\n<td>Outlined, elevated or filled</td>\n</tr>\n<tr>\n<td><code>surfaceEffects</code></td>\n<td>true</td>\n<td>Mount shared decorative surface effects; false keeps static themed styling for dense collections</td>\n</tr>\n<tr>\n<td><code>opaque</code></td>\n<td>inherited</td>\n<td>Optional opaque presentation</td>\n</tr>\n<tr>\n<td><code>clickable</code></td>\n<td>false</td>\n<td>Whole-card action; native <code>button[bx-card]</code> is always clickable</td>\n</tr>\n<tr>\n<td><code>selected</code></td>\n<td>absent</td>\n<td>Controlled boolean selection; absence creates a plain action</td>\n</tr>\n<tr>\n<td><code>selectedChange</code></td>\n<td>—</td>\n<td>Requested next boolean selection, emitted only when <code>selected</code> is supplied; supports <code>[(selected)]</code></td>\n</tr>\n<tr>\n<td><code>activated</code></td>\n<td>—</td>\n<td>Enabled pointer, Enter or Space activation, and guarded <code>activate()</code> calls</td>\n</tr>\n<tr>\n<td><code>highlightColor: Color</code></td>\n<td>CSS/primary</td>\n<td>Semantic or palette token for hover, focus and selected emission</td>\n</tr>\n<tr>\n<td><code>disabled</code></td>\n<td>false</td>\n<td>Suppresses activation and excludes a clickable card from keyboard navigation</td>\n</tr>\n<tr>\n<td><code>readonly</code>, <code>readOnly</code></td>\n<td>false</td>\n<td>Prevents activation while preserving focus and selected appearance</td>\n</tr>\n<tr>\n<td><code>ariaLabel</code></td>\n<td>content</td>\n<td>Optional translated accessible name</td>\n</tr>\n<tr>\n<td><code>ariaLabelledBy</code>, <code>ariaDescribedBy</code></td>\n<td>absent</td>\n<td>Optional labeling/description IDs</td>\n</tr>\n<tr>\n<td><code>activate()</code></td>\n<td>—</td>\n<td>Requests activation after checking current interactive state</td>\n</tr>\n<tr>\n<td><code>focus(options?)</code></td>\n<td>—</td>\n<td>Focuses an enabled clickable card</td>\n</tr>\n</tbody></table>\n<p>Set <code>[surfaceEffects]=&quot;false&quot;</code> for dense static collections such as the token catalog. Theme variables, focus styling, content slots and actions remain\navailable.</p>\n<p>Slots: <code>bxCardMedia</code>, <code>bxCardHeader</code>, default body and <code>bxCardFooter</code>. Header content follows the optional generated title/subtitle. Empty sections take no\nspace.</p>\n<h2>Appearance and customization</h2>\n<p>Existing variables: <code>--bx-card-background</code>, <code>--bx-card-color</code>, <code>--bx-card-border</code>, <code>--bx-card-radius</code>, <code>--bx-card-shadow</code>, <code>--bx-card-padding</code> and\n<code>--bx-card-title-size</code>.</p>\n<p>Interactive variables: <code>--bx-card-highlight</code> (defaults to <code>--bx-primary</code>), <code>--bx-card-selected-background</code> (element active), <code>--bx-card-selected-border</code> (custom\ncard border or semantic brand border), <code>--bx-card-hover-background</code> (element hover), <code>--bx-card-pressed-background</code> (element active), <code>--bx-card-focus-color</code>\n(highlight), and <code>--bx-card-disabled-opacity</code> (0.6).</p>\n<p><code>highlightColor</code> overrides <code>--bx-card-highlight</code> with a typed Blocks token. Selected cards resolve their highlight in their own theme scope and emit the same\npersistent border light as selected Blocks controls, without adding a second selection outline. Keyboard focus retains its own visible ring. Colors follow the\nactive palette, and mounted surfaces react to theme and appearance changes.</p>\n<h2>Behavior and accessibility</h2>\n<p>Ordinary cards remain containers whose links and buttons provide interaction. Prefer <code>button[bx-card]</code> for a native whole-card action; it uses <code>type=&quot;button&quot;</code>.\n<code>bx-card[clickable]</code> adds button semantics and Enter/Space operation. Enter activates on keydown without repeats; Space activates on keyup and does not scroll\nthe page. <code>selected</code> supplies <code>aria-pressed</code>; selection is accompanied by material and emitted-light feedback. Add a visible check or other content indicator\nwhen useful.</p>\n<p>Use <code>activated</code> for guarded actions. Read-only cards remain focusable and announce that activation is unavailable. Disabled cards are removed from tab order and\nretain a readable disabled presentation. Application-driven selection updates remain possible in either state.</p>\n<p>A whole-card action should contain descriptive, noninteractive content. Use an ordinary card for multiple independent actions; nested controls do not activate\nthe card. Long content wraps. Combine with Grid and Container for responsive pages, and give images meaningful alternative text.</p>\n<p>The surface engine respects reduced motion and transparency; forced colors uses a static selected border and visible keyboard focus. No decorative motion is\nneeded to identify selection.</p>\n<p>Setting <code>opaque</code> to false follows the application material only when neither the application nor the OS requests reduced transparency. An active accessibility\npreference takes precedence; selected cards retain their semantic contour in opaque presentation.</p>\n<h2>Playground</h2>\n<p><code>/components/card</code> demonstrates native actions, controlled/two-way selection, configurable highlight tokens, disabled and read-only states, and ordinary content\ncards. <code>/appearance</code> uses clickable cards for Light, Dark and Auto.</p>\n',
  'projects/blocks/primitives/components/chip/README.md':
    '<h1>Interactive chip</h1>\n<p>A compact native action, toggle or removable token using Blocks semantic palettes.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Chip</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-chip</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Design&quot;</span> [(<span class="hljs-attr">selected</span>)]=<span class="hljs-string">&quot;designSelected&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-chip</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Angular&quot;</span> [<span class="hljs-attr">selectable</span>]=<span class="hljs-string">&quot;false&quot;</span> [<span class="hljs-attr">removable</span>]=<span class="hljs-string">&quot;true&quot;</span> (<span class="hljs-attr">removed</span>)=<span class="hljs-string">&quot;removeAngular()&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-chip</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Fixed selection&quot;</span> [<span class="hljs-attr">selected</span>]=<span class="hljs-string">&quot;true&quot;</span> [<span class="hljs-attr">readOnly</span>]=<span class="hljs-string">&quot;true&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>API</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>label</code></td>\n<td>required</td>\n<td><code>ResolvableText</code></td>\n</tr>\n<tr>\n<td><code>selected</code></td>\n<td>false</td>\n<td>Two-way selection model</td>\n</tr>\n<tr>\n<td><code>selectable</code></td>\n<td>true</td>\n<td>Toggles selection and exposes aria-pressed</td>\n</tr>\n<tr>\n<td><code>deselectable</code></td>\n<td>true</td>\n<td>Allows an active selectable chip to be deselected</td>\n</tr>\n<tr>\n<td><code>removable</code></td>\n<td>false</td>\n<td>Separate accessible remove action</td>\n</tr>\n<tr>\n<td><code>disabled</code></td>\n<td>false</td>\n<td>Removes both actions from normal focus</td>\n</tr>\n<tr>\n<td><code>readonly / readOnly</code></td>\n<td>false</td>\n<td>Prevents activation and removal while retaining focus</td>\n</tr>\n<tr>\n<td><code>config</code></td>\n<td>{}</td>\n<td><code>IChipConfig</code> appearance and remove label</td>\n</tr>\n<tr>\n<td><code>activated</code></td>\n<td>—</td>\n<td>Main action, after selection changes</td>\n</tr>\n<tr>\n<td><code>removed</code></td>\n<td>—</td>\n<td>Removal request; application owns the array</td>\n</tr>\n<tr>\n<td><code>focus(options?)</code></td>\n<td>—</td>\n<td>Focuses the main action</td>\n</tr>\n</tbody></table>\n<p><code>deselectable</code> defaults to true. Set it to false for an application-coordinated single-choice group: activating an unselected chip selects it, while activating\nan already selected chip leaves it selected. The owner clears selection on the other chips. <code>activated</code> still emits for each enabled activation.</p>\n<p><code>IChipConfig</code> supports <code>color</code> (primary), <code>variant</code> (tonal), <code>size</code> (medium), optional <code>icon</code>, and translatable <code>removeLabel</code> (Remove {label}). Provide\n<code>BX_CHIP_DEFAULTS</code> for shared values; instance configuration wins.</p>\n<h2>Appearance and customization</h2>\n<p><code>--bx-chip-background</code>, <code>--bx-chip-color</code>, <code>--bx-chip-border</code>, <code>--bx-chip-radius</code>, <code>--bx-chip-min-height</code>, <code>--bx-chip-hover-background</code> and\n<code>--bx-chip-remove-background</code>, and <code>--bx-chip-fill-opacity</code> override the shared tag palette and spacing defaults. Main-action hover fills the entire chip behind\nthe separate circular remove action for tonal/outlined chips. Filled chips preserve their fill and use an inset hover outline, keeping the theme&#39;s on-fill text\ncontrast stable; <code>--bx-chip-hover-background</code> can override that behavior. Filled chips default to an opaque semantic fill (<code>--bx-chip-fill-opacity: 1</code>),\nmatching filled-button intent and keeping primary selection visible.</p>\n<h2>Behavior and accessibility</h2>\n<p>Enter and Space activate native buttons. Delete or Backspace on the main action requests removal when enabled. Selection has a check mark and inset outline. The\nlabel wraps. The application should move focus to an adjacent chip or another action after removing the focused item; the playground demonstrates this. This\nprimitive is not a form field; use selectedChange to coordinate application or form state.</p>\n<h2>Playground</h2>\n<p><code>/components/chip</code> includes live examples and shared appearance controls.</p>\n',
  'projects/blocks/primitives/components/collapsible/README.md':
    '<h1>Collapsible</h1>\n<p>A standalone disclosure. The same component also provides the bx-accordion-item selector.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Collapsible</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-collapsible</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Project details&quot;</span> [(<span class="hljs-attr">expanded</span>)]=<span class="hljs-string">&quot;expanded&quot;</span> [<span class="hljs-attr">region</span>]=<span class="hljs-string">&quot;true&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Persistent content.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-collapsible</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-collapsible</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Notifications&quot;</span> [<span class="hljs-attr">titleTemplate</span>]=<span class="hljs-string">&quot;heading&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> #<span class="hljs-attr">heading</span> <span class="hljs-attr">let-title</span> <span class="hljs-attr">let-expanded</span>=<span class="hljs-string">&quot;expanded&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>{{ title }} · {{ expanded ? &#x27;Open&#x27; : &#x27;Closed&#x27; }}<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-collapsible</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Notifications&quot;</span> [<span class="hljs-attr">trailingTemplate</span>]=<span class="hljs-string">&quot;status&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> #<span class="hljs-attr">status</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-tag</span> <span class="hljs-attr">text</span>=<span class="hljs-string">&quot;Current theme&quot;</span> <span class="hljs-attr">size</span>=<span class="hljs-string">&quot;small&quot;</span> [<span class="hljs-attr">focusable</span>]=<span class="hljs-string">&quot;false&quot;</span> /&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-collapsible</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Lazy content&quot;</span> [<span class="hljs-attr">contentTemplate</span>]=<span class="hljs-string">&quot;details&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> #<span class="hljs-attr">details</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Created only while expanded.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span></code></pre>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>API</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>title</code></td>\n<td>required</td>\n<td>Translated heading and button name</td>\n</tr>\n<tr>\n<td><code>expanded</code></td>\n<td>false</td>\n<td>Two-way state model</td>\n</tr>\n<tr>\n<td><code>disabled</code></td>\n<td>false</td>\n<td>Prevents toggling and heading focus</td>\n</tr>\n<tr>\n<td><code>readonly / readOnly</code></td>\n<td>false</td>\n<td>Prevents user toggling while retaining focus</td>\n</tr>\n<tr>\n<td><code>headingLevel</code></td>\n<td>3</td>\n<td>Heading level, clamped to 1–6</td>\n</tr>\n<tr>\n<td><code>region</code></td>\n<td>false</td>\n<td>Adds a named region for substantial content</td>\n</tr>\n<tr>\n<td><code>titleTemplate</code></td>\n<td>absent</td>\n<td>Noninteractive heading template with <code>ICollapsibleTitleContext</code>: <code>$implicit</code> translated title and <code>expanded</code> state</td>\n</tr>\n<tr>\n<td><code>trailingTemplate</code></td>\n<td>absent</td>\n<td>Noninteractive content at the heading&#39;s logical end, before the chevron; receives the same context as <code>titleTemplate</code></td>\n</tr>\n<tr>\n<td><code>contentTemplate</code></td>\n<td>absent</td>\n<td>Lazy template, recreated on expansion</td>\n</tr>\n<tr>\n<td><code>id</code></td>\n<td>generated</td>\n<td>Base ID for the trigger and panel</td>\n</tr>\n<tr>\n<td><code>toggle() / focus()</code></td>\n<td>—</td>\n<td>Guarded toggle and heading focus</td>\n</tr>\n</tbody></table>\n<p>Keep title templates noninteractive; the enclosing native button owns keyboard activation and the accessible name. Use a number-only <code>Tag</code> for counts.</p>\n<p><code>trailingTemplate</code> places status text, tags, or icons on the right in LTR layouts and on the left in RTL layouts. Content can wrap on narrow screens. Import\n<code>Tag</code> from the Primitives entry point for the example above. Keep trailing content noninteractive and set embedded tags to <code>[focusable]=&quot;false&quot;</code>; the heading\nremains one disclosure button, and its accessible name includes the status content.</p>\n<p>Projected content remains mounted while collapsed; lazy template state is recreated on reopening. Application-driven expanded changes remain possible for\ndisabled/readonly sections.</p>\n<h2>Appearance and customization</h2>\n<p><code>--bx-collapsible-background</code>, <code>--bx-collapsible-border</code>, <code>--bx-collapsible-radius</code>, <code>--bx-collapsible-padding</code> and <code>--bx-collapsible-content-padding</code> follow\nshared semantic defaults.</p>\n<p>The heading&#39;s hover background follows the surface&#39;s inner corners. Expanded headings keep rounded top corners and square bottom corners, with no divider\nbetween the heading and content. Accordion items share this appearance.</p>\n<h2>Behavior and accessibility</h2>\n<p>Native button activation, aria-expanded and aria-controls connect the heading and panel. Hidden panels are inert. Programmatic collapse moves contained focus to\nthe heading. Optional regions avoid filling the page with unnecessary landmarks.</p>\n<h3>Motion and material response</h3>\n<p>After initialization, disclosure height uses a quick 120ms grid transition (customizable with <code>--bx-collapsible-duration</code>) that follows dynamic content. Rapid\nexpand/collapse changes retarget the current layout. Closed content is immediately inert and hidden from accessibility APIs while its visual height settles;\nprojected content stays mounted and lazy content follows the existing expanded-only lifecycle. The trigger keeps its title undistorted and uses local material\nfeedback. Initial rendering and live reduced motion use immediate state changes. Inspect <code>/components/collapsible</code> and <code>/components/accordion</code>.</p>\n<h2>Playground</h2>\n<p><code>/components/collapsible</code> includes live examples and shared appearance controls.</p>\n',
  'projects/blocks/primitives/components/container/README.md':
    '<h1>Content container</h1>\n<p>Centers content and constrains page width using the shared breakpoint scale.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Container</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-container</span> <span class="hljs-attr">size</span>=<span class="hljs-string">&quot;lg&quot;</span> <span class="hljs-attr">landmark</span>=<span class="hljs-string">&quot;main&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">h1</span>&gt;</span>Workspace<span class="hljs-tag">&lt;/<span class="hljs-name">h1</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Main page content.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-container</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>size: ContainerSize</code> is sm, md, lg (default), xl or full. Optional <code>landmark</code> accepts main, region or complementary. <code>ariaLabel</code> accepts <code>ResolvableText</code> and\nnames a landmark when needed. The component adds no surface or scroll container.</p>\n<h2>Appearance and customization</h2>\n<p><code>--bx-container-max-width</code> and <code>--bx-container-padding</code> override width and logical gutters. Presets come from core/styles/helpers; full width stays within the\nparent.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use main once per page. Give regions descriptive names. Logical gutters and auto margins support RTL, narrow containers and zoom. Compose Stack, Grid and Card\ninside it.</p>\n<h2>Playground</h2>\n<p><code>/components/layout/container</code> includes live examples and shared appearance controls.</p>\n',
  'projects/blocks/primitives/components/divider/README.md':
    '<h1>Divider</h1>\n<p>Separates adjacent content with a horizontal or vertical rule and an optional translated label.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Divider</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-divider</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-divider</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Continue&quot;</span> <span class="hljs-attr">lineStyle</span>=<span class="hljs-string">&quot;dashed&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-stack</span> <span class="hljs-attr">direction</span>=<span class="hljs-string">&quot;horizontal&quot;</span>&gt;</span> <span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>Start<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-divider</span> <span class="hljs-attr">orientation</span>=<span class="hljs-string">&quot;vertical&quot;</span> /&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>End<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span> <span class="hljs-tag">&lt;/<span class="hljs-name">bx-stack</span>&gt;</span></code></pre>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Input</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>orientation</code></td>\n<td><code>horizontal</code></td>\n<td><code>horizontal</code> or <code>vertical</code></td>\n</tr>\n<tr>\n<td><code>lineStyle</code></td>\n<td><code>solid</code></td>\n<td><code>solid</code>, <code>dashed</code> or <code>dotted</code></td>\n</tr>\n<tr>\n<td><code>label</code></td>\n<td>absent</td>\n<td><code>ResolvableText</code> between the two rule segments</td>\n</tr>\n<tr>\n<td><code>decorative</code></td>\n<td><code>false</code></td>\n<td>Hides the rule and label from assistive technology</td>\n</tr>\n</tbody></table>\n<p>Also exports <code>DividerOrientation</code> and <code>DividerStyle</code>. The stack example additionally imports <code>Stack</code>.</p>\n<h2>Appearance and customization</h2>\n<p><code>--bx-divider-color</code>, <code>--bx-divider-thickness</code>, <code>--bx-divider-margin</code>, <code>--bx-divider-gap</code>, <code>--bx-divider-text</code>, <code>--bx-divider-font-size</code> and\n<code>--bx-divider-min-height</code> override shared defaults. Thickness falls back to <code>--bx-border-width</code> (<code>1px</code>). The explicit <code>lineStyle</code> input defaults to <code>solid</code> and\ncontinues to take precedence over shared border style. Spacing follows the live shared spacing tokens.</p>\n<h2>Behavior and accessibility</h2>\n<p>Uses separator semantics and reports its orientation. Labels wrap. Vertical dividers stretch within a flex row; give the row a meaningful height. No motion is\nrequired.</p>\n<h2>Playground</h2>\n<p><code>/components/layout/divider</code> includes live examples and shared appearance controls.</p>\n',
  'projects/blocks/primitives/components/grid/README.md':
    '<h1>Grid layout</h1>\n<p>Responsive CSS grid for cards and general content without a separate layout framework.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Grid</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-grid</span> <span class="hljs-attr">minColumnWidth</span>=<span class="hljs-string">&quot;16rem&quot;</span> [<span class="hljs-attr">gap</span>]=<span class="hljs-string">&quot;4&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-card</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Project one&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-card</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Project two&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-grid</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>minColumnWidth</code> defaults to 16rem and controls auto-fit columns. Optional <code>columns</code> selects a fixed count clamped to 1–24. <code>gap: LayoutGap</code> defaults to 4 and\nuses the shared spacing scale. Fixed and automatic grids become one column below the shared sm breakpoint. The usage also imports <code>Card</code>.</p>\n<h2>Appearance and customization</h2>\n<p><code>--bx-grid-gap</code> overrides spacing. Minimum column width never exceeds the parent. Fixed columns use minmax(0, 1fr) to allow long content to shrink.</p>\n<h2>Behavior and accessibility</h2>\n<p>Keeps natural DOM order without adding roles or keyboard behavior. Place semantic sections and controls inside the grid. Text enlargement, narrow containers and\nRTL use normal CSS layout.</p>\n<h2>Playground</h2>\n<p><code>/components/layout/grid</code> includes live examples and shared appearance controls.</p>\n',
  'projects/blocks/primitives/components/loading-indicator/README.md':
    '<h1>Loading indicator</h1>\n<p>Reusable loading feedback integrated with Blocks themes and accessibility preferences.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">LoadingIndicator</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-loading-indicator</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Fetching results&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>label</code> accepts translated text; <code>size</code> controls its decorative spinner. The host is a polite busy status region. Project optional supporting content after the\nstatus text. CSS variables: <code>--bx-loading-color</code>, <code>--bx-loading-gap</code>.</p>\n<h2>Appearance and accessibility</h2>\n<p>Uses Blocks semantic tokens and the active <code>ThemingService</code> configuration. Customize through documented inputs, templates and CSS variables. Existing components\nupdate when the application theme changes. Keyboard focus, forced colors, reduced transparency and <code>BxA11yService</code> reduced-motion preferences remain supported.</p>\n<p>Text inputs accept <code>ResolvableText</code>: plain text or <code>{ key: &#39;translation.key&#39; }</code>. With <code>BX_I18N</code>, text is resolved reactively, including already-mounted controls\nwhen the adapter&#39;s <code>version</code> signal changes. Plain text works without an adapter.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/loading-indicator</code>. Fake asynchronous requests demonstrate progress and loading buttons. Reduced-motion preferences remove continuous\nanimation while preserving status feedback.</p>\n',
  'projects/blocks/primitives/components/loading-spinner/README.md':
    '<h1>Loading spinner</h1>\n<p>Reusable loading feedback integrated with Blocks themes and accessibility preferences.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">LoadingSpinner</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-loading-spinner</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Fetching results&quot;</span> [<span class="hljs-attr">size</span>]=<span class="hljs-string">&quot;24&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>size</code> is the diameter in pixels (20 by default). <code>label</code> is translatable. <code>decorative</code> defaults to false; set it to true when surrounding content already names\nthe operation. CSS variables: <code>--bx-spinner-color</code>, <code>--bx-spinner-stroke</code>, <code>--bx-spinner-size</code>.</p>\n<h2>Appearance and accessibility</h2>\n<p>Uses Blocks semantic tokens and the active <code>ThemingService</code> configuration. Customize through documented inputs, templates and CSS variables. Existing components\nupdate when the application theme changes. Keyboard focus, forced colors, reduced transparency and <code>BxA11yService</code> reduced-motion preferences remain supported.</p>\n<p>Text inputs accept <code>ResolvableText</code>: plain text or <code>{ key: &#39;translation.key&#39; }</code>. With <code>BX_I18N</code>, text is resolved reactively, including already-mounted controls\nwhen the adapter&#39;s <code>version</code> signal changes. Plain text works without an adapter.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/loading-spinner</code>. Fake asynchronous requests demonstrate progress and loading buttons. Reduced-motion preferences remove continuous animation\nwhile preserving status feedback.</p>\n',
  'projects/blocks/primitives/components/menu-item/README.md':
    '<h1>Menu item</h1>\n<p>A menu action with optional icons, a shortcut hint, and destructive intent.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">MenuItem</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-menu-item</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Delete&quot;</span> <span class="hljs-attr">icon</span>=<span class="hljs-string">&quot;trash-2&quot;</span> [<span class="hljs-attr">danger</span>]=<span class="hljs-string">&quot;true&quot;</span> (<span class="hljs-attr">action</span>)=<span class="hljs-string">&quot;remove()&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>label</code>, <code>icon</code>, <code>endIcon</code>, <code>shortcut</code>, <code>disabled</code>, <code>danger</code>, and <code>wrapLabel</code>. Set <code>wrapLabel</code> to <code>true</code> when a menu item should wrap long content instead of\ntruncating it. <code>action</code> emits the mouse event for enabled items. Clipped labels and projected text use the shared <code>TruncateDirective</code> and receive an automatic\ntooltip. <code>[tooltipOnTruncate]=&quot;false&quot;</code> disables that tooltip while retaining ellipsis, allowing application-owned feedback. <code>wrapLabel</code> disables truncation\nitself.</p>\n<h2>Shortcut definitions</h2>\n<p><code>shortcut</code> accepts <code>ResolvableShortcut</code> from <code>@filip.mazev/blocks/core</code>:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-comment">&lt;!-- A portable combination: ⌘ ⇧ V on Apple, Ctrl Shift V elsewhere. --&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-menu-item</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Open view&quot;</span> [<span class="hljs-attr">shortcut</span>]=<span class="hljs-string">&quot;[&#x27;mod&#x27;, &#x27;shift&#x27;, &#x27;v&#x27;]&quot;</span> (<span class="hljs-attr">action</span>)=<span class="hljs-string">&quot;openView()&quot;</span> /&gt;</span>\n\n<span class="hljs-comment">&lt;!-- Explicit OS differences; default is required. --&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-menu-item</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Duplicate&quot;</span> [<span class="hljs-attr">shortcut</span>]=<span class="hljs-string">&quot;duplicateShortcut&quot;</span> (<span class="hljs-attr">action</span>)=<span class="hljs-string">&quot;duplicate()&quot;</span> /&gt;</span></code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ResolvableShortcut</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">duplicateShortcut</span>: <span class="hljs-title class_">ResolvableShortcut</span> = {\n  <span class="hljs-attr">mac</span>: [<span class="hljs-string">&#x27;command&#x27;</span>, <span class="hljs-string">&#x27;shift&#x27;</span>, <span class="hljs-string">&#x27;d&#x27;</span>],\n  <span class="hljs-attr">windows</span>: [<span class="hljs-string">&#x27;ctrl&#x27;</span>, <span class="hljs-string">&#x27;shift&#x27;</span>, <span class="hljs-string">&#x27;d&#x27;</span>],\n  <span class="hljs-attr">linux</span>: [<span class="hljs-string">&#x27;alt&#x27;</span>, <span class="hljs-string">&#x27;shift&#x27;</span>, <span class="hljs-string">&#x27;d&#x27;</span>],\n  <span class="hljs-attr">ios</span>: [<span class="hljs-string">&#x27;command&#x27;</span>, <span class="hljs-string">&#x27;shift&#x27;</span>, <span class="hljs-string">&#x27;d&#x27;</span>],\n  <span class="hljs-attr">android</span>: [<span class="hljs-string">&#x27;ctrl&#x27;</span>, <span class="hljs-string">&#x27;shift&#x27;</span>, <span class="hljs-string">&#x27;d&#x27;</span>],\n  <span class="hljs-attr">default</span>: [<span class="hljs-string">&#x27;mod&#x27;</span>, <span class="hljs-string">&#x27;shift&#x27;</span>, <span class="hljs-string">&#x27;d&#x27;</span>]\n};</code></pre>\n<p>A string is <strong>one token</strong>; use an array for a combination. <code>&#39;Ctrl+K&#39;</code> remains a single custom display token and is not parsed. <code>[&#39;mod&#39;, &#39;k&#39;, &#39;v&#39;]</code> displays\nthree tokens, but does not define a sequence or a valid single-event combination. To open a menu with Command/Ctrl+K followed by V, track two separate events;\nthe playground demonstrates application-owned sequence state with a two-second timeout, cancellation and cleanup.</p>\n<table>\n<thead>\n<tr>\n<th>Input aliases (case insensitive)</th>\n<th>macOS / iOS / iPadOS</th>\n<th>Windows</th>\n<th>Linux / Unix</th>\n<th>Android / unknown / SSR</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>mod</code>, <code>primary</code>, <code>cmdorctrl</code>, <code>commandorcontrol</code></td>\n<td>⌘</td>\n<td>Ctrl</td>\n<td>Ctrl</td>\n<td>Ctrl</td>\n</tr>\n<tr>\n<td><code>command</code>, <code>cmd</code>, <code>meta</code>, <code>super</code>, <code>win</code>, <code>windows</code>, <code>⌘</code></td>\n<td>⌘</td>\n<td>Win</td>\n<td>Super</td>\n<td>Meta</td>\n</tr>\n<tr>\n<td><code>ctrl</code>, <code>control</code>, <code>⌃</code></td>\n<td>⌃</td>\n<td>Ctrl</td>\n<td>Ctrl</td>\n<td>Ctrl</td>\n</tr>\n<tr>\n<td><code>alt</code>, <code>option</code>, <code>opt</code>, <code>⌥</code></td>\n<td>⌥</td>\n<td>Alt</td>\n<td>Alt</td>\n<td>Alt</td>\n</tr>\n<tr>\n<td><code>shift</code>, <code>⇧</code></td>\n<td>⇧</td>\n<td>Shift</td>\n<td>Shift</td>\n<td>Shift</td>\n</tr>\n<tr>\n<td><code>enter</code>, <code>return</code></td>\n<td>↩</td>\n<td>Enter</td>\n<td>Enter</td>\n<td>Enter</td>\n</tr>\n<tr>\n<td><code>backspace</code> / <code>delete</code></td>\n<td>⌫ / ⌦</td>\n<td>Backspace / Delete</td>\n<td>Backspace / Delete</td>\n<td>Backspace / Delete</td>\n</tr>\n<tr>\n<td><code>tab</code> / <code>escape</code>, <code>esc</code></td>\n<td>⇥ / ⎋</td>\n<td>Tab / Escape</td>\n<td>Tab / Escape</td>\n<td>Tab / Escape</td>\n</tr>\n<tr>\n<td><code>up</code>, <code>down</code>, <code>left</code>, <code>right</code> (or <code>Arrow…</code>)</td>\n<td>↑ ↓ ← →</td>\n<td>↑ ↓ ← →</td>\n<td>↑ ↓ ← →</td>\n<td>↑ ↓ ← →</td>\n</tr>\n</tbody></table>\n<p>Letters display in uppercase. <code>space</code> becomes Space, and <code>plus</code> becomes +. Existing symbol tokens and unknown custom labels remain usable. Explicit <code>ctrl</code>\nalways means Control, including on Mac; use <code>mod</code> for Command/Control adaptation. <code>ios</code> falls back to <code>mac</code>, then <code>default</code>; other absent overrides use\n<code>default</code>. Mobile mappings apply to hardware keyboards. Unknown platforms and server rendering use <code>default</code>, where <code>mod</code> means Control.</p>\n<h2>Handling keyboard activation</h2>\n<p>The component renders a hint and emits <code>action</code> for button activation. <strong>It does not attach a global keyboard listener or open a menu automatically.</strong>\n<code>BxShortcutService</code> now shares platform selection, alias normalization, presentation, accessibility metadata and event matching, so the hint and application\nhandler use the same definition.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Component</span>, inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxShortcutService</span>, <span class="hljs-title class_">ResolvableShortcut</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">MenuItem</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;\n\n<span class="hljs-meta">@Component</span>({\n    <span class="hljs-attr">selector</span>: <span class="hljs-string">&#x27;app-view-command&#x27;</span>,\n    <span class="hljs-attr">imports</span>: [<span class="hljs-title class_">MenuItem</span>],\n    <span class="hljs-attr">template</span>: <span class="hljs-string">`&lt;bx-menu-item label=&quot;Open view&quot; [shortcut]=&quot;viewShortcut&quot; (action)=&quot;openView()&quot; /&gt;`</span>,\n    <span class="hljs-attr">host</span>: { <span class="hljs-string">&#x27;(document:keydown)&#x27;</span>: <span class="hljs-string">&#x27;onKeydown($event)&#x27;</span> }\n})\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">ViewCommand</span> {\n    <span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> bxShortcutService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">BxShortcutService</span>);\n    <span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">viewShortcut</span>: <span class="hljs-title class_">ResolvableShortcut</span> = [<span class="hljs-string">&#x27;mod&#x27;</span>, <span class="hljs-string">&#x27;shift&#x27;</span>, <span class="hljs-string">&#x27;v&#x27;</span>];\n\n    <span class="hljs-keyword">protected</span> <span class="hljs-title function_">onKeydown</span>(<span class="hljs-attr">event</span>: <span class="hljs-title class_">KeyboardEvent</span>): <span class="hljs-built_in">void</span> {\n        <span class="hljs-keyword">if</span> (!<span class="hljs-variable language_">this</span>.<span class="hljs-property">bxShortcutService</span>.<span class="hljs-title function_">matches</span>(event, <span class="hljs-variable language_">this</span>.<span class="hljs-property">viewShortcut</span>)) <span class="hljs-keyword">return</span>;\n\n        event.<span class="hljs-title function_">preventDefault</span>();\n        <span class="hljs-variable language_">this</span>.<span class="hljs-title function_">openView</span>();\n    }\n\n    <span class="hljs-keyword">protected</span> <span class="hljs-title function_">openView</span>(): <span class="hljs-built_in">void</span> {\n        <span class="hljs-comment">// Run the same application action used by the menu item.</span>\n    }\n}</code></pre>\n<p>For opening a menu, call the public <code>MenuTriggerDirective.open(true)</code> method after a successful match. It opens with focus on the first enabled item; Escape\nrestores focus to the trigger. Angular removes the host listener when this example&#39;s component is destroyed. Choose a handler scope appropriate to your\napplication and enforce the same disabled/permission guards for pointer and keyboard activation.</p>\n<table>\n<thead>\n<tr>\n<th>Service API</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>platform(): ShortcutPlatform</code></td>\n<td>Detect the platform through <code>DeviceTypeService</code>.</td>\n</tr>\n<tr>\n<td><code>resolve(shortcut, platform?): string[] | undefined</code></td>\n<td>Return display tokens; optionally preview another platform. Empty/absent shortcuts return undefined.</td>\n</tr>\n<tr>\n<td><code>toAriaKeyshortcuts(shortcut, platform?): string | null</code></td>\n<td>Return canonical names such as <code>Meta+Shift+V</code>; invalid/custom hints return null. Does not register a binding.</td>\n</tr>\n<tr>\n<td><code>matches(event, shortcut, options?): boolean</code></td>\n<td>Match one ordinary key plus the exact requested modifiers. Does not prevent defaults or invoke actions.</td>\n</tr>\n</tbody></table>\n<p><code>IShortcutMatchOptions</code> exposes <code>platform</code>, <code>allowInEditable</code> (false), and <code>allowRepeat</code> (false). Matching always ignores already-handled, composing and\nAltGraph events. By default it ignores input, textarea, select, contenteditable and textbox targets, including readonly inputs. Modifiers alone, duplicate\nmodifiers, multiple ordinary keys and custom labels are display-only. Matching uses <code>KeyboardEvent.key</code> (case insensitive), so keyboard layout matters;\nOption/Alt characters must match the actual produced key. The service does not track pressed keys, sequences, global registrations, priority, or conflict\nresolution.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<p>Rows share their menu&#39;s opaque backing. Hover and press use the themed normal/danger background tokens, keyboard focus retains its outline, and rows do not emit\nlight onto neighboring rows or surrounding page surfaces. Press deformation still follows application motion preferences.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use <code>action</code> for activation and <code>disabled</code> for unavailable commands. Valid combinations expose <code>aria-keyshortcuts</code> on the internal button while visual keycaps\nare hidden from its accessible name. Disabled items omit shortcut metadata; application handlers must also guard the disabled command. Only supply a binding\nhint when the application actually implements it. Existing custom display hints remain supported, but do not generate keyboard metadata.</p>\n<p>Browsers, operating systems and assistive technology may reserve key combinations. Keep actions reachable by button, choose suitable bindings for your audience,\nand offer application-owned remapping where needed. See\n<a href="https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-keyshortcuts">MDN&#39;s aria-keyshortcuts guidance</a>.</p>\n<h3>Motion and material response</h3>\n<p>Inside a Blocks Menu, hover and keyboard focus share its moving material surface rather than independently painting a backing on every row. Disabled rows are\nexcluded, semantic danger text remains visible, and focus outlines remain native to the item. Standalone items keep their local interaction styling. Inspect\n<code>/components/menu-item</code>; reduced motion snaps the shared surface.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/menu-item</code> or <code>/components/menu</code> for working menu-opening combinations and sequences, OS previews, disabled-command guards, an editable field,\nand visible action results.</p>\n',
  'projects/blocks/primitives/components/menu/README.md':
    '<h1>Menu</h1>\n<p>A shared surface for related menu actions.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Menu</span>, <span class="hljs-title class_">MenuItem</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-menu</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-menu-item</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Duplicate&quot;</span> <span class="hljs-attr">icon</span>=<span class="hljs-string">&quot;copy&quot;</span> (<span class="hljs-attr">action</span>)=<span class="hljs-string">&quot;duplicate()&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-menu-item</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Archive&quot;</span> <span class="hljs-attr">icon</span>=<span class="hljs-string">&quot;archive&quot;</span> (<span class="hljs-attr">action</span>)=<span class="hljs-string">&quot;archive()&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-menu</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>Menu</code> projects its children and provides the menu surface. Use <code>MenuItem</code> for consistent action styling. Place it in <code>bxDropdown</code> for positioned dismissal and\nkeyboard behavior.</p>\n<h2>Keyboard shortcuts</h2>\n<p>Use <code>[shortcut]=&quot;[&#39;mod&#39;, &#39;shift&#39;, &#39;v&#39;]&quot;</code> on a <code>MenuItem</code> to display a platform-aware hint: Command on Apple devices, Ctrl elsewhere. Explicit <code>mac</code>, <code>windows</code>,\n<code>linux</code>, <code>ios</code> and <code>android</code> overrides are also supported with a required <code>default</code> fallback. Hints do not register actions.</p>\n<p>Use <code>BxShortcutService.matches(event, definition)</code> in an application-owned keyboard handler, then call <code>MenuTriggerDirective.open(true)</code> to open a positioned\nmenu with focus. Use the same definition for the hint and handler, and apply the same disabled guards as pointer activation. The service also formats\naliases/symbols and supplies <code>aria-keyshortcuts</code> names.</p>\n<p>Command/Ctrl+K followed by V is a sequence of two combinations, requiring application-owned state and cancellation. An array such as <code>[&#39;mod&#39;, &#39;k&#39;, &#39;v&#39;]</code> is only\na hint with three tokens. See the <a href="components/menu-item">menu item README</a> for complete aliases, fallback rules, the service API and a working handler\nexample. Both menu playground routes demonstrate a combination and a timed sequence opening an overlay.</p>\n<h2>Appearance</h2>\n<p>Menus use an opaque themed backing with no container blur, reflections, or live lighting. Colors, spacing, radius, elevation and row interactions still follow\nBlocks tokens. Rows provide local hover/pressed fills and visible keyboard focus without emitting light onto neighboring rows or the page. Press feedback and\ntrigger effects retain their application appearance settings.</p>\n<p><code>BxA11yService</code> controls reduced motion. Forced colors preserve native contrast and focus states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Keep menu labels action-oriented. The container provides one opaque backing for its items. Avoid nested interactive controls inside one item.</p>\n<h3>Motion and material response</h3>\n<p>Pointer hover paints the existing hover color immediately, including a clearly semantic danger hover. Keyboard focus may use the shared surface with bounded\nsettling. It does not change application selection or focus, enter the accessibility tree, or intercept pointer input. Danger items use their semantic surface.\nThe surface remains inside the menu&#39;s scrolling coordinate space and reacts to dynamic rows. Dropdown and context-menu wrappers share the overlay\nmaterialization spring. Live reduced motion snaps movement; focus outlines remain available in forced colors. Inspect <code>/components/menu</code>,\n<code>/components/dropdown</code>, and <code>/components/context-menu</code>.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/menu</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/primitives/components/page-container/README.md':
    '<h1>Page container</h1>\n<p>A shared page layout with responsive gutters, a section label, title, description, content, and optional footer. The playground uses it on every page except\nhome. It preserves the existing eyebrow and large heading treatment while giving catalogs, examples, utilities, and configurators the same spacing.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">PageContainer</span>, <span class="hljs-title class_">PageHeader</span>, <span class="hljs-title class_">PageContent</span>, <span class="hljs-title class_">PageFooter</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-page-container</span> <span class="hljs-attr">sectionTitle</span>=<span class="hljs-string">&quot;Workspace&quot;</span> <span class="hljs-attr">pageTitle</span>=<span class="hljs-string">&quot;Projects&quot;</span> <span class="hljs-attr">pageDescription</span>=<span class="hljs-string">&quot;Manage your active projects.&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-page-content</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Your projects appear here.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-page-content</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-page-footer</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;button&quot;</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;createProject()&quot;</span>&gt;</span>Create project<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-page-footer</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-page-container</span>&gt;</span></code></pre>\n<p>Content may also be projected directly without <code>PageContent</code>. Supply a <code>bx-page-header</code> when you need actions or other content below the default heading:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-page-container</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-page-header</span> [<span class="hljs-attr">pageTitle</span>]=<span class="hljs-string">&quot;{ key: &#x27;projects.title&#x27; }&quot;</span> [<span class="hljs-attr">pageDescription</span>]=<span class="hljs-string">&quot;{ key: &#x27;projects.description&#x27; }&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;button&quot;</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;createProject()&quot;</span>&gt;</span>Create project<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-page-header</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-page-content</span>&gt;</span>Project list<span class="hljs-tag">&lt;/<span class="hljs-name">bx-page-content</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-page-container</span>&gt;</span></code></pre>\n<h3>Automatic navigation</h3>\n<p><code>provideNavigation()</code> from <code>@filip.mazev/blocks/navigation</code> installs <code>BX_PAGE_NAVIGATION</code>. The container and header consume this optional reactive adapter\nwithout introducing a dependency from primitives to navigation. No router or navigation provider is needed when using explicit titles without breadcrumb links.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { defineNavigation, provideNavigation } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/navigation&#x27;</span>;\n\n<span class="hljs-keyword">const</span> navigation = <span class="hljs-title function_">defineNavigation</span>({ <span class="hljs-attr">sections</span>: [{ <span class="hljs-attr">id</span>: <span class="hljs-string">&#x27;workspace&#x27;</span>, <span class="hljs-attr">title</span>: { <span class="hljs-attr">key</span>: <span class="hljs-string">&#x27;workspace.title&#x27;</span> } }] });\n<span class="hljs-keyword">const</span> { withInAppNavigation } = navigation;\n\n<span class="hljs-comment">// In application providers: provideRouter(routes), ...provideNavigation(navigation.config)</span>\n<span class="hljs-keyword">const</span> routes = [\n    <span class="hljs-title function_">withInAppNavigation</span>(\n        {\n            <span class="hljs-attr">path</span>: <span class="hljs-string">&#x27;projects&#x27;</span>,\n            <span class="hljs-attr">children</span>: [\n                <span class="hljs-title function_">withInAppNavigation</span>(\n                    { <span class="hljs-attr">path</span>: <span class="hljs-string">&#x27;details&#x27;</span>, <span class="hljs-attr">loadComponent</span>: <span class="hljs-function">() =&gt;</span> <span class="hljs-keyword">import</span>(<span class="hljs-string">&#x27;./project-details&#x27;</span>).<span class="hljs-title function_">then</span>(<span class="hljs-function">(<span class="hljs-params"><span class="hljs-variable language_">module</span></span>) =&gt;</span> <span class="hljs-variable language_">module</span>.<span class="hljs-property">ProjectDetails</span>) },\n                    { <span class="hljs-attr">label</span>: { <span class="hljs-attr">key</span>: <span class="hljs-string">&#x27;projects.details&#x27;</span> }, <span class="hljs-attr">menu</span>: <span class="hljs-literal">true</span> }\n                )\n            ]\n        },\n        { <span class="hljs-attr">label</span>: { <span class="hljs-attr">key</span>: <span class="hljs-string">&#x27;projects.title&#x27;</span> }, <span class="hljs-attr">section</span>: <span class="hljs-string">&#x27;workspace&#x27;</span>, <span class="hljs-attr">menu</span>: <span class="hljs-literal">true</span> }\n    )\n];</code></pre>\n<p>At <code>/projects</code>, the default breadcrumb trail stays hidden. At <code>/projects/details</code>, it appears with a link back to Projects. Nesting counts breadcrumb entries\nthat participate in navigation, excluding routes without breadcrumb metadata. Set <code>[breadcrumbsAfter]=&quot;2&quot;</code> to wait until two nesting levels. Set it to zero to\nshow even a root entry, or set <code>[showBreadcrumbs]=&quot;false&quot;</code> to hide the trail. A custom <code>breadcrumbs</code> array follows the same threshold.</p>\n<p>The default header resolves <code>sectionTitle</code> from the navigation section and <code>pageTitle</code> from the active breadcrumb label, falling back to its menu label.\nComponentless routes and metadata-free child outlets retain the nearest route&#39;s heading. <code>pageDescription</code> is always manually supplied. Explicit empty title\nstrings suppress their automatic values. A projected <code>PageHeader</code> owns its own inputs; container heading inputs configure only the generated header.</p>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Input</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>size: ContainerSize</code></td>\n<td><code>xl</code></td>\n<td>Shared Container maximum-width preset: <code>sm</code>, <code>md</code>, <code>lg</code>, <code>xl</code>, or <code>full</code></td>\n</tr>\n<tr>\n<td><code>sectionTitle?: ResolvableText</code></td>\n<td>Navigation section</td>\n<td>Small label above the title; empty string hides it</td>\n</tr>\n<tr>\n<td><code>pageTitle?: ResolvableText</code></td>\n<td>Navigation label</td>\n<td>Page heading; empty string hides it</td>\n</tr>\n<tr>\n<td><code>pageDescription?: ResolvableText</code></td>\n<td>None</td>\n<td>Explicit supporting text</td>\n</tr>\n<tr>\n<td><code>autoResolveTitlesFromNavigation: boolean</code></td>\n<td><code>true</code></td>\n<td>Resolves undefined titles from navigation; breadcrumbs are independent</td>\n</tr>\n<tr>\n<td><code>breadcrumbs?: readonly IPageBreadcrumb[]</code></td>\n<td>Adapter trail</td>\n<td>Explicit labels and absolute router URLs; an empty array suppresses automatic entries</td>\n</tr>\n<tr>\n<td><code>breadcrumbsAfter: number</code></td>\n<td><code>1</code></td>\n<td>Minimum nesting before showing breadcrumbs; negative values clamp to zero</td>\n</tr>\n<tr>\n<td><code>showBreadcrumbs: boolean</code></td>\n<td><code>true</code></td>\n<td>Enables the trail when its threshold is met</td>\n</tr>\n<tr>\n<td><code>breadcrumbLabel: ResolvableText</code></td>\n<td><code>Breadcrumbs</code></td>\n<td>Accessible name for the navigation landmark</td>\n</tr>\n</tbody></table>\n<p><code>PageHeader</code> accepts the same title, description, and <code>autoResolveTitlesFromNavigation</code> inputs, plus <code>headingLevel</code> (1–6, default 1). It projects additional\nheader content below the description. <code>PageContent</code> and <code>PageFooter</code> project content without introducing a new surface, landmark, or scrolling region.</p>\n<p>Applications with custom navigation can provide <code>BX_PAGE_NAVIGATION</code> as a <code>Signal&lt;IPageNavigation&gt;</code>. Its optional titles and ordered <code>IPageBreadcrumb[]</code> support\n<code>ResolvableText</code>; the final breadcrumb represents the current page. All layout text uses the optional <code>BX_I18N</code> adapter and reacts to its version signal.\nWithout an adapter, plain strings render unchanged and translation keys fall back to their keys.</p>\n<h2>Appearance and customization</h2>\n<table>\n<thead>\n<tr>\n<th>CSS variable</th>\n<th>Default</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--bx-container-max-width</code></td>\n<td>Shared <code>size</code> preset (<code>xl</code>: 1280px)</td>\n</tr>\n<tr>\n<td><code>--bx-page-padding-inline</code></td>\n<td><code>clamp(1rem, 3vw, 2.5rem)</code> from shared spacing tokens</td>\n</tr>\n<tr>\n<td><code>--bx-page-padding-block</code></td>\n<td><code>clamp(1rem, 3vw, 2.5rem)</code> from shared spacing tokens</td>\n</tr>\n<tr>\n<td><code>--bx-page-gap</code></td>\n<td>Shared spacing 8</td>\n</tr>\n<tr>\n<td><code>--bx-page-section-color</code></td>\n<td><code>--bx-text-brand</code></td>\n</tr>\n<tr>\n<td><code>--bx-page-title-color</code></td>\n<td><code>--bx-text-heading</code></td>\n</tr>\n<tr>\n<td><code>--bx-page-title-size</code></td>\n<td><code>clamp(2rem, 4vw, 3rem)</code></td>\n</tr>\n<tr>\n<td><code>--bx-page-description-width</code></td>\n<td><code>48rem</code></td>\n</tr>\n<tr>\n<td><code>--bx-page-description-color</code></td>\n<td><code>--bx-text-secondary</code></td>\n</tr>\n</tbody></table>\n<p>Use the shared theme and appearance configuration. Nesting a preview can override the padding variables without changing other page instances.</p>\n<h2>Behavior and accessibility</h2>\n<p>The layout does not create a second <code>main</code> landmark or a nested scroll area. Place it inside the application&#39;s existing <code>main</code>. The generated header uses one\nnative <code>h1</code>. For nested examples, project <code>PageHeader</code> with <code>[headingLevel]=&quot;2&quot;</code> or a deeper level.</p>\n<p>Breadcrumbs use an ordered list in a named navigation landmark, keyboard-accessible router links, visible focus, and <code>aria-current=&quot;page&quot;</code> on the final label.\nLinks preserve the router&#39;s normal focus and scrolling policy. Gutters use logical properties; headings and trails wrap for translated content, RTL, narrow\ncontainers, and zoom. Theme changes apply through semantic tokens; no motion is introduced.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/layout/page-container</code> to change the title, description, breadcrumb depth, root/child trail, automatic navigation, and footer. The footer\naction reports its result. <code>/components/layout</code> groups Page container, Content container, Stack layout, Grid layout, and Divider. Existing\n<code>/components/container</code>, <code>/components/stack</code>, <code>/components/grid</code>, and <code>/components/divider</code> URLs redirect to their layout destinations.</p>\n',
  'projects/blocks/primitives/components/page-content/README.md':
    '<h1>Page content</h1>\n<p>The content section of a page. It keeps projected content shrinkable and supports wrapping without adding a scroll surface.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">PageContent</span>, <span class="hljs-title class_">PageContainer</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-page-container</span> <span class="hljs-attr">pageTitle</span>=<span class="hljs-string">&quot;Projects&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-page-content</span>&gt;</span>Project list<span class="hljs-tag">&lt;/<span class="hljs-name">bx-page-content</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-page-container</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p>Projects application-owned content without inputs or outputs.</p>\n<h2>Appearance and customization</h2>\n<p>See the <a href="components/layout/page-container#appearance-and-customization">Page container CSS variables</a>. Additional projected content retains its owning component&#39;s\nstyles and uses shared theme tokens.</p>\n<h2>Behavior and accessibility</h2>\n<p>Adds no landmark, focus behavior, or scrolling region. Keep actions keyboard accessible and status announcements application-owned.</p>\n<h2>Playground</h2>\n<p><code>/components/layout/page-container</code> demonstrates this section with the other page components.</p>\n',
  'projects/blocks/primitives/components/page-footer/README.md':
    '<h1>Page footer</h1>\n<p>An optional trailing section for page actions or status. The footer remains in the normal page flow.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">PageFooter</span>, <span class="hljs-title class_">PageContainer</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-page-container</span> <span class="hljs-attr">pageTitle</span>=<span class="hljs-string">&quot;Projects&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-page-content</span>&gt;</span>Project list<span class="hljs-tag">&lt;/<span class="hljs-name">bx-page-content</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-page-footer</span>&gt;</span>Page status<span class="hljs-tag">&lt;/<span class="hljs-name">bx-page-footer</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-page-container</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p>Projects application-owned content without inputs or outputs.</p>\n<h2>Appearance and customization</h2>\n<p>See the <a href="components/layout/page-container#appearance-and-customization">Page container CSS variables</a>. Additional projected content retains its owning component&#39;s\nstyles and uses shared theme tokens.</p>\n<h2>Behavior and accessibility</h2>\n<p>Adds no landmark, focus behavior, or scrolling region. Keep actions keyboard accessible and status announcements application-owned.</p>\n<h2>Playground</h2>\n<p><code>/components/layout/page-container</code> demonstrates this section with the other page components.</p>\n',
  'projects/blocks/primitives/components/page-header/README.md':
    '<h1>Page header</h1>\n<p>The title section of a page, with a translated eyebrow, heading, description, and projected actions.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">PageHeader</span>, <span class="hljs-title class_">PageContainer</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-page-header</span> <span class="hljs-attr">sectionTitle</span>=<span class="hljs-string">&quot;Workspace&quot;</span> <span class="hljs-attr">pageTitle</span>=<span class="hljs-string">&quot;Projects&quot;</span> <span class="hljs-attr">pageDescription</span>=<span class="hljs-string">&quot;Manage your projects.&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>sectionTitle</code>, <code>pageTitle</code>, and <code>pageDescription</code> accept optional <code>ResolvableText</code>. Undefined titles resolve from navigation when\n<code>autoResolveTitlesFromNavigation</code> is true (the default). An empty string hides that title. Descriptions are explicit. <code>headingLevel</code> defaults to 1 and clamps to\n1–6; use 2 for nested previews.</p>\n<h2>Appearance and customization</h2>\n<p>See the <a href="components/layout/page-container#appearance-and-customization">Page container CSS variables</a>. Additional projected content retains its owning component&#39;s\nstyles and uses shared theme tokens.</p>\n<h2>Behavior and accessibility</h2>\n<p>Uses a native heading and reacts to <code>BX_I18N</code> language updates. Plain strings work without an adapter.</p>\n<h2>Playground</h2>\n<p><code>/components/layout/page-container</code> demonstrates this section with the other page components.</p>\n',
  'projects/blocks/primitives/components/popover/README.md':
    '<h1>Popover</h1>\n<p>A general content surface and trigger for interactive help, compact forms and contextual details. Uses the existing CDK overlay, theme inheritance and surface\nengine.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Popover</span>, <span class="hljs-title class_">PopoverDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> [<span class="hljs-attr">bxPopover</span>]=<span class="hljs-string">&quot;details&quot;</span> #<span class="hljs-attr">popover</span>=<span class="hljs-string">&quot;bxPopover&quot;</span> [<span class="hljs-attr">popoverConfig</span>]=<span class="hljs-string">&quot;{ ariaLabel: &#x27;Project details&#x27;, placement: &#x27;bottom&#x27; }&quot;</span>&gt;</span>Details<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> #<span class="hljs-attr">details</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-popover</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Interactive content belongs here.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">button</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;popover.close()&quot;</span>&gt;</span>Done<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-popover</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span></code></pre>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>API</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>[bxPopover]</code></td>\n<td>required</td>\n<td>Content <code>TemplateRef&lt;unknown&gt;</code></td>\n</tr>\n<tr>\n<td><code>popoverConfig</code></td>\n<td><code>{}</code></td>\n<td><code>IPopoverConfig</code> overrides</td>\n</tr>\n<tr>\n<td><code>popoverDisabled</code></td>\n<td><code>false</code></td>\n<td>Prevents opening and closes an open panel</td>\n</tr>\n<tr>\n<td><code>isOpen()</code></td>\n<td><code>false</code></td>\n<td>Read-only trigger state</td>\n</tr>\n<tr>\n<td><code>openedChange</code></td>\n<td>—</td>\n<td>Emits a boolean after opening or closing</td>\n</tr>\n<tr>\n<td><code>open() / close() / toggle()</code></td>\n<td>—</td>\n<td>Programmatic trigger methods</td>\n</tr>\n<tr>\n<td><code>close(false)</code></td>\n<td>—</td>\n<td>Dismiss without restoring trigger focus</td>\n</tr>\n<tr>\n<td><code>opaque</code> on <code>bx-popover</code></td>\n<td>absent</td>\n<td>Local reduced-transparency override</td>\n</tr>\n</tbody></table>\n<p><code>IPopoverConfig</code>: <code>placement</code> (bottom), <code>offset</code> (8px), <code>ariaLabel</code> (Details), <code>autoFocus</code> (true), <code>closeOnOutside</code> (true), <code>closeOnEscape</code> (true),\n<code>closeOnFocusOutside</code> (true). Labels accept <code>ResolvableText</code>.</p>\n<p>Provide <code>{ provide: BX_POPOVER_DEFAULTS, useValue: { placement: &#39;top&#39; } }</code> for application defaults. Instance properties win, followed by shared defaults and\nlibrary defaults.</p>\n<h2>Appearance and customization</h2>\n<p><code>--bx-popover-width</code>, <code>--bx-popover-max-width</code>, <code>--bx-popover-padding</code>, <code>--bx-popover-background</code>, <code>--bx-popover-color</code>, <code>--bx-popover-border</code>,\n<code>--bx-popover-radius</code> and <code>--bx-popover-shadow</code>. Use Blocks buttons and fields for controls inside the content. The material wrapper clips decorative layers; a\nseparate content region scrolls vertically only when its content exceeds the available viewport.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use a native button trigger. The directive owns nonmodal dialog semantics and its translated accessible name. Focus moves to the first tabbable control or the\npanel; Escape restores trigger focus. Tab exits at the panel boundary. Inside clicks stay open. Surface motion follows BxA11yService. Panels scroll within the\nviewport and inherit live theme changes, including modal/top-layer contexts. For a modal interaction use the modal package.</p>\n<h2>Playground</h2>\n<p><code>/components/popover</code> includes live examples and shared appearance controls.</p>\n',
  'projects/blocks/primitives/components/progress-bar/README.md':
    '<h1>Progress bar</h1>\n<p>Reusable loading feedback integrated with Blocks themes and accessibility preferences.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ProgressBar</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-progress-bar</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Upload progress&quot;</span> [<span class="hljs-attr">value</span>]=<span class="hljs-string">&quot;progress()&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>mode</code> supports <code>determinate</code>, <code>indeterminate</code>, <code>buffer</code>, and <code>query</code>. <code>value</code> and <code>bufferValue</code> are clamped to 0–100. Unknown progress omits <code>aria-valuenow</code>.\n<code>label</code> accepts translations. CSS variables: <code>--bx-progress-color</code>, <code>--bx-progress-track</code>, <code>--bx-progress-height</code>, <code>--bx-progress-radius</code>.</p>\n<h2>Appearance and accessibility</h2>\n<p>Uses Blocks semantic tokens and the active <code>ThemingService</code> configuration. Customize through documented inputs, templates and CSS variables. Existing components\nupdate when the application theme changes. Keyboard focus, forced colors, reduced transparency and <code>BxA11yService</code> reduced-motion preferences remain supported.</p>\n<p>Text inputs accept <code>ResolvableText</code>: plain text or <code>{ key: &#39;translation.key&#39; }</code>. With <code>BX_I18N</code>, text is resolved reactively, including already-mounted controls\nwhen the adapter&#39;s <code>version</code> signal changes. Plain text works without an adapter.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/progress-bar</code>. Fake asynchronous requests demonstrate progress and loading buttons. Reduced-motion preferences remove continuous animation\nwhile preserving status feedback.</p>\n',
  'projects/blocks/primitives/components/side-panel-layout/README.md':
    '<h1>Side panel layout</h1>\n<p><code>SidePanelLayout</code> supplies stable bounds for declarative overlay and push panels alongside a page&#39;s content. It keeps containment in CSS and reserves real space\nfor push panels without reparenting or recreating their content when modes change.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SidePanel</span>, <span class="hljs-title class_">SidePanelLayout</span>, <span class="hljs-title class_">SidePanelHeaderDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-side-panel-layout</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-side-panel</span> [(<span class="hljs-attr">open</span>)]=<span class="hljs-string">&quot;filtersOpen&quot;</span> <span class="hljs-attr">placement</span>=<span class="hljs-string">&quot;left&quot;</span> [<span class="hljs-attr">breakpoints</span>]=<span class="hljs-string">&quot;{ &#x27;2xl&#x27;: &#x27;push&#x27; }&quot;</span> <span class="hljs-attr">ariaLabel</span>=<span class="hljs-string">&quot;Filters&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">h2</span> <span class="hljs-attr">bxSidePanelHeader</span>&gt;</span>Filters<span class="hljs-tag">&lt;/<span class="hljs-name">h2</span>&gt;</span>\n        <span class="hljs-comment">&lt;!-- Filter controls --&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-side-panel</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">main</span> <span class="hljs-attr">class</span>=<span class="hljs-string">&quot;workspace-content&quot;</span>&gt;</span><span class="hljs-comment">&lt;!-- Page content; give its scroll wrapper overflow: auto. --&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">main</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-side-panel-layout</span>&gt;</span></code></pre>\n<p>Give the layout a definite available height or a constrained flex/grid slot. A page with a toolbar can use a column flex shell: the toolbar occupies its natural\nheight, and the layout fills <code>flex: 1</code> with <code>min-block-size: 0</code>. This keeps panels below the toolbar without numeric offsets or scroll-time rectangle tracking.</p>\n<h2>API</h2>\n<p>The layout has no configuration inputs. Direct <code>bx-side-panel</code> children occupy their physical left/right slots; all other content is projected into the flexible\nmiddle region. A panel&#39;s <code>layoutMode</code>, <code>breakpoints</code>, <code>width</code>, <code>placement</code>, and <code>open</code> model determine its slot. Default mode is overlay. Breakpoint overrides\nuse the shared minimum-width <code>BreakpointKey</code> contract and <code>WindowDimensionsService</code>; the highest matching configured breakpoint wins.</p>\n<h2>Appearance and customization</h2>\n<p>The host is a positioned, isolated flex region with viewport-constrained clipping. Configure surfaces and projected sections on each panel. Size the host with\nyour existing Blocks layout tokens and keep the middle content&#39;s actual scroll wrapper constrained.</p>\n<h2>Behavior and accessibility</h2>\n<p>Push mode reserves space, while overlay mode leaves content width unchanged. Both preserve the same panel instance and projected form state. Mode and open\nchanges coordinate slot-width transitions with panel motion; reduced motion removes those transitions. The layout adds no focus trap, scroll lock, or modal\nsemantics. Child panels provide the existing top-layer overlay context for dropdowns and tooltips.</p>\n<p>An explicit panel <code>container=&quot;viewport&quot;</code> escapes this layout and uses overlay mode. An arbitrary external element can still provide overlay bounds. Push mode\nrequires this layout host; standalone panels otherwise retain overlay behavior.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/side-panel</code> to exercise containment and breakpoint behavior, or <code>/icons</code> for coordinated responsive panels and a resizing virtual grid.</p>\n',
  'projects/blocks/primitives/components/side-panel/README.md':
    '<h1>Declarative side panel</h1>\n<p><code>SidePanel</code> is a persistent nonmodal surface controlled by its parent through <code>model&lt;boolean&gt;()</code>. It supports physical left/right placement, viewport or element\nbounds, optional scoped backdrops, and projected header, footer, banner, and body content. It uses no modal service, focus trap, inert page content, or scroll\nlock.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SidePanel</span>, <span class="hljs-title class_">SidePanelBannerDirective</span>, <span class="hljs-title class_">SidePanelFooterDirective</span>, <span class="hljs-title class_">SidePanelHeaderDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Import the component and the slot directives used by the template.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">div</span> #<span class="hljs-attr">contentContainer</span> <span class="hljs-attr">class</span>=<span class="hljs-string">&quot;content-region&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;button&quot;</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;filtersOpen.set(true)&quot;</span>&gt;</span>Filters<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-side-panel</span>\n    [(<span class="hljs-attr">open</span>)]=<span class="hljs-string">&quot;filtersOpen&quot;</span>\n    <span class="hljs-attr">placement</span>=<span class="hljs-string">&quot;left&quot;</span>\n    [<span class="hljs-attr">container</span>]=<span class="hljs-string">&quot;contentContainer&quot;</span>\n    [<span class="hljs-attr">width</span>]=<span class="hljs-string">&quot;400&quot;</span>\n    <span class="hljs-attr">ariaLabel</span>=<span class="hljs-string">&quot;Filters&quot;</span>\n    [<span class="hljs-attr">headerIcon</span>]=<span class="hljs-string">&quot;{ name: &#x27;sliders-horizontal&#x27;, color: &#x27;accent&#x27;, bgColor: &#x27;auto&#x27; }&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">h2</span> <span class="hljs-attr">bxSidePanelHeader</span>&gt;</span>Filters<span class="hljs-tag">&lt;/<span class="hljs-name">h2</span>&gt;</span>\n    <span class="hljs-comment">&lt;!-- Persistent filter controls --&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">div</span> <span class="hljs-attr">bxSidePanelFooter</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;button&quot;</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;filtersOpen.set(false)&quot;</span>&gt;</span>Done<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-side-panel</span>&gt;</span></code></pre>\n<p><code>filtersOpen</code> is a writable boolean signal. For stable page containment and responsive push behavior, use <a href="components/side-panel">SidePanelLayout</a>:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-side-panel-layout</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-side-panel</span> [(<span class="hljs-attr">open</span>)]=<span class="hljs-string">&quot;filtersOpen&quot;</span> <span class="hljs-attr">placement</span>=<span class="hljs-string">&quot;left&quot;</span> [<span class="hljs-attr">breakpoints</span>]=<span class="hljs-string">&quot;{ &#x27;2xl&#x27;: &#x27;push&#x27; }&quot;</span> <span class="hljs-attr">ariaLabel</span>=<span class="hljs-string">&quot;Filters&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">h2</span> <span class="hljs-attr">bxSidePanelHeader</span>&gt;</span>Filters<span class="hljs-tag">&lt;/<span class="hljs-name">h2</span>&gt;</span>\n        <span class="hljs-comment">&lt;!-- Filter controls --&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-side-panel</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">div</span> <span class="hljs-attr">class</span>=<span class="hljs-string">&quot;page-scroll-content&quot;</span>&gt;</span><span class="hljs-comment">&lt;!-- Adjacent page content --&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-side-panel-layout</span>&gt;</span></code></pre>\n<p>Give the layout a constrained height. Its page scroll wrapper can then use <code>overflow: auto</code>. A toolbar stays in its own natural-height flex/grid row above the\nlayout. The panel and its projected controls remain the same instances when mode changes; push reserves space and overlay leaves the content width unchanged.</p>\n<p>The element&#39;s actual visible bounds determine the surface and backdrop area; no sidebar offsets or relative-position styles are required. Omit <code>container</code> for\nviewport placement. Ensure an element-bound panel&#39;s container has meaningful height.</p>\n<h3>Width resizing</h3>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-side-panel</span> [(<span class="hljs-attr">open</span>)]=<span class="hljs-string">&quot;filtersOpen&quot;</span> <span class="hljs-attr">placement</span>=<span class="hljs-string">&quot;left&quot;</span> [<span class="hljs-attr">width</span>]=<span class="hljs-string">&quot;360&quot;</span> [<span class="hljs-attr">resizable</span>]=<span class="hljs-string">&quot;true&quot;</span> <span class="hljs-attr">ariaLabel</span>=<span class="hljs-string">&quot;Filters&quot;</span>&gt;</span>\n    <span class="hljs-comment">&lt;!-- Persistent filter controls --&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-side-panel</span>&gt;</span></code></pre>\n<p><code>width</code> sets the initial width directly, including CSS lengths. It is now a model, so <code>[(width)]=&quot;panelWidth&quot;</code> can retain the user&#39;s width in application state;\nuse a <code>number | string</code> writable signal because user adjustments write numeric CSS pixels. Existing one-way <code>[width]</code> bindings remain supported. Escape\ncancellation restores the pre-gesture width, including its original CSS-length representation.</p>\n<p>Resizing is opt-in and uses <a href="components/resize-handle">ResizeHandleDirective</a>. A left panel resizes from its right edge; a right panel resizes\nfrom its left edge. Side panels expose width resizing only, even though the underlying directive also supports top/bottom height resizing for other layouts.</p>\n<p>The default maximum is 50% of the containing region, retaining an outside backdrop area. The initial width is constrained to that maximum when resizing is\nenabled. <code>resizeDisableShrink</code> defaults to true: growth and return to the original rendered width are allowed. Set it to false to enable the default minimum of\n30% of the original width. Supply <code>resizeMinWidth</code>/<code>resizeMaxWidth</code> to use explicit pixel limits; available container width always takes precedence. The\nreference is the original rendered width at the first resize gesture. A custom initial width remains as simple as <code>[width]=&quot;360&quot;</code>.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-side-panel</span>\n    [(<span class="hljs-attr">open</span>)]=<span class="hljs-string">&quot;editorOpen&quot;</span>\n    [(<span class="hljs-attr">width</span>)]=<span class="hljs-string">&quot;editorWidth&quot;</span>\n    [<span class="hljs-attr">resizable</span>]=<span class="hljs-string">&quot;true&quot;</span>\n    [<span class="hljs-attr">resizeDisableShrink</span>]=<span class="hljs-string">&quot;false&quot;</span>\n    [<span class="hljs-attr">resizeMinWidth</span>]=<span class="hljs-string">&quot;240&quot;</span>\n    [<span class="hljs-attr">resizeMaxWidth</span>]=<span class="hljs-string">&quot;720&quot;</span>\n    <span class="hljs-attr">resizeLabel</span>=<span class="hljs-string">&quot;Resize editor width&quot;</span>\n    <span class="hljs-attr">ariaLabel</span>=<span class="hljs-string">&quot;Editor&quot;</span>&gt;</span>\n    <span class="hljs-comment">&lt;!-- Editor content --&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-side-panel</span>&gt;</span></code></pre>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Input/model</th>\n<th>Default</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>open</code> / <code>openChange</code></td>\n<td><code>false</code></td>\n<td>Parent-controlled model and user dismissal updates</td>\n</tr>\n<tr>\n<td><code>panelId</code></td>\n<td>Generated unique ID</td>\n<td>Stable surface ID for <code>aria-controls</code></td>\n</tr>\n<tr>\n<td><code>placement</code></td>\n<td><code>&#39;right&#39;</code></td>\n<td>Physical <code>&#39;left&#39;</code> or <code>&#39;right&#39;</code> edge</td>\n</tr>\n<tr>\n<td><code>headerIcon</code></td>\n<td><code>undefined</code></td>\n<td>Decorative <code>IIconData</code> beside projected heading; defaults to 24px and supports semantic color/background/stroke</td>\n</tr>\n<tr>\n<td><code>width</code> / <code>widthChange</code></td>\n<td><code>400</code></td>\n<td>Initial/current pixel or CSS-length width model; user resizing writes numeric pixels</td>\n</tr>\n<tr>\n<td><code>resizable</code></td>\n<td><code>false</code></td>\n<td>Enable an inner-edge width separator</td>\n</tr>\n<tr>\n<td><code>resizeMinWidth</code></td>\n<td>Relative</td>\n<td>Optional pixel minimum; defaults to 30% when shrinking is enabled</td>\n</tr>\n<tr>\n<td><code>resizeMaxWidth</code></td>\n<td>Relative</td>\n<td>Optional pixel maximum; defaults to 50% of container</td>\n</tr>\n<tr>\n<td><code>resizeDisableShrink</code></td>\n<td><code>true</code></td>\n<td>Prevent shrinking below the original rendered width</td>\n</tr>\n<tr>\n<td><code>resizeLabel</code></td>\n<td><code>&#39;Resize panel width&#39;</code></td>\n<td>Translatable accessible handle name</td>\n</tr>\n<tr>\n<td><code>resizeIdleDelay</code></td>\n<td><code>2000</code></td>\n<td>Milliseconds before the idle grip fades; zero keeps it revealed</td>\n</tr>\n<tr>\n<td><code>container</code></td>\n<td><code>undefined</code></td>\n<td>Nearest SidePanelLayout, or viewport without one; explicit element bounds or &#39;viewport&#39; override this</td>\n</tr>\n<tr>\n<td><code>layoutMode</code></td>\n<td><code>&#39;overlay&#39;</code></td>\n<td>Base push/overlay mode; push requires SidePanelLayout</td>\n</tr>\n<tr>\n<td><code>breakpoints</code></td>\n<td><code>undefined</code></td>\n<td>Typed minimum-width modes; the highest matching configured threshold wins</td>\n</tr>\n<tr>\n<td><code>currentLayoutMode()</code></td>\n<td>Resolved</td>\n<td>Effective mode after viewport resolution and layout availability</td>\n</tr>\n<tr>\n<td><code>backdrop</code></td>\n<td><code>false</code></td>\n<td>Blocks pointer interaction inside the configured bounds</td>\n</tr>\n<tr>\n<td><code>closeOnBackdrop</code></td>\n<td><code>true</code></td>\n<td>Backdrop activation requests model closure</td>\n</tr>\n<tr>\n<td><code>closeOnEscape</code></td>\n<td><code>true</code></td>\n<td>Unhandled Escape closes the open panel, including focus on the surrounding page</td>\n</tr>\n<tr>\n<td><code>showCloseButton</code></td>\n<td><code>true</code></td>\n<td>Built-in accessible close control</td>\n</tr>\n<tr>\n<td><code>ariaLabel</code></td>\n<td><code>&#39;Side panel&#39;</code></td>\n<td><code>ResolvableText</code> accessible region name</td>\n</tr>\n<tr>\n<td><code>labelledBy</code></td>\n<td><code>undefined</code></td>\n<td>Visible label element ID, taking precedence over <code>ariaLabel</code></td>\n</tr>\n<tr>\n<td><code>closeLabel</code></td>\n<td><code>&#39;Close panel&#39;</code></td>\n<td><code>ResolvableText</code> close-control name</td>\n</tr>\n<tr>\n<td><code>autoFocus</code></td>\n<td><code>true</code></td>\n<td>Focuses the surface once when opening</td>\n</tr>\n<tr>\n<td><code>restoreFocus</code></td>\n<td><code>true</code></td>\n<td>Returns focus if it remains inside the closing surface</td>\n</tr>\n<tr>\n<td><code>animationDuration</code></td>\n<td><code>175</code></td>\n<td>Entrance/exit milliseconds; reduced-motion preferences force zero</td>\n</tr>\n</tbody></table>\n<p>Slots are <code>[bxSidePanelBanner]</code>, <code>[bxSidePanelHeader]</code>, <code>[bxSidePanelFooter]</code>, and unmarked body content. Omitted sections consume no spacing. The body scrolls\nindependently; header and footer stay reachable. The component has no imperative opening methods or separate lifecycle events; the open model is the state\ncontract.</p>\n<h2>Appearance and customization</h2>\n<p>The panel shares surface material, square corners, frame, header/footer, banner, and close-control presentation with Modal Side. Its <code>bxSurface</code> material\nfollows the existing <code>ThemingService</code>, lighting, transparency, contrast, and theme inheritance helpers. Existing modal lifecycle and presentation APIs remain\navailable.</p>\n<p>The heading row uses the same banner presentation as Modal Side: aligned icon/text, shared title typography, divider spacing, and the compact 32px close button.\nSet <code>headerIcon</code> to an <code>IIconData</code> value for the leading icon; <code>name</code>, optional <code>size</code> (24px), <code>color</code>, <code>bgColor</code>, and <code>strokeWidth</code> match modal banner icons.\nThe icon is decorative; projected text and <code>ariaLabel</code> / <code>labelledBy</code> provide the panel name. Projected headings remain application-owned; reset their margin to\nzero and use <code>font: inherit</code> to retain the shared banner typography. The separate <code>bxSidePanelBanner</code> slot remains available above the heading.</p>\n<p>Set these variables on the component or a theme scope:</p>\n<table>\n<thead>\n<tr>\n<th>Variable</th>\n<th>Default</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--bx-panel-bg</code></td>\n<td><code>--bx-modal-bg</code>, then <code>--bx-bg-surface</code></td>\n</tr>\n<tr>\n<td><code>--bx-panel-text</code></td>\n<td><code>--bx-modal-text</code>, then <code>--bx-text-primary</code></td>\n</tr>\n<tr>\n<td><code>--bx-panel-padding</code></td>\n<td>Shared spacing 4</td>\n</tr>\n<tr>\n<td><code>--bx-panel-gap</code></td>\n<td>Shared spacing 4</td>\n</tr>\n<tr>\n<td><code>--bx-panel-z-index</code></td>\n<td>Shared fixed layer, below modal overlays</td>\n</tr>\n<tr>\n<td><code>--bx-panel-resize-gutter</code></td>\n<td>Shared spacing 6; space between the panel and adjacent content for the grip</td>\n</tr>\n<tr>\n<td><code>--bx-panel-backdrop</code></td>\n<td>Shared backdrop fallback</td>\n</tr>\n</tbody></table>\n<p>Projected content remains under the consumer&#39;s control. Use semantic tokens and Blocks controls; long content can wrap, and the panel shrinks to narrow bounds.</p>\n<h2>Behavior and accessibility</h2>\n<p>The panel is an accessible complementary region, not a modal dialog. It never sets <code>aria-modal</code>, traps focus, or makes surrounding content inert. An optional\nbackdrop blocks pointer interaction only inside its bounds; normal keyboard access to the page remains available. Use Modal when the task requires modal\nsemantics and focus trapping.</p>\n<p>Nested Selects, Multiselects, dropdowns, popovers, and tooltips inherit <code>BX_OVERLAY_CONTEXT</code> with top-layer hosting, so floating content is not clipped or\nhidden behind the panel. Explicit nested overlay contexts still follow their existing contract. All four surface corners are square, shared with Modal Side.</p>\n<p>On opening, focus moves to the surface unless <code>autoFocus</code> is false. On closing, it returns to the opening element only if focus is still inside the panel;\ninteractions elsewhere retain their focus. The panel observes unhandled Escape for its complete open lifetime, including after icon/content updates and focus\nchanges. Child overlays can consume Escape first. The built-in close action remains keyboard-accessible on touch-sized surfaces. Supply an accessible\nalternative if hiding it.</p>\n<p>Content stays mounted and becomes inert and hidden from assistive technology while closed. CSS transitions respond directly to the model, allowing rapid\nreversals without pending completion timers. <code>BxA11yService</code> preference changes update mounted motion immediately. Inside SidePanelLayout, CSS containment\nanchors the layer without scroll-driven measurements or a body portal. The stable parent bounds stay below any toolbar outside that layout. Arbitrary external\nelement bounds use synchronous, ancestor-filtered positioning; viewport presentation remains available. Theme/lighting inheritance is applied when hosting\nexternally. Listeners, observers, inheritance, and externally hosted nodes are disposed on destruction.</p>\n<p>Resize handles support mouse, pen, touch, and keyboard arrows with Home/End bounds. Pointer moves are frame-coalesced. Active resizing temporarily disables\npanel/slot size motion so the edge tracks the pointer directly; normal entrance/exit motion resumes afterward. The handle has a touch-sized hit area around the\ninner edge and remains outside the scrolling body. A spacing gutter holds a compact pill with three dots without overlapping the surface or adjacent content.\nPush layout reserves the gutter alongside the panel. The grip fades after two seconds of pointer inactivity, reappears on movement within the panel&#39;s content\nregion, and uses a neutral full-height line without dots on hover or while dragging. Focus and touch retain a visible affordance; reduced motion removes fades.\nSet <code>resizeIdleDelay</code> to configure the delay or zero to keep the idle grip visible. Escape first cancels resizing, then can dismiss the panel on the next\nactivation.</p>\n<p>Text accepts plain strings without an adapter. Optional <code>BX_I18N</code> resolution tracks the adapter&#39;s language revision through computed state.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/side-panel</code> to change placement, width, containment, and backdrop while open and verify persistent form content. <code>/icons</code> demonstrates\ncoordinated Filters and Details panels constrained to the main content region.</p>\n',
  'projects/blocks/primitives/components/skeleton/README.md':
    '<h1>Skeleton</h1>\n<p>Reserves space while content loads, with text, rectangle and circle shapes.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Skeleton</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-skeleton</span> [<span class="hljs-attr">lines</span>]=<span class="hljs-string">&quot;3&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-skeleton</span> <span class="hljs-attr">shape</span>=<span class="hljs-string">&quot;circle&quot;</span> <span class="hljs-attr">height</span>=<span class="hljs-string">&quot;3rem&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-skeleton</span> <span class="hljs-attr">shape</span>=<span class="hljs-string">&quot;rectangle&quot;</span> <span class="hljs-attr">height</span>=<span class="hljs-string">&quot;8rem&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-skeleton</span> [<span class="hljs-attr">decorative</span>]=<span class="hljs-string">&quot;false&quot;</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Loading profile&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Input</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>shape</code></td>\n<td><code>text</code></td>\n<td><code>SkeletonShape</code>: text, rectangle or circle</td>\n</tr>\n<tr>\n<td><code>lines</code></td>\n<td><code>1</code></td>\n<td>Text rows, clamped to 1–100</td>\n</tr>\n<tr>\n<td><code>width / height</code></td>\n<td>absent</td>\n<td>Optional CSS dimensions</td>\n</tr>\n<tr>\n<td><code>animated</code></td>\n<td><code>true</code></td>\n<td>Enables the pulse when motion preferences permit</td>\n</tr>\n<tr>\n<td><code>decorative</code></td>\n<td><code>true</code></td>\n<td>Hides repeated placeholders from accessibility APIs</td>\n</tr>\n<tr>\n<td><code>label</code></td>\n<td>Loading content</td>\n<td>Translatable status name when nondecorative</td>\n</tr>\n</tbody></table>\n<h2>Appearance and customization</h2>\n<p><code>--bx-skeleton-background</code>, <code>--bx-skeleton-height</code>, <code>--bx-skeleton-gap</code>, <code>--bx-skeleton-radius</code>, <code>--bx-skeleton-duration</code> and <code>--bx-skeleton-last-line-width</code>.\nDefaults use semantic element colors.</p>\n<h2>Behavior and accessibility</h2>\n<p>Replace skeletons with real content when the application finishes loading. Use one named status for a group of decorative placeholders. BxA11yService changes\nstop the pulse immediately, retaining the placeholder. Forced colors use a static system color.</p>\n<h2>Playground</h2>\n<p><code>/components/skeleton</code> includes live examples and shared appearance controls.</p>\n',
  'projects/blocks/primitives/components/stack/README.md':
    '<h1>Stack layout</h1>\n<p>A small flex layout for vertical content, action rows and responsive groups.</p>\n<h2>Public import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Stack</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-stack</span> <span class="hljs-attr">direction</span>=<span class="hljs-string">&quot;responsive&quot;</span> [<span class="hljs-attr">gap</span>]=<span class="hljs-string">&quot;4&quot;</span> <span class="hljs-attr">align</span>=<span class="hljs-string">&quot;center&quot;</span> <span class="hljs-attr">justify</span>=<span class="hljs-string">&quot;between&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>Project details<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>Updated today<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-stack</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>direction: StackDirection</code> is vertical (default), horizontal or responsive. Responsive stacks vertically below the shared sm breakpoint. <code>gap: LayoutGap</code>\ndefaults to 4; supported shared spacing keys are 0, 1, 2, 3, 4, 5, 6, 8, 10 and 12. <code>align: LayoutAlign</code> is start, center, end or stretch (default).\n<code>justify: LayoutJustify</code> is start (default), center, end or between. <code>wrap</code> defaults to false; enable it for action rows.</p>\n<h2>Appearance and customization</h2>\n<p><code>--bx-stack-gap</code> overrides token-based spacing. CSS flex properties remain available for application-specific proportions.</p>\n<h2>Behavior and accessibility</h2>\n<p>Adds no ARIA role or keyboard behavior. DOM order remains reading and tab order. Use wrapping horizontal stacks for long translated actions; use responsive\ndirection when content should stack on small screens.</p>\n<h2>Playground</h2>\n<p><code>/components/layout/stack</code> includes live examples and shared appearance controls.</p>\n',
  'projects/blocks/primitives/components/tab/README.md':
    '<h1>Tab</h1>\n<p>Declares a labelled panel inside <a href="components/tabs"><code>Tabs</code></a>.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Tabs</span>, <span class="hljs-title class_">Tab</span>, <span class="hljs-title class_">TabContentDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-tabs</span> <span class="hljs-attr">ariaLabel</span>=<span class="hljs-string">&quot;Project details&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-tab</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Overview&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;overview&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxTabContent</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">app-overview</span> /&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-tab</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-tab</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Activity&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;activity&quot;</span> [<span class="hljs-attr">disabled</span>]=<span class="hljs-string">&quot;loading()&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxTabContent</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">app-activity</span> /&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-tab</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-tabs</span>&gt;</span></code></pre>\n<p><code>label</code> is required and accepts <code>ResolvableText</code>. <code>value</code> identifies selection and must be unique within its group; an omitted value is generated. <code>disabled</code>\nremoves the tab from selection and arrow-key navigation.</p>\n<p><code>color</code> chooses a semantic palette role: <code>primary</code>, <code>accent</code>, <code>success</code>, <code>danger</code>, <code>info</code>, <code>warn</code>, or <code>grayscale</code>. The <code>accent</code> role follows the second tone of\nthe active palette. <code>textColor</code>, <code>highlightColor</code> and <code>contentColor</code> accept Blocks color tokens for the label, selected highlight/light and panel text. <code>icon</code>\nand <code>endIcon</code> add leading and trailing Blocks icons.</p>\n<p>Use direct content for simple panels, or <code>ng-template bxTabContent</code> to create the contents only while selected. The Tabs component renders the header and\naccessible panel; <code>bx-tab</code> is the projected declaration.</p>\n<p>See the Tabs documentation and <code>/components/tabs</code> for appearance, lifecycle, two-way selection and keyboard behavior.</p>\n',
  'projects/blocks/primitives/components/tabs/README.md':
    '<h1>Tabs</h1>\n<p>Switch between related panels with themed segmented or underline tabs.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Tabs</span>, <span class="hljs-title class_">Tab</span>, <span class="hljs-title class_">TabContentDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Add these standalone declarations to the consuming component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-tabs</span> <span class="hljs-attr">ariaLabel</span>=<span class="hljs-string">&quot;Project information&quot;</span> [(<span class="hljs-attr">selectedValue</span>)]=<span class="hljs-string">&quot;selectedTab&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-tab</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Documentation&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;documentation&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxTabContent</span>&gt;</span>\n            <span class="hljs-tag">&lt;<span class="hljs-name">app-documentation</span> /&gt;</span>\n        <span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-tab</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-tab</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Code Examples&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;code&quot;</span> <span class="hljs-attr">color</span>=<span class="hljs-string">&quot;accent&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxTabContent</span>&gt;</span>\n            <span class="hljs-tag">&lt;<span class="hljs-name">app-examples</span> /&gt;</span>\n        <span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-tab</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-tab</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Unavailable&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;unavailable&quot;</span> [<span class="hljs-attr">disabled</span>]=<span class="hljs-string">&quot;true&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-tabs</span>&gt;</span></code></pre>\n<p>Initialize <code>selectedTab</code> to a tab&#39;s value or <code>null</code> to select the first enabled tab. Values must be unique within a group. Omitted values receive generated\nidentifiers.</p>\n<p>Use <code>variant=&quot;underline&quot;</code> for file tabs or a full-width navigation strip. The default <code>segmented</code> variant groups the controls in a compact material.</p>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Declaration</th>\n<th>Input or method</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Tabs</code></td>\n<td><code>ariaLabel: ResolvableText</code></td>\n<td>Accessible group name; defaults to <code>Tabs</code>.</td>\n</tr>\n<tr>\n<td><code>Tabs</code></td>\n<td><code>variant: TabsVariant</code></td>\n<td><code>segmented</code> or <code>underline</code>.</td>\n</tr>\n<tr>\n<td><code>Tabs</code></td>\n<td><code>selectedValue: string | null</code></td>\n<td>Two-way selection model with <code>selectedValueChange</code>.</td>\n</tr>\n<tr>\n<td><code>Tabs</code></td>\n<td><code>select(value: string)</code></td>\n<td>Selects an enabled tab by value.</td>\n</tr>\n<tr>\n<td><code>Tabs</code></td>\n<td><code>dragSelection: boolean</code></td>\n<td>Defaults to true. Drag with a pointer or hold then drag with touch; release selects using position and recent velocity.</td>\n</tr>\n<tr>\n<td><code>Tab</code></td>\n<td><code>label: ResolvableText</code></td>\n<td>Required visible and accessible label.</td>\n</tr>\n<tr>\n<td><code>Tab</code></td>\n<td><code>value: string</code></td>\n<td>Unique selection value.</td>\n</tr>\n<tr>\n<td><code>Tab</code></td>\n<td><code>disabled: boolean</code></td>\n<td>Removes the tab from selection and keyboard navigation.</td>\n</tr>\n<tr>\n<td><code>Tab</code></td>\n<td><code>color: TabColor</code></td>\n<td><code>primary</code> (default), <code>accent</code>, <code>success</code>, <code>danger</code>, <code>info</code>, <code>warn</code>, or <code>grayscale</code>.</td>\n</tr>\n<tr>\n<td><code>Tab</code></td>\n<td><code>textColor: Color</code></td>\n<td>Optional theme token for the header label and its icons.</td>\n</tr>\n<tr>\n<td><code>Tab</code></td>\n<td><code>highlightColor: Color</code></td>\n<td>Overrides the selected tint, border, underline and emitted light. Defaults to the tab&#39;s color.</td>\n</tr>\n<tr>\n<td><code>Tab</code></td>\n<td><code>contentColor: Color</code></td>\n<td>Optional inherited text color for the panel&#39;s content.</td>\n</tr>\n<tr>\n<td><code>Tab</code></td>\n<td><code>icon: IconName</code></td>\n<td>Optional leading Blocks icon.</td>\n</tr>\n<tr>\n<td><code>Tab</code></td>\n<td><code>endIcon: IconName</code></td>\n<td>Optional trailing Blocks icon.</td>\n</tr>\n<tr>\n<td><code>TabContentDirective</code></td>\n<td><code>ng-template[bxTabContent]</code></td>\n<td>Defers construction until selection and destroys the view when deselected.</td>\n</tr>\n</tbody></table>\n<p>Labels accept strings or <code>{ key: &#39;translation.key&#39; }</code> using <code>BX_I18N</code>. Removing or disabling the selected tab selects the first enabled tab. An empty or fully\ndisabled group has no selected panel and a <code>null</code> model.</p>\n<h2>Per-tab colors and icons</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-tabs</span> <span class="hljs-attr">ariaLabel</span>=<span class="hljs-string">&quot;Workspace&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-tab</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Overview&quot;</span> <span class="hljs-attr">icon</span>=<span class="hljs-string">&quot;house&quot;</span> <span class="hljs-attr">color</span>=<span class="hljs-string">&quot;primary&quot;</span>&gt;</span>Overview content.<span class="hljs-tag">&lt;/<span class="hljs-name">bx-tab</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-tab</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Checks&quot;</span> <span class="hljs-attr">icon</span>=<span class="hljs-string">&quot;badge-check&quot;</span> <span class="hljs-attr">endIcon</span>=<span class="hljs-string">&quot;chevron-right&quot;</span> <span class="hljs-attr">color</span>=<span class="hljs-string">&quot;success&quot;</span>&gt;</span> All checks passed. <span class="hljs-tag">&lt;/<span class="hljs-name">bx-tab</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-tab</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Activity&quot;</span> <span class="hljs-attr">icon</span>=<span class="hljs-string">&quot;activity&quot;</span> <span class="hljs-attr">color</span>=<span class="hljs-string">&quot;info&quot;</span> <span class="hljs-attr">textColor</span>=<span class="hljs-string">&quot;text-warn&quot;</span> <span class="hljs-attr">highlightColor</span>=<span class="hljs-string">&quot;text-warn&quot;</span> <span class="hljs-attr">contentColor</span>=<span class="hljs-string">&quot;text-info&quot;</span>&gt;</span> Recent activity. <span class="hljs-tag">&lt;/<span class="hljs-name">bx-tab</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-tabs</span>&gt;</span></code></pre>\n<p>Color overrides use the existing Blocks <code>Color</code> tokens, including semantic tokens such as <code>text-success</code> and palette tokens such as <code>purple-500</code>. Tokens follow\nthe active theme. <code>textColor</code> styles the header in both selected and inactive states; <code>contentColor</code> supplies an inherited panel color without overriding\nprojected components&#39; own semantic styles. Icons are decorative and inherit the header&#39;s text color. Their leading/trailing placement follows the text\ndirection.</p>\n<h2>Content lifecycle</h2>\n<p>Direct content is supported for simple panels:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-tabs</span> <span class="hljs-attr">ariaLabel</span>=<span class="hljs-string">&quot;Project details&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-tab</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Overview&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Project overview.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-tab</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-tab</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Activity&quot;</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Recent updates.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-tab</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-tabs</span>&gt;</span></code></pre>\n<p>Angular constructs directly projected components eagerly. Use <code>ng-template bxTabContent</code> for lazy documentation, syntax highlighting or other work that should\nrun only for the selected panel. Panel-local state is recreated when revisiting a lazy panel; keep persistent state in the consuming component or a service.</p>\n<h2>Appearance</h2>\n<p>Tabs use Blocks semantic colors, spacing, radius, focus and surface effects. The shared glass header remains transmissive, while the selected tab has a\ntranslucent tint and emits a restrained amount of its highlight color into nearby surfaces. The default highlight follows the primary palette role. Use\n<code>color=&quot;accent&quot;</code> for the second tone, such as supporting Code Examples navigation. The initial render uses the same glass styling before the runtime mounts, and\ntransitions apply to later interactions. Appearance settings and reduced motion follow <code>ThemingService</code> and <code>BxA11yService</code>, like other primitives. Forced\ncolors use a visible selected outline.</p>\n<p>Tabs resolve their own minimum material opacity inside panels and dialogs. Inactive triggers stay transparent so a containing surface cannot cover the moving\nselection with its opacity floor. Header, selection and label stacking keep their existing clipping and motion behavior.</p>\n<p>Reduced transparency gives the header and selected tint opaque fills. Foreground tab triggers leave that selection visible; hover uses a separate neutral fill.\nThe selected shape and underline remain visible independently of text color, and live preference changes preserve selection, scrolling, and dragging.</p>\n<p><code>--bx-tabs-panel-gap</code> customizes the space below the headers. Panels follow the page&#39;s natural scroll flow by default. For a bounded viewer, set\n<code>--bx-tabs-panel-overflow: auto</code> together with <code>--bx-tabs-max-panel-height</code> or a constrained group height to keep headers visible while content scrolls. Let the\npanel own scrolling instead of also adding scroll containers to nested code blocks. Header labels scroll horizontally only when the actual tab row exceeds the\navailable width; the animated surface is clipped in a separate decorative layer so stretching and overshoot cannot create a scrollbar. The glass decoration sits\noutside that scroll area.</p>\n<h2>Keyboard and accessibility</h2>\n<p>Mouse and pen can press a header and drag immediately. Touch swipes retain native horizontal header scrolling and vertical page scrolling. Hold a tab for 200 ms\nbefore dragging to select instead; the material responds when the hold is ready. Pinch zoom and ordinary taps remain available. Set <code>[dragSelection]=&quot;false&quot;</code> to\ndisable selection dragging for every input without changing scrolling, clicks, or keyboard navigation.</p>\n<p>During selection dragging, the surface tracks the actual gesture and interpolates its width between enabled headers. Panels, <code>selectedValue</code>, and ARIA selection\nremain committed until release. A release projects recent velocity toward the nearest enabled header, bounded to a local tab span; a short pause removes\nmomentum for precise placement. A flick can therefore reach the next tab before the pointer reaches its midpoint. The release spring retains gesture velocity.\nEscape, pointer cancellation, lost capture, window blur, vertical scrolling, or release beyond the header&#39;s vertical tolerance restores the committed selection.\nExternal selection, changed geometry and removed/disabled targets cancel stale gestures. Holding near an overflowing header&#39;s edges scrolls continuously using\nthe shared frame clock. Release, cancellation and scroll boundaries stop that work.</p>\n<p>Programmatic changes and clicks use the same retargetable spring. Rapid changes preserve position and velocity, and variable-width headers resize the surface\ncontinuously. There is no entrance movement. Live reduced motion snaps selection and removes pressure/stretch while retaining direct manipulation and selected\nstate. Reduced transparency uses the engine&#39;s opaque fallback independently. The moving surface remains a receiver in the existing lighting engine. Panels\nswitch immediately to preserve dynamic content height; no panel-position animation is introduced. Programmatic replacement of a focused panel returns focus to\nthe newly selected header.</p>\n<p>Tab enters the selected header; another Tab moves into its panel. Left and Right select and focus the next enabled header, wrapping at the ends and respecting\nright-to-left layout. Home and End select the first and last enabled tabs. Native Enter and Space activation also work.</p>\n<p>Each header has <code>role=&quot;tab&quot;</code>, roving <code>tabindex</code>, <code>aria-selected</code> and a matching <code>aria-controls</code>. Panels use <code>role=&quot;tabpanel&quot;</code>, a matching <code>aria-labelledby</code>, and\nunique generated IDs. Nested groups maintain independent selection and keyboard handling.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/tabs</code> for enabled and disabled tabs, dynamic selection, lazy content and both appearances. The modal and toast configurators also use Tabs for\nDocumentation, Code Examples and source files.</p>\n<p>The pilot controls include unequal-width labels, programmatic selection, dynamic insertion/removal and an overflow list. Compare quick touch swipes with\nhold-and-drag, slow placement with short flicks, and stationary edge scrolling. Use <code>/appearance</code> for light/dark/custom palettes and independent reduced-motion\nand opaque-surface settings.</p>\n',
  'projects/blocks/primitives/components/tag/README.md':
    '<h1>Tag</h1>\n<p>Informational labels with semantic colors, tonal/filled/outlined variants, optional icons and counts, disabled presentation, and accessible tooltips. Tags do\nnot imply a button or selection action.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Tag</span>, <span class="hljs-title class_">ITagConfig</span>, <span class="hljs-title class_">TagColor</span>, <span class="hljs-title class_">TagVariant</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-tag</span>\n    [<span class="hljs-attr">text</span>]=<span class="hljs-string">&quot;{ key: &#x27;locations.skopje&#x27; }&quot;</span>\n    <span class="hljs-attr">color</span>=<span class="hljs-string">&quot;accent&quot;</span>\n    <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;tonal&quot;</span>\n    <span class="hljs-attr">leadingIcon</span>=<span class="hljs-string">&quot;map-pin&quot;</span>\n    <span class="hljs-attr">trailingIcon</span>=<span class="hljs-string">&quot;chevron-right&quot;</span>\n    [<span class="hljs-attr">trailingNumber</span>]=<span class="hljs-string">&quot;12&quot;</span>\n    [<span class="hljs-attr">tooltip</span>]=<span class="hljs-string">&quot;{ key: &#x27;locations.description&#x27; }&quot;</span> /&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-tag</span> [<span class="hljs-attr">leadingNumber</span>]=<span class="hljs-string">&quot;42&quot;</span> <span class="hljs-attr">color</span>=<span class="hljs-string">&quot;info&quot;</span> <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;filled&quot;</span> <span class="hljs-attr">ariaLabel</span>=<span class="hljs-string">&quot;42 locations&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-tag</span> <span class="hljs-attr">text</span>=<span class="hljs-string">&quot;Skopje&quot;</span> /&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-tag</span> <span class="hljs-attr">text</span>=<span class="hljs-string">&quot;+2&quot;</span> <span class="hljs-attr">tooltip</span>=<span class="hljs-string">&quot;Ohrid, Bitola&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>text</code>, <code>tooltip</code>, and <code>ariaLabel</code> accept <code>ResolvableText</code>. <code>color</code> selects primary, accent, success, danger, info, warn or neutral. <code>variant</code> is tonal\n(default), filled or outlined. <code>size</code> is small or medium. <code>disabled</code> changes the visual/accessible presentation without inventing an action.</p>\n<p><code>leadingIcon</code>, <code>trailingIcon</code>, and <code>iconSize</code> configure decorative icons. <code>leadingNumber</code> and <code>trailingNumber</code> accept numbers, strings such as <code>+2</code>, or null to\nhide a count. Omit text for a number-only tag. Numeric values use <code>Intl.NumberFormat</code> with the optional <code>locale</code>; strings retain their prefixes.</p>\n<p><code>config</code> accepts reusable <code>ITagConfig</code> appearance, icon, count and tooltip defaults. Direct inputs take precedence. <code>opaque</code> (also in <code>ITagConfig</code>) removes\ntranslucency and backdrop blur when true; false or absent follows application appearance and accessibility preferences. Navigation badges use it to keep their\nrows opaque. Consumer CSS variables can override the semantic palette without changing the component.</p>\n<p>Without an explicit <code>tooltip</code>, a tag automatically shows its complete label only when its rendered text is truncated. Resizing, content/translation changes, and\nloaded fonts update this condition through the shared <a href="components/truncate">TruncateDirective</a>. An explicit tooltip still describes the tag even\nwhen its label fits, including overflow tags listing hidden selections. Set <code>[tooltipOnTruncate]=&quot;false&quot;</code> to retain truncation while supplying custom feedback.\n<code>ITagConfig.tooltipOnTruncate</code> provides the reusable default, with the direct input taking precedence. <code>tooltip=&quot;&quot;</code> also suppresses the automatic tooltip. The\npublic <code>TruncateDirective</code>, <code>TruncatedTextPipe</code> (<code>bxTruncatedText</code>), and <code>truncatedText()</code> helper are available for application-owned text.</p>\n<h2>Appearance</h2>\n<p>Uses Blocks semantic theme colors and the shared glass surface. Tags inherit application translucency, receive surrounding emitted light, and follow\nopaque/reduced-transparency preferences. They have no hover illumination or press effect because they are informational. Tooltip motion follows <code>BxA11yService</code>.</p>\n<p>Text tags use small rounded corners. A single number without text or icons uses a circle that grows for longer counts. Override <code>--bx-tag-background</code>,\n<code>--bx-tag-color</code>, <code>--bx-tag-border</code>, <code>--bx-tag-radius</code>, <code>--bx-tag-padding</code>, <code>--bx-tag-gap</code>, <code>--bx-tag-font-size</code>, <code>--bx-tag-shadow</code>,\n<code>--bx-tag-counter-background</code>, <code>--bx-tag-counter-radius</code>, and <code>--bx-tag-disabled-opacity</code> as needed. <code>--bx-tag-number-size</code> and <code>--bx-tag-number-padding</code>\nconfigure the minimum diameter and horizontal padding of number-only circles; vertical padding is zero so line height does not stretch them into ovals;\n<code>--bx-tag-fill-opacity</code> and <code>--bx-tag-outline-opacity</code> tune the variant tints. Forced colors retain a visible boundary.</p>\n<h2>Accessibility and translations</h2>\n<p>Visible text remains available to assistive technology; decorative icons are hidden. An explicit <code>ariaLabel</code> names the tag group when the visible numbers need\ncontext. Tooltip tags support hover, keyboard focus and touch-and-hold. <code>focusable</code> defaults to true for a tooltip-bearing standalone tag; set it false when a\nsurrounding interactive control supplies keyboard access to the same description.</p>\n<p>Text resolves through <code>BX_I18N</code>, tracks its optional version signal, and falls back to keys without an adapter. Plain text works directly.</p>\n<h2>Selected values</h2>\n<p>Select and multiselect support <code>selectionDisplay=&quot;tags&quot;</code>. <code>tagConfig</code> sets shared tag appearance, and option <code>tagConfig</code> provides per-value overrides.\n<code>visibleTagCount</code> defaults to one and is clamped to at least one. Remaining values become an overflow tag such as <code>+2</code>, with their translated names in its\ntooltip. <code>tagOverflowText</code> and <code>overflowTagConfig</code> customize that tag.</p>\n<p>The parent combobox exposes the complete selection for keyboard users; embedded tags do not introduce nested tab stops or actions. Multiselect&#39;s\n<code>allSelectedText</code> still takes precedence when select-all intent is active.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/tag</code> for configurable text, colors, variants, icons, both counters, number-only tags, disabled appearance, an English/Spanish/French/German\ntranslation dropdown, and resizable conditional tooltips. <code>/components/truncate</code> demonstrates the shared directive directly. <code>/components/multi-select</code> includes\nselected-tag mode, visible-tag limits, and a Skopje +2 style overflow example.</p>\n',
  'projects/blocks/primitives/components/tooltip/README.md':
    '<h1>Tooltip</h1>\n<p>A short descriptive surface for supplementary help.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Tooltip</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-tooltip</span> <span class="hljs-attr">text</span>=<span class="hljs-string">&quot;Changes are saved automatically.&quot;</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>text</code> is required and accepts plain text or a translation key object. For automatic positioning and trigger handling, use <code>TooltipDirective</code> instead.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<p>Tooltips retain their neutral, opaque background while nearby emissive colors add a restrained, directional highlight to the facing border. The arrow shares the\nbody&#39;s background and samples the lighting on its side of the bubble. Positioned tooltips receive light from their trigger&#39;s context, including inside dialogs,\nwhile remaining transparent to pointer events. The overview&#39;s wake-up hint and Bring home action include explanatory tooltips. The hint fades without changing\nthe layout and appears only while the orb is asleep in its pod.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Do not put essential instructions only in a tooltip. Direct use requires the application to supply positioning, visibility and a relationship to its trigger.\nPrefer the directive for interactive pages.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/tooltip</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/primitives/components/virtual-collection/README.md':
    '<h1>Virtual collection</h1>\n<p><code>VirtualCollection&lt;T&gt;</code> renders a bidirectional sliding window of measured rows. Responsive grids and vertical lists retain their scroll extent with spacers\nwhile unmounting distant content. It is separate from scroll-end detection, progressive reveal counts, and asynchronous load-more orchestration.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">VirtualCollection</span>, <span class="hljs-title class_">VirtualItemDirective</span>, <span class="hljs-keyword">type</span> <span class="hljs-title class_">IVirtualCollectionConfig</span>, <span class="hljs-keyword">type</span> <span class="hljs-title class_">VirtualTrackBy</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Import the standalone component and item-template directive.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">itemKey</span>: <span class="hljs-title class_">VirtualTrackBy</span>&lt;<span class="hljs-title class_">Workspace</span>&gt; = <span class="hljs-function">(<span class="hljs-params">item</span>) =&gt;</span> item.<span class="hljs-property">id</span>;\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">virtualConfig</span>: <span class="hljs-title class_">IVirtualCollectionConfig</span> = {\n    <span class="hljs-attr">layout</span>: <span class="hljs-string">&#x27;grid&#x27;</span>,\n    <span class="hljs-attr">minColumnWidth</span>: <span class="hljs-string">&#x27;12rem&#x27;</span>,\n    <span class="hljs-attr">estimatedRowHeight</span>: <span class="hljs-number">180</span>,\n    <span class="hljs-attr">overscan</span>: <span class="hljs-number">800</span>\n};</code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">div</span> #<span class="hljs-attr">viewport</span> <span class="hljs-attr">class</span>=<span class="hljs-string">&quot;results-viewport&quot;</span> <span class="hljs-attr">tabindex</span>=<span class="hljs-string">&quot;0&quot;</span> <span class="hljs-attr">role</span>=<span class="hljs-string">&quot;region&quot;</span> <span class="hljs-attr">aria-label</span>=<span class="hljs-string">&quot;Workspaces&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-virtual-collection</span> #<span class="hljs-attr">collection</span> [<span class="hljs-attr">items</span>]=<span class="hljs-string">&quot;items()&quot;</span> [<span class="hljs-attr">trackBy</span>]=<span class="hljs-string">&quot;itemKey&quot;</span> [<span class="hljs-attr">config</span>]=<span class="hljs-string">&quot;virtualConfig&quot;</span> [<span class="hljs-attr">scrollContainer</span>]=<span class="hljs-string">&quot;viewport&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> [<span class="hljs-attr">bxVirtualItem</span>]=<span class="hljs-string">&quot;collection&quot;</span> <span class="hljs-attr">let-item</span> <span class="hljs-attr">let-index</span>=<span class="hljs-string">&quot;index&quot;</span>&gt;</span>\n            <span class="hljs-tag">&lt;<span class="hljs-name">bx-card</span> [<span class="hljs-attr">title</span>]=<span class="hljs-string">&quot;item.name&quot;</span> [<span class="hljs-attr">surfaceEffects</span>]=<span class="hljs-string">&quot;false&quot;</span>&gt;</span>\n                <span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;button&quot;</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;select(item)&quot;</span>&gt;</span>Open workspace {{ index + 1 }}<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n            <span class="hljs-tag">&lt;/<span class="hljs-name">bx-card</span>&gt;</span>\n        <span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-virtual-collection</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span></code></pre>\n<p>Constrain <code>.results-viewport</code> with a height and <code>overflow: auto</code>; set <code>overflow-anchor: none</code> so the collection owns scroll correction. The component can also\nobserve a scrolling ancestor or the document when <code>scrollContainer</code> is omitted. Use stable unique keys, immutable item arrays, and application-owned selection\nand expanded/edit state. An unmounted item&#39;s component-local state is recreated when it returns.</p>\n<p>For progressive loading, pass the supplied/revealed item prefix, and put <code>bxInfiniteScroll</code> or <code>bxLoadMore</code> on the actual scroll wrapper. Append data through\nthe owner. The virtual component never fetches, retries, infers exhaustion, or changes the supplied data. A future table can use list mode with\napplication-owned row templates, <code>role=&quot;rowgroup&quot;</code>, and <code>itemRole=&quot;row&quot;</code>; table semantics, headers, pagination, and selection remain the owner&#39;s responsibility.\nDo not place its div-based rendering inside native elements with restricted children.</p>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Member</th>\n<th>Default</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>items</code></td>\n<td><code>[]</code></td>\n<td>Full supplied/revealed data, including temporarily unmounted items</td>\n</tr>\n<tr>\n<td><code>trackBy</code></td>\n<td>Required</td>\n<td><code>(item, index) =&gt; string | number</code> stable unique identity</td>\n</tr>\n<tr>\n<td><code>config.layout</code></td>\n<td><code>&#39;list&#39;</code></td>\n<td><code>&#39;list&#39;</code> or responsive row-based <code>&#39;grid&#39;</code></td>\n</tr>\n<tr>\n<td><code>config.estimatedRowHeight</code></td>\n<td><code>128</code></td>\n<td>Positive CSS-pixel row-height estimate, excluding the row gap</td>\n</tr>\n<tr>\n<td><code>config.overscan</code></td>\n<td><code>800</code></td>\n<td>Extra mounted pixels above and below the viewport</td>\n</tr>\n<tr>\n<td><code>config.minColumnWidth</code></td>\n<td><code>&#39;7rem&#39;</code></td>\n<td>CSS length or pixel number used to resolve grid columns</td>\n</tr>\n<tr>\n<td><code>scrollContainer</code></td>\n<td>Discovered</td>\n<td>Actual element or document scroll viewport</td>\n</tr>\n<tr>\n<td><code>measurementRevision</code></td>\n<td><code>undefined</code></td>\n<td>Clear stale height estimates after size, density, or typography changes</td>\n</tr>\n<tr>\n<td><code>itemRole</code></td>\n<td><code>&#39;listitem&#39;</code></td>\n<td>Accessible role on each item wrapper</td>\n</tr>\n<tr>\n<td><code>renderedRange()</code></td>\n<td>Measured</td>\n<td>Contiguous <code>{ start, end, columns }</code> range; end is exclusive</td>\n</tr>\n<tr>\n<td><code>renderedItems()</code></td>\n<td>Measured</td>\n<td>Mounted data, including an independently pinned focused row</td>\n</tr>\n<tr>\n<td><code>scrollToIndex(index, behavior?)</code></td>\n<td>Method</td>\n<td>Scroll to a supplied item, clamping the index; pre-mount calls are deferred</td>\n</tr>\n<tr>\n<td><code>scrollToItem(key, behavior?)</code></td>\n<td>Method</td>\n<td>Scroll to an existing supplied key; missing keys leave position unchanged</td>\n</tr>\n<tr>\n<td><code>refreshMeasurements()</code></td>\n<td>Method</td>\n<td>Imperatively clear heights while retaining the visible anchor</td>\n</tr>\n</tbody></table>\n<p>The typed <code>bxVirtualItem</code> context exposes <code>$implicit</code>, <code>index</code>, and <code>count</code>. Count describes supplied items rather than a complete remote result set.</p>\n<h2>Appearance and customization</h2>\n<p>The component supplies geometry and semantics; projected content supplies presentation. Use Blocks components and semantic tokens. Set <code>--bx-virtual-row-gap</code>\nand <code>--bx-virtual-column-gap</code>; both default to shared spacing 3. <code>minColumnWidth</code> accepts font-relative lengths. Grid columns are measured from CSS, so\nconstrained containers, push panels, browser zoom, and text scaling participate in the same layout.</p>\n<h2>Behavior and accessibility</h2>\n<p>Rows use cached measured heights or the configured estimate. A shared <code>ResizeObserver</code> updates mounted rows, and a prefix-sum tree handles height updates and\noffset lookups efficiently. Width/column changes and <code>measurementRevision</code> invalidate stale heights. Spacer changes apply scroll correction after rendering so\nthe first visible stable key remains anchored. Unknown distant heights remain estimates until visited; use a realistic estimate to minimize corrections.</p>\n<p>Passive scroll events update the range synchronously, with pixel overscan in both directions. DOM size depends on viewport height, row sizes, columns, and\noverscan rather than distance traveled. Far-offscreen collections can render only their placeholder extent. A focused row stays mounted independently without\nrendering all rows between it and the viewport. Responsive regrouping restores the focused control within its stable item when available.</p>\n<p>Item wrappers expose positions and counts, and interactive projected controls retain native focus and keyboard behavior. Label the actual viewport and provide\nvisible focus. Reduced-motion preferences override smooth programmatic scrolling. Observers and listeners disconnect on destruction; browser measurements start\nafter rendering. When <code>ResizeObserver</code> is unavailable, estimates still support windowed rendering, but dynamic height accuracy is limited.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/virtual-collection</code> for 3,000 variable-height items, list/grid selection, width and density controls, expandable content, mounted counts, and\nprogrammatic scrolling. <code>/icons</code> and <code>/tokens</code> combine this component with progressive local rendering and ordinary search/group controls.</p>\n',
  'projects/blocks/primitives/directives/context-menu/README.md':
    '<h1>Context menu</h1>\n<p>A menu positioned at a context action’s coordinates.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxOverlayContextDirective</span>, <span class="hljs-title class_">ContextMenuDirective</span>, <span class="hljs-title class_">Menu</span>, <span class="hljs-title class_">MenuItem</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">div</span> [<span class="hljs-attr">bxContextMenu</span>]=<span class="hljs-string">&quot;actions&quot;</span> <span class="hljs-attr">tabindex</span>=<span class="hljs-string">&quot;0&quot;</span>&gt;</span>Right-click or touch and hold here<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> #<span class="hljs-attr">actions</span>\n    &gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-menu</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-menu-item</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Copy&quot;</span> (<span class="hljs-attr">action</span>)=<span class="hljs-string">&quot;copy()&quot;</span> /&gt;</span>&lt;/bx-menu\n&gt;<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>bxContextMenu</code> requires a TemplateRef. <code>open(event: MouseEvent)</code> positions the menu at the event coordinates.</p>\n<p><code>bxContextMenuLongPress</code> defaults to <code>true</code>. Set it to <code>false</code> on targets where native touch selection or another hold gesture should take precedence. Mouse and\nkeyboard activation remain available.</p>\n<h2>Overlay placement</h2>\n<p>Menus use the normal application overlay layer by default. To let a menu escape a sticky header or another stacking context, provide a top-layer context on a\nwrapper or directly on the trigger:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">header</span> [<span class="hljs-attr">bxOverlayContext</span>]=<span class="hljs-string">&quot;{ useTopLayer: true }&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">button</span> [<span class="hljs-attr">bxDropdown</span>]=<span class="hljs-string">&quot;actions&quot;</span>&gt;</span>Actions<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">div</span> [<span class="hljs-attr">bxContextMenu</span>]=<span class="hljs-string">&quot;actions&quot;</span>&gt;</span>More actions<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">header</span>&gt;</span></code></pre>\n<p>Import <code>BxOverlayContextDirective</code> alongside the menu directive. The context applies only to nested menu triggers; menus elsewhere keep their normal stacking\norder. Angular components can also provide <code>BX_OVERLAY_CONTEXT</code> with <code>{ useTopLayer: true }</code> to scope the behavior to their view.</p>\n<h2>Appearance</h2>\n<p>The standard <code>bx-menu</code> container is opaque and uses Blocks colors, spacing, radius and elevation without container blur or live lighting. Rows use local themed\nhover/pressed fills and keyboard focus outlines without casting light outside the panel. Press feedback follows application motion preferences. Custom emitting\ncontrols inside the overlay retain its physical lighting boundary even though the panel inherits incoming lighting from its trigger.</p>\n<p>The transparent dismissal backdrop blocks outside interaction without changing the surrounding surfaces&#39; lighting. The visible menu still occludes the content\nunder its panel; opaque backdrops retain their normal lighting behavior.</p>\n<p><code>BxA11yService</code> controls reduced motion; enabling it skips the opening and closing fade.</p>\n<h2>Behavior and accessibility</h2>\n<p>Touch and hold for 500 ms to open the menu. Moving more than 10 CSS pixels, scrolling, adding another finger, releasing early, or cancelling the pointer cancels\nthe pending hold. Normal scrolling and pinch gestures are preserved. The release after a successful hold does not activate the target or a menu action, and a\nbrowser-generated context menu does not reopen the menu.</p>\n<p>Long press follows touch input on devices with both touch and mouse support. Inputs, text areas, selects, editable content, disabled controls, and existing text\nselections keep their native touch behavior. Text selection is not disabled by the directive; dedicated non-selectable action targets can use\n<code>user-select: none</code> and <code>-webkit-touch-callout: none</code> in their own styles.</p>\n<p>Always offer the same actions through a visible button or menu; a hold gesture is not easily discoverable. A focusable trigger also supports Shift + F10 and the\nContext Menu key. The playground includes a visible Open actions button and keyboard equivalent.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/context-menu</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/primitives/directives/dropdown/README.md':
    '<h1>Dropdown</h1>\n<p>A positioned menu that fades in and out without resizing its contents.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxOverlayContextDirective</span>, <span class="hljs-title class_">DropdownDirective</span>, <span class="hljs-title class_">Menu</span>, <span class="hljs-title class_">MenuItem</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> [<span class="hljs-attr">bxDropdown</span>]=<span class="hljs-string">&quot;actions&quot;</span> <span class="hljs-attr">bxTransition</span>=<span class="hljs-string">&quot;fade&quot;</span>&gt;</span>Actions<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> #<span class="hljs-attr">actions</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-menu</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-menu-item</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Save&quot;</span> (<span class="hljs-attr">action</span>)=<span class="hljs-string">&quot;save()&quot;</span> /&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-menu</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>bxDropdown</code>: required TemplateRef. <code>placement</code>: overlay placement. <code>bxTransition</code>: fade (default) or none; emerge remains a compatibility alias for fade.\nExport as <code>bxDropdown</code>; call <code>open()</code>, <code>close()</code>, or <code>toggle()</code>. Read <code>isOpen()</code> and <code>state()</code> for lifecycle.</p>\n<h2>Overlay placement</h2>\n<p>Menus use the normal application overlay layer by default. To let a menu escape a sticky header or another stacking context, provide a top-layer context on a\nwrapper or directly on the trigger:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">header</span> [<span class="hljs-attr">bxOverlayContext</span>]=<span class="hljs-string">&quot;{ useTopLayer: true }&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">button</span> [<span class="hljs-attr">bxDropdown</span>]=<span class="hljs-string">&quot;actions&quot;</span>&gt;</span>Actions<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">header</span>&gt;</span></code></pre>\n<p>Import <code>BxOverlayContextDirective</code> alongside the menu directive. The context applies only to nested menu triggers; menus elsewhere keep their normal stacking\norder. Angular components can also provide <code>BX_OVERLAY_CONTEXT</code> with <code>{ useTopLayer: true }</code> to scope the behavior to their view.</p>\n<p>Where supported, native CSS anchors keep ordinary menus attached to their triggers during document and nested scrolling. Top-layer popovers and other browsers\nuse synchronous measured CDK positioning, including when the trigger is inside a nested scroller.</p>\n<h2>Appearance</h2>\n<p>The standard <code>bx-menu</code> container is opaque and uses Blocks colors, spacing, radius and elevation without container blur or live lighting. Rows use local themed\nhover/pressed fills and focus outlines without casting light onto the page. Press feedback and trigger effects follow application appearance settings.</p>\n<p><code>BxA11yService</code> controls reduced motion; enabling it skips the opening and closing fade.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use a real button trigger. The fade interaction supports trigger arrow keys, menu arrows, Home, End and Escape; focus returns on dismissal. Reduced motion skips\nthe fade. Content keeps its full dimensions and the overlay retains a solid backing throughout its lifetime.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/dropdown</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/primitives/directives/infinite-scroll/README.md':
    '<h1>Infinite scroll detection</h1>\n<p><code>InfiniteScrollDirective</code> detects the bottom boundary of arbitrary scrollable elements. It emits a guarded event without owning data, requests, pagination,\nloading indicators, retry actions, or exhaustion. Use it for bounded local progressive rendering; use Forms&#39; shared load-more orchestration for remote paging.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">InfiniteScrollDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Add the standalone directive to the consuming component&#39;s imports.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">div</span>\n    <span class="hljs-attr">bxInfiniteScroll</span>\n    <span class="hljs-attr">class</span>=<span class="hljs-string">&quot;results&quot;</span>\n    [<span class="hljs-attr">infiniteScrollThreshold</span>]=<span class="hljs-string">&quot;128&quot;</span>\n    [<span class="hljs-attr">infiniteScrollDisabled</span>]=<span class="hljs-string">&quot;!hasMore()&quot;</span>\n    [<span class="hljs-attr">infiniteScrollLoading</span>]=<span class="hljs-string">&quot;loading()&quot;</span>\n    [<span class="hljs-attr">infiniteScrollRevision</span>]=<span class="hljs-string">&quot;items()&quot;</span>\n    (<span class="hljs-attr">scrollEnd</span>)=<span class="hljs-string">&quot;requestNextPage()&quot;</span>&gt;</span>\n    @for (item of items(); track item.id) {\n    <span class="hljs-tag">&lt;<span class="hljs-name">div</span>&gt;</span>{{ item.label }}<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>\n    }\n<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span></code></pre>\n<p>Give the wrapper a constrained height and <code>overflow: auto</code>. The owner sets loading before starting its promise, appends successful results, and disables the\ndetector when exhausted. The directive does not assume an HTTP service or cursor format. Pass the new items reference through <code>infiniteScrollRevision</code>, or call\n<code>complete()</code> when completion has no loading cycle or revision change.</p>\n<p>For content scrolled by an ancestor, bind that element to <code>infiniteScrollContainer</code>. <code>findScrollContainer(element)</code> finds a vertical scrolling ancestor or falls\nback to the document scrolling element. The host&#39;s bottom remains the observed boundary, so unrelated content after the host does not delay rendering.</p>\n<p>For finite, locally available data, enable <code>infiniteScrollCheckOnRender</code>. Initial rendering, appended content, and resizing then recheck the boundary. Append a\nbounded batch on each event and disable when the local dataset is exhausted. This fills an initially short viewport without polling. Leave this option false for\nremote data to prevent uncontrolled requests; the <a href="components/load-more">load-more directive</a> provides its reachable fallback and\nexplicit retry action.</p>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Member</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>infiniteScrollContainer</code></td>\n<td>Host</td>\n<td>Optional actual scroll viewport, including a document scrolling element</td>\n</tr>\n<tr>\n<td><code>infiniteScrollThreshold</code></td>\n<td><code>128</code></td>\n<td>Distance from the end in CSS pixels</td>\n</tr>\n<tr>\n<td><code>infiniteScrollDisabled</code></td>\n<td><code>false</code></td>\n<td>Suppresses events; owner decides exhaustion</td>\n</tr>\n<tr>\n<td><code>infiniteScrollLoading</code></td>\n<td><code>false</code></td>\n<td>Suppresses events during owner-controlled loading</td>\n</tr>\n<tr>\n<td><code>infiniteScrollRevision</code></td>\n<td><code>undefined</code></td>\n<td>New items reference or revision acknowledges the previous event</td>\n</tr>\n<tr>\n<td><code>infiniteScrollCheckOnRender</code></td>\n<td><code>false</code></td>\n<td>Also checks initial/render/content/resize changes; opt in for bounded local data</td>\n</tr>\n<tr>\n<td><code>infiniteScrollEndOffset</code></td>\n<td><code>0</code></td>\n<td>Excludes an owner-controlled footer height from measurement</td>\n</tr>\n<tr>\n<td><code>overflowing()</code></td>\n<td>Measured</td>\n<td>Read-only overflow state, independent of event suppression</td>\n</tr>\n<tr>\n<td><code>scrollEnd</code></td>\n<td>Event</td>\n<td>One boundary event until completion or leaving and reentering the boundary</td>\n</tr>\n<tr>\n<td><code>complete()</code></td>\n<td>Method</td>\n<td>Acknowledges completion without initiating another event</td>\n</tr>\n</tbody></table>\n<p><code>measureScrollBoundary(content, container?, endOffset?)</code> returns the distance, overflow, and viewport height in <code>IScrollBoundary</code>.\n<code>observeScrollBoundary(content, container, onScroll, onResize)</code> installs disposable passive events and geometry observers. Both the directive and Forms&#39;\n<code>LoadMoreDirective</code> use these helpers; Select and Multiselect continue sharing the same request guards, retry, loading, and fallback orchestration.</p>\n<p><a href="components/virtual-collection">VirtualCollection</a> independently bounds the mounted DOM in both scroll directions. Give it the revealed items\nand the actual scroll container; its placeholders preserve the scroll extent observed by this detector. Detection, virtual rendering, and remote orchestration\nremain separate contracts.</p>\n<h2>Appearance and customization</h2>\n<p>The detector creates no DOM and supplies no presentation. Render normal, empty, loading, and error states with Blocks components and semantic tokens in the\nowner. Footer offsets allow a separate orchestration layer to exclude its action without tying detection to a particular UI.</p>\n<h2>Behavior and accessibility</h2>\n<p>Scroll handling and measurements run outside Angular, with frame-coalesced detector events and change detection only when state changes or an event emits.\nObservers reconnect for a different container, track appended and removed children, and disconnect on destruction. Browser work starts after rendering, so\nserver rendering does not access browser observers.</p>\n<p>Appending preserves scroll position. Owners should use stable tracking keys, announce relevant asynchronous changes, retain existing items on failure, and\nprovide keyboard-accessible load/retry actions. The detector never retries errors or infers that the loaded page is the complete remote result set.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/infinite-scroll</code> or the scrolling example on <code>/utilities</code>. Adjust the batch size and container height to exercise local underfill and overflow\ntransitions. The asynchronous example demonstrates 800 ms requests, retained results after failure, and explicit retry through success.</p>\n',
  'projects/blocks/primitives/directives/menu-trigger/README.md':
    '<h1>Nested menu trigger</h1>\n<p><code>MenuTriggerDirective</code> opens a <code>bx-menu</code> template using Blocks&#39; overlay positioning and theme inheritance. Use it for arbitrary-depth opaque submenus; each\ndescendant receives the containing trigger through <code>menuParent</code>.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Menu</span>, <span class="hljs-title class_">MenuItem</span>, <span class="hljs-title class_">MenuTriggerDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> [<span class="hljs-attr">bxMenuTrigger</span>]=<span class="hljs-string">&quot;menu&quot;</span> <span class="hljs-attr">menuLabel</span>=<span class="hljs-string">&quot;Projects&quot;</span> #<span class="hljs-attr">projects</span>=<span class="hljs-string">&quot;bxMenuTrigger&quot;</span>&gt;</span>Projects<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> #<span class="hljs-attr">menu</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-menu</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">bx-menu-item</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Overview&quot;</span> /&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">role</span>=<span class="hljs-string">&quot;menuitem&quot;</span> [<span class="hljs-attr">bxMenuTrigger</span>]=<span class="hljs-string">&quot;children&quot;</span> [<span class="hljs-attr">menuParent</span>]=<span class="hljs-string">&quot;projects&quot;</span> <span class="hljs-attr">menuLabel</span>=<span class="hljs-string">&quot;Design&quot;</span>&gt;</span>Design<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-menu</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> #<span class="hljs-attr">children</span>\n    &gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-menu</span>&gt;</span><span class="hljs-tag">&lt;<span class="hljs-name">bx-menu-item</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Tokens&quot;</span> /&gt;</span>&lt;/bx-menu\n&gt;<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span></code></pre>\n<p><code>bxMenuTrigger</code> is required. Optional inputs are <code>menuOrigin</code> (the full row when the trigger is a separate disclosure), <code>menuParent</code>, physical <code>menuSide</code>\n(<code>right</code> by default), <code>menuHover</code> (true), <code>menuManual</code> (false), <code>menuLabel</code> (trigger label fallback), and <code>menuPinned</code> (false; keeps a search-revealed path open\nduring pointer movement). <code>menuOpened</code>/<code>menuClosed</code> report transitions. <code>isOpen()</code>, <code>open(focus?, origin?)</code>, <code>close(restoreFocus?)</code> and <code>toggle(event)</code> expose\nexplicit controls. Selection owners call <code>MenuCascadeService.closeAll()</code> after activating an action; this preserves parent disclosure clicks in recursive menus.</p>\n<p>Native trigger semantics supply Enter/Space. Arrow towards the menu and Up/Down open it with focus. Up/Down/Home/End navigate within an open menu;\nEscape/opposite arrow dismiss one layer, and Tab is trapped inside its surface. Click outside dismisses the entire path, including search-pinned menus. Hover\nclose has a short pointer-crossing delay and retains focused descendants. Cascades reuse the shared origin tracker&#39;s native CSS anchoring, refreshing dependent\ndescendants on geometry changes and using measured positions only as a fallback. Clipped or offscreen origins close their branch. Overlays, traps, listeners,\nsubscriptions, and timers are cleaned up on destruction. The trigger honors <code>bxOverlayContext</code> for top-layer positioning, as dropdowns and context menus do;\norigins inside dialogs and existing top-layer overlays retain that context. Opening another branch closes siblings, and nested menus inherit live theme state.\nSurfaces use the ordinary opaque <code>bx-menu</code> appearance, without added motion or glass effects.</p>\n<p>The <a href="components/top-nav">top-navigation demo</a> at <code>/components/top-nav</code> demonstrates owner-coordinated navigation panels. Menu\nwidth and scroll constraints belong to the owner. Side navigation browses nested lists inside its own panel.</p>\n<p><code>bx-menu</code> accepts <code>--bx-menu-min-width</code> (default <code>12rem</code>). Constrained submenu owners set it to <code>0</code>, use border-box sizing, and reserve their vertical scrollbar\ngutter.</p>\n<p><code>menuManual: true</code> lets an owner coordinate one overlay for several disclosure controls. Automatic click, pointer, and trigger-key handling and the directive&#39;s\nhost ARIA attributes are omitted; the owner supplies its visible controls and accessible semantics and calls <code>open()</code>/<code>close()</code>. <code>open(focus?, origin?)</code>\noptionally supplies the actual positioning origin for that opening, defaulting to <code>menuOrigin</code> and then the host. Overlay keyboard dismissal, focus trapping,\noutside-click handling, theme inheritance, and origin tracking remain shared. Top navigation uses this mode for its shared submenu panel.</p>\n<p><code>menuPlacement</code> optionally selects the existing dropdown placement strategy (<code>top</code>, <code>bottom</code>, <code>left</code>, or <code>right</code>). Omitting it retains physical side-aligned\nsubmenu positioning. <code>TopNav</code> uses <code>bottom</code> for its shared panel. The shared tracker, top-layer context, focus handling, outside-click dismissal, and clipping\nbehavior are unchanged.</p>\n<p><code>navigateMenuKey(event, menu, options?)</code> also accepts <code>IMenuKeyboardOptions</code>: vertical Up/Down navigation remains the default; horizontal orientation uses\nLeft/Right with optional RTL direction and a roving tab stop. This supports the top navigation menubar without introducing a separate keyboard implementation.</p>\n<p><code>menuClosing</code> fires before DOM detachment (after the overlay enters its closing path), allowing owners to retain current scroll/focus context. <code>menuClosed</code>\nstill fires after cleanup.</p>\n',
  'projects/blocks/primitives/directives/overlay-context/README.md':
    '<h1>Overlay context</h1>\n<p>Choose the overlay-hosting policy inherited by nested dropdowns, popovers, and other context-aware overlays.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxOverlayContextDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Add the directive to the consuming standalone component&#39;s imports.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">section</span> [<span class="hljs-attr">bxOverlayContext</span>]=<span class="hljs-string">&quot;{ useTopLayer: true }&quot;</span>&gt;</span>\n    <span class="hljs-comment">&lt;!-- Context-aware overlay triggers go here. --&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">section</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>bxOverlayContext</code> accepts <code>IBxOverlayContext</code> and defaults to <code>{}</code>. Its optional <code>useTopLayer</code> property selects browser top-layer hosting when supported by the\nowning overlay. Omission leaves the overlay&#39;s default policy in effect. Advanced integrations can inject <code>BX_OVERLAY_CONTEXT</code> to read the nearest context.</p>\n<h2>Appearance and customization</h2>\n<p>The context controls hosting, not presentation. Configure appearance through the owning overlay&#39;s inputs and shared Blocks theme.</p>\n<h2>Behavior and accessibility</h2>\n<p>Nested consumers, including tooltips, inherit the nearest provided context. SidePanel provides a top-layer context automatically so floating controls escape its\nclipping surface without component-specific z-index overrides. The owning overlay retains responsibility for focus, keyboard dismissal, positioning, and\ncleanup.</p>\n<h2>Playground</h2>\n<p>See <code>/components/dropdown</code> and <code>/components/popover</code> for overlay interactions.</p>\n',
  'projects/blocks/primitives/directives/popover/README.md':
    '<h1>Popover trigger</h1>\n<p>Import <code>PopoverDirective</code>, <code>Popover</code>, <code>IPopoverConfig</code> and optional <code>BX_POPOVER_DEFAULTS</code> from <code>@filip.mazev/blocks/primitives</code>.</p>\n<p>The directive owns positioning, focus, dismissal, dialog semantics and theme inheritance; the component supplies the visual surface. Use a native button trigger\nand a named dialog. See the <a href="components/popover">popover component guide</a> for working usage, API defaults, configuration, CSS variables and\naccessibility behavior.</p>\n<p>Playground: <code>/components/popover</code>.</p>\n<h2>Behavior and accessibility</h2>\n<p>Opening and closing share the effects runtime&#39;s restrained opacity/scale spring without modifying collision-aware overlay positioning. The scale origin follows\nthe opening side. Close reports closed state and makes the panel inert immediately, then releases it after exit; reopening and teardown invalidate stale\ncompletion. Reduced motion skips spatial movement. Existing focus restoration, Escape, outside-click and nested-overlay policies remain authoritative. Inspect\n<code>/components/popover</code>.</p>\n',
  'projects/blocks/primitives/directives/resize-handle/README.md':
    '<h1>Resize handle</h1>\n<p><code>ResizeHandleDirective</code> supplies a reusable, focusable resize separator. It adjusts an application-owned numeric size from pointer dragging or the keyboard,\nwithout positioning elements, applying dimensions to targets, or owning table/list/panel data.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ResizeHandleDirective</span>, <span class="hljs-keyword">type</span> <span class="hljs-title class_">IResizeHandleEvent</span>, <span class="hljs-keyword">type</span> <span class="hljs-title class_">ResizeHandleEdge</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Add the standalone directive to the consuming component&#39;s imports.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">div</span> #<span class="hljs-attr">container</span> <span class="hljs-attr">class</span>=<span class="hljs-string">&quot;workspace&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">section</span> #<span class="hljs-attr">surface</span> [<span class="hljs-attr">style.width.px</span>]=<span class="hljs-string">&quot;width()&quot;</span>&gt;</span>\n        <span class="hljs-comment">&lt;!-- Content --&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">div</span>\n            <span class="hljs-attr">bxResizeHandle</span>\n            <span class="hljs-attr">resizeEdge</span>=<span class="hljs-string">&quot;right&quot;</span>\n            <span class="hljs-attr">resizeLabel</span>=<span class="hljs-string">&quot;Resize workspace width&quot;</span>\n            [<span class="hljs-attr">resizeTarget</span>]=<span class="hljs-string">&quot;surface&quot;</span>\n            [<span class="hljs-attr">resizeContainer</span>]=<span class="hljs-string">&quot;container&quot;</span>\n            [(<span class="hljs-attr">resizeValue</span>)]=<span class="hljs-string">&quot;width&quot;</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">section</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span></code></pre>\n<p><code>width</code> is a writable numeric signal. Position and style the handle on the appropriate physical edge. A width handle usually spans the surface height; a height\nhandle spans its width. Use a reachable pointer/touch target and a visible focus indicator. Use <code>resizeEdge=&quot;top&quot;</code> or <code>&quot;bottom&quot;</code> with a height model for rows or\nvertically stacked regions; <code>&quot;left&quot;</code> and <code>&quot;right&quot;</code> adjust width for columns or side-by-side regions.</p>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Member</th>\n<th>Default</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>resizeValue</code> / <code>resizeValueChange</code></td>\n<td><code>0</code></td>\n<td>Owner-controlled size in CSS pixels; never writes target styles</td>\n</tr>\n<tr>\n<td><code>resizeEdge</code></td>\n<td><code>&#39;right&#39;</code></td>\n<td>Physical left/right width edge or top/bottom height edge</td>\n</tr>\n<tr>\n<td><code>resizeTarget</code></td>\n<td><code>undefined</code></td>\n<td>Optional element providing the actual rendered size at gesture start</td>\n</tr>\n<tr>\n<td><code>resizeContainer</code></td>\n<td>Target parent, then handle parent</td>\n<td>Available containing width/height for bounds</td>\n</tr>\n<tr>\n<td><code>resizeActivityContainer</code></td>\n<td>Bounds container</td>\n<td>Optional pointer-activity region, independent of portal geometry</td>\n</tr>\n<tr>\n<td><code>resizeMinSize</code></td>\n<td>30% of original</td>\n<td>Optional explicit pixel minimum; shrink prevention takes precedence</td>\n</tr>\n<tr>\n<td><code>resizeMaxSize</code></td>\n<td>50% of container</td>\n<td>Optional explicit pixel maximum; never exceeds available container size</td>\n</tr>\n<tr>\n<td><code>resizeInitialSize</code></td>\n<td>First gesture&#39;s rendered size</td>\n<td>Optional explicit reference for relative minimums and shrink prevention</td>\n</tr>\n<tr>\n<td><code>resizeDisableShrink</code></td>\n<td><code>true</code></td>\n<td>Prevent sizes below the original; enlarged sizes can return to the original</td>\n</tr>\n<tr>\n<td><code>resizeDisabled</code></td>\n<td><code>false</code></td>\n<td>Prevent interaction and cancel an active gesture</td>\n</tr>\n<tr>\n<td><code>resizeLabel</code></td>\n<td><code>&#39;Resize&#39;</code></td>\n<td>Accessible <code>ResolvableText</code> name, resolved reactively through optional <code>BX_I18N</code></td>\n</tr>\n<tr>\n<td><code>resizeControls</code></td>\n<td>Target ID when available</td>\n<td>Controlled element&#39;s ID for <code>aria-controls</code></td>\n</tr>\n<tr>\n<td><code>resizeStep</code></td>\n<td><code>10</code></td>\n<td>Keyboard increment in CSS pixels; Shift multiplies it by five</td>\n</tr>\n<tr>\n<td><code>resizeIdleDelay</code></td>\n<td><code>2000</code></td>\n<td>Milliseconds before the idle grip fades; zero keeps it revealed</td>\n</tr>\n<tr>\n<td><code>indicatorVisible()</code></td>\n<td>Computed</td>\n<td>Recent container pointer activity or an active gesture; exposed as <code>.bx-resize-visible</code></td>\n</tr>\n<tr>\n<td><code>resizing()</code></td>\n<td><code>false</code></td>\n<td>Read-only pointer/keyboard gesture state for suspending owner transitions</td>\n</tr>\n<tr>\n<td><code>minSize()</code> / <code>maxSize()</code></td>\n<td>Computed</td>\n<td>Effective pixel bounds, including available container size</td>\n</tr>\n<tr>\n<td><code>resizeStart</code> / <code>resizeEnd</code></td>\n<td>Events</td>\n<td><code>IResizeHandleEvent</code>: current/start size, source, and cancellation state</td>\n</tr>\n</tbody></table>\n<p>The reference size is captured once at the first gesture unless <code>resizeInitialSize</code> is supplied. Changing between width and height axes resets the implicit\nreference. Width/height are measured from the selected physical axis; the owner can set different explicit limits when changing axes.</p>\n<p>By default shrinking below the original is disabled, so the effective minimum is the original size. To permit shrinking to the default 30% floor, set\n<code>[resizeDisableShrink]=&quot;false&quot;</code>. Explicit minimum/maximum values replace the relative defaults. A smaller available container always wins over conflicting\nminimum constraints. Container resizing updates bounds through <code>ResizeObserver</code>; the directive constrains emitted values rather than changing application-owned\nsizes during unrelated layout changes.</p>\n<h2>Appearance and customization</h2>\n<p>The directive supplies separator semantics, cursor, pointer capture, and touch/selection behavior. It creates no markup or surface. Style its host using Blocks\nsemantic tokens; <code>.bx-resizing</code> marks active gestures. Layout owners should suspend width/height transitions while <code>resizing()</code> is true. The directive never\nintroduces a theme, fetches data, or manipulates table internals.</p>\n<p>For the shared presentation used by SidePanel and the standalone demo, import <code>core/styles/helpers</code> and include <code>resize-grip</code> on the positioned handle. It uses\na compact 8 × 24px pill with three dots. Hovering or dragging replaces the dots with a 4px rail running along the resized edge, inset by shared spacing 2 at\nboth ends so its pill-shaped caps remain visible. It uses the same background color as the dot grip. Top/bottom handles rotate the grip and run horizontally.\nKeep the host&#39;s hit area at least 24px; the visual grip does not determine pointer target size.</p>\n<p>The idle grip fades after <code>resizeIdleDelay</code> milliseconds without pointer activity in <code>resizeActivityContainer</code> (or the bounds container). Movement reveals it\nagain. Hover, focus, and active resizing retain a visible edge. Coarse-pointer/touch and forced-color modes keep a discovery grip visible. <code>BxA11yService</code> and\nthe system reduced-motion preference suppress fading. Activity listeners run outside Angular and timers/listeners are released when disabled, reconnected, or\ndestroyed.</p>\n<p>Customize <code>--bx-resize-rail-color</code>, <code>--bx-resize-grip-background</code>, <code>--bx-resize-grip-color</code>, <code>--bx-resize-grip-border</code>, and <code>--bx-resize-grip-duration</code> through\nthe shared semantic theme.</p>\n<h2>Behavior and accessibility</h2>\n<p>The separator exposes orientation, current value, bounds, accessible name, and controlled surface. Left/right width handles are vertical separators; top/bottom\nheight handles are horizontal separators. Native pointer events support mouse, pen, and touch. Pointer moves are frame-coalesced, with the final position\ncommitted before completion. Pointer capture/document listeners retain the gesture outside the original hit area. Selection and cursor styles are restored on\ncompletion, cancellation, disabling, loss of capture/window focus, and destruction.</p>\n<p>Arrow keys move the selected physical edge by <code>resizeStep</code>; Shift uses five times that step. Home and End select the effective minimum/maximum. Keyboard\ngestures end on key release or blur. Escape cancels the current gesture and restores its starting size before any surrounding overlay handles Escape. Destroyed\nhandles release listeners and styles without emitting late events. Browser geometry starts after rendering, keeping server rendering safe.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/resize-handle</code> for all four edges, default relative bounds, explicit pixel limits, shrink prevention, keyboard resizing, and event feedback.\n<code>/components/side-panel</code> demonstrates width-model integration. <code>/icons</code> enables resizing only on Filters.</p>\n',
  'projects/blocks/primitives/directives/side-panel-banner/README.md':
    '<h1>Side panel banner slot</h1>\n<p>Projects persistent banner content into <a href="components/side-panel">SidePanel</a>.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SidePanelBannerDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Import the standalone slot directive together with <code>SidePanel</code>.</p>\n<h2>Usage</h2>\n<p>Apply <code>bxSidePanelBanner</code> to projected content inside <code>bx-side-panel</code>.</p>\n<h2>API</h2>\n<p>The marker has no inputs or outputs. Its presence controls whether the owning panel reserves section space.</p>\n<h2>Appearance and customization</h2>\n<p>Use the owning panel&#39;s CSS variables and Blocks semantic tokens.</p>\n<h2>Behavior and accessibility</h2>\n<p>Content stays mounted when closed. Include a meaningful heading or keyboard-accessible actions as appropriate.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/side-panel</code>.</p>\n',
  'projects/blocks/primitives/directives/side-panel-footer/README.md':
    '<h1>Side panel footer slot</h1>\n<p>Projects persistent footer content into <a href="components/side-panel">SidePanel</a>.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SidePanelFooterDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Import the standalone slot directive together with <code>SidePanel</code>.</p>\n<h2>Usage</h2>\n<p>Apply <code>bxSidePanelFooter</code> to projected content inside <code>bx-side-panel</code>.</p>\n<h2>API</h2>\n<p>The marker has no inputs or outputs. Its presence controls whether the owning panel reserves section space.</p>\n<h2>Appearance and customization</h2>\n<p>Use the owning panel&#39;s CSS variables and Blocks semantic tokens.</p>\n<h2>Behavior and accessibility</h2>\n<p>Content stays mounted when closed. Include a meaningful heading or keyboard-accessible actions as appropriate.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/side-panel</code>.</p>\n',
  'projects/blocks/primitives/directives/side-panel-header/README.md':
    '<h1>Side panel header slot</h1>\n<p>Projects persistent header content into <a href="components/side-panel">SidePanel</a>.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SidePanelHeaderDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Import the standalone slot directive together with <code>SidePanel</code>.</p>\n<h2>Usage</h2>\n<p>Apply <code>bxSidePanelHeader</code> to projected content inside <code>bx-side-panel</code>.</p>\n<h2>API</h2>\n<p>The marker has no inputs or outputs. Its presence controls whether the owning panel reserves section space.</p>\n<h2>Appearance and customization</h2>\n<p>The owning panel uses the shared modal-banner title and close-control styling. Reset a projected heading&#39;s margin to zero and use <code>font: inherit</code> for the shared\ntitle typography. Set the panel&#39;s optional <code>headerIcon: IIconData</code> for a leading icon with configurable size, semantic color, background, and stroke.</p>\n<h2>Behavior and accessibility</h2>\n<p>Content stays mounted when closed. Include a meaningful heading or keyboard-accessible actions as appropriate.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/side-panel</code>.</p>\n',
  'projects/blocks/primitives/directives/tab-content/README.md':
    '<h1>Lazy tab content</h1>\n<p>Declare a tab panel as a template so its contents are instantiated only while that tab is selected.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Tab</span>, <span class="hljs-title class_">TabContentDirective</span>, <span class="hljs-title class_">Tabs</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Add these declarations to the consuming standalone component&#39;s imports.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-tabs</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-tab</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Summary&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;summary&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxTabContent</span>&gt;</span>\n            <span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Summary content is created when this tab is active.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span>\n        <span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-tab</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-tab</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Details&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;details&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> <span class="hljs-attr">bxTabContent</span>&gt;</span>\n            <span class="hljs-tag">&lt;<span class="hljs-name">p</span>&gt;</span>Details content is created when this tab is active.<span class="hljs-tag">&lt;/<span class="hljs-name">p</span>&gt;</span>\n        <span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-tab</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-tabs</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>TabContentDirective</code> selects <code>ng-template[bxTabContent]</code>. Its readonly <code>templateRef</code> exposes the captured <code>TemplateRef&lt;unknown&gt;</code> to the owning <code>Tab</code>.</p>\n<h2>Appearance and customization</h2>\n<p>Style the projected content normally; the directive adds no wrapper or visual treatment. Configure the tab strip through <code>Tabs</code> and <code>Tab</code>.</p>\n<h2>Behavior and accessibility</h2>\n<p>Switching tabs destroys the inactive template&#39;s view. Keep state outside that view when it must survive selection changes. <code>Tabs</code> supplies panel relationships\nand keyboard navigation; see the <a href="components/tabs">tabs guide</a>.</p>\n<h2>Playground</h2>\n<p>Visit <code>/components/tabs</code>.</p>\n',
  'projects/blocks/primitives/directives/tooltip/README.md':
    '<h1>Tooltip trigger</h1>\n<p>Connects a help surface to a trigger using the overlay positioning system.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">TooltipDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">bxTooltip</span>=<span class="hljs-string">&quot;Saves this project&quot;</span> <span class="hljs-attr">placement</span>=<span class="hljs-string">&quot;top&quot;</span>&gt;</span>Save<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p><code>bxTooltip</code>: required text or translation key. <code>placement</code>: top, bottom, left, right, and supported aligned placements. <code>show()</code> and <code>hide()</code> expose explicit\nlifecycle control.</p>\n<p>Changing the text updates an open tooltip. Empty text dismisses it; restoring text while hovered or keyboard-focused reveals it again. This supports labels that\nonly need a tooltip while truncated.</p>\n<p>Use the shared <a href="components/truncate">TruncateDirective</a> for ellipsis and reactive truncation detection instead of duplicating element-size observers. Pass\n<code>resolvedText | bxTruncatedText: overflow.truncated()</code> to <code>bxTooltip</code> using the public <code>TruncatedTextPipe</code>; the owner supplies an appropriate focus target and\nvisible focus styling.</p>\n<p><code>bxTooltipHover</code> defaults to <code>true</code>. Set it to <code>false</code> to keep the keyboard description while nested content supplies its own pointer tooltip, such as an\noverflow tag within a select trigger.</p>\n<p><code>bxTooltipTouch</code> defaults to <code>&#39;none&#39;</code>: normal touch taps activate the control without showing its tooltip. Set it to <code>&#39;longpress&#39;</code> for an optional\ntouch-and-hold hint, or <code>&#39;tap&#39;</code> on a dedicated information button that has no other action.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;button&quot;</span> <span class="hljs-attr">bxTooltip</span>=<span class="hljs-string">&quot;Appearance settings apply to all components&quot;</span> <span class="hljs-attr">bxTooltipTouch</span>=<span class="hljs-string">&quot;tap&quot;</span> <span class="hljs-attr">aria-label</span>=<span class="hljs-string">&quot;More information&quot;</span>&gt;</span>ⓘ<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;button&quot;</span> <span class="hljs-attr">bxTooltip</span>=<span class="hljs-string">&quot;Optional extra context&quot;</span> <span class="hljs-attr">bxTooltipTouch</span>=<span class="hljs-string">&quot;longpress&quot;</span>&gt;</span>Hold for a hint<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Keep trigger text meaningful without its tooltip. Use short, non-interactive text; put interactive help in a menu or dialog.</p>\n<p>Tooltips open on mouse hover and keyboard focus. Touch focus and compatibility mouse events do not show ordinary tooltips. Screen-reader descriptions remain\navailable while the visual tooltip is hidden, and existing <code>aria-describedby</code> references are preserved. Supply an accessible label independently for icon-only\ncontrols.</p>\n<p>Optional long press opens after 500 ms. Moving more than 10 CSS pixels, scrolling, another finger, cancellation, or releasing early cancels it. Releasing after\na successful hold does not click the control; the hint dismisses after 1.5 seconds, or on another press or scrolling. Editable controls and existing text\nselections keep their native behavior. For dedicated non-selectable hold targets, apply <code>user-select: none</code> and <code>-webkit-touch-callout: none</code> in the target&#39;s\nstyles.</p>\n<p>Long-press hints yield to a <code>bxContextMenu</code> directive on the trigger or an ancestor. Dedicated tap help remains available. Avoid assigning multiple hold\ngestures to one target.</p>\n<p>Tap mode is intended for dedicated help buttons, including the built-in form-field information buttons. Tap again, tap elsewhere, scroll, or press Escape to\ndismiss the help. Use a separate popover or dialog for interactive or essential explanations rather than hiding them in a tooltip.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/tooltip-directive</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/primitives/directives/truncate/README.md':
    '<h1>Truncated text</h1>\n<p>Shared single-line ellipsis styling, reactive overflow detection, and conditional text selection. <code>TruncateDirective</code> measures the rendered element.\n<code>TruncatedTextPipe</code> and <code>truncatedText()</code> use that measured state for tooltips or application-owned feedback. The pure pipe does not poll the DOM or own\nobservers.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">TruncateDirective</span>, <span class="hljs-title class_">TruncatedTextPipe</span>, <span class="hljs-title class_">TooltipDirective</span>, truncatedText } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Add the standalone directive, pipe, and tooltip directive to the component&#39;s <code>imports</code> when composing a conditional tooltip. Include Blocks&#39; established\n<code>core/styles/index</code> global entry once; it supplies the shared <code>.bx-truncate</code> utility used by the directive.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">div</span> <span class="hljs-attr">class</span>=<span class="hljs-string">&quot;label-container&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">span</span>\n        <span class="hljs-attr">bxTruncate</span>\n        #<span class="hljs-attr">overflow</span>=<span class="hljs-string">&quot;bxTruncate&quot;</span>\n        [<span class="hljs-attr">bxTooltip</span>]=<span class="hljs-string">&quot;label() | bxTruncatedText: overflow.truncated()&quot;</span>\n        [<span class="hljs-attr">attr.tabindex</span>]=<span class="hljs-string">&quot;overflow.truncated() ? 0 : null&quot;</span>\n        <span class="hljs-attr">bxTooltipTouch</span>=<span class="hljs-string">&quot;longpress&quot;</span>\n        <span class="hljs-attr">placement</span>=<span class="hljs-string">&quot;top&quot;</span>\n        &gt;</span>{{ label() }}&lt;/span\n    &gt;\n<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span></code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { signal } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> label = <span class="hljs-title function_">signal</span>(<span class="hljs-string">&#x27;A long location name that may not fit&#x27;</span>);</code></pre>\n<p>Constrain the available width so overflow can occur:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="scss code example"><code class="hljs language-scss"><span class="hljs-selector-class">.label-container</span> {\n    <span class="hljs-attribute">inline-size</span>: <span class="hljs-number">14rem</span>;\n    <span class="hljs-attribute">max-inline-size</span>: <span class="hljs-number">100%</span>;\n    <span class="hljs-attribute">min-inline-size</span>: <span class="hljs-number">0</span>;\n}</code></pre>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>API</th>\n<th>Default</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>[bxTruncate]</code></td>\n<td><code>true</code></td>\n<td>Enables block display and the shared ellipsis utility. False removes the directive&#39;s styling/class and reports no truncation.</td>\n</tr>\n<tr>\n<td><code>#overflow=&quot;bxTruncate&quot;</code></td>\n<td>—</td>\n<td>Exports the directive for template access.</td>\n</tr>\n<tr>\n<td><code>truncated()</code></td>\n<td><code>false</code></td>\n<td>Readonly signal indicating overflow of the rendered content box. Remains false during server rendering.</td>\n</tr>\n<tr>\n<td><code>text()</code></td>\n<td><code>&#39;&#39;</code></td>\n<td>Readonly signal with current DOM text or a native input&#39;s value/placeholder, refreshed after rendering. Useful for projected content.</td>\n</tr>\n<tr>\n<td><code>truncatedChange</code></td>\n<td>—</td>\n<td>Boolean event emitted when the measured state changes.</td>\n</tr>\n<tr>\n<td><code>refresh()</code></td>\n<td>—</td>\n<td>Immediately rechecks after an application-owned style or layout change outside normal Angular rendering. Safe before rendering or after destruction.</td>\n</tr>\n</tbody></table>\n<h3>Public pipe and helper</h3>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-comment">&lt;!-- Empty text disables the existing tooltip when content fits or the feature is off. --&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">span</span> <span class="hljs-attr">bxTruncate</span> #<span class="hljs-attr">overflow</span>=<span class="hljs-string">&quot;bxTruncate&quot;</span> [<span class="hljs-attr">bxTooltip</span>]=<span class="hljs-string">&quot;label() | bxTruncatedText: overflow.truncated(): automaticTooltips()&quot;</span>&gt;</span>{{ label() }}<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span></code></pre>\n<p><code>bxTruncatedText</code> accepts text, the measured boolean, and an optional enabled boolean (default true). It returns the original string or translation-key object\nwhen both booleans are true, otherwise an empty string. Null and undefined text become empty strings. It preserves <code>ResolvableText</code> for the existing translation\nadapter.</p>\n<p>The exported <code>truncatedText(text, truncated, enabled = true)</code> helper provides the same behavior in TypeScript. Read the directive signals directly when custom\nbehavior is more useful:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { computed, signal, viewChild } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">TruncateDirective</span>, truncatedText } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;\n\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> overflow = <span class="hljs-title function_">viewChild</span>(<span class="hljs-title class_">TruncateDirective</span>);\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> label = <span class="hljs-title function_">signal</span>(<span class="hljs-string">&#x27;A long label&#x27;</span>);\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> automaticTooltips = <span class="hljs-title function_">signal</span>(<span class="hljs-literal">true</span>);\n<span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> customFeedback = <span class="hljs-title function_">computed</span>(<span class="hljs-function">() =&gt;</span>\n  <span class="hljs-title function_">truncatedText</span>(<span class="hljs-variable language_">this</span>.<span class="hljs-title function_">label</span>(), <span class="hljs-variable language_">this</span>.<span class="hljs-title function_">overflow</span>()?.<span class="hljs-title function_">truncated</span>() ?? <span class="hljs-literal">false</span>, <span class="hljs-variable language_">this</span>.<span class="hljs-title function_">automaticTooltips</span>())\n);</code></pre>\n<p>The pipe is pure: pass the current <code>truncated()</code> boolean rather than an element or directive object. This lets Angular update its result when measurement\nchanges.</p>\n<h3>Disable automatic tooltips without disabling truncation</h3>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-tag</span> [<span class="hljs-attr">text</span>]=<span class="hljs-string">&quot;label()&quot;</span> [<span class="hljs-attr">tooltipOnTruncate</span>]=<span class="hljs-string">&quot;false&quot;</span> <span class="hljs-attr">tooltip</span>=<span class="hljs-string">&quot;My application description&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-menu-item</span> [<span class="hljs-attr">label</span>]=<span class="hljs-string">&quot;label()&quot;</span> [<span class="hljs-attr">tooltipOnTruncate</span>]=<span class="hljs-string">&quot;false&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-input-field</span> [<span class="hljs-attr">label</span>]=<span class="hljs-string">&quot;label()&quot;</span> [<span class="hljs-attr">tooltipOnTruncate</span>]=<span class="hljs-string">&quot;false&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-search-input</span> [<span class="hljs-attr">value</span>]=<span class="hljs-string">&quot;label()&quot;</span> [<span class="hljs-attr">tooltipOnTruncate</span>]=<span class="hljs-string">&quot;false&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-select</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Location&quot;</span> [<span class="hljs-attr">options</span>]=<span class="hljs-string">&quot;options()&quot;</span> [<span class="hljs-attr">tooltipOnTruncate</span>]=<span class="hljs-string">&quot;false&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">bx-multi-select</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Locations&quot;</span> [<span class="hljs-attr">options</span>]=<span class="hljs-string">&quot;options()&quot;</span> [<span class="hljs-attr">tooltipOnTruncate</span>]=<span class="hljs-string">&quot;false&quot;</span> /&gt;</span></code></pre>\n<p><code>tooltipOnTruncate</code> defaults to true. False suppresses the component&#39;s automatic ellipsis tooltip while retaining ellipsis and measurement, so an application\ncan attach its own tooltip. Explicit tag tooltip descriptions and overflow-tag lists are independent; they retain their existing contract.\n<code>ITagConfig.tooltipOnTruncate</code> supplies a reusable tag default, and a direct tag input takes precedence.</p>\n<p>Forms resolve the instance input, then shared application settings, then true:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">FormSettingsService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> formSettingsService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">FormSettingsService</span>);\n\n<span class="hljs-comment">// For example, in application initialization:</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">formSettingsService</span>.<span class="hljs-title function_">update</span>({ <span class="hljs-attr">tooltipOnTruncate</span>: <span class="hljs-literal">false</span> });</code></pre>\n<p><code>[bxTruncate]=&quot;false&quot;</code> is a separate choice: it disables ellipsis itself on a custom text element. <code>tooltipOnTruncate</code> only disables automatic tooltips on an\nowning component.</p>\n<h2>Appearance and customization</h2>\n<p>The directive supplies ellipsis mechanics rather than a theme or a tooltip. Keep widths, typography, colors, borders, and focus styling on the owning control or\ncontainer using Blocks tokens. Apply it to the text element rather than a wrapper containing icons, counters, or actions. The shared <code>truncate-text</code> Sass mixin\nis available through <code>core/styles/helpers</code> for stylesheet-only integrations; the directive and existing components use that same utility.</p>\n<p>All existing library ellipsis sites use the shared implementation: tag labels, menu-item content, floating input labels, search values/placeholders,\nselect/multiselect captions and values, and multiselect&#39;s full-selection measurement. Menu <code>wrapLabel</code> disables ellipsis through the same directive. The\nappearance preview&#39;s clipped status text also uses it. Custom select trigger templates keep application-owned presentation.</p>\n<h2>Behavior and accessibility</h2>\n<p>Resize and content observers, Angular render callbacks, viewport changes, and font loading refresh measurement. Checks are coalesced into animation frames.\nObservers, listeners, and pending frames are cleaned up on destruction; asynchronous font completion is guarded. Browser measurement starts after rendering.</p>\n<p>Native single-line input values are measured with their current font and inline padding, since their rendered values are not DOM text nodes. Regular text uses\nits content-box overflow metrics. Full-selection summary measurement uses a constrained, visually hidden copy of the text and the same directive.</p>\n<p>The complete text stays in the DOM for assistive technology. The directive does not add focusability, roles, action semantics, or text of its own. The owner\nprovides keyboard access and a visible focus indicator when a tooltip needs an independent focus target. Use the existing <code>TooltipDirective</code> for hover, keyboard\nfocus, touch-and-hold, overlay theming, positioning, and reduced-motion behavior. Passing an empty tooltip while text fits also removes its description and\ndismisses an open tooltip.</p>\n<p>Translation stays in the caller: resolve <code>ResolvableText</code> through <code>BX_I18N</code> in a computation that reads the adapter&#39;s version, then render and pass that same\nresolved string to the tooltip. Rendered language changes trigger new measurements.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/truncate</code> for the short pipe example, helper/custom logic, application defaults, opt-out examples, and interactive previews across tags,\nmenus, input fields, search, select and multiselect. Edit text, adjust width, enlarge typography, disable automatic tooltips, or supply a custom tag/text\ntooltip. <code>/components/tag</code> includes the same demo alongside tag customization.</p>\n<p>Previews use an aligned responsive card grid. Width changes affect each example inside its card; preview areas and caption space stay reserved. Wrapped content\nscrolls inside its preview rather than moving later examples.</p>\n',
  'projects/blocks/primitives/directives/virtual-item/README.md':
    '<h1>Virtual item template</h1>\n<p>Typed projection for <a href="components/virtual-collection">VirtualCollection</a>. The collection mounts only the item templates in its sliding window.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">VirtualCollection</span>, <span class="hljs-title class_">VirtualItemDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">bx-virtual-collection</span> #<span class="hljs-attr">collection</span> [<span class="hljs-attr">items</span>]=<span class="hljs-string">&quot;items()&quot;</span> [<span class="hljs-attr">trackBy</span>]=<span class="hljs-string">&quot;itemKey&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> [<span class="hljs-attr">bxVirtualItem</span>]=<span class="hljs-string">&quot;collection&quot;</span> <span class="hljs-attr">let-item</span> <span class="hljs-attr">let-index</span>=<span class="hljs-string">&quot;index&quot;</span>&gt;</span>{{ index + 1 }}. {{ item.label }}<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">bx-virtual-collection</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p>The required <code>bxVirtualItem</code> binding supplies its owning collection for generic type inference. <code>IVirtualItemContext&lt;T&gt;</code> exposes the item through <code>$implicit</code>,\nits zero-based <code>index</code>, and the supplied item <code>count</code>.</p>\n<h2>Appearance and customization</h2>\n<p>Use Blocks controls and semantic tokens inside the projected template. The collection owns row geometry and gap variables.</p>\n<h2>Behavior and accessibility</h2>\n<p>Keep application state outside temporary item views. Stable keys preserve anchoring; template-local state is recreated after unmounting. Label interactive\ncontrols and preserve ordinary keyboard behavior.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/virtual-collection</code>, <code>/icons</code>, or <code>/tokens</code>.</p>\n',
  'projects/blocks/toastr/README.md':
    '<h1>Toastr</h1>\n<p>Component-driven notifications with a bounded queue, typed custom content, semantic message helpers, progress, pause/resume, and swipe dismissal.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Toast</span>, <span class="hljs-title class_">ToastrService</span>, <span class="hljs-title class_">ToastrGlobalSettingsService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/toastr&#x27;</span>;</code></pre>\n<p>Follow the <a href="installation">package setup</a>. Toastr is a secondary entry point of <code>@filip.mazev/blocks</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ChangeDetectionStrategy</span>, <span class="hljs-title class_">Component</span>, inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Button</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ToastrService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/toastr&#x27;</span>;\n\n<span class="hljs-meta">@Component</span>({\n    <span class="hljs-attr">selector</span>: <span class="hljs-string">&#x27;app-save-notification&#x27;</span>,\n    <span class="hljs-attr">imports</span>: [<span class="hljs-title class_">Button</span>],\n    <span class="hljs-attr">template</span>: <span class="hljs-string">&#x27;&lt;button bx-button (click)=&quot;notify()&quot;&gt;Show success&lt;/button&gt;&#x27;</span>,\n    <span class="hljs-attr">changeDetection</span>: <span class="hljs-title class_">ChangeDetectionStrategy</span>.<span class="hljs-property">OnPush</span>\n})\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">SaveNotification</span> {\n    <span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> toastrService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ToastrService</span>);\n\n    <span class="hljs-keyword">protected</span> <span class="hljs-title function_">notify</span>(): <span class="hljs-built_in">void</span> {\n        <span class="hljs-variable language_">this</span>.<span class="hljs-property">toastrService</span>.<span class="hljs-title function_">queueSuccess</span>({ <span class="hljs-attr">title</span>: <span class="hljs-string">&#x27;Saved&#x27;</span>, <span class="hljs-attr">message</span>: <span class="hljs-string">&#x27;Your settings are up to date.&#x27;</span> });\n    }\n}</code></pre>\n<h3>Custom content</h3>\n<p>Create content in its own component file. The string payload keeps this example self-contained; place larger data interfaces in a dedicated <code>interfaces</code> folder.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ChangeDetectionStrategy</span>, <span class="hljs-title class_">Component</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Button</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Toast</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/toastr&#x27;</span>;\n\n<span class="hljs-meta">@Component</span>({\n    <span class="hljs-attr">selector</span>: <span class="hljs-string">&#x27;app-custom-toast&#x27;</span>,\n    <span class="hljs-attr">imports</span>: [<span class="hljs-title class_">Button</span>],\n    <span class="hljs-attr">template</span>: <span class="hljs-string">&#x27;&lt;p&gt;{{ data() }}&lt;/p&gt;&lt;button bx-button (click)=&quot;close()&quot;&gt;Dismiss&lt;/button&gt;&#x27;</span>,\n    <span class="hljs-attr">changeDetection</span>: <span class="hljs-title class_">ChangeDetectionStrategy</span>.<span class="hljs-property">OnPush</span>\n})\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">CustomToast</span> <span class="hljs-keyword">extends</span> <span class="hljs-title class_ inherited__">Toast</span>&lt;<span class="hljs-built_in">string</span>, <span class="hljs-literal">undefined</span>&gt; {}</code></pre>\n<p>Inside an application action with an injected <code>ToastrService</code> and <code>CustomToast</code> imported from its defining file:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">const</span> ref = <span class="hljs-variable language_">this</span>.<span class="hljs-property">toastrService</span>.<span class="hljs-title function_">queueToast</span>(<span class="hljs-title class_">CustomToast</span>, {\n    <span class="hljs-attr">data</span>: <span class="hljs-string">&#x27;The export is ready.&#x27;</span>,\n    <span class="hljs-attr">position</span>: <span class="hljs-string">&#x27;bottom-right&#x27;</span>,\n    <span class="hljs-attr">durationInMs</span>: <span class="hljs-number">5000</span>,\n    <span class="hljs-attr">swipeToDismiss</span>: <span class="hljs-literal">true</span>\n});\n\nref.<span class="hljs-property">afterClosed$</span>.<span class="hljs-title function_">subscribe</span>(<span class="hljs-function">() =&gt;</span> <span class="hljs-variable language_">console</span>.<span class="hljs-title function_">log</span>(<span class="hljs-string">&#x27;Notification closed&#x27;</span>));</code></pre>\n<h2>API</h2>\n<h3>Queue and references</h3>\n<p><code>queueInfo</code>, <code>queueSuccess</code>, <code>queueWarning</code>, and <code>queueDanger</code> accept <code>IQueueSimpleToastRequest</code> and return a typed <code>ToastRef</code>.\n<code>queueToast(ContentComponent, config?)</code> queues custom content. Excess requests wait until an open slot becomes available; <code>maxOpened</code> defaults to four across\npositions.</p>\n<p><code>Toast&lt;D, R&gt;</code> provides typed reactive <code>data()</code>, the <code>toast</code> reference, <code>onToastInit()</code>, and <code>close(result?)</code>. <code>ToastRef&lt;D, R&gt;</code> exposes <code>close(result?)</code>,\n<code>pause()</code>, <code>resume()</code>, reactive <code>config()</code> and <code>data()</code>, and <code>afterClosed$</code>, <code>onPause$</code>, and <code>onResume$</code> observables.</p>\n<h3>Live configuration patching</h3>\n<p><code>ToastRef.patch(patch: IToastPatch&lt;D&gt;): void</code> updates an existing queued or open notification. The returned reference and <code>this.toast</code> inside content share the\nsame state. It is also injectable as <code>inject&lt;ToastRef&lt;D, R&gt;&gt;(ToastRef)</code>. Read resolved settings with <code>config()</code>, content with <code>data()</code>, lifecycle with\n<code>state()</code>, and the current pause preference with <code>paused()</code>.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">const</span> ref = <span class="hljs-variable language_">this</span>.<span class="hljs-property">toastrService</span>.<span class="hljs-title function_">queueInfo</span>({\n    <span class="hljs-attr">title</span>: <span class="hljs-string">&#x27;File upload&#x27;</span>,\n    <span class="hljs-attr">message</span>: <span class="hljs-string">&#x27;Uploading your file…&#x27;</span>,\n    <span class="hljs-attr">icon</span>: { <span class="hljs-attr">name</span>: <span class="hljs-string">&#x27;upload&#x27;</span> },\n    <span class="hljs-attr">loading</span>: <span class="hljs-literal">true</span>,\n    <span class="hljs-attr">durationInMs</span>: <span class="hljs-number">0</span>\n});\n\n<span class="hljs-comment">// In your application&#x27;s successful request completion:</span>\nref.<span class="hljs-title function_">patch</span>({\n    <span class="hljs-attr">data</span>: { <span class="hljs-attr">message</span>: <span class="hljs-string">&#x27;Upload complete&#x27;</span>, <span class="hljs-attr">type</span>: <span class="hljs-string">&#x27;success&#x27;</span>, <span class="hljs-attr">icon</span>: { <span class="hljs-attr">name</span>: <span class="hljs-string">&#x27;check&#x27;</span> }, <span class="hljs-attr">loading</span>: <span class="hljs-literal">false</span> },\n    <span class="hljs-attr">closeButtonColor</span>: <span class="hljs-string">&#x27;text-success&#x27;</span>,\n    <span class="hljs-attr">progressBarColor</span>: <span class="hljs-string">&#x27;text-success&#x27;</span>,\n    <span class="hljs-attr">durationInMs</span>: <span class="hljs-number">4000</span>\n});</code></pre>\n<p>The same operation inside custom content is <code>this.toast.patch(...)</code>. For example, a component extending <code>Toast&lt;{ message: string }, undefined&gt;</code> can call\n<code>this.toast.patch({ data: { message: &#39;Updated from inside&#39; } })</code> and render <code>{{ data()?.message }}</code>. Define application data interfaces in their own files.</p>\n<table>\n<thead>\n<tr>\n<th>Patch property</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>data</code></td>\n<td>Shallow-merge plain-object members; replace arrays, primitives, and nonplain objects. Undefined members retain existing values.</td>\n</tr>\n<tr>\n<td><code>durationInMs</code></td>\n<td>Explicitly restart the lifetime in milliseconds, even when the number equals the previous value; zero disables automatic dismissal.</td>\n</tr>\n<tr>\n<td><code>showCloseButton</code>, <code>closeButtonColor</code></td>\n<td>Update dismissal presentation; null clears the color override.</td>\n</tr>\n<tr>\n<td><code>showProgressBar</code>, <code>progressBarColor</code></td>\n<td>Update progress visibility/color without resetting time; null clears the color override.</td>\n</tr>\n<tr>\n<td><code>wrapperClass</code></td>\n<td>Replace wrapper classes; null restores the default wrapper. Include <code>default-wrapper</code> when extending its presentation.</td>\n</tr>\n<tr>\n<td><code>hasDefaultBackground</code>, <code>glassiness</code>, <code>glassQuality</code></td>\n<td>Update the existing surface policy, subject to application and accessibility settings.</td>\n</tr>\n</tbody></table>\n<p>Undefined means no change. Null clears the optional presentation overrides listed above. Data nullability follows the declared <code>D</code> contract; simple-toast\n<code>title</code> and <code>icon</code> explicitly accept null to clear them. Nested application objects are replaced, not recursively merged. Supply complete initial data for\nrequired object members before applying partial data updates. Patches never mutate the original payload or perform application requests.</p>\n<p>Simple-toast data also accepts <code>icon</code>, <code>loading</code>, and <code>loadingLabel</code>. Loading replaces only the icon with the shared spinner; the normal icon and its backing\nretain their dimensions and return when loading becomes false. Explicit loading state without an icon reserves a default 24px area to avoid shifts. Icon size\nfollows <code>icon.size</code>; invalid sizes fall back to 24px. The optional accessible <code>loadingLabel</code> accepts <code>ResolvableText</code> and defaults to the shared <code>Loading</code>\nlabel. Loading does not pause the toast or extend its lifetime: configure <code>durationInMs: 0</code> when the notification must remain open during an operation.</p>\n<p>Changing semantic <code>type</code> updates simple-toast text, surface, and emission. Explicit close/progress colors remain independently configurable; patch them\nalongside the type when they should change together, as in the example above.</p>\n<h4>Lifetime, queue, and dismissal</h4>\n<p>Patching message, icon, appearance, or visibility preserves the remaining time. A duration patch resets timer and progress together. A paused toast stays\npaused, including when its duration is patched; resuming uses the new remaining lifetime. Hidden progress can be restored at the current remaining fraction.\nPause/resume calls are idempotent, and existing hover and swipe interactions continue to use the reference&#39;s pause state.</p>\n<p>Each notification retains its own configuration, remaining lifetime, pause state, and dismissal controller. Queue processing serializes mounting, including when\ncontent construction or initialization synchronously queues another notification. The current capacity and pause policy are rechecked before each mount.</p>\n<p>Queued patches do not promote a toast or start a timer. The queue mounts the latest configuration and starts the lifetime on display. Closing a queued reference\nremoves it without rendering. Patches during closing or after destruction are ignored; asynchronous completions cannot reopen it. Progress animations, timers,\nsubscriptions, and wrapper callbacks are released on destruction.</p>\n<p>Position, component type, mounting, animation, and swipe configuration remain opening-time options and are absent from <code>IToastPatch&lt;D&gt;</code>.</p>\n<h4>Reactive custom content and migration</h4>\n<p><code>Toast&lt;D, R&gt;.data</code> is now a <code>Signal&lt;D | undefined&gt;</code>. Replace <code>data.message</code> with <code>data()?.message</code> in templates and <code>this.data.message</code> with\n<code>this.data()?.message</code> in TypeScript. Use <code>computed()</code> to derive translated or formatted content. A one-time local copy of <code>data()</code> does not subscribe to future\npatches. <code>IToast&lt;D, R&gt;</code> now requires this signal contract and a read-only reference; custom implementations can inject <code>ToastRef</code> and expose <code>toast.data</code>.</p>\n<p>Replace <code>ref.config</code> with <code>ref.config()</code> and direct mutation with <code>ref.patch(...)</code>. Configuration and data snapshots must be treated as read-only. <code>TOAST_DATA</code>\nremains a nonreactive initialization snapshot for direct token consumers; migrate to <code>ToastRef.data</code> or the <code>Toast</code> base class to receive updates. References\nare created by <code>ToastrService</code>; the wrapper no longer replaces the reference&#39;s <code>close()</code> method during initialization.</p>\n<h3>Configuration</h3>\n<table>\n<thead>\n<tr>\n<th><code>IToastConfig&lt;D&gt;</code> property</th>\n<th>Default and purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>data</code></td>\n<td>Optional custom component payload.</td>\n</tr>\n<tr>\n<td><code>position</code></td>\n<td><code>top-right</code>; also top-left, top-center, bottom-left, bottom-center, bottom-right.</td>\n</tr>\n<tr>\n<td><code>durationInMs</code></td>\n<td><code>5000</code>; notification lifetime.</td>\n</tr>\n<tr>\n<td><code>swipeToDismiss</code></td>\n<td><code>true</code>; allow swipe dismissal.</td>\n</tr>\n<tr>\n<td><code>animate</code></td>\n<td><code>true</code>; reduced motion takes precedence.</td>\n</tr>\n<tr>\n<td><code>showCloseButton</code>, <code>showProgressBar</code></td>\n<td><code>true</code>; display the wrapper actions and progress.</td>\n</tr>\n<tr>\n<td><code>closeButtonColor</code>, <code>progressBarColor</code></td>\n<td><code>text-primary</code>; semantic colors.</td>\n</tr>\n<tr>\n<td><code>wrapperClass</code></td>\n<td>Optional wrapper class override.</td>\n</tr>\n<tr>\n<td><code>hasDefaultBackground</code></td>\n<td><code>true</code>; false also suppresses added glassiness.</td>\n</tr>\n<tr>\n<td><code>glassiness</code></td>\n<td><code>auto</code>; shared browser policy and accessibility settings still apply.</td>\n</tr>\n<tr>\n<td><code>glassQuality</code></td>\n<td><code>enhanced</code>; the application baseline and device budget take precedence.</td>\n</tr>\n</tbody></table>\n<p>Simple requests require <code>message</code> and accept optional <code>title</code>, both with <code>ResolvableText</code>, plus optional icon, loading, and accessible loading label. The simple\nhelper&#39;s progress option retains the existing spelling <code>showProgessBar</code>; custom toast configuration and global settings use <code>showProgressBar</code>.</p>\n<p><code>ToastrGlobalSettingsService.update(partial)</code> merges defaults without discarding unrelated settings. Per-toast configuration overrides these settings, followed\nby library defaults. It also exposes <code>maxOpened</code> for queue capacity.</p>\n<h2>Appearance and customization</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ToastrGlobalSettingsService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/toastr&#x27;</span>;\n\n<span class="hljs-keyword">const</span> toastrGlobalSettingsService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ToastrGlobalSettingsService</span>);\ntoastrGlobalSettingsService.<span class="hljs-title function_">update</span>({ <span class="hljs-attr">position</span>: <span class="hljs-string">&#x27;bottom-right&#x27;</span>, <span class="hljs-attr">maxOpened</span>: <span class="hljs-number">3</span>, <span class="hljs-attr">glassQuality</span>: <span class="hljs-string">&#x27;auto&#x27;</span> });</code></pre>\n<p>Toast wrappers use Blocks semantic colors, spacing, radius, shared lighting, and the application appearance. Custom content shares its containing surface.\n<code>ThemingService</code> updates mounted notifications when appearance changes. See the\n<a href="appearance">appearance guide</a> for rendering policy and opaque fallbacks.</p>\n<h2>Behavior and accessibility</h2>\n<p>The service and wrapper coordinate queue capacity, lifetime, progress, pause/resume, dismissal, and cleanup. Give users enough time to read messages and retain\nimportant outcomes outside transient notifications. Use an inline alert or modal when acknowledgment is required.</p>\n<p>Reduced motion suppresses movement while preserving state; reduced transparency and forced colors use opaque presentation. Simple message text accepts strings\nor translation keys through <code>BX_I18N</code>; custom components own translation, keyboard access, accessible names, and descriptions for their own content.</p>\n<h3>Motion and material response</h3>\n<p>Toasts use shorter 12px entrance travel, a restrained scale, and the shared fluid settling curve. Existing grid collapse coordinates neighboring stack movement\nwhen an item closes. Lifetime, pause/resume, semantic patches and close results remain independent of decorative motion. Live reduced motion removes travel and\nsettling. Existing progress-light and opaque material behavior remains in place. Inspect <code>/toastr</code> with loading-to-success/error patches and stacked closes.</p>\n<h2>Playground</h2>\n<p>Open <code>/toastr</code> for initial configuration, live content/type/icon/surface/progress updates, paused lifetime resets, a loading-to-success transition, and a\nqueued-patch example. Open <code>/components/toast-core</code> for custom content, and <code>/components/simple-toast</code> for semantic notifications.</p>\n',
  'projects/blocks/toastr/components/toast-core/README.md':
    '<h1>Toast core</h1>\n<p>The toast lifecycle host with progress, dismissal and content composition.</p>\n<p>Toast wrappers opt into enhanced glassiness on supported browsers. The default maximum of four open notifications bounds the extra surfaces. The\napplication-wide baseline, automatic device budget, reduced transparency and high contrast still take precedence. Reflections have a bounded capture area and\nthrottled invalidation; hidden receivers suspend work.</p>\n<p>Per-toast <code>IToastConfig</code> supports <code>glassiness</code> (<code>auto</code>, <code>off</code>, <code>on</code>), <code>glassQuality</code> (<code>auto</code>, <code>baseline</code>, <code>enhanced</code>). The same defaults can be set through\n<code>ToastrGlobalSettingsService.update()</code>. Simple toast content keeps its semantic foreground colors while its material provides the backing. An explicit\n<code>hasDefaultBackground: false</code> suppresses the added glassiness enhancement.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">const</span> toastrGlobalSettingsService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ToastrGlobalSettingsService</span>);\ntoastrGlobalSettingsService.<span class="hljs-title function_">update</span>({ <span class="hljs-attr">glassQuality</span>: <span class="hljs-string">&#x27;auto&#x27;</span> }); <span class="hljs-comment">// One refraction pass for selected toasts.</span>\ntoastrGlobalSettingsService.<span class="hljs-title function_">update</span>({ <span class="hljs-attr">glassiness</span>: <span class="hljs-string">&#x27;off&#x27;</span> }); <span class="hljs-comment">// Existing material and lighting.</span></code></pre>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ToastCore</span>, <span class="hljs-title class_">ToastrService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/toastr&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;notify()&quot;</span>&gt;</span>Show notification<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p>Use <code>ToastrService.queueToast(ContentComponent, config)</code> for custom content, or queueInfo, queueSuccess, queueWarning and queueDanger for common messages.\nConfig controls position, durationInMs, progress and close actions. <code>config()</code> and <code>toastRef</code> share the reference&#39;s reactive configuration. Use\n<code>ToastRef.patch()</code> to update data, lifetime, close/progress presentation, and the existing surface policy without replacing content. Duration patches reset time\nand progress, preserve pause state, and apply to queued toasts before display. See the\n<a href="toastr#live-configuration-patching">patch contract and migration</a>.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Create notifications through the service; the wrapper owns timers, pause/resume and cleanup. Keep important information available outside transient messages.\nThe playground’s toast page can show all four semantic intents.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/toast-core</code> for a working example and its current value or action result.</p>\n',
  'projects/blocks/toastr/components/views/simple-toast/README.md':
    '<h1>Simple toast</h1>\n<p>A notification with a semantic type, optional icon and title, and a required message.</p>\n<p>The toast wrapper uses enhanced glassiness on supported browsers, with shared translucency and accessibility preferences. Text retains its semantic foreground\nas the background scrolls; the material keeps a minimum tint and blur for readability. Progress and border lighting retain the notification type. Use toast\nconfiguration or global toast settings to select automatic detail, or disable glassiness.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SimpleToast</span>, <span class="hljs-title class_">ToastrService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/toastr&#x27;</span>;</code></pre>\n<p>Add the standalone component or directive to your component&#39;s <code>imports</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> (<span class="hljs-attr">click</span>)=<span class="hljs-string">&quot;notify()&quot;</span>&gt;</span>Show success<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span></code></pre>\n<h2>API</h2>\n<p>Use <code>toastrService.queueSuccess({ title: &quot;Saved&quot;, message: &quot;Your settings are up to date.&quot; })</code>. Equivalent methods queueInfo, queueWarning and queueDanger set\nthe semantic intent. Request fields include position, durationInMs, animate, showCloseButton and showProgessBar (existing API spelling), plus optional icon,\nloading, and loadingLabel.</p>\n<p>The returned <code>ToastRef</code> supports <code>patch({ data: { message, type, icon, loading } })</code>. Data is reactive through <code>data()</code>; title and icon accept null to clear\nthem. Icon loading preserves the configured icon and its dimensions and does not extend the lifetime. Use <code>durationInMs: 0</code> for a persistent operation\nnotification, then patch the completion text and a timed duration. See <a href="toastr#live-configuration-patching">live patching and lifetime behavior</a>.</p>\n<h2>Appearance</h2>\n<p>Appearance uses Blocks semantic colors, spacing, radius and motion tokens. Glass surfaces inherit the application configuration from <code>ThemingService</code>; adjusting\ntranslucency updates existing components and overlays. Content-only parts share their containing surface instead of adding another backdrop filter.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n<span class="hljs-comment">// Application-wide, including open overlays.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span> });\n<span class="hljs-comment">// Opaque presentation retains the same layout and component API.</span>\n<span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({ <span class="hljs-attr">reducedTransparency</span>: <span class="hljs-literal">true</span> });</code></pre>\n<p><code>BxA11yService</code> controls reduced motion; reduced transparency and forced colors receive opaque presentation. Glass is decorative and does not replace labels,\nfocus states, or semantic control states.</p>\n<h2>Behavior and accessibility</h2>\n<p>Write a concise message with a clear outcome. Use a modal or an inline message when acknowledgement or a long interaction is required. Simple toast content\nshares the parent toast glass surface.</p>\n<h2>Playground</h2>\n<p>Open <code>/components/simple-toast</code> for a working example and its current value or action result.</p>\n',
  'projects/playground/src/app/components/screens/appearance/README.md':
    '<h1>Blocks appearance</h1>\n<p>Glass is integrated into Blocks components and its existing theme engine. Surface colors, text, borders, radii and elevation come from Blocks tokens. Icons,\nlabels, validation messages and other structural content inherit their containing surface instead of adding redundant blurred boxes.</p>\n<p>The <code>@filip.mazev/blocks/effects/runtime</code> entry point shipped inside Blocks provides the same material and motion primitives without Angular, CDK or RxJS.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxSurfaceDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/effects&#x27;</span>;</code></pre>\n<p>Use the core service to configure the application and the standalone surface directive for custom Angular surfaces.</p>\n<h2>Usage</h2>\n<p>Use an Angular 22 compatible Node version (22.22.3+, 24.15+, or 26+):</p>\n<pre class="playground-code-block" tabindex="0" aria-label="sh code example"><code class="hljs language-sh">npm ci\nnpm start</code></pre>\n<p>Open <a href="http://localhost:8080">http://localhost:8080</a>. The component catalogue links each component to its own demonstration and README. <code>/appearance</code> provides application-wide material\ncontrols and spatial-lighting and fade demonstrations. <code>/icon-catalog</code> provides searchable, paginated icons.</p>\n<p>The playground defaults to Carbon / Cobalt (<code>#292a2d</code> / <code>#356fe8</code>) when no valid saved palette is present; Reset returns to Carbon / Cobalt.</p>\n<p>The appearance preview is a scrollable national-parks article with English copy and photos adapted from EcoProject24. Independent glass search, bookmark,\ncontents, and navigation controls stay over the article while its images and text scroll beneath them. Search filters the featured places, and the contents and\nnavigation controls jump within the preview. The opening image uses the original mountain photograph; responsive WebP copies up to 2400 pixels wide are loaded\neagerly, with smaller versions for narrow screens. The preview sits above a separate translucency card. A short scroll down and back plays once when the preview\ncomes into view, stops on interaction, and is skipped when reduced motion is enabled.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="sh code example"><code class="hljs language-sh">npm run build:playground\nnpm run build:blocks</code></pre>\n<p>Documentation is generated automatically before serving/building the playground. After editing a README while the development server is already running, run\n<code>npm run tools:build-docs</code> to regenerate its bundled content. Runtime documentation does not fetch Markdown files. Fenced README examples are highlighted during\ngeneration with the same highlight.js engine used by live usage examples and configurator file tabs. Code blocks follow the active light/dark syntax theme and\nsupport keyboard scrolling; short inline API names remain inline code.</p>\n<p>Keep Angular packages, CLI, builder and ng-packagr on major 22 with TypeScript 6. The checked-in lockfile preserves compatible versions. Runtime Markdown and\nMermaid dependencies are no longer needed by the playground. Do not mix Angular 21 tooling with Angular 22.</p>\n<p>The toolbar&#39;s <a href="studio">Theme Studio</a> edits shared colors, borders, corners, spacing and resting shadows while previewing any page.\nIt exports SCSS with a named built-in base and separate light/dark colors. Material and accessibility preferences remain on this screen; high contrast and\nforced colors suspend Studio overrides without erasing the draft.</p>\n<h2>API</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ThemingService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">Settings</span> {\n    <span class="hljs-keyword">readonly</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\n\n    <span class="hljs-title function_">setAppearance</span>(<span class="hljs-params"></span>) {\n        <span class="hljs-variable language_">this</span>.<span class="hljs-property">themingService</span>.<span class="hljs-title function_">setAppearance</span>({\n            <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span>,\n            <span class="hljs-attr">quality</span>: <span class="hljs-string">&#x27;auto&#x27;</span>\n        });\n    }\n}</code></pre>\n<p>There is no global semantic-emission setting. Interactive lights use the color of the active control or status item; passive edge cues sample the surrounding\nscene automatically. Neutral edges and restrained highlights define the material. Glass buttons follow the full translucency range; fields and filled actions\nretain their own legibility constraints.</p>\n<p><code>themingService.appearance()</code> is the current typed configuration; <code>themingService.resetAppearance()</code> restores defaults. Changes apply to existing components and\nopen overlays. <code>translucency</code> is 0–1, defaulting to the balanced midpoint of 0.5. It adjusts tint and blur together: the minimum is nearly clear with light\nblur, while the maximum caps tint near 72.5% to retain a glassy appearance. <code>reducedTransparency: true</code> supplies fully opaque surfaces and preserves the chosen\ntranslucency for when transparency is restored. The playground offers <code>auto</code> and <code>baseline</code> rendering. Reduced motion continues through <code>BxA11yService</code>; system\ntransparency and contrast preferences remain respected. Previously saved tint preferences migrate to translucency, and a saved solid preference becomes reduced\ntransparency.</p>\n<p>The global styles are required once. <code>ng add @filip.mazev/blocks</code> adds the distributed material stylesheet to the application build. For an existing\napplication, add <code>node_modules/@filip.mazev/blocks/effects/effects.css</code> to <code>angular.json</code> styles before the application stylesheet, or import\n<code>@filip.mazev/blocks/effects/effects.css</code> globally. Continue including the usual Blocks Sass theme once. The playground already does this.</p>\n<h3>Framework-independent API</h3>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { configureAppearance, mountSurface, mountGlassScene, createGlassTransition } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/effects/runtime&#x27;</span>;\n<span class="hljs-keyword">import</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/effects/effects.css&#x27;</span>;\n\n<span class="hljs-keyword">const</span> configuration = <span class="hljs-title function_">configureAppearance</span>(<span class="hljs-variable language_">document</span>.<span class="hljs-property">documentElement</span>, {\n    <span class="hljs-attr">translucency</span>: <span class="hljs-number">0.5</span>,\n    <span class="hljs-attr">quality</span>: <span class="hljs-string">&#x27;auto&#x27;</span>\n});\n<span class="hljs-keyword">const</span> surface = <span class="hljs-title function_">mountSurface</span>(button);\n<span class="hljs-keyword">const</span> scene = <span class="hljs-title function_">mountGlassScene</span>(container, {\n    <span class="hljs-attr">lights</span>: [{ <span class="hljs-attr">element</span>: lightMarker, <span class="hljs-attr">z</span>: <span class="hljs-number">180</span>, <span class="hljs-attr">intensity</span>: <span class="hljs-number">1</span>, <span class="hljs-attr">radius</span>: <span class="hljs-number">640</span> }],\n    <span class="hljs-attr">reflectors</span>: [{ <span class="hljs-attr">element</span>: foreground, <span class="hljs-attr">depth</span>: <span class="hljs-number">80</span>, <span class="hljs-attr">intensity</span>: <span class="hljs-number">0.3</span> }]\n});\n<span class="hljs-comment">// Mount and lay out the panel first.</span>\n<span class="hljs-keyword">const</span> panelSurface = <span class="hljs-title function_">mountSurface</span>(panel);\n<span class="hljs-keyword">const</span> transition = <span class="hljs-title function_">createGlassTransition</span>(button, panel);\n<span class="hljs-keyword">await</span> transition.<span class="hljs-title function_">enter</span>();\n<span class="hljs-comment">// Later: await transition.exit(), then remove the panel.</span>\n<span class="hljs-comment">// Call scene.refresh() after changing registered objects&#x27; position or appearance.</span>\n<span class="hljs-comment">// On teardown: transition.destroy(); panelSurface.destroy(); surface.destroy();</span>\n<span class="hljs-comment">// scene.destroy(); configuration.destroy();</span></code></pre>\n<p>Transition promises resolve to <code>finished</code> or <code>cancelled</code>. Always guard asynchronous panel removal against a subsequent reopening. Controllers expose\nupdate/refresh and destroy methods; dispose them with their owning view. The former transition export remains as a deprecated compatibility alias; new code uses\n<code>createGlassTransition</code>.</p>\n<p>The native example can be served without Angular:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="sh code example"><code class="hljs language-sh">npm run build:blocks\npython3 -m http.server 8081</code></pre>\n<p>Open <a href="http://localhost:8081/projects/blocks/effects/examples/">http://localhost:8081/projects/blocks/effects/examples/</a>.</p>\n<h2>Appearance and customization</h2>\n<h3>Palettes</h3>\n<p>Each palette combines two tonal families. Choose one under <strong>Palettes</strong> in Appearance; the two swatches show its anchors. The same palette supplies both light\nand dark appearances.</p>\n<table>\n<thead>\n<tr>\n<th>Palette</th>\n<th>Anchors</th>\n<th><code>ng add --theme</code> value</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Carbon / Cobalt</td>\n<td><code>#292a2d</code> / <code>#356fe8</code></td>\n<td><code>carbon-cobalt</code></td>\n</tr>\n<tr>\n<td>Azure / Ember</td>\n<td><code>#217eff</code> / <code>#d85a1a</code></td>\n<td><code>azure-ember</code></td>\n</tr>\n<tr>\n<td>Violet / Teal</td>\n<td><code>#6d00ff</code> / <code>#0d9488</code></td>\n<td><code>violet-teal</code></td>\n</tr>\n<tr>\n<td>Tangerine / Indigo</td>\n<td><code>#ff6900</code> / <code>#4f78f5</code></td>\n<td><code>tangerine-indigo</code></td>\n</tr>\n<tr>\n<td>Brick Rose / Cyan</td>\n<td><code>#b64a50</code> / <code>#0891b2</code></td>\n<td><code>brick-rose-cyan</code></td>\n</tr>\n<tr>\n<td>Lime / Violet</td>\n<td><code>#c4f53d</code> / <code>#6842a6</code></td>\n<td><code>lime-violet</code></td>\n</tr>\n<tr>\n<td>Cyberpunk</td>\n<td><code>#3e5669</code> / <code>#e6da00</code></td>\n<td><code>cyberpunk</code></td>\n</tr>\n</tbody></table>\n<p>Primary roles identify main actions, links and field focus. Accent roles identify checked checkboxes, radios and switches, slider progress, selected options and\nsupporting actions. This follows Material&#39;s use of distinct color roles for emphasis while keeping broad surfaces neutral. For example, <code>color=&quot;accent&quot;</code> selects\nthe second tone on buttons and tabs; <code>text-accent</code> follows it on icons. Documentation uses the primary role and Code Examples uses the accent role. Success,\nwarning, danger and information retain their status meanings across palettes.</p>\n<p>Canvas backgrounds stay neutral white or black, leaving application background styling to the consuming app. Cards, toolbars, navigation and default controls\nuse neutral white/black/gray surfaces. Explicit primary and accent actions retain their palette roles. Scrollbars use a solid primary shade. The playground&#39;s\nmaterial sample places both tones behind a shared glass surface. Cyberpunk retains yellow actions and blue-slate supporting controls over neutral surfaces.</p>\n<p>Carbon / Cobalt combines a deep neutral charcoal with a saturated cobalt-blue accent. Its dark appearance uses neutral off-white primary actions instead of a\npale colored tint. Azure / Ember pairs blue with burnt orange, while Brick Rose / Cyan pairs a muted rose-red with cyan. Their dark action shades are tuned\nindividually: Cobalt provides a clear blue accent, Ember stays orange, and Brick Rose stays deeper and more muted than the danger red. Status colors are\nindependent of these palette families.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">const</span> themingService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ThemingService</span>);\nthemingService.<span class="hljs-title function_">setPalette</span>(<span class="hljs-string">&#x27;violet-teal&#x27;</span>);\nthemingService.<span class="hljs-title function_">setApplicationTheme</span>(<span class="hljs-string">&#x27;dark&#x27;</span>);</code></pre>\n<p>Use the palette IDs above in <code>ThemingService.setPalette()</code> and <code>ng add --theme</code>. Sass exports follow the same names, such as <code>$carbon-cobalt-light-theme</code> and\n<code>$carbon-cobalt-dark-theme</code>. High contrast overrides both expressive roles with contrast-first black/white values.</p>\n<p>All light-mode accent fills use white text; semantic fill shades become darker where necessary to reach 4.5:1 contrast. Raw 500-level palette anchors and picker\nswatches stay unchanged. Other filled-role foregrounds prefer white when it passes, with dark text on brighter fills that require it. Brand/accent and secondary\ntext also retain contrast on their supported neutral and normal/hover/active surfaces in both modes. High-contrast palettes and explicit theme overrides remain\nsupported.</p>\n<h3>Glassiness and translucency</h3>\n<p>The <strong>Translucency</strong> slider controls tint and blur. It defaults to 50%; the preceding midpoint now falls around 70% on the slider, with both endpoints\npreserved. The classic material retains its clear minimum and caps tint near 72.5%; active refraction adds the stronger readability floor below. Use <strong>Reduce\ntransparency</strong> for opaque surfaces.</p>\n<p><strong>Glassiness</strong> is a per-element enhancement on supported browsers. Ordinary components keep their existing material. Select individual controls:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> <span class="hljs-attr">variant</span>=<span class="hljs-string">&quot;icon&quot;</span> <span class="hljs-attr">glassiness</span>=<span class="hljs-string">&quot;auto&quot;</span> <span class="hljs-attr">aria-label</span>=<span class="hljs-string">&quot;Bookmark&quot;</span>&gt;</span>…<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">section</span> <span class="hljs-attr">bxSurface</span> <span class="hljs-attr">bxSurfaceGlassiness</span>=<span class="hljs-string">&quot;auto&quot;</span>&gt;</span>…<span class="hljs-tag">&lt;/<span class="hljs-name">section</span>&gt;</span></code></pre>\n<p><code>themingService.setAppearance({ translucency: 0.5, glassiness: &#39;auto&#39; })</code> sets the shared scale and browser policy. It does not select every component. Off\ndisables selected glassiness; browser opt-in allows testing future support. Automatic uses one refraction pass on selected surfaces. Device budgets, baseline\nquality and accessibility preferences take precedence.</p>\n<p>Text, placeholders and icons keep their theme or component foreground colors while scrolling. Active refraction retains a default minimum of 72% tint for\nreadability, increasing to about 74.9% tint at the slider midpoint and 89% at maximum. Blur starts at 0.5px, reaches about 0.8px at the midpoint and 9.2px at\nmaximum, keeping low settings sharper. Active, selected and open-popup controls have a stronger 90% minimum backing, and existing component opacity constraints\ncan demand more. The sampler supplies decorative edge lighting; it never chooses text or icon colors. Custom material and foreground overrides remain\napplication-owned. See the <a href="components/surface#glassiness-and-translucency">effects README</a> for material variables and\nbrowser/accessibility fallbacks.</p>\n<p>The numeric <code>glassiness</code> API was renamed to <code>translucency</code>. The directive inputs are now <code>bxSurfaceTranslucency</code> and <code>bxSurfaceGlassiness</code>, and the scalar CSS\nvariable is <code>--bx-translucency</code>. Saved older preferences migrate automatically to the new names and curve.</p>\n<h3>Existing components and custom surfaces</h3>\n<p>Blocks components receive glass automatically. The <code>BxSurfaceDirective</code> remains useful for your own containers and local overrides:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">section</span> <span class="hljs-attr">bxSurface</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">button</span> <span class="hljs-attr">bx-button</span> [<span class="hljs-attr">bxDropdown</span>]=<span class="hljs-string">&quot;actions&quot;</span>&gt;</span>Actions<span class="hljs-tag">&lt;/<span class="hljs-name">button</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">section</span>&gt;</span>\n<span class="hljs-tag">&lt;<span class="hljs-name">ng-template</span> #<span class="hljs-attr">actions</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">bx-menu</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">bx-menu-item</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Edit&quot;</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-menu-item</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">bx-menu-item</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;Duplicate&quot;</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">bx-menu-item</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">bx-menu</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">ng-template</span>&gt;</span></code></pre>\n<p>Place custom surfaces on containers with measurable CSS boxes. Native replaced elements such as inputs and images need a wrapper for decoration; use the\ndedicated <code>SliderDirective</code> (<code>input[type=range][bxSlider]</code>) for native ranges; Blocks form components already provide appropriate wrappers. Nested surfaces\nretain tint and reflection while avoiding a second backdrop-filter pass.</p>\n<h3>Overlay fades</h3>\n<p>The engine fades the material surface itself in and out while preserving its full dimensions, blur, and translucency. The positioning pane remains at full\nopacity so it does not interrupt backdrop filtering. Reopening reverses from the current opacity. Dropdowns use <code>bxTransition=&quot;fade&quot;</code> by default; the former\n<code>emerge</code> value remains a compatibility alias.</p>\n<p>Dropdowns expose <code>#actions=&quot;bxDropdown&quot;</code>, <code>open()</code>, <code>close()</code>, <code>toggle()</code>, <code>isOpen()</code> and <code>state()</code>. The adapter keeps an exiting panel inert and disposes it\nafter motion settles, with revision guards for reopening. Focus and keyboard behavior remain native. No dragging or repositioning behavior was added in this\niteration.</p>\n<p>The Theme picker includes a <strong>Create a theme</strong> action. It opens the existing Theme Studio sidebar beside Appearance, retaining the current palette and draft.\nCustomize and preview here, then export the theme from Studio. The action does not navigate or reset existing changes.</p>\n<h2>Behavior and accessibility</h2>\n<p>Appearance updates propagate through the shared theme and effects services to mounted components and overlays. Reduced motion takes precedence over requested\nanimation. Reduced transparency, high contrast, and forced colors preserve opaque, readable presentation. Keep semantic labels, focus indicators, and control\nstate independent of decorative glass and lighting. Destroy custom runtime controllers with their owning view.</p>\n<h3>Lighting and rendering limits</h3>\n<p>Lighting uses a bounded spatial model: up to four explicit lights and four foreground/background reflection proxies per scene. Every mounted glass surface also\nsamples a few points around its edge and picks up subtle color from nearby visible CSS backgrounds, images, video and canvas. Paint order separates foreground\nfrom backdrop cues; depth and distance reduce their strength. Different sources retain localized edge colors, crossfading beneath existing semantic and explicit\nlights. Real CSS backdrop filtering continues to display the pixels behind a surface.</p>\n<p>These are deliberate optical approximations. Media sampling uses a small downscaled buffer at selected edge points; the engine does not capture arbitrary DOM\ninto a texture, ray trace the page, or infer a 3D scene. Refractive refraction and rim reflection use the browser&#39;s live backdrop pixels through SVG filters.\nRegister moving scene objects and call <code>scene.refresh()</code> when your application changes them; call <code>refreshGlassLighting(element)</code> after application-driven\nchanges around an automatically lit surface. Static scenes do no ongoing sampling. Layout changes are coalesced over 180 ms; visible live media shares the\nexisting adaptive polling loop and backs off when unchanged. Media pixels are cached and color-only changes reuse the existing edge positions without hit\ntesting. Hidden pages and reduced-motion receivers stop live media checks.</p>\n<p>Baseline uses blur, tint and directional lighting. Automatic adapts material detail and refraction to CSS capability, coarse-pointer devices, reduced-cost\ndevice signals and data-saving preference. Use Glassiness Off or Baseline when the added GPU cost is unsuitable. Reduced transparency, unsupported backdrop\nfilters and increased contrast provide opaque presentation.</p>\n<p>Input and scene observation are shared per document. Scene updates batch a bounded number of visible surfaces; geometry reads precede writes. Animation frames\nstop when springs settle. Background scrolling can still cause browser GPU work even while JavaScript is idle: measure the real target devices before choosing\nhigh blur or putting glass over frequently changing content.</p>\n<h2>Playground</h2>\n<p>The <code>/appearance</code> page separates color mode, surfaces, theme palettes, and accessibility. Light and Dark select an explicit mode. Auto follows live system\ncolor-scheme changes, including after a reload. Clickable Blocks cards choose the mode; their inert previews use Blocks components in the selected palette. The\nselected card uses the shared emissive highlight, and Auto joins its light/dark preview halves without inner corner rounding.</p>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts">themingService.<span class="hljs-title function_">setApplicationTheme</span>(<span class="hljs-string">&#x27;dark&#x27;</span>);\nthemingService.<span class="hljs-title function_">setApplicationTheme</span>(<span class="hljs-literal">null</span>); <span class="hljs-comment">// Follow the system appearance.</span></code></pre>\n<p>The Surfaces section places its Surface Appearance title beside the scrolling journal on wide layouts and above it on smaller screens. The padded pill slider\nsits below the demo, followed by its description; Reset restores surface preferences. Its Blocks Advanced settings disclosure contains rendering and glassiness\noptions. Automatic and Baseline are the available rendering choices. Rendering, glassiness, translucency and reduced transparency are saved together in\n<code>blocks-appearance</code> and restored on refresh. Opening this page normalizes previously saved rendering choices that are no longer offered to Automatic, preserving\nother appearance preferences. Baseline temporarily sets Glassiness to Off and disables all glassiness choices, including browser opt-in. Switching back to\nAutomatic restores the previous Automatic or browser opt-in policy; an explicitly chosen Off remains Off. <code>themingService.preferredGlassiness()</code> exposes the\nrequested policy while <code>themingService.appearance().glassiness</code> reflects the effective value. Theme palettes and accessibility preferences have independent\nsections; resetting surfaces changes only surface preferences.</p>\n<p>The top bar provides Appearance and Theme Studio actions; edited themes also expose a compact preview pause/resume action. On wide screens, selectable Blocks\ncards offer Light, Dark and Auto. On screens at the shared <code>sm</code> breakpoint or narrower, Light and Dark appear side by side with portrait previews and an\nAutomatic slide toggle below. Automatic highlights the currently active mode and follows system changes; choosing the other card disables Auto, while choosing\nthe already active card keeps it enabled. Turning Auto off preserves the current mode. Mode and palette preferences remain available on this page and persist\nacross refreshes.</p>\n<p>Open <code>/appearance</code> to adjust the live application preferences and preview the material over scrollable content. Use <code>/components</code> to inspect individual controls\nand their colocated API documentation. The playground screen, its template/styles, and this guide live together.</p>\n',
  'projects/playground/src/app/components/screens/appearance/appearance-mode-preview/README.md':
    '<h1>Appearance mode preview</h1>\n<p>An inert miniature of Blocks Card, Tag, Icon and ProgressBar for the playground&#39;s appearance choices.</p>\n<h2>Import and usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">AppearanceModePreview</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;./appearance-mode-preview/appearance-mode-preview&#x27;</span>;</code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">app-appearance-mode-preview</span> <span class="hljs-attr">mode</span>=<span class="hljs-string">&quot;light&quot;</span> /&gt;</span></code></pre>\n<h2>API and appearance</h2>\n<p><code>mode</code> is required and accepts <code>light</code> or <code>dark</code>. The miniature uses the selected palette&#39;s existing theme class, responds to palette/high-contrast changes, and\npreserves its own color mode. The parent combines two previews for Auto.</p>\n<h2>Accessibility and behavior</h2>\n<p>The preview is inert, hidden from assistive technology and contains no working actions. Its parent clickable Card owns the mode action and accessible label. It\nperforms no animated demonstration.</p>\n<h2>Playground</h2>\n<p><code>/appearance</code>, in the Light, Dark and Auto choices.</p>\n',
  'projects/playground/src/app/components/screens/home/README.md':
    '<h1>Playground home</h1>\n<p>Introduces Blocks with a short headline, two primary actions, a portfolio homage and the interactive light garden.</p>\n<h2>Import</h2>\n<p>Home uses Blocks buttons, icons, tooltips and surfaces, plus the private <a href="home">theme material preview</a>. There is no\nexternal background renderer.</p>\n<h2>Usage</h2>\n<p>Open <code>/</code>. A gently floating glass composition complements the introduction without requiring interaction. The hero has a brief description and generous spacing;\nthree compact feature links lead to Appearance, Theme Studio and the interaction demo. Theme Studio changes its colors and corners; Appearance changes its\ntranslucency and glassiness. Updates flow through semantic CSS variables.</p>\n<h2>API</h2>\n<p>Theme and appearance preferences remain owned by the existing shared services. Orby retains its existing wake, drag and keyboard interactions. Its lighting\nscene and physics use the full Home content region, including the page gutters; no visible enclosure or nested padding is needed. The footer is separated with a\nBlocks <code>Divider</code> rather than a CSS border.</p>\n<h2>Appearance and customization</h2>\n<p>Two miniature pages recall the author’s first portfolio through its wave silhouette. A compact title and introduction sit behind the front glass; the second\npage contains abstract shapes, gradients and short text. A readable Blocks glass card overlaps them with static text and theme color samples. It uses the same\nshared glass defaults as Appearance’s search bar. All artwork is HTML, CSS and SVG, without imported image assets. The front samples use primary, accent and a\nblend of both; the headline uses the readable accent color. Rendering quality follows global preferences. Only the front pane receives Orby’s light; the\nbackground cards have surface effects disabled.</p>\n<h2>Behavior and accessibility</h2>\n<p>The decorative illustration is hidden from assistive technology and adds no controls or keyboard stops. Reduced transparency, forced colors and material quality\nuse the shared Blocks behavior. The rear pages float independently using sideways and vertical CSS translation with gentle rocking, pausing when offscreen or\nthe document is hidden. Reduced motion stops decorative movement; observers and listeners are cleaned up on navigation. Home no longer resolves theme colors\nthrough a canvas or runs a background rendering loop. The existing light orb remains a separate, user-activated demonstration. It bounces against the unframed\npage bounds, which update on resize and content changes.</p>\n<h2>Playground</h2>\n<p>Open <code>/</code>. See the <a href="studio">Theme Studio guide</a> for editing, import and export behavior.</p>\n',
  'projects/playground/src/app/components/screens/icon-catalog/README.md':
    '<h1>Lucide icon catalog</h1>\n<p>Browse generated Lucide icons with search, official category filters, progressive rendering, and a nonmodal customization inspector. Filters and per-icon\ninspector customizations remain local to the current visit.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Icon</span>, <span class="hljs-variable constant_">LUCIDE_CATEGORIES</span>, <span class="hljs-variable constant_">LUCIDE_ICON_CATEGORIES</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/icons&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">InfiniteScrollDirective</span>, <span class="hljs-title class_">SidePanel</span>, <span class="hljs-title class_">SidePanelLayout</span>, <span class="hljs-title class_">VirtualCollection</span>, <span class="hljs-title class_">VirtualItemDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<p>Open <code>/icons</code>. Search by icon identifier and select <strong>Filters</strong> for catalog size, stroke width, and the collapsible <strong>Category</strong> section. Existing Blocks chips\nlist all categories side by side, with a checkmark and opaque accent fill for the selected choice. Only one category is selected at a time. Activating the\nselected chip retains that choice; selecting another replaces it. Reset all restores appearance and the unrestricted category default while keeping the search.\nThe Filters button has a plain label without an active-filter count.</p>\n<p>Filters resizes from its right edge using the shared resize directive. Its initial width is 360px; the default maximum is 50% of the main-content container.\nShrinking below the original rendered width is disabled by default. Its width persists while the panel is closed/reopened during this visit. Details remains\nnon-resizable. Keyboard users can focus the separator and use arrows, Home/End, and Escape.</p>\n<p>Select any icon for its right-side Details panel. The preview, semantic color picker, size/stroke sliders, background toggle, and Angular example update\nreactively. Copy uses the exact displayed example and announces success or failure. Selecting another tile updates the current panel in place. The active tile\nhighlight and pressed state clear when Details closes or another panel opens. Inspector settings are retained independently per selected icon during the visit;\na new inspector starts at at least 64 pixels using the current catalog stroke width and the accent color, listed first in the color selector. Reset\ncustomization restores those starting values.</p>\n<h2>API</h2>\n<p>The catalog uses public <a href="components/icon">Icon</a>,\n<a href="components/side-panel">SidePanel</a>, and\n<a href="components/infinite-scroll">InfiniteScrollDirective</a> APIs.</p>\n<p>Generated category maps are imported directly. Runtime filtering performs lookups without name-based classification or network requests. Metadata comes from\n<a href="https://github.com/lucide-icons/lucide">official Lucide source</a> through a pinned local build snapshot; the\n<a href="../../../../../../../tools/icons/README.md">generator guide</a> documents synchronization.</p>\n<p>Filters are local to the current visit. Each navigation back to the catalog or page reload starts with all categories, 24 px icons, a 1.5 stroke width and an\nempty search. Changes remain while opening and closing panels during the same visit. The catalog does not read or write saved filter preferences; legacy\n<code>blocks.icon-catalog.v1</code> records are ignored. Reset all restores the default size, stroke width and category selection immediately.</p>\n<h2>Appearance and customization</h2>\n<p>Filters and Details use the shared side-panel/modal-banner heading styles, themed leading icons through <code>headerIcon</code>, and the same compact close action.</p>\n<p>All controls use Blocks components/directives and semantic spacing, color, border, radius, and responsive grid styling. Colors remain theme tokens rather than\nfixed RGB values. Background customization uses the supported <code>bgColor=&quot;auto&quot;</code> icon API. Code omits default size/stroke properties and background when turned\noff.</p>\n<p>The catalogs use a constrained main-content viewport below the toolbar&#39;s natural-height row. SidePanelLayout contains both panels, excluding global navigation\nand the toolbar without offsets or document-scroll tracking. Filters uses <code>{ &#39;2xl&#39;: &#39;push&#39; }</code>: larger screens reserve panel space and resize the virtual grid;\nsmaller screens use overlay mode. Details keeps its default overlay presentation. Each panel&#39;s breakpoint policy is independently configurable. Mode changes\nretain the panel and its projected controls. The body scrolls independently from reachable fixed header/footer actions, including at narrow viewport widths.</p>\n<h2>Behavior and accessibility</h2>\n<p>The catalog initially reveals 72 icons, appending bounded batches near the bottom. VirtualCollection independently mounts a measured row window with 800-pixel\noverscan, unmounts distant tiles in either direction, and restores them on return. Changing size invalidates row geometry with stable scroll anchoring; changing\nstroke width updates only mounted SVGs. Grid columns recalculate when push panels, viewport widths, or zoom change. Local underfill checks continue only until\nthe finite result set fills the viewport or is exhausted. Search/category changes reset the reveal count, stable names track tiles, and append operations\npreserve scroll position. A Show more button gives keyboard users an explicit route to the next batch. Empty results and result counts use status announcements.</p>\n<p>Search matches case-insensitive partial words in any order, treating spaces, hyphens, and underscores as separators. For example, <code>arrow down</code>, <code>down arrow</code>,\nand <code>arrow-down</code> find <code>arrow-down</code>; this follows the Tokens catalog&#39;s word-matching behavior.</p>\n<p>A single active-panel signal coordinates Filters and Details. Opening either panel closes the global Theme Studio; opening Theme Studio closes the catalog\npanel, preserving the current visit&#39;s filter and inspector settings. Closing preserves filter and inspector settings; tile highlighting is shown only while\nDetails is open. Panels use complementary region semantics, optional focus restoration, a close control, and Escape dismissal; the page remains interactive\nwithout focus trapping, scroll locking, or modal semantics. Existing Blocks controls provide labeled keyboard-accessible sliders and selections. Setting\ninformation tooltips support focus, hover, and touch tap.</p>\n<p>Scroll to catalog top appears after scrolling 400 pixels past the start of the results in the actual scroll viewport, staying hidden while reading the\ndocumentation above the catalog. Its threshold follows documentation expansion and viewport changes. It uses a Blocks tooltip without touch long-press and\nrespects shared reduced-motion preferences. It is aligned to the grid&#39;s actual horizontal bounds inside its positioned viewport. It remains visible beside push\npanels and is hidden while an overlay panel is open to keep actions clear. Activation returns to the start of the results, leaving documentation above the\nviewport. The Tokens catalog uses the same action; Utilities no longer renders it.</p>\n<h2>Playground</h2>\n<p>Open <code>/icons</code> from Tools. Related interactive infrastructure demos are <code>/components/side-panel</code>, <code>/components/infinite-scroll</code>, and <code>/utilities</code>.</p>\n',
  'projects/playground/src/app/components/screens/installation/README.md':
    '<h1>Blocks installation page</h1>\n<p>A dedicated destination for package installation and application setup, rendering the authoritative package guide.</p>\n<h2>Import</h2>\n<p>This playground page uses Blocks <code>PageContainer</code> and the bundled README renderer.</p>\n<h2>Usage</h2>\n<p>Follow <strong>See the package setup</strong> from Theme Studio or any component guide.</p>\n<h2>API</h2>\n<p>The source of truth is <code>projects/blocks/README.md</code>. This page does not maintain a second installation guide.</p>\n<h2>Appearance and customization</h2>\n<p>The page follows the active Blocks theme and shared documentation code styles.</p>\n<h2>Behavior and accessibility</h2>\n<p>Documentation links keep application navigation. Code blocks are keyboard accessible and use the current syntax theme.</p>\n<h2>Playground</h2>\n<p>Open <code>/installation</code>.</p>\n',
  'projects/playground/src/app/components/screens/library-components/page-examples/README.md':
    '<h1>Page layout playground</h1>\n<p>Interactive examples for the <a href="components/layout/page-container">Blocks page container</a>.</p>\n<h2>Import</h2>\n<p>The component catalog loads <code>PageExamples</code> through the page-container example.</p>\n<h2>Usage</h2>\n<p>Open <code>/components/layout/page-container</code>. Edit the title and description, choose a preview nesting, change the breadcrumb threshold, switch to the current\nroute, and toggle the footer. The footer button reports its result.</p>\n<h2>API</h2>\n<p>The example uses public <code>PageContainer</code>, <code>PageHeader</code>, <code>PageContent</code>, and <code>PageFooter</code> components with Blocks form controls.</p>\n<h2>Appearance and customization</h2>\n<p>The preview follows the current shared theme and appearance configuration. Its nested heading uses level 2.</p>\n<h2>Behavior and accessibility</h2>\n<p>Root and nested preview trails exercise the same threshold as automatic breadcrumbs. The footer action supports keyboard activation and announces its result.</p>\n<h2>Playground</h2>\n<p>Reach this example through <strong>Primitives → Layout → Page container</strong>.</p>\n',
  'projects/playground/src/app/components/screens/theme-studio-demo/README.md':
    '<h1>Theme Studio showcase</h1>\n<p>Explore how shared theme tokens affect the interface, with focused component examples integrated into the explanation. Colors, layout, mode and export each have\ntheir own section on <code>/studio</code>; there is no separate component-preview route or unrelated sample workspace.</p>\n<h2>Import</h2>\n<p>Private playground screen using the public Blocks entry points and the existing <code>ThemeStudioService</code>.</p>\n<h2>Usage</h2>\n<p>Open <code>/studio</code> and choose <strong>Customize theme</strong>. The editor stays available while you inspect the live color roles, spacing sample, field, foreground pairs and\ninherited dialog. <strong>Randomize theme</strong> applies a coherent starting point through the existing service.</p>\n<h2>API</h2>\n<p>Draft state belongs to <code>ThemeStudioService</code>; palette, mode and appearance remain owned by <code>ThemingService</code>. The screen introduces no parallel theme state.\nColor-role metadata is defined in <code>theme-studio-showcase.constants.ts</code>. The exported SCSS is derived from the same draft as the sidebar and setup dialog.</p>\n<h2>Appearance and customization</h2>\n<p>The introduction retains the <a href="studio">glass aperture</a> and current palette label. Four sections demonstrate the theme:</p>\n<ul>\n<li><strong>Colors:</strong> six live swatches explain primary, accent, surface, text, border and hover roles, with their semantic CSS variable names.</li>\n<li><strong>Layout:</strong> a Blocks card demonstrates shared corner radius, border and shadow tokens. Spacing bars show the 4, 8 and 12 steps; a readonly field remains\nfocusable to inspect its outline. The dialog action demonstrates these tokens on a real overlay.</li>\n<li><strong>Preview:</strong> Blocks tabs switch the application’s light/dark mode. Fill/foreground pairs show primary and accent combinations. Custom colors still require a\ncontrast check; the page makes no automatic accessibility guarantee.</li>\n<li><strong>Export:</strong> Copy / setup opens the existing setup modal; project initialization and package setup links retain their existing destinations. Generated SCSS and\nthe detailed guide remain in closed collapsibles until requested.</li>\n</ul>\n<p>Sections and the measurement card use Blocks <code>Divider</code> components. CSS borders remain only where they describe a component or color swatch contour. Grid columns\nrespond to available width, including when the editor pushes the page. All examples use the active semantic tokens rather than fixed sample palettes.</p>\n<h2>Behavior and accessibility</h2>\n<p>The readonly sample field can receive focus and text selection without modifying state. Mode tabs, buttons, collapsibles and dialogs retain their existing\nkeyboard and focus behavior. Separator semantics come from <code>Divider</code>. Shared reduced-motion, reduced-transparency and forced-color behavior remains active. The\ntheme illustration pauses offscreen and is decorative.</p>\n<p>Opening the dialog does not send data or create a project. Its sample field is local to that modal visit, and mounted overlays inherit live theme changes.\nExport and setup reuse the existing workflow without changing draft persistence, history, validation or preview ownership.</p>\n<h2>Playground</h2>\n<p><code>/studio</code> is the showcase and the sidebar’s <strong>Explore Theme Studio</strong> destination. <code>/tokens</code> remains the full token catalog; <code>/studio/new-project</code> and\n<code>/installation</code> provide project setup. The authoritative editor guide is available in the page and the sidebar’s Export tab.</p>\n',
  'projects/playground/src/app/components/screens/theme-studio-new-project/README.md':
    '<h1>Initialize a Blocks project</h1>\n<p>Create an Angular 22 SCSS workspace and initialize Blocks with the selected built-in base.</p>\n<h2>Import</h2>\n<p>This is playground tooling using the public Blocks entry points. Open Theme Studio from the toolbar.</p>\n<h2>Usage</h2>\n<p>Open <code>/studio/new-project</code>. The Studio toolbar and its Copy / setup and Import actions expose the complete workflow.</p>\n<h2>API</h2>\n<p>Draft state belongs to <code>ThemeStudioService</code>; palette, mode and appearance remain owned by <code>ThemingService</code>. Controls use signals and OnPush.</p>\n<h2>Appearance and customization</h2>\n<p>Uses shared semantic colors, spacing, radius, borders, shadows and existing Blocks components. The active theme applies to this view and its overlays.</p>\n<h2>Behavior and accessibility</h2>\n<p>Controls have accessible labels and keyboard operation. Existing focus, modal dismissal, reduced-motion and high-contrast mechanisms remain authoritative.</p>\n<h2>Playground</h2>\n<p>Open <code>/studio/new-project</code>. The authoritative Studio guide is available from the editor&#39;s Export tab.</p>\n',
  'projects/playground/src/app/components/screens/token-catalog/README.md':
    '<h1>Tokens page</h1>\n<p>Browse and search Blocks colors, color companions, spacing, corner radii, shadows, stacking layers, effects, component properties, utility classes, and Sass\nbreakpoints at <code>/tokens</code>. The page uses Blocks search, multiselect, select, button, accordion, and card components. Theme-only mode opens all result sections on\nentry; full-inventory mode opens only the first. Collapse all beside Categories closes every result section. Category titles and Blocks dividers separate the\nmatching groups; their labels follow the category filter. With at least 48 displayed cards across expanded sections, cards mount in small batches near the\nviewport. Smaller displayed sets bypass viewport observation and stay mounted. Distant batches release their component instances while preserving their measured\nspace, and focused batches stay mounted. Other groups mount their batch placeholders when opened. Dense cards keep shared themed styling with decorative surface\neffects disabled.</p>\n<p>The toolbar&#39;s <a href="studio">Theme Studio</a> edits the curated theme controls and exports SCSS. Catalog swatches, displayed values,\ncolor-copy formats and value search update with preview edits and resets. Existing theme-only filtering and expansion preferences remain independent.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">import</span> {\n    <span class="hljs-variable constant_">CSS_TOKEN_CATALOG</span>,\n    <span class="hljs-variable constant_">THEME_CSS_VARIABLES</span>,\n    <span class="hljs-variable constant_">CSS_VARIABLES</span>,\n    <span class="hljs-variable constant_">CSS_VARIABLE_REFERENCES</span>,\n    <span class="hljs-variable constant_">SEMANTIC_PAIRS</span>,\n    <span class="hljs-variable constant_">UTILITY_CLASSES</span>,\n    getComplementaryToken,\n    resolveTokenToCssVar\n} <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n<span class="hljs-keyword">import</span> <span class="hljs-keyword">type</span> { <span class="hljs-title class_">Color</span>, <span class="hljs-title class_">CssVariable</span>, <span class="hljs-title class_">CssVariableReference</span>, <span class="hljs-title class_">ICssToken</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;</code></pre>\n<p>Sass helpers are available through <code>@filip.mazev/blocks/core/styles/helpers</code>. Install the global Blocks styles and a theme as described in the\n<a href="components">Core guide</a>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="scss code example"><code class="hljs language-scss"><span class="hljs-keyword">@use</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core/styles/helpers&#x27;</span> as *;\n\n<span class="hljs-selector-class">.notice</span> {\n    <span class="hljs-attribute">padding</span>: <span class="hljs-built_in">var</span>(--bx-space-<span class="hljs-number">4</span>);\n    <span class="hljs-attribute">border</span>: <span class="hljs-built_in">var</span>(--bx-border-width) <span class="hljs-built_in">var</span>(--bx-border-style) <span class="hljs-built_in">var</span>(--bx-border-danger);\n    <span class="hljs-attribute">border-radius</span>: <span class="hljs-built_in">var</span>(--bx-rounded-md);\n    <span class="hljs-attribute">background</span>: <span class="hljs-built_in">var</span>(--bx-bg-danger);\n    <span class="hljs-attribute">color</span>: <span class="hljs-built_in">var</span>(--bx-text-danger);\n    <span class="hljs-attribute">box-shadow</span>: <span class="hljs-built_in">var</span>(--bx-shadow-sm);\n}\n\n<span class="hljs-keyword">@include</span> respond-up(md) {\n    <span class="hljs-selector-class">.notice</span> {\n        <span class="hljs-attribute">padding</span>: <span class="hljs-built_in">spacing</span>(<span class="hljs-number">6</span>);\n    }\n}</code></pre>\n<pre class="playground-code-block" tabindex="0" aria-label="ts code example"><code class="hljs language-ts"><span class="hljs-keyword">const</span> <span class="hljs-attr">color</span>: <span class="hljs-title class_">Color</span> = <span class="hljs-string">&#x27;danger-500&#x27;</span>;\n<span class="hljs-keyword">const</span> <span class="hljs-attr">reference</span>: <span class="hljs-title class_">CssVariableReference</span> = <span class="hljs-title function_">resolveTokenToCssVar</span>(color); <span class="hljs-comment">// var(--bx-color-danger-500)</span>\n<span class="hljs-keyword">const</span> companion = <span class="hljs-title function_">getComplementaryToken</span>(color); <span class="hljs-comment">// danger-50</span>\n<span class="hljs-keyword">const</span> <span class="hljs-attr">localOverrides</span>: <span class="hljs-keyword">readonly</span> <span class="hljs-title class_">ICssToken</span>[] = <span class="hljs-variable constant_">CSS_TOKEN_CATALOG</span>.<span class="hljs-title function_">filter</span>(<span class="hljs-function">(<span class="hljs-params">token</span>) =&gt;</span> token.<span class="hljs-property">scope</span> === <span class="hljs-string">&#x27;local&#x27;</span>);</code></pre>\n<p>Use semantic roles for content that should adapt to the selected theme. <code>primary</code> and <code>accent</code> palette shades follow the chosen brand/accent palettes. Named\npalettes such as <code>carbon</code>, <code>danger</code>, and <code>teal</code> expose their complete shade scales independently of the selected theme.</p>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Export</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>CSS_TOKEN_CATALOG</code></td>\n<td>Readonly <code>ICssToken</code> metadata for all discovered <code>--bx-*</code> variables, including declarations, fallbacks, selectors, sources, groups, and availability</td>\n</tr>\n<tr>\n<td><code>CSS_VARIABLES</code>, <code>CSS_VARIABLE_REFERENCES</code></td>\n<td>Names and <code>var(...)</code> references, with the corresponding <code>CssVariable</code> and <code>CssVariableReference</code> unions</td>\n</tr>\n<tr>\n<td><code>SEMANTIC_COLOR_TOKENS</code>, <code>PALETTE_NAMES</code>, <code>SHADE_NUMBERS</code>, <code>COLOR_TOKENS</code></td>\n<td>Supported color inputs, palettes, and shade scales</td>\n</tr>\n<tr>\n<td><code>SEMANTIC_PAIRS</code>, <code>getComplementaryToken()</code></td>\n<td>Explicit semantic companions and the shared palette/fallback companion rules</td>\n</tr>\n<tr>\n<td><code>SPACING_VALUES</code>, <code>RADIUS_VALUES</code>, <code>SHADOW_VALUES</code>, <code>BORDER_VALUES</code>, <code>Z_INDEX_VALUES</code></td>\n<td>Default Sass scale values serialized as CSS values</td>\n</tr>\n<tr>\n<td><code>BREAKPOINTS</code></td>\n<td>Numeric pixel thresholds for Sass helpers and responsive services; these are not CSS custom properties</td>\n</tr>\n<tr>\n<td><code>UTILITY_CLASSES</code> and family arrays</td>\n<td>Actual classes emitted by the global Sass entry point, including semantic color utilities</td>\n</tr>\n</tbody></table>\n<p><code>THEME_CSS_VARIABLES</code> and <code>ThemeCssVariable</code> identify the application theme subset. <code>ICssToken.themeEditable</code> marks that same set. <code>defaults</code> contains actual\ndeclarations; <code>fallbacks</code> contains separate <code>var()</code> alternatives; <code>selectors</code> and <code>sources</code> describe where tokens are declared and referenced. The catalog\ncombines declarations and labeled fallbacks for display and includes source paths in search.</p>\n<p>Availability has explicit meaning:</p>\n<ul>\n<li><code>global</code>: emitted globally by the Blocks utility or accessibility styles.</li>\n<li><code>theme</code>: emitted by <code>bx-theme</code>; values follow the nearest theme.</li>\n<li><code>local</code>: declared or given a fallback in a component/effect; it is not necessarily available on the document root.</li>\n<li><code>runtime</code>: referenced or assigned by TypeScript without a static declaration or fallback. Some are internal rendering state, not supported application\ncontrols.</li>\n</ul>\n<p>The catalog is a discovery inventory, not a promise that every runtime property is a public customization API. Consult the owning feature guide before setting a\nlocal or runtime property. A <code>var(...)</code> reference without a fallback is valid only where that variable exists.</p>\n<h3>Generator and maintenance</h3>\n<p>Run <code>npm run tools:generate-tokens</code> after changing Sass or variable usage. Library/playground build scripts and playground start/watch run it automatically.\n<code>npm run tools:sync-theme-types</code> remains a compatibility alias. Generated data lives in Core&#39;s <code>tokens.constants.ts</code>, <code>token-catalog.constants.ts</code>, and\n<code>theme-palettes.constants.ts</code>; types and interfaces are maintained in regular TypeScript files.</p>\n<p><code>$theme-palettes</code> in <code>_theme-engine.scss</code> is the source of theme IDs, labels, brand/accent palette assignments and optional preview order. Swatches derive from\nthose palettes&#39; shade 500; theme classes derive from their IDs. <code>make-palette-theme()</code> uses the same assignments for light/dark themes. Generated\n<code>THEME_PALETTE_ROLES</code> exposes the generated brand/accent assignments used to group palette colors and companions into theme sections. <code>THEME_PALETTE_IDS</code>\nsupplies the <code>BxThemeId</code> union, and <code>THEME_PALETTES</code> keeps the existing selector metadata contract.</p>\n<p><code>tools/tokens/catalog.scss</code> exports evaluated Sass maps through a Sass custom function. The source reader compiles global styles, component/directive styles,\nand effects, collects custom-property declarations (including <code>@property</code> registration) and nested <code>var()</code> fallbacks, and scans TypeScript string literals for\nruntime property usage. The data helper validates palettes, emitted foundation variables, breakpoint units, and semantic pairs. The writer uses the TypeScript\nAST to emit data declarations, then applies the shared ESLint/formatting pipeline before writing. No TypeScript program is maintained inside generator strings.</p>\n<p>Generation reports its source-reading and per-file validation stages, elapsed time, and updated/unchanged outputs. The shared writer formats before ESLint so\nlarge inventories avoid expensive formatter-difference processing. Unchanged files keep their modification times to avoid unnecessary watch rebuilds.</p>\n<p>The inventory follows statically discoverable Blocks names. Arbitrary application-defined properties and names constructed entirely at runtime are outside its\nscope; registered dynamic effect properties are included through their CSS registrations. Values come from default library Sass configuration, so applications\nthat configure Sass maps can have different scale values. Run <code>npm run tools:build-docs</code> to update the bundled guide.</p>\n<h3>Compatibility</h3>\n<p><code>meta-brand-palette</code> and <code>meta-accent-palette</code> are Sass theme metadata and are no longer included in <code>Color</code> or <code>SEMANTIC_COLOR_TOKENS</code>: <code>bx-theme</code> never\nemitted CSS variables for them. Use <code>ThemingService.palette()</code> and its palette definitions for application palette metadata; use <code>primary</code>/<code>accent</code> for themed\ncolors. Existing CSS-variable, scale, utility, and color-helper exports remain available. Variable/reference inventories now also include local and runtime\nproperties; filter <code>CSS_TOKEN_CATALOG</code> by scope when building a list of globally available values.</p>\n<h2>Appearance and customization</h2>\n<p>Use the playground toolbar to change the palette, light/dark mode, high contrast, or appearance. Swatches and shape previews use CSS variables directly. Color\ncards display the current HEX value; other global/theme cards display their current computed value and separate source defaults. Component/effect values show\ntheir declarations and fallbacks instead of suggesting a document-level computed value. Semantic border colors remain in Colors; Border geometry exposes shared\nwidth and style. The <strong>Theme controls only</strong> slide toggle defaults to enabled, remembers the chosen mode across refreshes and visits, and shows the curated\n<code>THEME_CSS_VARIABLES</code> set. Its hint explains the scope; turn it off to browse component hooks, effects and the rest of the inventory. Other entries are labeled\nAdvanced inventory; they remain discoverable for targeted customization and debugging. See Core&#39;s\n<a href="components#theme-token-audit-and-customization-contract">token audit and migration guide</a> for layer ownership, live override\nexamples and the <code>$static: true</code> Sass compatibility option.</p>\n<p>Spacing and radius scales follow their numeric/source scale order. Color tiles stay compact; other tiles have wider columns and more padding. Radius samples are\nlarge enough to distinguish the larger corners. Shadow samples use a light neutral preview canvas in both themes so the actual shadow remains visible.\nResponsive Sass snippets use the playground code wrapper. Palette shades and companions are grouped together by their registered theme, such as Carbon / Cobalt;\nprimary/accent aliases use the short Primary / Accent heading, and remaining standalone palettes stay available separately. Trailing tags identify the current\ntheme, palette sections, and companion sections without long title prefixes.</p>\n<h2>Behavior and accessibility</h2>\n<p>Search is case insensitive and matches every entered word against names, references, category, group, scope, default/fallback values, companions, and source\npaths. On page entry, theme-only mode opens every section; full-inventory mode opens only the first section. Section expansion and category filters are local to\nthe current visit; only the mode toggle is stored. Unavailable browser storage falls back to the enabled default without blocking interaction. Changing search\nopens only the first matching section. Category changes preserve explicitly expanded or collapsed sections, including when a category is hidden and later\nrestored. Other sections remain available to open individually. Choose multiple categories to include any selected family, for example Colors and Color pairs.\nClear the category selection to remove category filtering; turn off <strong>Theme controls only</strong> to include the full inventory. All categories is the absence of a\ncategory filter rather than a selectable option. Search and counts cover the complete catalog regardless of which batches are mounted. In <strong>Theme controls\nonly</strong> mode, categories without theme tokens are disabled and explain why on hover. Enabling the mode removes those categories from the current selection while\nretaining supported categories. Search text does not change which categories are available.</p>\n<p>Each expanded group initially exposes up to two 24-token chunks. Primitives&#39; <code>InfiniteScrollDirective</code> progressively reveals another two chunks at the group\nboundary, including filling a short viewport from this finite local dataset. A keyboard-accessible Show more action remains available while chunks remain.\nClosing a group preserves its reveal count; changing search or categories resets the counts.</p>\n<p>The shared <code>VirtualCollection</code> uses measured, bidirectional grid rows within each expanded group. Distant cards are unmounted, their height is retained with\nspacers, and returning restores rows without retaining every previously visited tile. Responsive column/height changes preserve a stable scroll anchor, and a\nfocused row can remain mounted independently. Groups outside the overscan area retain their scroll extent without mounting their cards. This replaces the old\nplayground-only viewport/chunk observer. Color conversion reads only mounted items, including pinned focused rows.</p>\n<p>A constrained catalog viewport occupies the content area below the top bar. The shared Scroll to catalog top action is aligned to the results width near that\nviewport&#39;s bottom-right corner, scrolls that container to the start of the results, and respects reduced motion. Documentation remains above the viewport. It\nhas a keyboard/hover tooltip with touch long-press disabled. It appears only after scrolling 400 pixels past the start of the results, staying hidden while\nreading the documentation above the catalog. Documentation expansion and viewport changes update the threshold.</p>\n<p>Metadata expansion within an unloaded batch is recreated when it returns. Current color-value search uses a lazy index; ordinary browsing converts only mounted\nbatches. One canvas and a conversion cache are reused until theme/appearance changes. Documentation content mounts only while its section is open. Clear the\ncategory selection to show all tokens. Blocks accordions provide heading navigation, expansion and focus restoration; source defaults and fallbacks use Blocks\ncollapsibles. Right-click a card, touch and hold, or use its <strong>Copy…</strong> button to open a Blocks menu with the applicable copy formats. Focused cards also support\nShift + F10 and the Context Menu key. CSS references copy <code>var(--bx-…)</code>; names copy only <code>--bx-…</code>. HEX uses eight digits when transparency is present; RGB uses\ncomma-separated channels and preserves transparency with <code>rgba(...)</code>; RGBA always includes explicit alpha. Pairs copy one value per line. Non-color variables\nprovide CSS-reference/name actions; utility classes and Sass breakpoints provide their respective copy actions. Menu choices follow live theme colors.</p>\n<p>Card text suppresses selection and iOS callouts to keep long-press gestures predictable. Source-default collapsibles retain selectable text and native selection\nmenus. Copy-menu rows use local themed hover/pressed fills and focus outlines without illuminating the cards or accordion sections behind the opaque menu. Copy\nactions report success/failure in a live region. Search and multiselect controls use dynamic subscript sizing and reserve no empty validation row.</p>\n<p>Color pairs show both named tokens and adjacent swatches. They reflect <code>getComplementaryToken()</code> exactly: explicit semantic mappings, <code>bg-surface</code> for unmapped\nroles, shade 50 for palette shades above 400, and shade 900 otherwise. They do not imply a guaranteed text contrast ratio. Labels identify colors without\nrelying on color alone. There is no catalog animation; reduced-motion and opaque/high-contrast preferences continue through the shared Blocks controls and\nstyles.</p>\n<h2>Playground</h2>\n<p>Open <code>/tokens</code> from Tools. Search for <code>warning</code>, <code>danger</code>, <code>background</code>, <code>shadow</code>, <code>rounded</code>, <code>glass</code>, a component name, a source path, or a full CSS variable.\nChoose <strong>Color pairs</strong> for the complete companion mapping, <strong>Sass breakpoints</strong> for responsive thresholds, or <strong>Utility classes</strong> for copyable class names.</p>\n',
  'projects/playground/src/app/components/screens/tools/README.md':
    '<h1>Playground tools</h1>\n<p>The Tools overview groups the modal and toast configurators behind one navigation entry. Cards open the existing <code>/modal</code> and <code>/toastr</code> pages.</p>\n<h2>Import</h2>\n<p>The playground lazy-loads <code>Tools</code> from <code>tools.ts</code> at <code>/tools</code>.</p>\n<h2>Usage</h2>\n<p>Open Tools from the main navigation, then choose a configurator from its overview or open its navigation disclosure to browse the same destinations.</p>\n<h2>API</h2>\n<p>The overview reads the shared <code>NavigationService</code> Tools section, preserving route visibility and resolved labels. It has no component inputs or outputs.</p>\n<h2>Appearance and customization</h2>\n<p>Cards use Blocks surfaces, the responsive Grid component, and semantic color, spacing, and radius tokens. The active playground theme applies immediately.</p>\n<h2>Behavior and accessibility</h2>\n<p>Cards are native links with visible keyboard focus. The grid fits narrow containers and enlarged text. Existing configurator URLs remain unchanged.</p>\n<h2>Playground</h2>\n<p>Visit <code>/tools</code>, <code>/modal</code>, or <code>/toastr</code>.</p>\n',
  'projects/playground/src/app/components/screens/utilities/README.md':
    '<h1>Utilities playground</h1>\n<p>Explore public Core utilities through focused interactive examples. Choose a utility from the overview or expand <strong>Core → Utilities</strong> in the sidenav. Each page\npresents its demo first, then separate documentation and source tabs. The <a href="components">Core guide</a> remains the entry-point\nreference.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> {\n    <span class="hljs-title class_">DeviceTypeService</span>,\n    findScrollContainer,\n    measureScrollBoundary,\n    observeScrollBoundary,\n    <span class="hljs-title class_">ScrollLockService</span>,\n    uuidv4,\n    <span class="hljs-title class_">WindowDimensionsService</span>\n} <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">InfiniteScrollDirective</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/primitives&#x27;</span>;</code></pre>\n<p>Services are provided in root; import the standalone scroll detector where used. Each utility guide documents its public imports, configuration, lifecycle, and\nsupporting types.</p>\n<h2>Usage</h2>\n<p>Search <code>/utilities</code> by utility or API name, then follow <strong>Explore utility</strong>. Direct URLs are supported, and the sidenav exposes the same six pages.</p>\n<table>\n<thead>\n<tr>\n<th>Utility</th>\n<th>Playground</th>\n<th>Guide</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Viewport and breakpoints</td>\n<td><code>/utilities/viewport</code></td>\n<td><a href="utilities/viewport">Viewport guide</a></td>\n</tr>\n<tr>\n<td>Device detection</td>\n<td><code>/utilities/device</code></td>\n<td><a href="utilities/device">Device guide</a></td>\n</tr>\n<tr>\n<td>Shared scroll locking</td>\n<td><code>/utilities/scroll-lock</code></td>\n<td><a href="utilities/scroll-lock">Scroll-lock guide</a></td>\n</tr>\n<tr>\n<td>Stable identifiers</td>\n<td><code>/utilities/identifiers</code></td>\n<td><a href="utilities/identifiers">Identifier guide</a></td>\n</tr>\n<tr>\n<td>Color-token helpers</td>\n<td><code>/utilities/color-tokens</code></td>\n<td><a href="utilities/color-tokens">Color-token guide</a></td>\n</tr>\n<tr>\n<td>Overlay positioning</td>\n<td><code>/utilities/overlay-positioning</code></td>\n<td><a href="utilities/overlay-positioning">Overlay guide</a></td>\n</tr>\n</tbody></table>\n<h2>API</h2>\n<h3>Scroll boundaries</h3>\n<p>The overview includes an interactive local scroll container with configurable batch size and height. It uses <code>InfiniteScrollDirective</code> to progressively expose\nrows and reports boundary-event counts and measured overflow. The accompanying shared load-more demo shows asynchronous loading, retained-content failure, and\nexplicit retry through success. See the <a href="components/infinite-scroll">detector guide</a> and\n<code>/components/infinite-scroll</code>.</p>\n<table>\n<thead>\n<tr>\n<th>API</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>findScrollContainer(element)</code></td>\n<td>Finds the nearest vertical scrolling ancestor or the document viewport</td>\n</tr>\n<tr>\n<td><code>measureScrollBoundary(content, container?, endOffset?)</code></td>\n<td>Returns distance, overflow, and viewport height without changing scroll position</td>\n</tr>\n<tr>\n<td><code>observeScrollBoundary(content, container, onScroll, onResize)</code></td>\n<td>Passive scroll/geometry observation; returns mandatory cleanup</td>\n</tr>\n<tr>\n<td><code>IScrollBoundary</code></td>\n<td>Typed measurement contract in CSS pixels</td>\n</tr>\n</tbody></table>\n<p>The <a href="components/virtual-collection">virtual collection guide</a> and <code>/components/virtual-collection</code> demonstrate\nbidirectional list/grid rendering, dynamic heights, column changes, and programmatic scrolling. Scroll to top is available on Icons and Tokens, inside their own\ncontent viewports.</p>\n<h3>Coverage audit</h3>\n<table>\n<thead>\n<tr>\n<th>Utilities</th>\n<th>Interactive coverage</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>WindowDimensionsService</code>, <code>BREAKPOINTS</code></td>\n<td>Live CSS-pixel dimensions, shared breakpoint tags, range queries, responsive columns</td>\n</tr>\n<tr>\n<td><code>DeviceTypeService</code>, device/OS contracts</td>\n<td>Device identity, platform flags, orientation events, explicit refresh</td>\n</tr>\n<tr>\n<td><code>ScrollLockService</code>, <code>IScrollLockConfig</code></td>\n<td>Independent owners, remaining-owner behavior, release actions, navigation cleanup</td>\n</tr>\n<tr>\n<td>Scroll-boundary directive and helpers</td>\n<td>Local batch/height controls, overflow status, asynchronous fallback/retry example; linked virtual collection coverage</td>\n</tr>\n<tr>\n<td><code>uuidv4()</code></td>\n<td>Regenerated UUID and stable instance ID comparison</td>\n</tr>\n<tr>\n<td>Color-token helpers, <code>resolveThemeId()</code></td>\n<td>Semantic/palette selection, CSS reference, complementary/inverted tokens, saved palette validation</td>\n</tr>\n<tr>\n<td><code>BxOverlayPositionService</code>, origin/theme helpers</td>\n<td>Preferred placement, viewport fallback, tracked origin, inherited theme, teardown</td>\n</tr>\n</tbody></table>\n<p>The <a href="tokens">token catalog</a> at <code>/tokens</code> covers <code>CSS_TOKEN_CATALOG</code>, the curated <code>THEME_CSS_VARIABLES</code> theme contract, CSS reference types,\nutility classes, foundation scales, and all color companions. Focused color-helper examples live in the utilities section above.</p>\n<p>Other public utilities retain their established guides:</p>\n<table>\n<thead>\n<tr>\n<th>Utilities</th>\n<th>Existing coverage</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>ThemingService</code>, appearance/palette configuration</td>\n<td><a href="appearance">Appearance</a>, <code>/appearance</code></td>\n</tr>\n<tr>\n<td><code>BxA11yService</code> and reduced motion</td>\n<td><a href="appearance#behavior-and-accessibility">Appearance accessibility preferences</a>, <code>/appearance</code></td>\n</tr>\n<tr>\n<td><code>BxShortcutService</code>, shortcut helpers and contracts</td>\n<td><a href="components/menu-item">Menu item</a>, <code>/components/menu-item</code></td>\n</tr>\n<tr>\n<td><code>BX_I18N</code>, <code>ResolvableText</code>, <code>resolveText()</code>, <code>isTextWithKey()</code></td>\n<td><a href="components#translation-and-overlays">Core translation integration</a> and <a href="components/signal-forms">Forms</a></td>\n</tr>\n<tr>\n<td>Form state/defaults, <code>BxBaseControl</code>, <code>FormSettingsService</code></td>\n<td><a href="components/signal-forms">Forms</a> and <a href="components/truncate">Truncate</a></td>\n</tr>\n<tr>\n<td>Navigation, modal, notification and effects services</td>\n<td>Their <a href="../../../../../../blocks/navigation/README.md">Navigation</a>, <a href="modal">Modal</a>, <a href="toastr">Toastr</a>, and <a href="components/surface">Effects</a> guides</td>\n</tr>\n</tbody></table>\n<p>The effects runtime&#39;s shared motion helpers (<code>createSpringMotion</code>, <code>GestureVelocity</code>, <code>projectMotion</code>, <code>subscribeFrame</code>, <code>mountSelectionMotion</code>,\n<code>createGlassTransition</code>) retain their focused <a href="components/surface">Effects guide</a> and\n<a href="../../../../../../blocks/effects/runtime/README.md">runtime API guide</a>, with interactive coverage at <code>/components/tabs</code>, <code>/components/stepper</code>,\n<code>/components/slider</code>, <code>/components/slide-toggle</code>, <code>/components/menu</code>, and the select/overlay pages.</p>\n<p>Internal coordination services, implementation classes, and type-only contracts do not receive separate playground pages.</p>\n<h2>Appearance and customization</h2>\n<p>The overview uses Blocks search, cards, grids, stacks, tags, icons, links styled as buttons, and alerts. Every demo uses public Blocks controls and shared theme\nstyles. Layouts shrink and wrap for narrow containers, zoom, and long content. Semantic HTML remains in use for headings, descriptions, definition lists, and\noutputs.</p>\n<h2>Behavior and accessibility</h2>\n<p>Each utility loads independently. Leaving a demo tears down its owned listeners, scroll locks, and overlays. No demo changes global appearance preferences.\nInteractive controls use Blocks keyboard and focus behavior, while status changes and generated identifiers use polite announcements. Viewport resizing avoids\nrepeated live announcements.</p>\n<p>The overview and detail pages share <code>PageContainer</code> gutters and headings. Detail pages use automatic breadcrumbs to return to Utilities.</p>\n<h2>Playground</h2>\n<p>Open <code>/utilities</code> from <strong>Core → Utilities</strong>. Expand its sidenav item for all six utility pages, or use the overview search and links. On each page, the\ninteractive example precedes the documentation and source tabs.</p>\n',
  'projects/playground/src/app/components/screens/utilities/components/color-tokens/README.md':
    '<h1>Color-token helpers</h1>\n<p>Map typed colors to CSS references and inspect companion, inversion, and palette-validation helpers.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { getComplementaryToken, invertPaletteToken, isPaletteToken, isThemedColor, resolveThemeId, resolveTokenToCssVar } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-title function_">resolveTokenToCssVar</span>(<span class="hljs-string">&#x27;primary&#x27;</span>); <span class="hljs-comment">// var(--bx-primary)</span>\n<span class="hljs-title function_">resolveTokenToCssVar</span>(<span class="hljs-string">&#x27;orange-500&#x27;</span>); <span class="hljs-comment">// var(--bx-color-orange-500)</span>\n<span class="hljs-title function_">getComplementaryToken</span>(<span class="hljs-string">&#x27;text-primary&#x27;</span>); <span class="hljs-comment">// bg-element</span>\n<span class="hljs-title function_">getComplementaryToken</span>(<span class="hljs-string">&#x27;orange-500&#x27;</span>); <span class="hljs-comment">// orange-50</span>\n<span class="hljs-title function_">invertPaletteToken</span>(<span class="hljs-string">&#x27;blue-100&#x27;</span>); <span class="hljs-comment">// blue-900</span>\n<span class="hljs-title function_">isPaletteToken</span>(<span class="hljs-string">&#x27;primary&#x27;</span>); <span class="hljs-comment">// false</span>\n<span class="hljs-title function_">isThemedColor</span>({ <span class="hljs-attr">light</span>: <span class="hljs-string">&#x27;primary&#x27;</span>, <span class="hljs-attr">dark</span>: <span class="hljs-string">&#x27;accent&#x27;</span> }); <span class="hljs-comment">// true</span>\n<span class="hljs-title function_">resolveThemeId</span>(<span class="hljs-string">&#x27;carbon-cobalt&#x27;</span>); <span class="hljs-comment">// carbon-cobalt</span>\n<span class="hljs-title function_">resolveThemeId</span>(<span class="hljs-string">&#x27;retired-palette&#x27;</span>); <span class="hljs-comment">// undefined</span></code></pre>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Helper</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>resolveTokenToCssVar(token)</code></td>\n<td>Maps a typed semantic or palette color to a CSS <code>var(...)</code> reference; it does not resolve an RGB value</td>\n</tr>\n<tr>\n<td><code>isPaletteToken(token)</code></td>\n<td>Recognizes supported palette names and numeric shades; accepts typed <code>Color</code> values</td>\n</tr>\n<tr>\n<td><code>getComplementaryToken(token)</code></td>\n<td>Looks up semantic pairs (falling back to <code>bg-surface</code>) or chooses palette shade 50 for shades above 400, otherwise 900</td>\n</tr>\n<tr>\n<td><code>invertPaletteToken(token)</code></td>\n<td>Mirrors a palette shade, including 50→900 and 1000→50; leaves semantic tokens or unsupported results unchanged</td>\n</tr>\n<tr>\n<td><code>isThemedColor(value)</code></td>\n<td>Narrows non-null objects with a <code>light</code> member; does not validate individual token values or choose a theme</td>\n</tr>\n<tr>\n<td><code>resolveThemeId(value)</code></td>\n<td>Accepts current palette IDs; returns undefined for absent, unknown or retired IDs</td>\n</tr>\n</tbody></table>\n<p>These helpers do not guarantee contrast. <code>Color</code>, <code>ThemeColorToken</code>, <code>SemanticColorToken</code>, and <code>ThemedColor</code> describe typed consumer configuration. Prefer\nsemantic tokens for values that should follow theme and palette changes.</p>\n<h2>Appearance and customization</h2>\n<p>The interactive example uses public Blocks components, semantic theme variables, and shared spacing and responsive helpers. It follows the active playground\nappearance. Open the source tab for the component and template.</p>\n<h2>Behavior and accessibility</h2>\n<p>The Blocks select updates every helper result reactively. Change the active playground theme to see semantic CSS variables update the decorative swatch; every\nresult is also shown as text.</p>\n<p>Browse the <a href="tokens">complete token catalog</a> at <code>/tokens</code> for all CSS variables, companions, scales, and utility classes. Companion\nmappings do not guarantee contrast.</p>\n<h2>Playground</h2>\n<p>Open <code>/utilities/color-tokens</code> from <strong>Core → Utilities → Color-token helpers</strong>. The demo appears first, followed by separate documentation and code tabs.</p>\n<p>Return to the <a href="utilities">utilities overview</a> for the coverage audit and related feature guides.</p>\n',
  'projects/playground/src/app/components/screens/utilities/components/device/README.md':
    '<h1>Device detection</h1>\n<p>Inspect browser device identity, operating-system hints, and screen orientation with <code>DeviceTypeService</code>.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">DeviceTypeService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">DeviceTypeService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">const</span> deviceTypeService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">DeviceTypeService</span>);\n<span class="hljs-keyword">const</span> state = deviceTypeService.<span class="hljs-title function_">getDeviceState</span>();\n<span class="hljs-keyword">const</span> isAppleDevice = state.<span class="hljs-property">isAppleDevice</span>;\n<span class="hljs-keyword">const</span> landscape = state.<span class="hljs-title function_">isLandscapeOrientation</span>();</code></pre>\n<p>Call <code>inject()</code> in an Angular injection context. Store the snapshot in a signal and refresh it from browser events when the view needs live updates.</p>\n<h2>API</h2>\n<p><code>getDeviceState(): IDeviceState</code> returns a snapshot of mobile/tablet/desktop and OS detection based on browser identity, including iPadOS desktop identity with\ntouch hardware. It exposes <code>isDesktop</code>, <code>isMobile</code>, <code>isTablet</code>, <code>desktopOS</code>, <code>mobileOS</code>, <code>isAppleDevice</code>, <code>isAndroidDevice</code>, <code>isWindowsDesktop</code>,\n<code>isLinuxOrUnixDesktop</code>, and <code>isUnknownMobileDevice</code>.</p>\n<p><code>isLandscapeOrientation()</code> and <code>isPortraitOrientation()</code> are available on both the service and the returned state. They read the latest tracked <strong>screen</strong>\norientation. They are ordinary methods, not Angular signals. This page refreshes its snapshot on Screen Orientation change events and offers an explicit refresh\naction. Without that browser API, the service initializes orientation from a media query; live screen rotation is not tracked there.</p>\n<p>Viewport resizing does not change device categories. Device detection is heuristic and browser identity can be overridden. Use capabilities for interaction\ndecisions and viewport signals for layout. During SSR, identity is unavailable: the current fallback reports desktop/unknown OS and portrait orientation.</p>\n<h2>Appearance and customization</h2>\n<p>The interactive example uses public Blocks components, semantic theme variables, and shared spacing and responsive helpers. It follows the active playground\nappearance. Open the source tab for the component and template.</p>\n<h2>Behavior and accessibility</h2>\n<p>The demo uses Blocks cards, a tag, and a refresh button. Screen Orientation change events refresh the OnPush snapshot and the subscription is removed on\ndestruction.</p>\n<p>Resizing does not change browser identity. Detection is heuristic; prefer capability checks for interaction decisions and viewport signals for layout.</p>\n<h2>Playground</h2>\n<p>Open <code>/utilities/device</code> from <strong>Core → Utilities → Device detection</strong>. The demo appears first, followed by separate documentation and code tabs.</p>\n<p>Return to the <a href="utilities">utilities overview</a> for the coverage audit and related feature guides.</p>\n',
  'projects/playground/src/app/components/screens/utilities/components/identifiers/README.md':
    '<h1>Stable identifiers</h1>\n<p>Create version-4 UUIDs for controls, overlays, and stable shared-resource ownership.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { uuidv4 } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { uuidv4 } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">const</span> <span class="hljs-attr">ownerId</span>: <span class="hljs-built_in">string</span> = <span class="hljs-title function_">uuidv4</span>();\n<span class="hljs-comment">// Reuse ownerId for acquisition and cleanup throughout this instance&#x27;s lifetime.</span></code></pre>\n<h2>API</h2>\n<p><code>uuidv4(): string</code> uses <code>crypto.getRandomValues()</code> to generate a version-4 UUID. It requires that runtime API. Generate once per owning instance; avoid calling\nit from templates or computed values that may regenerate an owner ID. Coordinate server/client IDs explicitly when stable hydration identity is required.</p>\n<h2>Appearance and customization</h2>\n<p>The interactive example uses public Blocks components, semantic theme variables, and shared spacing and responsive helpers. It follows the active playground\nappearance. Open the source tab for the component and template.</p>\n<h2>Behavior and accessibility</h2>\n<p>The Blocks button generates a fresh preview UUID. A separate instance ID remains unchanged for comparison. Updated previews are announced politely, and long\nvalues wrap on narrow screens.</p>\n<p>The helper needs <code>crypto.getRandomValues()</code>. Coordinate server/client IDs explicitly when hydration requires the same identity.</p>\n<h2>Playground</h2>\n<p>Open <code>/utilities/identifiers</code> from <strong>Core → Utilities → Stable identifiers</strong>. The demo appears first, followed by separate documentation and code tabs.</p>\n<p>Return to the <a href="utilities">utilities overview</a> for the coverage audit and related feature guides.</p>\n',
  'projects/playground/src/app/components/screens/utilities/components/overlay-positioning/README.md':
    '<h1>Overlay positioning</h1>\n<p>Extend Blocks overlays with shared connected positioning, visibility tracking, and live theme inheritance.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxOverlayPositionService</span>, inheritOverlayTheme, isOverlayOriginVisible, trackOverlayOrigin } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Overlay</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/cdk/overlay&#x27;</span>;\n<span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">BxOverlayPositionService</span>, inheritOverlayTheme, trackOverlayOrigin } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-keyword">const</span> overlay = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">Overlay</span>);\n<span class="hljs-keyword">const</span> bxOverlayPositionService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">BxOverlayPositionService</span>);\n\n<span class="hljs-comment">// Run after the origin is rendered and attach a portal before tracking.</span>\n<span class="hljs-keyword">function</span> <span class="hljs-title function_">attachPreview</span>(<span class="hljs-params"><span class="hljs-attr">origin</span>: <span class="hljs-title class_">HTMLElement</span></span>) {\n    <span class="hljs-keyword">const</span> overlayRef = overlay.<span class="hljs-title function_">create</span>({\n        <span class="hljs-attr">positionStrategy</span>: bxOverlayPositionService.<span class="hljs-title function_">getElementStrategy</span>(origin, <span class="hljs-string">&#x27;bottom&#x27;</span>),\n        <span class="hljs-attr">scrollStrategy</span>: overlay.<span class="hljs-property">scrollStrategies</span>.<span class="hljs-title function_">noop</span>()\n    });\n\n    <span class="hljs-keyword">return</span> overlayRef;\n}</code></pre>\n<p>The complete demo source shows portal attachment, theme inheritance, origin tracking, outside-pointer/Escape dismissal, and destruction cleanup.</p>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Utility</th>\n<th>Contract</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>getElementStrategy(element, placement, offset = 8)</code></td>\n<td>Connected CDK strategy with alternative sides, viewport push and an 8 CSS-pixel viewport margin</td>\n</tr>\n<tr>\n<td><code>getSubmenuStrategy(element, side, offset = 4)</code></td>\n<td>Physical left/right preference with opposite-side fallback and fixed dimensions</td>\n</tr>\n<tr>\n<td><code>getCoordinateStrategy(x, y)</code></td>\n<td>Client-coordinate anchor, initially below with a 2 CSS-pixel offset, then fallback positions</td>\n</tr>\n<tr>\n<td><code>trackOverlayOrigin(overlay, origin, options?)</code></td>\n<td>Tracks an attached connected overlay with native anchoring where available, otherwise measured fallback; returns callable cleanup with <code>reposition()</code></td>\n</tr>\n<tr>\n<td><code>isOverlayOriginVisible(origin)</code></td>\n<td>Checks viewport intersection and clipping ancestors; disconnected or zero-size origins return false</td>\n</tr>\n<tr>\n<td><code>inheritOverlayTheme(source, pane)</code></td>\n<td>Copies inherited theme/appearance context and observes relevant scope attributes; returns observer cleanup</td>\n</tr>\n</tbody></table>\n<p><code>IOverlayOriginOptions</code> can disable native anchoring with <code>nativeAnchoring: false</code>, run <code>onPosition</code> after positioning, or run <code>onOriginHidden</code> when the anchor\nleaves view. The owner decides whether to dismiss. Attach content before tracking so size measurement is meaningful. Call both returned cleanup functions before\ndisposing the overlay; the owner also cleans up its subscriptions and portal.</p>\n<p>Top-layer popovers always use synchronous measured CDK positioning, including when native CSS anchors are available. This prevents a frame of drift while a\nnested ancestor scrolls. The returned lifecycle and visibility callbacks work the same way in both paths.</p>\n<p>The demo is an informational preview with focus kept on its trigger. It directly uses an element strategy, visibility guard, origin tracker and inherited theme.\nCoordinate and submenu strategies are documented extension points; ready-made\n<a href="components/context-menu">Context menu</a> and\n<a href="components/menu">Menu</a> demonstrate their intended interactions. Prefer the public overlay components and\ndirectives when their existing focus, dismissal and accessibility behavior meets your needs.</p>\n<h2>Appearance and customization</h2>\n<p>The interactive example uses public Blocks components, semantic theme variables, and shared spacing and responsive helpers. It follows the active playground\nappearance. Open the source tab for the component and template.</p>\n<h2>Behavior and accessibility</h2>\n<p>Use the Blocks select and trigger to try each preferred side. Toggle <strong>Use top layer</strong> to compare the native-anchor and measured positioning paths; changing the\ntoggle closes an open preview. The preview is a Blocks card constrained to the viewport, with scrollable content at larger text sizes. It inherits mounted theme\nand appearance changes.</p>\n<p>Focus stays on the trigger. Escape, blur, outside pointer events, a hidden origin, and navigation close the preview. Reduced-motion and opaque appearances\nfollow the shared Blocks surface behavior.</p>\n<h2>Playground</h2>\n<p>Open <code>/utilities/overlay-positioning</code> from <strong>Core → Utilities → Overlay positioning</strong>. The demo appears first, followed by separate documentation and code tabs.</p>\n<p>Return to the <a href="utilities">utilities overview</a> for the coverage audit and related feature guides.</p>\n',
  'projects/playground/src/app/components/screens/utilities/components/scroll-lock/README.md':
    '<h1>Shared scroll locking</h1>\n<p>Coordinate page scroll locks across multiple owners without releasing another component&#39;s lock.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ScrollLockService</span>, uuidv4 } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">ChangeDetectionStrategy</span>, <span class="hljs-title class_">Component</span>, <span class="hljs-title class_">DestroyRef</span>, inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ScrollLockService</span>, uuidv4 } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Button</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/forms&#x27;</span>;\n\n<span class="hljs-meta">@Component</span>({\n    <span class="hljs-attr">selector</span>: <span class="hljs-string">&#x27;app-scroll-lock-example&#x27;</span>,\n    <span class="hljs-attr">imports</span>: [<span class="hljs-title class_">Button</span>],\n    <span class="hljs-attr">template</span>: <span class="hljs-string">`\n        &lt;button bx-button type=&quot;button&quot; (click)=&quot;lock()&quot;&gt;Lock page&lt;/button&gt;\n        &lt;button bx-button type=&quot;button&quot; (click)=&quot;unlock()&quot;&gt;Release my lock&lt;/button&gt;\n    `</span>,\n    <span class="hljs-attr">changeDetection</span>: <span class="hljs-title class_">ChangeDetectionStrategy</span>.<span class="hljs-property">OnPush</span>\n})\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">ScrollLockExample</span> {\n    <span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> scrollLockService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">ScrollLockService</span>);\n    <span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">lockId</span>: <span class="hljs-built_in">string</span> = <span class="hljs-title function_">uuidv4</span>();\n\n    <span class="hljs-title function_">constructor</span>(<span class="hljs-params"></span>) {\n        <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">DestroyRef</span>).<span class="hljs-title function_">onDestroy</span>(<span class="hljs-function">() =&gt;</span> <span class="hljs-variable language_">this</span>.<span class="hljs-title function_">unlock</span>());\n    }\n\n    <span class="hljs-keyword">protected</span> <span class="hljs-title function_">lock</span>(): <span class="hljs-built_in">void</span> {\n        <span class="hljs-variable language_">this</span>.<span class="hljs-property">scrollLockService</span>.<span class="hljs-title function_">disableScroll</span>(<span class="hljs-variable language_">this</span>.<span class="hljs-property">lockId</span>, { <span class="hljs-attr">handleTouchInput</span>: <span class="hljs-literal">false</span> });\n    }\n\n    <span class="hljs-keyword">protected</span> <span class="hljs-title function_">unlock</span>(): <span class="hljs-built_in">void</span> {\n        <span class="hljs-variable language_">this</span>.<span class="hljs-property">scrollLockService</span>.<span class="hljs-title function_">enableScroll</span>(<span class="hljs-variable language_">this</span>.<span class="hljs-property">lockId</span>);\n    }\n}</code></pre>\n<p>Keep release actions reachable while the page is locked. Release on close and presentation changes as well as destruction. Repeated acquisition with the same ID\nupdates that owner&#39;s lock. Releasing an unknown ID does nothing, and releasing your ID preserves other owners&#39; locks.</p>\n<h2>API</h2>\n<p><code>isScrollDisabled()</code> is a readonly signal indicating that any owner holds a lock. Observe it instead of writing to the backing signal.\n<code>disableScroll(id, config)</code> requires an owner ID and configuration; <code>enableScroll(id)</code> releases that owner. The legacy optional second argument to\n<code>enableScroll</code> is accepted but does not change final cleanup.</p>\n<table>\n<thead>\n<tr>\n<th><code>IScrollLockConfig</code> member</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>handleTouchInput</code></td>\n<td><code>false</code> preserves touch gestures; <code>true</code> enables touchmove prevention. Omission still applies <code>touch-action: none</code>, without adding a touchmove listener by itself</td>\n</tr>\n<tr>\n<td><code>allowTouchInputOn</code></td>\n<td>Elements whose descendants may receive touch input; absent/empty lists permit targets through the touchmove handler</td>\n</tr>\n<tr>\n<td><code>mobileOnlyTouchPrevention</code></td>\n<td>Limits the touchmove handler to detected mobile devices; tablets use their separate category</td>\n</tr>\n<tr>\n<td><code>handleExtremeOverflow</code></td>\n<td>Adds global wheel/scroll prevention listeners; leave unset for ordinary pages and panels</td>\n</tr>\n<tr>\n<td><code>animationDuration</code></td>\n<td>Milliseconds before installing prevention listeners, plus the service&#39;s 10 ms coordination delay; omitted means zero before that delay</td>\n</tr>\n</tbody></table>\n<p>Any active owner requesting touch/extreme prevention keeps it enabled. Touch allow-list details follow the most recently inserted owner whose <code>handleTouchInput</code>\nis not false; reacquiring an existing ID updates its options without changing its insertion order. The maximum active animation duration controls listener\ninstallation. Original inline body overflow, right padding, touch action and priorities are restored after the final lock releases.</p>\n<p>The demo uses <code>{ handleTouchInput: false }</code> for both owners so touch users can reach every action. It does not enable extreme overflow handling. Lock\nacquisition and release are no-ops during SSR.</p>\n<h2>Appearance and customization</h2>\n<p>The interactive example uses public Blocks components, semantic theme variables, and shared spacing and responsive helpers. It follows the active playground\nappearance. Open the source tab for the component and template.</p>\n<h2>Behavior and accessibility</h2>\n<p>The compact Blocks control panel exposes pressed-state buttons for both owner cards. Acquire both locks and release one to inspect remaining-owner behavior. The\nshared status is announced politely.</p>\n<p>Before acquiring the first lock, the demo brings its controls into view without animation or moving focus. The panel is constrained to the viewport and can\nscroll internally when text is enlarged. Touch gestures remain enabled and release actions stay reachable. Navigating to another utility releases both demo\nlocks. Locks held by navigation or other overlays remain active.</p>\n<h2>Playground</h2>\n<p>Open <code>/utilities/scroll-lock</code> from <strong>Core → Utilities → Shared scroll locking</strong>. The demo appears first, followed by separate documentation and code tabs.</p>\n<p>Return to the <a href="utilities">utilities overview</a> for the coverage audit and related feature guides.</p>\n',
  'projects/playground/src/app/components/screens/utilities/components/utility-page/README.md':
    '<h1>Utility page layout</h1>\n<p>Shared playground presentation for the six <a href="utilities">utility examples</a>. Route metadata selects the title, public API summary, guide, and source files.\nThe nested router outlet loads the selected example independently. Every page presents the demo above the documentation and code tabs.</p>\n<h2>Import</h2>\n<p>Routes lazy-load <code>UtilityPage</code> from <code>@playground/components/screens/utilities/components/utility-page/utility-page</code>.</p>\n<h2>Usage</h2>\n<p>Register utility metadata in <code>constants/utility-catalog.constants.ts</code>. The <code>/utilities</code> route uses this catalog for child routes, sidenav entries, and overview\ncards.</p>\n<h2>API</h2>\n<p><code>IUtilityExample</code> connects each route ID, title, description, icon, public symbol, README, and lazy demo loader. Supporting declarations stay under the\nutilities screen&#39;s category folders.</p>\n<h2>Appearance and customization</h2>\n<p>The layout uses the shared Blocks PageContainer, automatic breadcrumbs, stacks, dividers, and component-info documentation tabs. The container resolves section\nand page titles through NavigationService; descriptions come from the utility catalog. Shared semantic tokens keep it consistent with the active playground\nappearance.</p>\n<h2>Behavior and accessibility</h2>\n<p>A single page heading labels the article. Named demo and documentation sections appear in reading order. Each example owns cleanup of its resources.</p>\n<h2>Playground</h2>\n<p>Reach this layout through any <code>/utilities/&lt;utility&gt;</code> route, such as <code>/utilities/viewport</code>.</p>\n',
  'projects/playground/src/app/components/screens/utilities/components/viewport/README.md':
    '<h1>Viewport and breakpoints</h1>\n<p>Build responsive layouts with live viewport signals and the shared Blocks breakpoint scale.</p>\n<h2>Import</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">WindowDimensionsService</span>, <span class="hljs-variable constant_">BREAKPOINTS</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;</code></pre>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="typescript code example"><code class="hljs language-typescript"><span class="hljs-keyword">import</span> <span class="hljs-keyword">type</span> { <span class="hljs-title class_">Signal</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ChangeDetectionStrategy</span>, <span class="hljs-title class_">Component</span>, computed, inject } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@angular/core&#x27;</span>;\n\n<span class="hljs-keyword">import</span> { <span class="hljs-title class_">WindowDimensionsService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">&#x27;@filip.mazev/blocks/core&#x27;</span>;\n\n<span class="hljs-meta">@Component</span>({\n    <span class="hljs-attr">selector</span>: <span class="hljs-string">&#x27;app-responsive-summary&#x27;</span>,\n    <span class="hljs-attr">template</span>: <span class="hljs-string">&#x27;&lt;p&gt;{{ width() }} CSS pixels · {{ columns() }} columns&lt;/p&gt;&#x27;</span>,\n    <span class="hljs-attr">changeDetection</span>: <span class="hljs-title class_">ChangeDetectionStrategy</span>.<span class="hljs-property">OnPush</span>\n})\n<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">ResponsiveSummary</span> {\n    <span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> windowDimensionsService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">WindowDimensionsService</span>);\n\n    <span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">width</span>: <span class="hljs-title class_">Signal</span>&lt;<span class="hljs-built_in">number</span>&gt; = <span class="hljs-title function_">computed</span>(<span class="hljs-function">() =&gt;</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">windowDimensionsService</span>.<span class="hljs-title function_">dimensions</span>().<span class="hljs-property">width</span>);\n    <span class="hljs-keyword">protected</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">columns</span>: <span class="hljs-title class_">Signal</span>&lt;<span class="hljs-built_in">number</span>&gt; = <span class="hljs-title function_">computed</span>(<span class="hljs-function">() =&gt;</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">windowDimensionsService</span>.<span class="hljs-title function_">resolveResponsiveValue</span>({ <span class="hljs-attr">md</span>: <span class="hljs-number">2</span>, <span class="hljs-attr">xl</span>: <span class="hljs-number">3</span> }, <span class="hljs-number">1</span>));\n}</code></pre>\n<h2>API</h2>\n<table>\n<thead>\n<tr>\n<th>Member</th>\n<th>Behavior</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>dimensions(): IWindowDimensions</code></td>\n<td>Readonly signal with <code>width</code> and <code>height</code> in CSS pixels; resize updates are coalesced to animation frames</td>\n</tr>\n<tr>\n<td><code>breakpoints</code> / <code>BREAKPOINTS</code></td>\n<td>Shared minimums: xs 360, sm 640, md 768, lg 1024, xl 1280, 2xl 1536, 3xl 1920, 4xl 2560</td>\n</tr>\n<tr>\n<td><code>currentBreakpoint()</code></td>\n<td>Largest matching breakpoint; widths below 360 still report <code>xs</code>; undefined during SSR</td>\n</tr>\n<tr>\n<td><code>currentBreakpointValue()</code></td>\n<td>Minimum for the reported breakpoint, not the actual viewport width; undefined during SSR</td>\n</tr>\n<tr>\n<td><code>isBelow(key)</code> / <code>isAtLeast(key)</code></td>\n<td>Strict upper bound / inclusive lower bound</td>\n</tr>\n<tr>\n<td><code>isBetween(min, max)</code></td>\n<td>Inclusive minimum and exclusive maximum</td>\n</tr>\n<tr>\n<td><code>resolveResponsiveValue&lt;T&gt;(values, fallback)</code></td>\n<td>Value at the highest configured matching breakpoint, otherwise the fallback; always the fallback during SSR</td>\n</tr>\n<tr>\n<td><code>isBrowser</code></td>\n<td>Whether browser viewport observation is available</td>\n</tr>\n</tbody></table>\n<p>Convenience signals cover <code>isXsMobile</code> (below sm), <code>isSmMobile</code> (sm–md), <code>isMobile</code> (below md), <code>isTablet</code> (md–lg), <code>isSmallLaptop</code> (lg–xl), <code>isDesktop</code>\n(xl–2xl), <code>isLargeDesktop</code> (2xl–3xl), and <code>isUltraWide</code> (3xl and above). Upper bounds are exclusive. <code>isTabletAndBelow</code>, <code>isSmallLaptopAndBelow</code>,\n<code>isDesktopAndBelow</code>, and <code>isLargeDesktopAndBelow</code> are below lg, xl, 2xl, and 3xl respectively.</p>\n<p>SSR dimensions are zero. Simple range predicates compare against zero there; do not interpret them as actual device detection. Responsive values describe\nviewport width, even when the component occupies a smaller container. Browser zoom can change CSS-pixel dimensions.</p>\n<h2>Appearance and customization</h2>\n<p>The interactive example uses public Blocks components, semantic theme variables, and shared spacing and responsive helpers. It follows the active playground\nappearance. Open the source tab for the component and template.</p>\n<h2>Behavior and accessibility</h2>\n<p>Resize the browser or change zoom to observe width, height, breakpoint tags, and the responsive preview. Values use CSS pixels. The preview uses Blocks cards,\ngrids, and tags.</p>\n<p>Viewport changes derive from signals under OnPush and are not announced on every resize. SSR dimensions are zero; responsive values use the fallback.</p>\n<h2>Playground</h2>\n<p>Open <code>/utilities/viewport</code> from <strong>Core → Utilities → Viewport and breakpoints</strong>. The demo appears first, followed by separate documentation and code tabs.</p>\n<p>Return to the <a href="utilities">utilities overview</a> for the coverage audit and related feature guides.</p>\n',
  'projects/playground/src/app/components/shared/sidenav/README.md':
    '<h1>Playground navigation</h1>\n<p>The playground shell uses Blocks SideNav for an expandable desktop sidebar, a compact icon rail, and a mobile drawer.</p>\n<h2>Import</h2>\n<p>The application shell imports <code>Sidenav</code> from <code>./components/shared/sidenav/sidenav</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">app-sidenav</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;Blocks&quot;</span> /&gt;</span></code></pre>\n<p>Use the desktop header control to collapse or expand the navigation. The preference persists across reloads. On mobile, use the toolbar menu button.</p>\n<h2>API</h2>\n<p><code>title</code> is required. <code>mobile()</code>, <code>open()</code>, <code>panelId()</code>, and <code>toggle(event)</code> connect the application&#39;s mobile trigger to the shared drawer.</p>\n<p>The route-driven tree presents Home, Appearance, Components, Tokens, Icons, Utilities, Tools, and Release notes as separate entries with icons. Components\ncontains Primitives, Forms, Navigation, Modals, and Notifications; each category contains its component pages. Layout adds a third level under Primitives.\nCategory links open a filtered component index. Tools contains the modal and toast configurators and links to its own overview page. Release notes is the last\nentry. Nested leaf pages use text-only rows; nested parents retain their icons.</p>\n<h2>Appearance and customization</h2>\n<p>The header shows the Blocks logo alone when compact and includes the title and release label when expanded. Shared SideNav controls all panel surfaces,\ndimensions, icons, tooltips, search, and theme behavior.</p>\n<h2>Behavior and accessibility</h2>\n<p>The navigation retains the shared keyboard browsing, Back and ancestor actions, focus restoration, reduced-motion support, and mobile focus trap. Opening a\nbranch or search temporarily expands the icon rail without changing the saved preference. Existing component and configurator URLs remain valid. Desktop labels\nretain their final layout while the panel expands, then fade in briefly. Reduced motion skips the delay and fade, including live preference changes. Keyboard\nfocus reveals labels immediately, and accessible names remain available during the visual transition.</p>\n<h2>Playground</h2>\n<p>The navigation is available on every playground page. Visit <code>/components</code>, <code>/components/category/forms</code>, <code>/components/layout</code>, and <code>/tools</code> to explore the\nhierarchy.</p>\n',
  'projects/playground/src/app/components/shared/theme-material-preview/README.md':
    '<h1>Theme material preview</h1>\n<p>Two decorative miniature pages recall Filip Mazev’s first portfolio through its original wave silhouette, paired with abstract shapes and typography. A readable\nBlocks glass card overlaps the pages with static typography and theme color samples.</p>\n<h2>Import</h2>\n<p>Private playground component, imported from <code>@playground/components/shared/theme-material-preview/theme-material-preview</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">app-theme-material-preview</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p>No inputs. The decorative pages follow the active theme through semantic CSS variables. Visibility and the shared motion preference control their floating\nanimation.</p>\n<h2>Appearance and customization</h2>\n<p>The miniature profile and portfolio project pages use Blocks cards and icons with container-relative typography. The wave silhouette comes from the author’s\nfirst portfolio, with a gradient mixing primary and accent into the theme surface for readable overlaid text. The project composition uses a ring, a tilted\npanel, gradients and short text; its strongest gradient sits below the text, while the text area uses muted surface tints. There are no image assets or project\nfooter. Material, text, borders and corners follow the live theme.</p>\n<p>The rear pages are opaque Blocks cards with <code>surfaceEffects</code> disabled: they neither receive environmental or Orby lighting nor render glass or press effects.\nThe foreground Blocks card uses <code>bxSurfaceGlassiness=&quot;auto&quot;</code> with the shared material defaults, matching Appearance’s search bar instead of adding a stronger\nblur. Its own text stays crisp while the headings and abstract artwork cross its refractive edges. Rendering quality is omitted to follow the global setting.\nGlassiness Off, Baseline quality, unsupported browsers and accessibility preferences retain the shared fallback.</p>\n<p>The 6:5 composition is capped at 32rem. The “Design &amp; code.” title and short introductions keep the previews recognizable as pages. The pages fan outward by six\ndegrees while overlapping, and a taller landscape Blocks pane (about 1.76:1) covers their shared center with extra internal spacing. The front samples use\naccent, primary and a blend of both, so all three respond to palette changes and Theme Studio overrides instead of retaining status colors across palettes.</p>\n<h2>Behavior and accessibility</h2>\n<p>The illustration is decorative, hidden from assistive technology and contains no buttons or focus stops. Only the stationary foreground pane participates in the\nshared lighting engine, with pressure feedback explicitly disabled. The two rear pages follow small, repeating diagonal bobs over independent 8- and 9.5-second\nCSS cycles. Each page’s translation and rotation share one cycle: travel is bounded to 0.7% horizontally and 1.5% vertically, with 0.6 degrees of rocking. There\nis no separate wandering rotation, application frame loop or repeated lighting measurement.</p>\n<p>An intersection observer and document visibility listener pause motion offscreen or in a hidden tab. <code>BxA11yService</code> and the system reduced-motion preference\nprovide a static composition and react to changes while mounted. Observers and listeners are removed on destruction; the shared surface runtime owns the\nforeground filter, lighting and its teardown.</p>\n<h2>Playground</h2>\n<p>Open <code>/</code>. Studio uses a separate <a href="studio">glass panel composition</a>. Theme and appearance edits update both mounted illustrations.</p>\n',
  'projects/playground/src/app/components/shared/theme-palette-preview/README.md':
    '<h1>Theme palette preview</h1>\n<p>Six glass blocks form an aperture-like ring beside Theme Studio’s introduction. Equal angular spacing, a consistent overlap and an open center preserve the\nstructure of a lens while the rounded rectangular panels retain Blocks’ visual language.</p>\n<h2>Import</h2>\n<p>Private playground component, imported from <code>@playground/components/shared/theme-palette-preview/theme-palette-preview</code>.</p>\n<h2>Usage</h2>\n<pre class="playground-code-block" tabindex="0" aria-label="html code example"><code class="hljs language-html"><span class="hljs-tag">&lt;<span class="hljs-name">app-theme-palette-preview</span> /&gt;</span></code></pre>\n<h2>API</h2>\n<p>No inputs or controls. Semantic CSS variables update the illustration when the theme changes. Local motion state owns only decorative rotation, bobbing and\nhover contraction.</p>\n<h2>Appearance and customization</h2>\n<p>Each panel is a Blocks <code>Card</code> with <code>bxSurface</code>, selecting <code>bxSurfaceGlassiness=&quot;auto&quot;</code>. The directive owns its surface renderer, with the card’s automatic\nrenderer disabled. Rendering quality is omitted to inherit the global Automatic, Enhanced or Baseline setting.</p>\n<p>Primary and accent supply two panels. Info, success, warning and danger supply the remaining tints, each blended with the active primary or accent so palette\nswitches and live token edits affect every panel. Each panel advances by 60 degrees around one center, with an eight-degree rotation of the ring. Narrower\npanels turn back by 14 degrees locally, exposing their individual ends instead of forming a continuous hexagonal perimeter. Overlaps retain visible refraction\nand the central aperture. The composition is capped at 27rem and uses shared corner radii, with no surrounding card, badge or color legend. Its stage clips the\ninvisible rotated positioning bounds so the decoration cannot create horizontal page overflow.</p>\n<p>When the Studio introduction’s container is narrow, the illustration shrinks to at most 11rem and becomes a faint backing beside the heading, without adding a\nseparate row. This also applies when the Studio sidebar constrains the page. The compact backing is hidden in forced-colors and increased-contrast modes.</p>\n<h2>Behavior and accessibility</h2>\n<p>The illustration is decorative, hidden from assistive technology and has no focus targets or press feedback. The ring turns as one unit at two degrees per\nsecond (one turn every three minutes). Each pane has a staggered 9–13-second bob, bounded to 0.3% sideways, 0.65% vertically and 0.25 degrees of tilt.</p>\n<p>Hovering the stable outer stage with a fine pointer draws every pane inward by at most 9% of its height and turns it another four degrees, gently tightening the\naperture. Leaving or cancelling returns it to its resting position. The shared soft spring preserves velocity during interruptions; touch does not latch hover\nfeedback. This effect conveys no action or essential information and adds no keyboard stop.</p>\n<p>The component uses the existing effects runtime’s shared frame scheduler, spring and geometry-aware style painting. Moving panels update their own lighting\ngeometry without invalidating unrelated surfaces. The runtime continues to own lighting and refraction rendering. Intersection and document visibility suspend\nmotion offscreen or in hidden tabs, resuming without elapsed-time catch-up. Live <code>BxA11yService</code> reduced motion stops all decorative movement, including hover\ncontraction, and restores the resting composition. Destruction removes the frame subscription, visibility listener and observer.</p>\n<p>Unsupported glass rendering falls back to the standard Blocks material; reduced transparency and forced colors retain the shared accessible presentation.\nNoninteractive surfaces remain available to lighting hit tests without responding to pointer presses.</p>\n<h2>Playground</h2>\n<p>Open <code>/studio</code>. Edit the theme or change rendering quality in Appearance while the panels are visible to compare the live material.</p>\n',
  'projects/playground/src/app/components/shared/theme-studio-import/README.md':
    '<h1>Theme Studio import dialog</h1>\n<p>Validate and import Studio JSON or a Studio SCSS export without executing imported code. A Blocks button opens the native chooser and shows the selected\nfilename. The multiline text editor autosizes between four and eight rows, with space reserved between its scrollbar and the modal scrollbar. Import\nconfirmation and status stay in the fixed modal footer while the editor scrolls.</p>\n<h2>Import</h2>\n<p>This is playground tooling using the public Blocks entry points. Open Theme Studio from the toolbar.</p>\n<h2>Usage</h2>\n<p>Open <code>/studio</code>. The Studio toolbar and its Copy / setup and Import actions expose the complete workflow.</p>\n<h2>API</h2>\n<p>Draft state belongs to <code>ThemeStudioService</code>; palette, mode and appearance remain owned by <code>ThemingService</code>. Controls use signals and OnPush.</p>\n<h2>Appearance and customization</h2>\n<p>Uses shared semantic colors, spacing, radius, borders, shadows and existing Blocks components. The active theme applies to this view and its overlays.</p>\n<h2>Behavior and accessibility</h2>\n<p>Controls have accessible labels and keyboard operation. Existing focus, modal dismissal, reduced-motion and high-contrast mechanisms remain authoritative.</p>\n<h2>Playground</h2>\n<p>Open <code>/studio</code>. The authoritative Studio guide is available from the editor&#39;s Export tab.</p>\n',
  'projects/playground/src/app/components/shared/theme-studio-preview-dialog/README.md':
    '<h1>Theme Studio preview dialog</h1>\n<p>Inspect an actual centered Blocks modal and editable field using the current shared theme.</p>\n<h2>Import</h2>\n<p>This is playground tooling using the public Blocks entry points. Open Theme Studio from the toolbar.</p>\n<h2>Usage</h2>\n<p>Open <code>/studio</code> and choose <strong>Inspect a themed dialog</strong> in the Layout section. Edit the sample field or use <strong>Done</strong> to close it.</p>\n<h2>API</h2>\n<p>Draft state belongs to <code>ThemeStudioService</code>; palette, mode and appearance remain owned by <code>ThemingService</code>. Controls use signals and OnPush.</p>\n<h2>Appearance and customization</h2>\n<p>Uses shared semantic colors, spacing, radius, borders, shadows and existing Blocks components. The active theme applies while the modal remains open; reopening\nis not required to receive preview changes.</p>\n<h2>Behavior and accessibility</h2>\n<p>Controls have accessible labels and keyboard operation. Existing focus, modal dismissal, reduced-motion and high-contrast mechanisms remain authoritative.</p>\n<h2>Playground</h2>\n<p>Open <code>/studio</code>. The authoritative Studio guide is available from the editor&#39;s Export tab.</p>\n',
  'projects/playground/src/app/components/shared/theme-studio-setup/README.md':
    '<h1>Theme Studio setup dialog</h1>\n<p>Copy an exported theme through a Blocks stepper: Configure the project/method, Install with the selected package manager, then Apply theme. The stepper stays in\nthe fixed modal header; Back/Next/Done and copy feedback stay in the footer. Each code preview and its copy action have explicit spacing. The modal uses a\nstable viewport-bounded size across steps and opens as a bottom sheet at the shared small-screen breakpoint.</p>\n<h2>Import</h2>\n<p>This is playground tooling using the public Blocks entry points. Open Theme Studio from the toolbar.</p>\n<h2>Usage</h2>\n<p>Open <code>/studio</code>. The Studio toolbar and its Copy / setup and Import actions expose the complete workflow.</p>\n<h2>API</h2>\n<p>Draft state belongs to <code>ThemeStudioService</code>; palette, mode and appearance remain owned by <code>ThemingService</code>. Controls use signals and OnPush.</p>\n<h2>Appearance and customization</h2>\n<p>Uses shared semantic colors, spacing, radius, borders, shadows and existing Blocks components. The active theme applies to this view and its overlays.</p>\n<h2>Behavior and accessibility</h2>\n<p>Step changes patch the existing modal title and icon through <code>ModalRef.patch()</code> without reopening it. Footer navigation focuses the new step heading; header\nnavigation retains the stepper’s keyboard focus. Project, package manager and method selections survive revisiting steps.</p>\n<p>Controls have accessible labels and keyboard operation. Existing focus, modal dismissal, reduced-motion and high-contrast mechanisms remain authoritative.</p>\n<h2>Playground</h2>\n<p>Open <code>/studio</code>. The authoritative Studio guide is available from the editor&#39;s Export tab.</p>\n',
  'projects/playground/src/app/components/shared/theme-studio/README.md':
    '<h1>Blocks Theme Studio</h1>\n<p>Design a Blocks theme while exploring real components. The toolbar opens a nonmodal editor on the physical right; the same draft and preview remain active\nacross playground pages. Open <code>/studio</code> for an integrated theme and token showcase.</p>\n<h2>Import</h2>\n<p>Studio is playground tooling. Applications use its generated SCSS and public Blocks package:</p>\n<pre class="playground-code-block" tabindex="0" aria-label="scss code example"><code class="hljs language-scss"><span class="hljs-keyword">@use</span> <span class="hljs-string">&#x27;@filip.mazev/blocks&#x27;</span> as bx;</code></pre>\n<p>Merge an existing Blocks import instead of loading global styles twice. Keep the effects stylesheet and normal high-contrast theme installed. See the\n<a href="installation">package setup</a>.</p>\n<h2>Usage</h2>\n<ol>\n<li>Open Theme Studio from the toolbar or the <a href="studio">component preview</a>.</li>\n<li>Use the Light/Dark segmented selector and Theme palette dropdown at the top. Palette options and the selected value show the same paired swatches as\nAppearance. Below Explore Theme Studio, choose Corner radius, Base color, Menu color and Menu accent.</li>\n<li>Adjust common colors with color pickers and opacity sliders. Advanced semantic roles remain available in a disclosure.</li>\n<li>Choose Default, None, Small, Medium or Large corner radii; Layout also offers coordinated spacing and border settings.</li>\n<li>Use Shadows to choose a target and edit color, opacity, blur, spread and X/Y offsets. All targets share the edited shadow when All resting shadows is\nselected.</li>\n<li>Select <strong>Copy / setup</strong> for the Configure → Install → Apply theme stepper. Configure selects New/Existing project, package manager and Quick/Manual setup.\nThe stepper stays in the modal header. Install provides commands, then Apply theme provides SCSS. Code previews and copy actions have explicit spacing;\nBack/Next/Done stay in a fixed footer.</li>\n<li>Use <strong>Import</strong> to paste or upload Studio JSON or an unmodified SCSS export. Download JSON from Export to resume editing elsewhere.</li>\n</ol>\n<p>Undo, Redo and Randomize stay in the fixed panel header while the editor scrolls, with the undo-2, redo-2 and dices icons. Closing the panel preserves draft and\npreview. Preview off restores owned inline styles. Feedback occupies a fixed-height region above Live preview in the footer, so messages cannot overlap the\neditor or shift the actions.</p>\n<h2>API</h2>\n<p><code>ThemeStudioService</code> owns sparse shared overrides, separate light/dark colors, editing text and a bounded session history. <code>ThemingService</code> remains the owner of\npalette, mode and appearance. Undo restores the captured mode preference, including automatic mode; appearance, accessibility and panel preferences remain\nindependent. History retains at most 30 combined undo/redo entries and a 2 MiB estimated serialized UTF-16 budget; oldest undo entries and farthest redo entries\nare evicted first. This bounds history storage without claiming a fixed JavaScript heap size. A typing session or slider drag is one change. Cancellation\nrestores the draft and retains redo history.</p>\n<p>Pure helpers own validation, coordinated presets, shadow serialization, import and deterministic export. Preview ownership is separate. Supported document keys\nstill derive from <code>THEME_CSS_VARIABLES</code>; runtime lighting, focus rings, optical variables and component hooks are excluded.</p>\n<h3>Coordinated controls</h3>\n<p>Corner radius changes all six ordinary radii together. Default removes radius overrides, None sets them to zero, and Small/Medium/Large use half, equal or\none-and-a-half times the generated Sass scale. Structural square and pill shapes retain their contracts. Custom imported scales remain intact and display Custom\nvalues with an explanation until a preset is chosen. Unsupported Custom options are not offered in dropdown menus. Spacing presets apply the same multiplier to\nevery nonzero shared spacing step.</p>\n<p>Base color uses generated neutral shade inventories for Carbon or Slate and updates surfaces, text and neutral borders in both modes. Default removes those\noverrides. Theme chooses the existing built-in palette and preserves explicit overrides. Menu color controls shared surface tokens; Menu accent controls shared\nhover/active tokens. These selectors also affect cards and other controls that consume those roles, as stated in the editor. They do not create a separate menu\ntheme or add private component hooks to the document.</p>\n<p>The shadow editor supports All resting shadows, Controls, Surfaces, Cards, Modals and Toasts. It reads the current first layer and preserves imported lists\nuntil a control is edited; editing replaces selected targets with one validated layer. Opacity is 0–100%, blur 0–64px, spread ±32px and offsets ±64px. Reduced\nmotion and semantic emission remain separate. Transparent shadows use a valid zero-opacity layer rather than <code>none</code> when composed with semantic light.</p>\n<p>Randomize chooses a built-in palette, a coordinated neutral base and subtle menu fills with modest geometry and elevation changes. It resolves both modes from\nshared semantic palette roles; generated color overrides use six-digit hex, or eight-digit hex when transparency is needed, including shadow colors. Contrast\nchecks use these serialized colors. Preview, JSON and SCSS retain the same values; Undo restores the preceding draft. Existing imported or manually entered\ncolor formats remain supported. Inherited palette colors also prepopulate the editor in hex without becoming overrides. It does not certify overall\naccessibility of a consumer&#39;s content.</p>\n<h3>Import and export</h3>\n<p>JSON uses schema version 1, a supported <code>palette</code>, a <code>shared</code> override map, and <code>light</code>/<code>dark</code> color maps. Files and pasted input are limited to 64 KiB. Every\nname, family and value is validated before atomically replacing the draft. Unknown versions, malformed data, unsupported tokens, duplicate SCSS declarations,\nunsupported selectors and unreadable files leave the current draft unchanged. A successful import is one undoable change. Pending file reads cannot update a\ndestroyed dialog or replace a newer file selection.</p>\n<p>SCSS import accepts the Studio export grammar: the Blocks <code>@use</code>, forced-colors guard, shared root block and the two <code>data-theme</code> blocks with matching built-in\nbase includes. Arbitrary Sass, third-party theme formats and executable snippets are not evaluated. JSON is the portable editing format; SCSS is the application\nstylesheet format.</p>\n<p>Export includes the named built-in base in both modes and sparse validated overrides, with stable ordering, LF and a final newline. Set <code>data-theme=&quot;light&quot;</code> or\n<code>data-theme=&quot;dark&quot;</code> and <code>.high-contrast</code> on the root. Place declarations after existing palette rules. Commands initialize Blocks&#39; built-in base using its\nexisting Angular schematic; paste the generated SCSS afterward to apply Studio customizations. There is no command that silently downloads a private draft.</p>\n<p>Drafts and history last for the current application session. Reload starts a fresh draft. Palette, mode, appearance and catalog preferences keep their existing\nstorage behavior. There is no named-preset storage or cloud sharing.</p>\n<h2>Appearance and customization</h2>\n<p>The Export tab renders live SCSS in the shared highlighted code preview, with spacing between its actions and code and a gutter beside nested scrollbars.</p>\n<p>The editor uses Blocks forms, sliders, tabs, disclosures, SidePanel/SidePanelLayout and responsive Modal. It overlays on narrow screens and pushes at the shared\n<code>2xl</code> breakpoint. Its initial width is 480px, with pointer/touch/keyboard resizing from 480px to 624px (30% larger); a smaller available container takes\nprecedence. The chosen width remains while navigating and reopening. The toolbar remains outside panel bounds. Header history, footer actions and the close\ncontrol stay outside the editor&#39;s scroll region. The editor has bottom padding so its final disclosure remains separated from the footer. The compact toolbar\npreview action remains available when extreme spacing makes the editor difficult to use.</p>\n<p>Colors accept literal hex, rgb/rgba, hsl/hsla, black, white or transparent. Imported geometry accepts bounded px/rem/em values; shadows accept up to four\nliteral layers. References, expressions and declaration delimiters are rejected. Invalid editing text retains the last valid preview and prevents export until\nfixed or reset. Choosing a color preserves its alpha; opacity sliders change it explicitly.</p>\n<h2>Behavior and accessibility</h2>\n<p>Reset returns to Carbon / Cobalt and clears all Studio overrides; mode and appearance preferences remain unchanged. Reset is undoable. Randomize chooses a\ncoordinated built-in palette and a curated recipe linking neutral base, menu treatment, interaction accent, spacing, corners and elevation. The recipes keep\nmenu surfaces neutral and use one subtle brand or accent hue for interaction. Menu presets reuse the same semantic roles as the manual controls. Candidate\nrecipes check primary and secondary text at 4.5:1 against canvas, surfaces and interaction fills in both modes. These checks cover the generated combinations,\nnot every consumer-defined component state.</p>\n<p>While Studio is open, Ctrl/Cmd+Z undoes a theme change and Ctrl/Cmd+Shift+Z redoes it. Text inputs, textareas, editable content and open modals retain their\nnormal keyboard behavior. At the retained history boundaries, focusable tooltip wrappers explain why Undo or Redo is unavailable. The Undo tooltip distinguishes\nan empty history from older entries discarded by the 30-entry / 2 MiB bound.</p>\n<p>The setup modal keeps a stable viewport-bounded frame across steps and patches its title and icon in place. On small screens it uses the shared bottom-sheet\nlayout. Its header and footer remain reachable while the body scrolls. The import editor is capped at eight rows and reserves a gutter beside nested scrollbars.</p>\n<p>Named controls, keyboard-operable tabs, visible focus and live feedback follow Blocks mechanisms. The nonmodal sidebar does not trap focus or make the page\ninert. Child dropdowns consume Escape first. Setup/import dialogs use the shared modal lifecycle and have accessible names. Their text regions and commands can\nbe selected with the keyboard. Import keeps confirmation and status in a fixed modal footer, and its Blocks button opens the native file chooser. Import, reset,\ncopy, download and randomize actions use tonal Blocks buttons with icons. Copy failures provide a manual route; download URLs and temporary anchors are cleaned\nup on success and failure.</p>\n<p>High contrast and forced colors suspend Studio overrides without erasing the draft. Reduced motion and transparency remain live, independent preferences.\nPreview diffs only owned root custom properties, preserves previous inline values and priorities, and restores them on reset, preview off or destruction. If\nanother owner changes a property, Studio relinquishes it until preview is toggled or the token is reset. Baselines come from isolated palette scopes and\ngenerated geometry, never previous preview overrides. Token catalog values, copy formats and search refresh with preview edits.</p>\n<p>Opening Studio closes icon Filters/Details. Opening either catalog panel closes Studio while retaining its draft and preview. Catalog filtering and visit-local\nicon settings keep their existing behavior.</p>\n<h2>Playground</h2>\n<p><code>/studio</code> presents integrated sections for semantic color roles, layout tokens, light/dark foreground pairs and export. A card, readonly field, mode tabs and\nresponsive dialog demonstrate the relevant tokens in context, without a separate component-preview route. The sidebar links here as <strong>Explore Theme Studio</strong>.\n<code>/studio/new-project</code> provides Angular workspace initialization and Blocks setup commands for npm, pnpm, yarn and bun. Both are reachable from the Studio\nworkflow. Theme Studio appears directly below Appearance in the main navigation with its Palette icon. <code>/installation</code> renders the authoritative package setup\nguide; documentation links no longer redirect installation requests to Home.</p>\n<p>Commands and SCSS use the shared code-preview container with syntax highlighting and keyboard scrolling. The SCSS viewer has an inline gutter separating its\nscrollbar from the modal scrollbar. The Studio editor fields and border slider retain explicit spacing around their controls.</p>\n<p>Tabs inside the sidebar and dialogs keep inactive triggers transparent even when an enclosing material has a minimum-opacity floor. The traveling selection\ntherefore remains visible above the header backing, with labels above it, including when the header and page use different surface colors.</p>\n<p>The toolbar action gradually lights up with a saturated rainbow rim and a diffuse halo when Studio overrides are being previewed. Pausing preview or resetting\nthe overrides fades the light out; resuming preview fades it back in. Both layers follow the button&#39;s shared radius. Four subdued light sources use the existing\nBlocks lighting scene; colors, brightness and the border move together on the shared lazy frame clock. Frame work stops after fading out and while the document\nor button is hidden. Reduced motion changes brightness immediately and leaves static colors; forced colors and high contrast remove the decoration and its light\nsources while preserving the ordinary Blocks button and focus outline.</p>\n'
};
